def _demografia_response_cache_ttl_seconds(
    *,
    rango: str | None,
    desde: str | None,
    hasta: str | None,
) -> int:
    rango_norm = (rango or "").strip().lower()
    if rango_norm in {"7d", "30d"}:
        return 600
    if rango_norm == "hoy":
        return 120
    if rango_norm == "ayer":
        return 900
    if rango_norm == "fechas":
        return 300 if (desde or hasta) else 180
    return 180
