async def _resolve_quote_logo_url(
    *,
    organizacion_id: UUID,
) -> str | None:
    logger.info(
        "quote_logo_debug_start",
        extra={"organizacion_id": str(organizacion_id)},
    )
    try:
        platform_repo = PlatformRepository()
        template_row = await platform_repo.get_quote_template(
            slug=DEFAULT_QUOTE_TEMPLATE_SLUG,
            organizacion_id=organizacion_id,
        )
    except PlatformRepositoryError:
        logger.warning(
            "quote_logo_debug_template_fetch_failed",
            extra={"organizacion_id": str(organizacion_id)},
        )
        return DEFAULT_QUOTE_LOGO_PATH
    if not isinstance(template_row, dict):
        logger.warning(
            "quote_logo_debug_template_not_dict",
            extra={"organizacion_id": str(organizacion_id)},
        )
        return DEFAULT_QUOTE_LOGO_PATH
    config = _ensure_dict(template_row.get("config"), default={})
    logger.info(
        "quote_logo_debug_template_loaded",
        extra={
            "organizacion_id": str(organizacion_id),
            "config_keys": sorted(config.keys()),
        },
    )
    for key in ("logoUrl", "logo_url"):
        value = config.get(key)
        if isinstance(value, str) and value.strip():
            raw_logo_url = value.strip()
            logger.info(
                "quote_logo_debug_logo_value_found",
                extra={
                    "organizacion_id": str(organizacion_id),
                    "config_key": key,
                    "raw_logo_url": raw_logo_url,
                },
            )
            data_uri = _quote_logo_data_uri(raw_logo_url)
            if data_uri:
                logger.info(
                    "quote_logo_debug_logo_data_uri_ready",
                    extra={
                        "organizacion_id": str(organizacion_id),
                        "config_key": key,
                        "data_uri_prefix": data_uri[:40],
                        "data_uri_length": len(data_uri),
                    },
                )
                return data_uri
            if raw_logo_url.startswith(("http://", "https://", "data:")):
                logger.info(
                    "quote_logo_debug_logo_uses_absolute_url",
                    extra={
                        "organizacion_id": str(organizacion_id),
                        "config_key": key,
                        "resolved_url": raw_logo_url,
                    },
                )
                return raw_logo_url
            public_base_url = None
            try:
                public_base_url = await tenant_runtime.get_org_public_base_url(
                    organizacion_id=organizacion_id
                )
            except Exception:
                public_base_url = None
            base_url = (public_base_url or "https://talia.mx").rstrip("/")
            if raw_logo_url.startswith("/"):
                resolved_url = f"{base_url}{raw_logo_url}"
            else:
                resolved_url = f"{base_url}/{raw_logo_url}"
            logger.info(
                "quote_logo_debug_logo_resolved_relative",
                extra={
                    "organizacion_id": str(organizacion_id),
                    "config_key": key,
                    "public_base_url": public_base_url,
                    "resolved_url": resolved_url,
                },
            )
            return resolved_url
    logger.warning(
        "quote_logo_debug_no_logo_in_template",
        extra={"organizacion_id": str(organizacion_id)},
    )
    return DEFAULT_QUOTE_LOGO_PATH


def _quote_logo_data_uri(raw_logo_url: str) -> str | None:
    path_value = raw_logo_url.strip()
    if not path_value:
        logger.info("quote_logo_debug_empty_path")
        return None
    if path_value.startswith("data:"):
        logger.info("quote_logo_debug_existing_data_uri")
        return path_value

    parsed = urlparse(path_value)
    if parsed.scheme in {"http", "https"}:
        path_value = parsed.path or path_value

    repo_root = Path(__file__).resolve().parents[4]
    candidate_paths: list[Path] = []
    normalized = path_value.lstrip("/")
    filename = Path(path_value).name

    if normalized.startswith("assets/logos/"):
        candidate_paths.extend(
            [
                repo_root / "frontend/panel/public" / normalized,
                repo_root / "backend/app/public/shared/logos" / filename,
                repo_root / "backend/app/public/shared" / normalized,
            ]
        )
    else:
        candidate_paths.extend(
            [
                repo_root / "frontend/panel/public" / normalized,
                repo_root / "backend/app/public/shared" / normalized,
            ]
        )
    logger.info(
        "quote_logo_debug_candidate_paths",
        extra={
            "raw_logo_url": raw_logo_url,
            "normalized": normalized,
            "candidate_paths": [str(candidate) for candidate in candidate_paths],
        },
    )

    for candidate in candidate_paths:
        if not candidate.exists() or not candidate.is_file():
            continue
        mime_type, _ = guess_type(str(candidate))
        safe_mime = mime_type or "image/png"
        try:
            encoded = base64.b64encode(candidate.read_bytes()).decode("ascii")
        except OSError:
            logger.warning(
                "quote_logo_debug_read_failed",
                extra={"candidate_path": str(candidate)},
            )
            continue
        logger.info(
            "quote_logo_debug_logo_file_found",
            extra={
                "candidate_path": str(candidate),
                "mime_type": safe_mime,
                "byte_length": candidate.stat().st_size,
            },
        )
        return f"data:{safe_mime};base64,{encoded}"

    logger.warning(
        "quote_logo_debug_no_local_file",
        extra={"raw_logo_url": raw_logo_url, "normalized": normalized},
    )
    return None


async def _render_quote_pdf_after_sale(
    repo: CRMRepository,
    organizacion_id: UUID,
    quote_id: UUID,
    oportunidad_id: UUID,
    usuario_id: UUID | None = None,
) -> None:
    try:
        quote_row = await repo.get_quote_entry(
            organizacion_id=organizacion_id,
            quote_id=quote_id,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "quote_entry_fetch_failed_after_sale",
            extra={
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote_id),
                "error": str(exc),
            },
        )
        return
    try:
        opportunity = await repo.get_opportunity_with_contact(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "opportunity_fetch_failed_for_pdf",
            extra={
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "quote_id": str(quote_id),
                "error": str(exc),
            },
        )
        return
    contact = opportunity.get("contacto") or {}
    vendor_context = await _resolve_quote_vendor_context(
        repo=repo,
        organizacion_id=organizacion_id,
        opportunity=opportunity,
    )
    quote_display_timezone = await _resolve_quote_display_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
    )
    logo_url = await _resolve_quote_logo_url(organizacion_id=organizacion_id)
    subtotal_value = _as_number(quote_row.get("subtotal"))
    impuestos_value = _as_number(quote_row.get("impuestos"))
    total_value = _as_number(quote_row.get("total"))
    items_list = quote_row.get("items") or []
    conceptos = _concepts_from_items(items_list if isinstance(items_list, list) else [])
    reference = str(oportunidad_id).split("-")[0]
    quote_context = quotes_service.QuoteRenderContext(
        lead_label=_clean_text(
            opportunity.get("titulo")
            or contact.get("company_name")
            or contact.get("nombre_completo")
        )
        or "Cotización",
        reference=reference,
        issuer_name=settings.mail_username or "Tal-IA",
        issuer_email=settings.mail_username,
        contact_name=_clean_text(contact.get("nombre_completo")),
        contact_company=_clean_text(contact.get("company_name")),
        contact_email=_clean_text(contact.get("correo")),
        contact_phone=_clean_text(contact.get("telefono_e164")),
        conceptos=conceptos,
        subtotal=subtotal_value,
        impuestos=impuestos_value,
        total=total_value,
        moneda=_clean_text(quote_row.get("moneda") or "MXN") or "MXN",
        valido_hasta=_parse_date(quote_row.get("valida_hasta")),
        items=items_list if isinstance(items_list, list) else [],
        organization_name=vendor_context["organization_name"],
        organization_slogan=vendor_context["organization_slogan"],
        organization_razon_social=vendor_context["organization_razon_social"],
        organization_rfc=vendor_context["organization_rfc"],
        organization_street=vendor_context["organization_street"],
        organization_exterior_number=vendor_context["organization_exterior_number"],
        organization_interior_number=vendor_context["organization_interior_number"],
        organization_colonia=vendor_context["organization_colonia"],
        organization_postal_code=vendor_context["organization_postal_code"],
        organization_state=vendor_context["organization_state"],
        organization_city=vendor_context["organization_city"],
        organization_country=vendor_context["organization_country"],
        organization_website=vendor_context["organization_website"],
        display_timezone=quote_display_timezone,
        vendor_company_name=vendor_context["vendor_company_name"],
        vendor_razon_social=vendor_context["vendor_razon_social"],
        vendor_assessor_name=vendor_context["vendor_assessor_name"],
        vendor_assessor_phone=vendor_context["vendor_assessor_phone"],
        vendor_assessor_email=vendor_context["vendor_assessor_email"],
        logo_url=logo_url,
    )
    try:
        pdf_doc = await quotes_service.render_quote_pdf(quote_context)
    except Exception as exc:  # pragma: no cover - best effort
        logger.warning(
            "quote_pdf_render_failed",
            extra={"quote_id": str(quote_id), "error": str(exc)},
        )
        return
    try:
        upload = await storage.upload_quote_document(
            content=pdf_doc.content,
            filename=pdf_doc.filename,
            lead_id=str(oportunidad_id),
        )
    except StorageError as exc:
        logger.warning(
            "quote_pdf_upload_failed",
            extra={"quote_id": str(quote_id), "error": str(exc)},
        )
        return
    metadata_patch = {
        "pdf_url": upload["url"],
        "pdf_path": upload["path"],
        "pdf_generated_en": datetime.now(timezone.utc).isoformat(),
    }
    if usuario_id:
        metadata_patch["pdf_generado_por"] = str(usuario_id)
    try:
        await repo.mark_quote_entry(
            organizacion_id=organizacion_id,
            quote_id=quote_id,
            metadata_patch=metadata_patch,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "quote_metadata_patch_failed",
            extra={
                "quote_id": str(quote_id),
                "organizacion_id": str(organizacion_id),
                "error": str(exc),
            },
        )


async def _mark_quote_as_accepted_from_mapbox(
    repo: CRMRepository,
    organizacion_id: UUID,
    quote_id: UUID,
    usuario_id: UUID | None = None,
) -> None:
    metadata_patch: dict[str, Any] = {
        "canal_envio": "mapbox",
        "marcada_en": datetime.now(timezone.utc).isoformat(),
    }
    if usuario_id:
        metadata_patch["marcada_por"] = str(usuario_id)
    try:
        quote_row = await repo.mark_quote_entry(
            organizacion_id=organizacion_id,
            quote_id=quote_id,
            estatus="aceptada",
            metadata_patch=metadata_patch,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "quote_mark_from_mapbox_failed",
            extra={
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote_id),
                "error": str(exc),
            },
        )
        return
    quote = _quote_from_row(quote_row)
    event_payload = {
        "organizacion_id": str(organizacion_id),
        "quote_id": str(quote_id),
        "oportunidad_id": str(quote.oportunidad_id) if quote.oportunidad_id else None,
        "canal_envio": metadata_patch["canal_envio"],
        "estatus": "aceptada",
    }
    if usuario_id:
        event_payload["usuario_id"] = str(usuario_id)
    sale_logger.info(
        "propiedad_quote_marked_from_mapbox",
        extra=event_payload,
    )
    _write_propiedad_sale_event("quote_marked_from_mapbox", event_payload)
    if quote.oportunidad_id:
        await _reject_previous_quotes_for_opportunity(
            repo=repo,
            organizacion_id=organizacion_id,
            oportunidad_id=UUID(str(quote.oportunidad_id)),
            keep_quote_id=quote_id,
            usuario_id=usuario_id,
        )
        await _auto_move_opportunity_to_won(
            repo=repo,
            organizacion_id=organizacion_id,
            oportunidad_id=UUID(str(quote.oportunidad_id)),
            quote=quote,
        )


async def _ensure_product_for_catalog_item(
    repo: CRMRepository,
    organizacion_id: UUID,
    catalog_item_id: UUID,
) -> dict[str, Any]:
    catalog_item = await repo.get_catalog_item(
        organizacion_id=organizacion_id,
        item_id=catalog_item_id,
    )
    if not catalog_item:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="catalog_item_not_found")
    product = await repo.get_product(
        organizacion_id=organizacion_id,
        product_id=catalog_item_id,
    )
    if product:
        return product
    metadata = _ensure_dict(
        catalog_item.get("metadatos") or catalog_item.get("metadata") or {},
        default={},
    )
    metadata["catalog_item_id"] = str(catalog_item_id)
    codigo = (catalog_item.get("slug") or catalog_item.get("nombre") or str(catalog_item_id)).strip()
    if not codigo:
        codigo = str(catalog_item_id)
    payload: dict[str, Any] = {
        "id": str(catalog_item_id),
        "codigo": codigo,
        "nombre": catalog_item.get("nombre") or "Producto inmobiliario",
        "descripcion": catalog_item.get("descripcion_corta")
        or catalog_item.get("descripcion_larga")
        or catalog_item.get("descripcion")
        or None,
        "precio_base": _coerce_optional_number(catalog_item.get("precio_base")),
        "moneda": (catalog_item.get("moneda") or "MXN").strip().upper()[:3],
        "activo": bool(catalog_item.get("activo") is not False),
        "metadata": metadata,
    }
    familia_id = catalog_item.get("familia_id")
    if isinstance(familia_id, str) and familia_id.strip():
        payload["familia_id"] = familia_id.strip()
    modelo_id = catalog_item.get("modelo_id")
    if isinstance(modelo_id, str) and modelo_id.strip():
        payload["modelo_id"] = modelo_id.strip()
    product = await repo.create_product(
        organizacion_id=organizacion_id,
        payload=payload,
    )
    return product


def _trigger_catalog_reindex(
    background_tasks: BackgroundTasks,
    organizacion_value: Any | None,
    *,
    usuario_id: UUID | None = None,
    canal: str | None = None,
) -> None:
    """Programa la reindexación completa en segundo plano."""
    if not organizacion_value:
        return
    try:
        organizacion_id = UUID(str(organizacion_value))
    except (TypeError, ValueError):
        logger.warning(
            "vector_store.reindex.invalid_organizacion_id",
            extra={"value": organizacion_value},
        )
        return
    background_tasks.add_task(
        _run_catalog_reindex,
        organizacion_id,
        usuario_id=str(usuario_id) if usuario_id else None,
        canal=canal,
    )


def _trigger_catalog_reindex_entity(
    background_tasks: BackgroundTasks,
    organizacion_value: Any | None,
    *,
    entity_type: Literal["linea", "familia", "modelo", "producto"],
    entity_id_value: Any | None,
    usuario_id: UUID | None = None,
    canal: str | None = None,
) -> None:
    if not organizacion_value or not entity_id_value:
        return
    try:
        organizacion_id = UUID(str(organizacion_value))
        entity_id = UUID(str(entity_id_value))
    except (TypeError, ValueError):
        logger.warning(
            "vector_store.reindex_entity.invalid_payload",
            extra={
                "organizacion_id": organizacion_value,
                "entity_type": entity_type,
                "entity_id": entity_id_value,
            },
        )
        return
    background_tasks.add_task(
        _run_catalog_reindex_entity,
        organizacion_id,
        entity_type=entity_type,
        entity_id=entity_id,
        usuario_id=str(usuario_id) if usuario_id else None,
        canal=canal,
    )


def _normalize_metadata_value(value: Any) -> dict[str, Any] | None:
    if isinstance(value, Mapping):
        return {str(key): val for key, val in value.items() if val is not None}
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return None
        if isinstance(parsed, Mapping):
            return {str(key): val for key, val in parsed.items() if val is not None}
    return None


def _coerce_optional_number(value: Any) -> float | None:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _extract_metadata_from_content(content: str) -> dict[str, Any] | None:
    if not content:
        return None
    marker = "Metadata:"
    index = content.find(marker)
    if index == -1:
        return None
    start = content.find("{", index + len(marker))
    if start == -1:
        return None
    depth = 0
    end = None
    for pos in range(start, len(content)):
        char = content[pos]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                end = pos + 1
                break
    if end is None:
        return None
    snippet = content[start:end]
    try:
        metadata = json.loads(snippet)
    except json.JSONDecodeError:
        return None
    if isinstance(metadata, Mapping):
        return {str(key): val for key, val in metadata.items() if val is not None}
    return None


async def _enrich_item_detail_with_unit_area(
    repo: CRMRepository,
    *,
    organizacion_id: UUID,
    item_data: Mapping[str, Any] | None,
    metadata: dict[str, Any],
) -> dict[str, Any]:
    merged = dict(metadata)
    unit_id = merged.get("unidad_id")
    if not unit_id and isinstance(item_data, Mapping):
        unit_id = item_data.get("unidad_id")
    if not unit_id:
        return merged
    try:
        unidad_row = await repo.get_propiedad_unidad(
            organizacion_id=organizacion_id,
            unidad_id=UUID(str(unit_id)),
        )
    except (CRMRepositoryError, ValueError) as exc:
        logger.warning(
            "catalog.item_details_unit_lookup_failed",
            extra={
                "organizacion_id": str(organizacion_id),
                "unidad_id": str(unit_id),
                "error": str(exc),
            },
        )
        return merged
    if not unidad_row:
        return merged

    area_m2 = unidad_row.get("area_m2")
    if area_m2 is not None:
        merged.setdefault("area_m2", area_m2)
        merged.setdefault("m2_de_terreno", area_m2)
    unidad_metadata = unidad_row.get("metadata")
    if isinstance(unidad_metadata, Mapping):
        for key, value in unidad_metadata.items():
            if value is None:
                continue
            merged.setdefault(f"unidad_metadata_{key}", value)
    return merged




def _map_delete_exception(
    exc: CRMRepositoryError,
    *,
    not_found_key: str,
    dependency_key: str,
    dependency_message: str,
) -> tuple[str, int]:
    text = str(exc)
    if dependency_key in text:
        return dependency_message, status.HTTP_409_CONFLICT
    if not_found_key in text:
        return not_found_key, status.HTTP_404_NOT_FOUND
    return text, status.HTTP_502_BAD_GATEWAY


def _extract_demo_booking_id(metadata: dict[str, Any]) -> str | None:
    """Obtiene el booking_id registrado en metadata.stage_prep.demo."""
    stage_prep = _ensure_dict(metadata.get("stage_prep"), default={})
    raw_demo = stage_prep.get("demo")
    if not isinstance(raw_demo, dict):
        return None
    booking_value = raw_demo.get("demo_booking_id")
    if isinstance(booking_value, str):
        trimmed = booking_value.strip()
        return trimmed or None
    return None


def _display_name_from_user_like(value: Any) -> str | None:
    if not isinstance(value, dict):
        return None
    for key in ("nombre_completo", "nombre", "correo"):
        candidate = str(value.get(key) or "").strip()
        if candidate:
            return candidate
    return None


class CRMAccount(BaseModel):
    """Representación pública de una cuenta."""

    id: UUID
    organizacion_id: UUID
    nombre: str
    alias: str | None = None
    tipo: str | None = None
    estado: str | None = None
    industria: str | None = None
    tamano: str | None = Field(default=None, alias="tamano")
    sitio_web: str | None = None
    telefono: str | None = None
    correo: str | None = None
    correo_principal: str | None = None
    correo_secundario: str | None = None
    telefono_principal_e164: str | None = None
    telefono_principal_tipo_linea: str | None = None
    telefono_principal_extension: str | None = None
    telefono_secundario_e164: str | None = None
