class GoogleProspeccionBusquedaPayload(BaseModel):
    """Parámetros para lanzar una captura desde Google Places."""

    query: str | None = Field(
        default=None,
        max_length=200,
        description="Texto de búsqueda libre (obligatorio en estrategia text).",
    )
    lat: float = Field(..., description="Latitud del centro de búsqueda.")
    lng: float = Field(..., description="Longitud del centro de búsqueda.")
    radio_m: int = Field(
        default=1000,
        ge=50,
        le=50000,
        description="Radio en metros para limitar la búsqueda.",
    )
    included_types: list[str] | None = Field(
        default=None,
        description="Clasificaciones soportadas por Google Places (obligatorias en estrategia nearby).",
    )
    strategy: Literal["nearby", "text"] = Field(
        default="nearby",
        description="Define si se usa searchNearby (por tipo) o searchText (por texto).",
    )
    language_code: str | None = Field(
        default=None,
        min_length=2,
        max_length=10,
        description="Sobrescribe el código de idioma enviado a Google Places.",
    )
    region_code: str | None = Field(
        default=None,
        min_length=2,
        max_length=10,
        description="Sobrescribe el código de región enviado a Google Places.",
    )
    meta: dict[str, Any] | None = Field(
        default=None,
        description="Metadatos adicionales para guardar en public.busquedas.meta.",
    )
    dense_mode: bool = Field(
        default=False,
        description="Activa el modo denso para cubrir zonas amplias sin límite de resultados.",
    )

    model_config = ConfigDict(extra="ignore")

    @field_validator("included_types")
    @classmethod
    def _validate_types(cls, value: list[str] | None) -> list[str] | None:
        if value is None:
            return None
        cleaned = [part.strip() for part in value if part and part.strip()]
        return cleaned or None

    @field_validator("query")
    @classmethod
    def _strip_query(cls, value: str | None) -> str | None:
        if value is None:
            return None
        trimmed = value.strip()
        return trimmed or None

    @model_validator(mode="after")
    def validate_strategy(self) -> GoogleProspeccionBusquedaPayload:
        if self.strategy == "nearby" and not self.included_types:
            raise ValueError("included_types_required")
        if self.strategy == "text":
            query = (self.query or "").strip()
            if not query:
                raise ValueError("query_required")
            self.query = query
        return self


class GoogleTrendsPayload(BaseModel):
    """Parámetros de consulta para Google Trends."""

    model_config = ConfigDict(extra="forbid")

    keywords: list[str] = Field(
        default_factory=lambda: [
            "IA de WhatsApp",
            "IA para WhatsApp",
            "IA para ventas",
            "asistente de IA",
            "CRM IA",
        ],
        min_length=1,
        max_length=5,
    )
    timeframe: str = Field(default="today 12-m", min_length=3, max_length=32)
    geo: str = Field(default="MX", max_length=10)
    source: Literal["", "images", "news", "froogle", "youtube"] = Field(default="")
    hl: str = Field(default="es-MX", min_length=2, max_length=10)
    tz: int = Field(default=360, ge=-720, le=840)
    include_region: bool = Field(default=True)
    region_resolution: Literal["COUNTRY", "REGION", "SUBREGION", "DMA", "CITY"] = Field(default="REGION")
    inc_low_vol: bool = Field(default=False)
    inc_geo_code: bool = Field(default=False)
    min_sleep: float = Field(default=1.5, ge=0, le=10)
    max_sleep: float = Field(default=3.0, ge=0, le=20)

    @field_validator("keywords")
    @classmethod
    def _normalize_keywords(cls, value: list[str]) -> list[str]:
        cleaned: list[str] = []
        seen: set[str] = set()
        for raw in value:
            normalized = str(raw or "").strip()
            if not normalized:
                continue
            key = normalized.casefold()
            if key in seen:
                continue
            seen.add(key)
            cleaned.append(normalized[:100])
        if not cleaned:
            raise ValueError("keywords_required")
        if len(cleaned) > 5:
            raise ValueError("keywords_limit_exceeded")
        return cleaned

    @model_validator(mode="after")
    def _validate_sleep_bounds(self) -> "GoogleTrendsPayload":
        if self.max_sleep and self.max_sleep < self.min_sleep:
            self.min_sleep, self.max_sleep = self.max_sleep, self.min_sleep
        return self


