def _persona_alta_clean_text(value: str | None, *, compact_spaces: bool = False) -> str | None:
    if value is None:
        return None
    trimmed = str(value).strip()
    if compact_spaces:
        trimmed = " ".join(trimmed.split())
    return trimmed or None


_PERSONA_ESTADO_VALIDOS = {"lead", "activo", "inactivo", "bloqueado", "fusionado"}
_PERSONA_ESTADO_ALIAS = {
    "nuevo": "lead",
    "nueva": "lead",
    "prospecto": "lead",
    "prospecta": "lead",
    "lead": "lead",
    "activo": "activo",
    "activa": "activo",
    "cliente": "activo",
    "cliente_activo": "activo",
    "inactivo": "inactivo",
    "inactiva": "inactivo",
    "bloqueado": "bloqueado",
    "bloqueada": "bloqueado",
    "fusionado": "fusionado",
    "fusionada": "fusionado",
}


def _persona_alta_normalize_estado(value: str | None) -> str:
    cleaned = _persona_alta_clean_text(value, compact_spaces=True)
    if not cleaned:
        return "lead"
    normalized = unicodedata.normalize("NFKD", cleaned).encode("ascii", "ignore").decode("ascii")
    normalized = normalized.replace("-", "_").replace(" ", "_").casefold()
    if normalized in _PERSONA_ESTADO_ALIAS:
        return _PERSONA_ESTADO_ALIAS[normalized]
    if normalized in _PERSONA_ESTADO_VALIDOS:
        return normalized
    return "lead"


def _persona_alta_normalize_email(value: str | None) -> str | None:
    cleaned = _persona_alta_clean_text(value)
    return cleaned.lower() if cleaned else None


def _normalize_rfc_text(value: str | None) -> str | None:
    cleaned = _persona_alta_clean_text(value, compact_spaces=True)
    if not cleaned:
        return None
    normalized = re.sub(r"[^0-9A-Za-z]+", "", cleaned).upper()
    return normalized or None


def _expected_rfc_length_for_account_type(account_type: str | None) -> int | None:
    normalized = _persona_alta_clean_text(account_type, compact_spaces=True)
    if not normalized:
        return None
    normalized = normalized.casefold()
    if normalized in {"persona_fisica_actividad_empresarial", "pfae", "fisica"}:
        return 13
    if normalized in {"empresa", "empresa_nueva", "moral"}:
        return 12
    return None


def _validate_rfc_length_for_account_type(rfc: str | None, account_type: str | None) -> str | None:
    normalized = _normalize_rfc_text(rfc)
    if not normalized:
        return None
    expected = _expected_rfc_length_for_account_type(account_type)
    if expected is not None and len(normalized) != expected:
        raise ValueError(
            "rfc_must_be_12_chars_for_company" if expected == 12 else "rfc_must_be_13_chars_for_physical_person"
        )
    if expected is None and len(normalized) not in {12, 13}:
        raise ValueError("rfc_must_be_12_or_13_alphanumeric_chars")
    return normalized


def _rfc_length_error_message(expected: int | None) -> str:
    if expected == 13:
        return "Personas Físicas: Consta de 13 caracteres"
    if expected == 12:
        return "Personas Morales (Empresas): Consta de 12 caracteres"
    return "El RFC debe tener 12 o 13 caracteres alfanuméricos."


def _expected_rfc_length_for_persona_alta(
    contexto: "CRMPersonaAltaContexto",
    cuenta: "CRMPersonaAltaCuenta | None" = None,
    existing_account: "CRMAccount | None" = None,
) -> int | None:
    if contexto.modo == "persona_fisica_actividad_empresarial":
        return 13
    if contexto.modo in {"empresa_nueva", "empresa_existente"}:
        account_type = None
        if existing_account and existing_account.tipo:
            account_type = existing_account.tipo
        elif cuenta:
            account_type = cuenta.tipo or cuenta.tipo_cuenta
            if not account_type and cuenta.tipo_persona == "moral":
                account_type = "empresa"
        expected = _expected_rfc_length_for_account_type(account_type)
        if expected is not None:
            return expected
        return 12
    return None


def _validate_persona_alta_rfc_length(
    *,
    contexto: "CRMPersonaAltaContexto",
    rfc: str | None,
    cuenta: "CRMPersonaAltaCuenta | None" = None,
    existing_account: "CRMAccount | None" = None,
) -> str | None:
    normalized = _normalize_rfc_text(rfc)
    if not normalized:
        return None
    expected = _expected_rfc_length_for_persona_alta(
        contexto,
        cuenta=cuenta,
        existing_account=existing_account,
    )
    if expected is not None:
        if len(normalized) != expected:
            raise HTTPException(status_code=400, detail=_rfc_length_error_message(expected))
        return normalized
    if len(normalized) not in {12, 13}:
        raise HTTPException(status_code=400, detail=_rfc_length_error_message(None))
    return normalized


def _persona_alta_normalize_phone(value: str | None) -> str | None:
    cleaned = _persona_alta_clean_text(value)
    if not cleaned:
        return None
    return normalize_phone(cleaned) or cleaned


def _persona_alta_normalize_phone_line_type(value: str | None) -> str | None:
    cleaned = _persona_alta_clean_text(value, compact_spaces=True)
    if not cleaned:
        return None
    normalized = unicodedata.normalize("NFKD", cleaned).encode("ascii", "ignore").decode("ascii")
    normalized = normalized.replace("-", "_").replace(" ", "_").casefold()
    if normalized in {"fijo", "fija", "landline", "fixed", "linea_fija", "linea_fijo"}:
        return "fijo"
    if normalized in {"movil", "movil", "mobile", "celular", "cell", "linea_movil"}:
        return "movil"
    return normalized


def _persona_alta_first_text(*values: str | None) -> str | None:
    for value in values:
        cleaned = _persona_alta_clean_text(value)
        if cleaned:
            return cleaned
    return None


def _persona_alta_normalize_persona(payload: CRMPersonaAltaPersona) -> CRMPersonaAltaPersona:
    return payload.model_copy(
        update={
            "codigo_contacto": _persona_alta_clean_text(payload.codigo_contacto, compact_spaces=True),
            "nombre": _persona_alta_clean_text(payload.nombre, compact_spaces=True),
            "apellido_paterno": _persona_alta_clean_text(payload.apellido_paterno, compact_spaces=True),
            "apellido_materno": _persona_alta_clean_text(payload.apellido_materno, compact_spaces=True),
            "nombre_completo": _persona_alta_clean_text(payload.nombre_completo, compact_spaces=True),
            "correo_principal": _persona_alta_normalize_email(payload.correo_principal)
            or _persona_alta_normalize_email(getattr(payload, "correo", None))
            or _persona_alta_normalize_email(getattr(payload, "email", None)),
            "correo_institucional": _persona_alta_normalize_email(payload.correo_institucional),
            "correo_personal_3": _persona_alta_normalize_email(payload.correo_personal_3),
            "telefono_principal_e164": _persona_alta_normalize_phone(payload.telefono_principal_e164)
            or _persona_alta_normalize_phone(payload.telefono_movil_1_e164),
            "telefono_principal_tipo_linea": _persona_alta_normalize_phone_line_type(payload.telefono_principal_tipo_linea)
            or _persona_alta_normalize_phone_line_type(payload.telefono_movil_1_tipo_linea),
            "telefono_principal_extension": _persona_alta_clean_text(payload.telefono_principal_extension),
            "telefono_movil_1_e164": _persona_alta_normalize_phone(payload.telefono_movil_1_e164)
            or _persona_alta_normalize_phone(payload.telefono_principal_e164),
            "telefono_movil_1_tipo_linea": _persona_alta_normalize_phone_line_type(payload.telefono_movil_1_tipo_linea)
            or _persona_alta_normalize_phone_line_type(payload.telefono_principal_tipo_linea),
            "telefono_movil_2_e164": _persona_alta_normalize_phone(payload.telefono_movil_2_e164)
            or _persona_alta_normalize_phone(payload.telefono_secundario_e164),
            "telefono_movil_2_tipo_linea": _persona_alta_normalize_phone_line_type(payload.telefono_movil_2_tipo_linea)
            or _persona_alta_normalize_phone_line_type(payload.telefono_secundario_tipo_linea),
            "telefono_movil_2_extension": _persona_alta_clean_text(payload.telefono_movil_2_extension)
            or _persona_alta_clean_text(payload.telefono_secundario_extension),
            "telefono_secundario_e164": _persona_alta_normalize_phone(payload.telefono_secundario_e164)
            or _persona_alta_normalize_phone(payload.telefono_movil_2_e164),
            "telefono_secundario_tipo_linea": _persona_alta_normalize_phone_line_type(payload.telefono_secundario_tipo_linea)
            or _persona_alta_normalize_phone_line_type(payload.telefono_movil_2_tipo_linea),
            "telefono_secundario_extension": _persona_alta_clean_text(payload.telefono_secundario_extension)
            or _persona_alta_clean_text(payload.telefono_movil_2_extension),
            "telefono_empresa_1_e164": _persona_alta_normalize_phone(payload.telefono_empresa_1_e164),
            "telefono_empresa_1_extension": _persona_alta_clean_text(payload.telefono_empresa_1_extension),
            "telefono_empresa_2_e164": _persona_alta_normalize_phone(payload.telefono_empresa_2_e164),
            "telefono_empresa_2_extension": _persona_alta_clean_text(payload.telefono_empresa_2_extension),
            "puesto": _persona_alta_clean_text(payload.puesto, compact_spaces=True),
            "area": _persona_alta_clean_text(payload.area, compact_spaces=True),
            "rol_decision": _persona_alta_clean_text(payload.rol_decision, compact_spaces=True),
            "estado": _persona_alta_normalize_estado(payload.estado),
            "origen": _persona_alta_clean_text(payload.origen),
            "notas": _persona_alta_clean_text(payload.notas),
        }
    )


def _persona_alta_normalize_cuenta(payload: CRMPersonaAltaCuenta | None) -> CRMPersonaAltaCuenta | None:
    if payload is None:
        return None
    return payload.model_copy(
        update={
            "nombre_comercial": _persona_alta_clean_text(payload.nombre_comercial, compact_spaces=True),
            "razon_social": _persona_alta_clean_text(payload.razon_social, compact_spaces=True),
            "alias": _persona_alta_clean_text(payload.alias, compact_spaces=True),
            "tipo_cuenta": _persona_alta_clean_text(payload.tipo_cuenta),
            "tipo": _persona_alta_clean_text(payload.tipo),
            "codigo_cuenta": _persona_alta_clean_text(payload.codigo_cuenta, compact_spaces=True),
            "rfc": _persona_alta_clean_text(payload.rfc, compact_spaces=True),
            "industria": _persona_alta_clean_text(payload.industria, compact_spaces=True),
            "segmento": _persona_alta_clean_text(payload.segmento, compact_spaces=True),
            "tamano": _persona_alta_clean_text(payload.tamano, compact_spaces=True),
            "sitio_web": _persona_alta_clean_text(payload.sitio_web),
            "correo_principal": _persona_alta_normalize_email(payload.correo_principal)
            or _persona_alta_normalize_email(payload.correo)
            or _persona_alta_normalize_email(getattr(payload, "email", None)),
            "correo_secundario": _persona_alta_normalize_email(payload.correo_secundario),
            "telefono_principal": _persona_alta_normalize_phone(payload.telefono_principal)
            or _persona_alta_normalize_phone(payload.telefono_principal_e164)
            or _persona_alta_normalize_phone(payload.telefono),
            "telefono_principal_e164": _persona_alta_normalize_phone(payload.telefono_principal_e164)
            or _persona_alta_normalize_phone(payload.telefono_principal)
            or _persona_alta_normalize_phone(payload.telefono),
            "telefono_principal_tipo_linea": _persona_alta_normalize_phone_line_type(payload.telefono_principal_tipo_linea),
            "telefono_principal_extension": _persona_alta_clean_text(payload.telefono_principal_extension),
            "telefono_secundario_e164": _persona_alta_normalize_phone(payload.telefono_secundario_e164),
            "telefono_secundario_tipo_linea": _persona_alta_normalize_phone_line_type(payload.telefono_secundario_tipo_linea),
            "telefono_secundario_extension": _persona_alta_clean_text(payload.telefono_secundario_extension),
            "correo": _persona_alta_normalize_email(payload.correo)
            or _persona_alta_normalize_email(payload.correo_principal),
            "telefono": _persona_alta_normalize_phone(payload.telefono)
            or _persona_alta_normalize_phone(payload.telefono_principal_e164)
            or _persona_alta_normalize_phone(payload.telefono_principal),
            "notas": _persona_alta_clean_text(payload.notas),
            "necesidad_proposito": _persona_alta_clean_text(payload.necesidad_proposito),
            "tipo_establecimiento": _persona_alta_clean_text(payload.tipo_establecimiento, compact_spaces=True),
        }
    )


def _persona_alta_normalize_extras(payload: CRMPersonaAltaExtras | None) -> CRMPersonaAltaExtras | None:
    if payload is None:
        return None
    fiscales = payload.fiscales
    direccion = payload.direccion
    fiscales_norm = (
        fiscales.model_copy(
            update={
                "regimen_capital": _persona_alta_clean_text(fiscales.regimen_capital),
                "uso_cfdi": _persona_alta_clean_text(fiscales.uso_cfdi),
                "forma_pago": _persona_alta_clean_text(fiscales.forma_pago),
                "metodo_pago": _persona_alta_clean_text(fiscales.metodo_pago),
                "email_facturacion": _persona_alta_normalize_email(fiscales.email_facturacion),
            }
        )
        if fiscales
        else None
    )
    direccion_norm = (
        direccion.model_copy(
            update={
                "pais": _persona_alta_clean_text(direccion.pais, compact_spaces=True),
                "tipo": _persona_alta_clean_text(direccion.tipo, compact_spaces=True),
                "clave_entidad": _persona_alta_clean_text(direccion.clave_entidad, compact_spaces=True),
                "entidad": _persona_alta_clean_text(direccion.entidad, compact_spaces=True),
                "clave_municipio": _persona_alta_clean_text(direccion.clave_municipio, compact_spaces=True),
                "municipio": _persona_alta_clean_text(direccion.municipio, compact_spaces=True),
                "clave_localidad": _persona_alta_clean_text(direccion.clave_localidad, compact_spaces=True),
                "localidad": _persona_alta_clean_text(direccion.localidad, compact_spaces=True),
                "tipo_vialidad": _persona_alta_clean_text(direccion.tipo_vialidad, compact_spaces=True),
                "nombre_vialidad": _persona_alta_clean_text(direccion.nombre_vialidad, compact_spaces=True),
                "numero_exterior": _persona_alta_clean_text(direccion.numero_exterior, compact_spaces=True),
                "letra_exterior": _persona_alta_clean_text(direccion.letra_exterior, compact_spaces=True),
                "edificio": _persona_alta_clean_text(direccion.edificio, compact_spaces=True),
                "edificio_piso": _persona_alta_clean_text(direccion.edificio_piso, compact_spaces=True),
                "numero_interior": _persona_alta_clean_text(direccion.numero_interior, compact_spaces=True),
                "letra_interior": _persona_alta_clean_text(direccion.letra_interior, compact_spaces=True),
                "tipo_asentamiento": _persona_alta_clean_text(direccion.tipo_asentamiento, compact_spaces=True),
                "colonia": _persona_alta_clean_text(direccion.colonia, compact_spaces=True),
                "tipo_centro_comercial": _persona_alta_clean_text(direccion.tipo_centro_comercial, compact_spaces=True),
                "corredor_industrial": _persona_alta_clean_text(direccion.corredor_industrial, compact_spaces=True),
                "numero_local": _persona_alta_clean_text(direccion.numero_local, compact_spaces=True),
                "codigo_postal": _persona_alta_clean_text(direccion.codigo_postal, compact_spaces=True),
                "latitud": direccion.latitud,
                "longitud": direccion.longitud,
            }
        )
        if direccion
        else None
    )
    return payload.model_copy(update={"fiscales": fiscales_norm, "direccion": direccion_norm})


def _persona_alta_match_key(value: str | None) -> str:
    text = _persona_alta_clean_text(value, compact_spaces=True)
    if not text:
        return ""
    normalized = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")
    return normalized.lower()


def _persona_alta_match_rfc(value: str | None) -> str:
    text = _persona_alta_clean_text(value, compact_spaces=True)
    if not text:
        return ""
    return re.sub(r"\s+", "", text).upper()


def _persona_alta_match_name(value: str | None) -> str:
    text = _persona_alta_clean_text(value, compact_spaces=True)
    if not text:
        return ""
    normalized = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")
    lowered = normalized.lower()
    lowered = re.sub(r"[^a-z0-9 ]+", " ", lowered)
    return " ".join(lowered.split())


def _dedupe_level_rank(level: str) -> int:
    if level == "fuerte":
        return 3
    if level == "medio":
        return 2
    return 1


def _dedupe_tipo_registro_label(value: str | None) -> str:
    normalized = _persona_alta_clean_text(value, compact_spaces=True)
    if not normalized:
        return "Contacto"
    lowered = normalized.casefold()
    if lowered in {"empresa", "empresa_nueva"}:
        return "Empresa"
    if lowered in {"persona_fisica_actividad_empresarial", "pfae"}:
        return "Empresa propia"
    if lowered in {"contacto"}:
        return "Contacto"
    return normalized


async def _attach_dedupe_owner_names(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    candidates: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    owner_ids: list[UUID] = []
    seen: set[str] = set()
    for candidate in candidates:
        owner_id = _safe_uuid(candidate.get("propietario_usuario_id"))
        if not owner_id:
            continue
        owner_key = str(owner_id)
        if owner_key in seen:
            continue
        seen.add(owner_key)
        owner_ids.append(owner_id)
    owner_map: dict[str, str] = {}
    if owner_ids:
        try:
            users = await repo.list_users_by_ids(organizacion_id=organizacion_id, user_ids=owner_ids)
        except CRMRepositoryError:
            users = []
        for user in users:
            if not isinstance(user, dict):
                continue
            user_id = str(user.get("id") or "").strip()
            if not user_id:
                continue
            owner_map[user_id] = str(user.get("nombre_completo") or user.get("correo") or "").strip()
    for candidate in candidates:
        owner_id = _safe_uuid(candidate.get("propietario_usuario_id"))
        if owner_id:
            candidate["propietario_nombre"] = owner_map.get(str(owner_id)) or candidate.get("propietario_nombre")
        candidate["tipo_registro"] = _dedupe_tipo_registro_label(str(candidate.get("tipo_registro") or ""))
        record_type = str(candidate.get("tipo_registro") or "").strip().lower()
        candidate_id = _safe_uuid(candidate.get("id"))
        if candidate_id:
            if record_type in {"contacto", "persona"} and not str(candidate.get("codigo_contacto") or "").strip():
                try:
                    persona_row = await repo.get_persona_by_id(persona_id=str(candidate_id))
                except CRMRepositoryError:
                    persona_row = None
                if isinstance(persona_row, dict):
                    candidate["codigo_contacto"] = (
                        str(persona_row.get("codigo_contacto") or persona_row.get("legacy_contacto_codigo") or "").strip() or None
                    )
            if record_type in {"empresa", "empresa_propia"} and not str(candidate.get("codigo_cuenta") or "").strip():
                try:
                    account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=candidate_id)
                except CRMRepositoryError:
                    account_row = None
                if isinstance(account_row, dict):
                    candidate["codigo_cuenta"] = (
                        str(account_row.get("codigo_cuenta") or account_row.get("codigo") or "").strip() or None
                    )
    return candidates


def _merge_dedupe_candidates(
    current: list[dict[str, Any]],
    candidate: dict[str, Any],
) -> list[dict[str, Any]]:
    candidate_id = str(candidate.get("id") or "").strip()
    if not candidate_id:
        return current
    found_index = -1
    for index, item in enumerate(current):
        if str(item.get("id") or "").strip() == candidate_id:
            found_index = index
            break
    if found_index == -1:
        current.append(candidate)
        return current
    existing = current[found_index]
    existing_level = str(existing.get("nivel") or "debil")
    candidate_level = str(candidate.get("nivel") or "debil")
    if _dedupe_level_rank(candidate_level) > _dedupe_level_rank(existing_level):
        current[found_index] = candidate
    return current


def _is_active_dedupe_row(row: Mapping[str, Any]) -> bool:
    archived_at = row.get("archived_at")
    merged_persona = row.get("merged_into_persona_id")
    merged_cuenta = row.get("merged_into_cuenta_id")
    estado = str(row.get("estado") or "").strip().lower()
    return archived_at is None and merged_persona is None and merged_cuenta is None and estado != "fusionado"


def _account_duplicate_match_payload(account: Mapping[str, Any]) -> tuple[set[str], set[str], str | None]:
    email_keys = {
        _persona_alta_normalize_email(account.get("correo_principal")),
        _persona_alta_normalize_email(account.get("correo_secundario")),
        _persona_alta_normalize_email(account.get("correo")),
        _persona_alta_normalize_email(account.get("email")),
    }
    phone_keys = {
        _persona_alta_normalize_phone(account.get("telefono_principal_e164")),
        _persona_alta_normalize_phone(account.get("telefono_secundario_e164")),
        _persona_alta_normalize_phone(account.get("telefono")),
    }
    email_keys = {value for value in email_keys if value}
    phone_keys = {value for value in phone_keys if value}
    rfc_key = _normalize_rfc_text(account.get("rfc"))
    return email_keys, phone_keys, rfc_key


def _account_duplicate_candidate_row(
    row: Mapping[str, Any],
    *,
    reason: str,
    match_field: str,
) -> dict[str, Any]:
    return {
        "id": str(row.get("id") or ""),
        "codigo_cuenta": row.get("codigo_cuenta"),
        "nombre": row.get("nombre"),
        "alias": row.get("alias"),
        "rfc": row.get("rfc"),
        "correo": row.get("correo_principal") or row.get("correo"),
        "telefono": row.get("telefono_principal_e164") or row.get("telefono"),
        "tipo_registro": "empresa_propia" if str(row.get("tipo") or "") == "persona_fisica_actividad_empresarial" else "empresa",
        "coincidencia_en": match_field or reason,
        "propietario_usuario_id": row.get("propietario_usuario_id"),
        "nivel": "fuerte",
        "motivo": reason,
    }


async def _find_account_duplicate_candidates(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    account_like: Mapping[str, Any],
    exclude_account_id: UUID | None = None,
) -> tuple[list[dict[str, Any]], UUID | None]:
    email_keys, phone_keys, rfc_key = _account_duplicate_match_payload(account_like)
    if not email_keys and not phone_keys and not rfc_key:
        return [], None

    candidates: list[dict[str, Any]] = []
    selected: UUID | None = None
    offset = 0
    page_size = 200
    while True:
        try:
            rows = await repo.list_accounts(organizacion_id=organizacion_id, limit=page_size, offset=offset)
        except CRMRepositoryError:
            return [], None
        if not rows:
            break
        for row in rows:
            if not isinstance(row, dict) or not _is_active_dedupe_row(row):
                continue
            row_id = _safe_uuid(row.get("id"))
            if exclude_account_id and row_id == exclude_account_id:
                continue
            row_rfc = _normalize_rfc_text(row.get("rfc"))
            row_email_keys, row_phone_keys, _ = _account_duplicate_match_payload(row)
            reason = ""
            match_field = ""
            if rfc_key and row_rfc and row_rfc == rfc_key:
                reason = "rfc"
                match_field = "rfc"
            elif email_keys and row_email_keys.intersection(email_keys):
                reason = "correo"
                match_field = "correo"
            elif phone_keys and row_phone_keys.intersection(phone_keys):
                reason = "telefono"
                match_field = "telefono"
            if not reason or not row_id:
                continue
            candidates = _merge_dedupe_candidates(
                candidates,
                _account_duplicate_candidate_row(row, reason=reason, match_field=match_field),
            )
            if selected is None:
                selected = row_id
        if len(rows) < page_size or offset >= 2000:
            break
        offset += page_size

    candidates.sort(key=lambda item: _dedupe_level_rank(str(item.get("nivel") or "debil")), reverse=True)
    candidates = await _attach_dedupe_owner_names(
        repo=repo,
        organizacion_id=organizacion_id,
        candidates=candidates[:10],
    )
    return candidates, selected


async def _persona_alta_find_existing_account(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    cuenta: CRMPersonaAltaCuenta | None,
    exclude_account_id: UUID | None = None,
) -> tuple[CRMAccount | None, list[dict[str, Any]]]:
    if not cuenta:
        return None, []
    email_keys, phone_keys, rfc_key = _account_duplicate_match_payload(cuenta.model_dump(mode="python", exclude_none=True))
    if not rfc_key and not email_keys and not phone_keys:
        return None, []
    accounts: list[CRMAccount] = []
    offset = 0
    page_size = 200
    while True:
        try:
            rows = await repo.list_accounts(organizacion_id=organizacion_id, limit=page_size, offset=offset)
        except CRMRepositoryError:
            return None, []
        batch = [CRMAccount.model_validate(row) for row in rows]
        accounts.extend(batch)
        if len(batch) < page_size or offset >= 2000:
            break
        offset += page_size
    candidates: list[dict[str, Any]] = []
    selected: CRMAccount | None = None
    selected_level = "debil"
    for account in accounts:
        if exclude_account_id and account.id == exclude_account_id:
            continue
        if not _is_active_dedupe_row(account.model_dump(mode="python", exclude_none=True)):
            continue
        level = ""
        reason = ""
        match_field = ""
        account_email_keys = {
            _persona_alta_normalize_email(account.correo_principal),
            _persona_alta_normalize_email(account.correo_secundario),
            _persona_alta_normalize_email(account.correo),
            _persona_alta_normalize_email(account.email),
        }
        account_phone_keys = {
            _persona_alta_normalize_phone(account.telefono_principal_e164),
            _persona_alta_normalize_phone(account.telefono),
            _persona_alta_normalize_phone(account.telefono_secundario_e164),
        }
        account_email_keys = {value for value in account_email_keys if value}
        account_phone_keys = {value for value in account_phone_keys if value}
        if rfc_key and _persona_alta_match_rfc(account.rfc) == rfc_key:
            level = "fuerte"
            reason = "rfc"
            match_field = "rfc"
        elif email_keys and account_email_keys.intersection(email_keys):
            level = "fuerte"
            reason = "correo"
            match_field = "correo"
        elif phone_keys and account_phone_keys.intersection(phone_keys):
            level = "fuerte"
            reason = "telefono"
            match_field = "telefono"
        if not level:
            continue
        candidates = _merge_dedupe_candidates(
            candidates,
            {
                "id": str(account.id),
                "codigo_cuenta": account.codigo_cuenta,
                "nombre": account.nombre,
                "alias": account.alias,
                "rfc": account.rfc,
                "correo": account.correo_principal or account.correo,
                "telefono": account.telefono_principal_e164 or account.telefono,
                "tipo_registro": "empresa_propia" if account.tipo == "persona_fisica_actividad_empresarial" else "empresa",
                "coincidencia_en": match_field or reason,
                "propietario_usuario_id": account.propietario_usuario_id,
                "nivel": level,
                "motivo": reason,
            },
        )
        if selected is None or _dedupe_level_rank(level) > _dedupe_level_rank(selected_level):
            selected = account
            selected_level = level
    # Auto-reuso solo en fuerte. Medio/debil quedan para confirmación explícita en UI.
    if selected and selected_level == "fuerte":
        enriched = await _attach_dedupe_owner_names(
            repo=repo,
            organizacion_id=organizacion_id,
            candidates=candidates[:10],
        )
        return selected, enriched
    enriched = await _attach_dedupe_owner_names(
        repo=repo,
        organizacion_id=organizacion_id,
        candidates=candidates[:10],
    )
    return None, enriched


async def _persona_alta_find_persona_candidates(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    persona: CRMPersonaAltaPersona,
    cuenta: CRMPersonaAltaCuenta | None,
    exclude_contacto_id: UUID | None = None,
) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    telefono_keys = {
        _persona_alta_normalize_phone(persona.telefono_principal_e164),
        _persona_alta_normalize_phone(persona.telefono_movil_1_e164),
        _persona_alta_normalize_phone(persona.telefono_movil_2_e164),
        _persona_alta_normalize_phone(persona.telefono_secundario_e164),
        _persona_alta_normalize_phone(persona.telefono_empresa_1_e164),
        _persona_alta_normalize_phone(persona.telefono_empresa_2_e164),
    }
    correo_keys = {
        _persona_alta_normalize_email(persona.correo_principal),
        _persona_alta_normalize_email(persona.correo_secundario),
        _persona_alta_normalize_email(persona.correo_institucional),
        _persona_alta_normalize_email(persona.correo_personal_3),
    }
    telefono_keys = {value for value in telefono_keys if value}
    correo_keys = {value for value in correo_keys if value}

    for telefono_key in telefono_keys:
        try:
            by_phone = await repo.get_persona_by_phone_e164(
                phone_e164=telefono_key,
                organizacion_id=organizacion_id,
            )
        except CRMRepositoryError:
            by_phone = None
        if by_phone and exclude_contacto_id and _safe_uuid(by_phone.get("id")) == exclude_contacto_id:
            by_phone = None
        if by_phone:
            candidates = _merge_dedupe_candidates(
                candidates,
                {
                    "id": str(by_phone.get("id")),
                    "codigo_contacto": by_phone.get("codigo_contacto") or by_phone.get("legacy_contacto_codigo"),
                    "nombre": by_phone.get("nombre_completo"),
                    "correo": by_phone.get("correo"),
                    "telefono": by_phone.get("telefono_e164"),
                    "empresa": by_phone.get("company_name"),
                    "propietario_usuario_id": by_phone.get("propietario_usuario_id"),
                    "tipo_registro": "contacto",
                    "coincidencia_en": "telefono",
                    "correo_institucional": by_phone.get("correo_secundario") or by_phone.get("correo_institucional"),
                    "telefono_movil_1_e164": by_phone.get("telefono_movil_1_e164"),
                    "nivel": "fuerte",
                    "motivo": "telefono",
                },
            )
    for correo_key in correo_keys:
        try:
            by_email = await repo.get_persona_by_email(
                email=correo_key,
                organizacion_id=organizacion_id,
            )
        except CRMRepositoryError:
            by_email = None
        if by_email and exclude_contacto_id and _safe_uuid(by_email.get("id")) == exclude_contacto_id:
            by_email = None
        if by_email:
            candidates = _merge_dedupe_candidates(
                candidates,
                {
                    "id": str(by_email.get("id")),
                    "codigo_contacto": by_email.get("codigo_contacto") or by_email.get("legacy_contacto_codigo"),
                    "nombre": by_email.get("nombre_completo"),
                    "correo": by_email.get("correo"),
                    "telefono": by_email.get("telefono_e164"),
                    "empresa": by_email.get("company_name"),
                    "propietario_usuario_id": by_email.get("propietario_usuario_id"),
                    "tipo_registro": "contacto",
                    "coincidencia_en": "correo",
                    "correo_institucional": by_email.get("correo_secundario") or by_email.get("correo_institucional"),
                    "telefono_movil_1_e164": by_email.get("telefono_movil_1_e164"),
                    "nivel": "fuerte",
                    "motivo": "correo",
                },
            )

    candidates.sort(key=lambda item: _dedupe_level_rank(str(item.get("nivel") or "debil")), reverse=True)
    candidates = await _attach_dedupe_owner_names(
        repo=repo,
        organizacion_id=organizacion_id,
        candidates=candidates[:10],
    )
    return candidates


def _pick_first_strong_persona_candidate(candidates: list[dict[str, Any]]) -> UUID | None:
    for item in candidates:
        if str(item.get("nivel") or "") != "fuerte":
            continue
        candidate_id = _safe_uuid(item.get("id"))
        if candidate_id:
            return candidate_id
    return None


async def _persona_alta_build_dedupe_preview(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    contexto: CRMPersonaAltaContexto,
    persona: CRMPersonaAltaPersona,
    cuenta: CRMPersonaAltaCuenta | None,
    dedupe: CRMPersonaAltaDedupeDecision | None,
    exclude_contacto_id: UUID | None = None,
    exclude_account_id: UUID | None = None,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], UUID | None, UUID | None, bool]:
    persona_candidates = await _persona_alta_find_persona_candidates(
        repo=repo,
        organizacion_id=organizacion_id,
        persona=persona,
        cuenta=cuenta,
        exclude_contacto_id=exclude_contacto_id,
    )
    suggested_persona_id = _pick_first_strong_persona_candidate(persona_candidates)

    reused_account: CRMAccount | None = None
    account_candidates: list[dict[str, Any]] = []
    suggested_account_id: UUID | None = None
    if cuenta and not cuenta.cuenta_id and contexto.modo in {
        "empresa_nueva",
        "persona_fisica_actividad_empresarial",
    }:
        reused_account, account_candidates = await _persona_alta_find_existing_account(
            repo=repo,
            organizacion_id=organizacion_id,
            cuenta=cuenta,
            exclude_account_id=exclude_account_id,
        )
        suggested_account_id = reused_account.id if reused_account else None

    persona_pending = [item for item in persona_candidates if isinstance(item, dict)]
    cuenta_pending = [item for item in account_candidates if isinstance(item, dict)]
    requires_confirmation = bool(persona_pending or cuenta_pending)
    if dedupe and (dedupe.persona_reutilizar_id or dedupe.cuenta_reutilizar_id):
        requires_confirmation = False

    return (
        persona_candidates,
        account_candidates,
        suggested_persona_id,
        suggested_account_id,
        requires_confirmation,
    )


async def _persona_dedupe_preview(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    persona_id: UUID,
) -> tuple[list[dict[str, Any]], UUID | None, bool]:
    persona_row = await repo.get_persona_by_id(persona_id=str(persona_id))
    if not isinstance(persona_row, dict) or not persona_row.get("id"):
        raise CRMRepositoryError("persona_no_encontrada_para_dedupe")
    persona = CRMPersonaAltaPersona(
        nombre=str(persona_row.get("nombre") or "").strip() or str(persona_row.get("nombre_completo") or "").strip() or "Contacto",
        apellido_paterno=str(persona_row.get("apellido_paterno") or "").strip() or " ",
        apellido_materno=persona_row.get("apellido_materno") or None,
        nombre_completo=persona_row.get("nombre_completo"),
        correo_principal=persona_row.get("correo_principal") or persona_row.get("correo"),
        correo_institucional=persona_row.get("correo_institucional") or persona_row.get("correo_principal") or persona_row.get("correo"),
        correo_personal_3=persona_row.get("correo_personal_3"),
        telefono_principal_e164=persona_row.get("telefono_principal_e164") or persona_row.get("telefono_e164"),
        telefono_principal_extension=persona_row.get("telefono_principal_extension"),
        telefono_movil_1_e164=persona_row.get("telefono_movil_1_e164") or persona_row.get("telefono_principal_e164") or persona_row.get("telefono_e164"),
        telefono_movil_2_e164=persona_row.get("telefono_movil_2_e164"),
        telefono_empresa_1_e164=persona_row.get("telefono_empresa_1_e164"),
        telefono_empresa_1_extension=persona_row.get("telefono_empresa_1_extension"),
        telefono_empresa_2_e164=persona_row.get("telefono_empresa_2_e164"),
        telefono_empresa_2_extension=persona_row.get("telefono_empresa_2_extension"),
        puesto=persona_row.get("puesto"),
        area=persona_row.get("area"),
        rol_decision=persona_row.get("rol_decision"),
        estado=persona_row.get("estado"),
        origen=persona_row.get("origen"),
        notas=persona_row.get("notas"),
        propietario_usuario_id=_safe_uuid(persona_row.get("propietario_usuario_id")),
    )
    candidates = await _persona_alta_find_persona_candidates(
        repo=repo,
        organizacion_id=organizacion_id,
        persona=persona,
        cuenta=None,
        exclude_contacto_id=persona_id,
    )
    suggested = _pick_first_strong_persona_candidate(candidates)
    pending = [item for item in candidates if str(item.get("nivel") or "") in {"medio", "debil"}]
    return candidates, suggested, bool(pending)


async def _account_dedupe_preview(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    cuenta_id: UUID,
) -> tuple[list[dict[str, Any]], UUID | None, bool]:
    account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta_id)
    if not account_row:
        raise CRMRepositoryError("cuenta_no_encontrada_para_dedupe")
    account = CRMAccount.model_validate(account_row)
    reused_account, candidates = await _persona_alta_find_existing_account(
        repo=repo,
        organizacion_id=organizacion_id,
        cuenta=CRMPersonaAltaCuenta(
            cuenta_id=account.id,
            nombre_comercial=account.nombre,
            razon_social=account.razon_social if hasattr(account, "razon_social") else None,
            alias=account.alias,
            tipo_persona=None,
            tipo_cuenta=account.tipo,
            tipo=account.tipo,
            codigo_cuenta=account.codigo_cuenta if hasattr(account, "codigo_cuenta") else None,
            rfc=account.rfc,
            industria=account.industria,
            segmento=None,
            tamano=account.tamano,
            sitio_web=account.sitio_web,
            correo_principal=account.correo_principal or account.correo,
            correo_secundario=account.correo_secundario,
            telefono_principal=account.telefono_principal_e164 or account.telefono,
            telefono_principal_e164=account.telefono_principal_e164 or account.telefono,
            telefono_principal_tipo_linea=account.telefono_principal_tipo_linea,
            telefono_principal_extension=account.telefono_principal_extension,
            telefono_secundario_e164=account.telefono_secundario_e164,
            telefono_secundario_tipo_linea=account.telefono_secundario_tipo_linea,
            telefono_secundario_extension=account.telefono_secundario_extension,
            correo=account.correo,
            telefono=account.telefono,
            notas=account.notas if hasattr(account, "notas") else None,
            necesidad_proposito=account.necesidad_proposito if hasattr(account, "necesidad_proposito") else None,
            tipo_establecimiento=None,
            latitud=None,
            longitud=None,
            fecha_incorporacion=None,
        ),
        exclude_account_id=cuenta_id,
    )
    pending = [item for item in candidates if str(item.get("nivel") or "") in {"medio", "debil"}]
    suggested = reused_account.id if reused_account else None
    return candidates, suggested, bool(pending)


def _persona_alta_full_name(payload: CRMPersonaAltaPersona) -> str:
    derived = " ".join(
        part
        for part in [
            _persona_alta_clean_text(payload.nombre, compact_spaces=True),
            _persona_alta_clean_text(payload.apellido_paterno, compact_spaces=True),
            _persona_alta_clean_text(payload.apellido_materno, compact_spaces=True),
        ]
        if part
    ).strip()
    if derived:
        return derived
    explicit = _persona_alta_clean_text(payload.nombre_completo, compact_spaces=True)
    return explicit or ""


