def _normalize_orden_compra_row(row: Mapping[str, Any]) -> dict[str, Any]:
    normalized = dict(row)
    for field in ("condiciones_comerciales", "condiciones_pago", "logistica"):
        normalized[field] = _single_related(normalized.get(field))
    normalized["pagos_programados"] = _ensure_concept_list(normalized.get("pagos_programados"))
    return normalized


def _normalize_pedimento_importacion_row(row: Mapping[str, Any]) -> dict[str, Any]:
    normalized = dict(row)
    normalized["agente_aduanal"] = _single_related(normalized.get("agente_aduanal"))
    normalized["ordenes_compra"] = _ensure_concept_list(normalized.get("ordenes_compra"))
    normalized["gastos"] = _ensure_concept_list(normalized.get("gastos"))
    normalized["prorrateos"] = _ensure_concept_list(normalized.get("prorrateos"))
    return normalized


async def _load_pedimento_importacion_detail(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    pedimento_id: UUID,
) -> dict[str, Any] | None:
    row = await repo.get_pedimento_importacion(
        organizacion_id=organizacion_id,
        pedimento_id=pedimento_id,
    )
    if row is None:
        return None
    row["ordenes_compra"] = await repo.list_pedimento_ordenes_importacion(
        organizacion_id=organizacion_id,
        pedimento_id=pedimento_id,
    )
    row["gastos"] = await repo.list_pedimento_gastos_importacion(
        organizacion_id=organizacion_id,
        pedimento_id=pedimento_id,
    )
    row["prorrateos"] = await repo.list_pedimento_prorrateos_importacion(
        organizacion_id=organizacion_id,
        pedimento_id=pedimento_id,
    )
    return _normalize_pedimento_importacion_row(row)


async def _recalculate_pedimento_importacion_or_raise(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    pedimento_id: UUID,
) -> dict[str, Any]:
    try:
        await repo.recalcular_pedimento_importacion(
            organizacion_id=organizacion_id,
            pedimento_id=pedimento_id,
        )
        row = await _load_pedimento_importacion_detail(
            repo=repo,
            organizacion_id=organizacion_id,
            pedimento_id=pedimento_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if row is None:
        raise HTTPException(status_code=404, detail="pedimento_importacion_not_found")
    return row


def _normalize_orden_compra_pago_programado_rows(
    value: Any,
    *,
    default_moneda_codigo: str = "MXN",
    subtotal: Decimal | None = None,
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    normalized: list[dict[str, Any]] = []
    subtotal_decimal = subtotal if isinstance(subtotal, Decimal) else None
    if subtotal_decimal is None and subtotal is not None:
        try:
            subtotal_decimal = Decimal(str(subtotal))
        except (ArithmeticError, ValueError, TypeError):
            subtotal_decimal = None

    for raw in value:
        if isinstance(raw, BaseModel):
            raw_item = raw.model_dump(exclude_none=True)
        elif isinstance(raw, dict):
            raw_item = raw
        else:
            continue

        tipo_pago = _clean_text(raw_item.get("tipo_pago")).lower()
        evento_base = _clean_text(raw_item.get("evento_base"))
        if not tipo_pago or not evento_base:
            continue

        porcentaje = _decimal_from_value(raw_item.get("porcentaje"))
        monto = _decimal_from_value(raw_item.get("monto"))
        if subtotal_decimal and subtotal_decimal > 0:
            if porcentaje is None and monto is not None:
                porcentaje = (monto / subtotal_decimal * Decimal("100")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            elif monto is None and porcentaje is not None:
                monto = (subtotal_decimal * porcentaje / Decimal("100")).quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP)

        moneda_codigo = (_clean_text(raw_item.get("moneda_codigo")) or "").upper()
        if len(moneda_codigo) != 3:
            moneda_codigo = (default_moneda_codigo or "MXN").upper()

        estado = _clean_text(raw_item.get("estado")).lower() or "programado"
        if estado not in {"programado", "pendiente", "parcial", "pagado", "vencido", "cancelado"}:
            estado = "programado"

        entry: dict[str, Any] = {
            "tipo_pago": tipo_pago,
            "evento_base": evento_base,
            "moneda_codigo": moneda_codigo,
            "estado": estado,
        }
        if porcentaje is not None:
            entry["porcentaje"] = float(porcentaje.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
        if monto is not None:
            entry["monto"] = float(monto.quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP))
        dias_credito = raw_item.get("dias_credito")
        if dias_credito is not None:
            try:
                entry["dias_credito"] = int(dias_credito)
            except (TypeError, ValueError):
                pass
        fecha_vencimiento = raw_item.get("fecha_vencimiento_calculada")
        if fecha_vencimiento is not None:
            entry["fecha_vencimiento_calculada"] = fecha_vencimiento
        fecha_evento_real = raw_item.get("fecha_evento_real")
        if fecha_evento_real is not None:
            entry["fecha_evento_real"] = fecha_evento_real
        fecha_pago_real = raw_item.get("fecha_pago_real")
        if fecha_pago_real is not None:
            entry["fecha_pago_real"] = fecha_pago_real
        referencia_pago = _clean_text(raw_item.get("referencia_pago"))
        if referencia_pago:
            entry["referencia_pago"] = referencia_pago
        observaciones = _clean_text(raw_item.get("observaciones"))
        if observaciones:
            entry["observaciones"] = observaciones
        normalized.append(entry)

    return normalized


def _resolve_pago_programado_tipo_cambio_fecha(row: Mapping[str, Any]) -> date | None:
    for field in ("fecha_pago_real", "fecha_evento_real", "fecha_vencimiento_calculada"):
        parsed = _parse_date(row.get(field))
        if parsed is not None:
            return parsed
    return date.today()


async def _enrich_orden_compra_pago_programado_row(
    *,
    row: dict[str, Any],
    fallback_currency: str | None = None,
) -> dict[str, Any]:
    normalized = dict(row)
    currency = (_clean_text(normalized.get("moneda_codigo")) or _clean_text(fallback_currency) or "MXN").upper()
    normalized["moneda_codigo"] = currency

    amount = _decimal_from_value(normalized.get("monto"))
    if amount is None:
        normalized["tipo_cambio_aplicado"] = 1.0 if currency == "MXN" else None
        return normalized

    if currency == "MXN":
        normalized["tipo_cambio_aplicado"] = 1.0
        return normalized

    fecha_tipo_cambio = _resolve_pago_programado_tipo_cambio_fecha(normalized)
    try:
        resultado = await fetch_banxico_tipo_cambio_at_date(currency, fecha_tipo_cambio)
    except BanxicoError as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail=str(exc),
        ) from exc

    tipo_cambio = float(resultado.tipo_cambio)
    if not tipo_cambio or tipo_cambio <= 0:
        raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail="tipo_cambio_invalido")

    normalized["tipo_cambio_aplicado"] = tipo_cambio
    return normalized


def _resolve_orden_compra_payment_limit(order: Mapping[str, Any], tipo_pago: str) -> Decimal | None:
    condiciones = order.get("condiciones_pago")
    if not isinstance(condiciones, Mapping):
        return None

    if tipo_pago == "anticipo":
        monto = _decimal_from_value(condiciones.get("monto_anticipo"))
        porcentaje = _decimal_from_value(condiciones.get("porcentaje_anticipo"))
    elif tipo_pago == "saldo":
        monto = _decimal_from_value(condiciones.get("monto_saldo"))
        porcentaje = _decimal_from_value(condiciones.get("porcentaje_saldo"))
    else:
        return None

    if monto is not None:
        monto = _round_currency_decimal(monto)
        if monto > 0:
            return monto
        return None

    subtotal = _decimal_from_value(order.get("subtotal"))
    if porcentaje is None or subtotal is None or subtotal <= 0:
        return None

    resolved = subtotal * porcentaje / Decimal("100")
    if resolved <= 0:
        return None
    return _round_currency_decimal(resolved)


def _sum_orden_compra_payment_rows(
    rows: Iterable[Mapping[str, Any]],
    *,
    tipo_pago: str,
    exclude_pago_id: UUID | None = None,
) -> Decimal:
    excluded_id = str(exclude_pago_id) if exclude_pago_id is not None else ""
    total = Decimal("0")
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        if excluded_id and str(row.get("id") or "") == excluded_id:
            continue
        if _clean_text(row.get("tipo_pago")).lower() != tipo_pago:
            continue
        if _clean_text(row.get("estado")).lower() == "cancelado":
            continue
        monto = _decimal_from_value(row.get("monto"))
        if monto is None or monto <= 0:
            continue
        total += monto
    return _round_currency_decimal(total)


def _ensure_orden_compra_payment_limit(
    *,
    order: Mapping[str, Any],
    existing_rows: Iterable[Mapping[str, Any]],
    pending_rows: Iterable[Mapping[str, Any]],
    tipo_pago: str,
    exclude_pago_id: UUID | None = None,
) -> None:
    limit = _resolve_orden_compra_payment_limit(order, tipo_pago)
    if limit is None:
        return

    pending_total = _sum_orden_compra_payment_rows(pending_rows, tipo_pago=tipo_pago)
    if pending_total <= 0:
        return

    used_total = _sum_orden_compra_payment_rows(existing_rows, tipo_pago=tipo_pago, exclude_pago_id=exclude_pago_id)
    total_after = _round_currency_decimal(used_total + pending_total)
    if total_after > limit:
        raise HTTPException(
            status_code=409,
            detail=(
                f"El total de pagos tipo {tipo_pago} supera el monto pactado. "
                f"Disponible: {float(max(limit - used_total, Decimal('0'))):.4f}, "
                f"intentas registrar: {float(pending_total):.4f}, "
                f"tope: {float(limit):.4f}"
            ),
        )


async def _replace_orden_compra_pagos_programados(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    orden_id: UUID,
    order: Mapping[str, Any],
    pagos_programados: Any,
    subtotal: Decimal | None,
    moneda_codigo: str | None,
) -> None:
    normalized_rows = _normalize_orden_compra_pago_programado_rows(
        pagos_programados,
        default_moneda_codigo=moneda_codigo or "MXN",
        subtotal=subtotal,
    )
    enriched_rows: list[dict[str, Any]] = []
    for row in normalized_rows:
        enriched_rows.append(
            await _enrich_orden_compra_pago_programado_row(
                row=row,
                fallback_currency=moneda_codigo,
            )
        )
    for tipo_pago in {str(row.get("tipo_pago") or "").lower() for row in enriched_rows if isinstance(row, dict)}:
        if tipo_pago not in {"anticipo", "saldo"}:
            continue
        _ensure_orden_compra_payment_limit(
            order=order,
            existing_rows=[],
            pending_rows=[row for row in enriched_rows if str(row.get("tipo_pago") or "").lower() == tipo_pago],
            tipo_pago=tipo_pago,
        )
    try:
        await repo.replace_orden_compra_pagos_programados(
            organizacion_id=organizacion_id,
            orden_id=orden_id,
            pagos_programados=enriched_rows,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc


async def _resolve_orden_compra_tipo_cambio_referencia(
    *,
    moneda: str | None,
    fecha_emision: Any,
    tipo_cambio_referencia: float | None,
) -> float:
    currency = (_clean_text(moneda) or "MXN").upper()
    if currency == "MXN":
        return float(tipo_cambio_referencia or 1)
    if tipo_cambio_referencia is not None and tipo_cambio_referencia > 0:
        return float(tipo_cambio_referencia)

    fecha_emision_dt = fecha_emision if isinstance(fecha_emision, datetime) else _parse_iso_datetime(fecha_emision)
    fecha_tipo_cambio = fecha_emision_dt.date() if isinstance(fecha_emision_dt, datetime) else date.today()
    try:
        resultado = await fetch_banxico_tipo_cambio_at_date(currency, fecha_tipo_cambio)
    except BanxicoError as exc:
        raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=str(exc)) from exc
    rate = float(resultado.tipo_cambio)
    if not rate or rate <= 0:
        raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail="tipo_cambio_invalido")
    return rate


