def _contact_export_value(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, UUID):
        return str(value)
    return str(value)


def _mask_record_fields(record: dict[str, Any], field_names: Iterable[str]) -> dict[str, Any]:
    masked = dict(record)
    for field_name in field_names:
        if field_name in masked:
            masked[field_name] = None
    return masked


def _contact_owner_user_id(record: Mapping[str, Any]) -> UUID | None:
    return _safe_uuid(
        record.get("propietario_usuario_id")
        or record.get("propietario_id")
        or record.get("owner_id")
    )


def _account_owner_user_id(record: Mapping[str, Any]) -> UUID | None:
    return _safe_uuid(record.get("propietario_usuario_id") or record.get("owner_id"))


async def _resolve_sensitive_access_context(
    *,
    repo: CRMRepository,
    permission_code: str,
) -> tuple[UUID | None, bool]:
    permission_context = await _get_permission_context_or_raise(repo)
    current_user_id = _safe_uuid(permission_context.get("usuario_id"))
    if _coerce_bool(permission_context.get("es_admin")) is True:
        return current_user_id, True
    if _coerce_bool(permission_context.get("es_owner")) is True:
        return current_user_id, True
    if current_user_id is None:
        return None, False
    try:
        has_permission = await repo.current_user_has_perm(codigo=permission_code)
    except CRMRepositoryError:
        has_permission = False
    return current_user_id, has_permission


async def _can_view_contact_sensitive_fields(
    *,
    repo: CRMRepository,
    persona_id: UUID | None,
    owner_user_id: UUID | None,
    current_user_id: UUID | None = None,
    can_view_all: bool | None = None,
) -> bool:
    if current_user_id is None or can_view_all is None:
        current_user_id, can_view_all = await _resolve_sensitive_access_context(
            repo=repo,
            permission_code="contacts.view_sensitive_unowned",
        )
    if can_view_all:
        return True
    if current_user_id is None:
        return False
    if owner_user_id is not None and current_user_id == owner_user_id:
        return True
    return False


async def _can_view_account_sensitive_fields(
    *,
    repo: CRMRepository,
    cuenta_id: UUID | None,
    owner_user_id: UUID | None,
    current_user_id: UUID | None = None,
    can_view_all: bool | None = None,
) -> bool:
    if current_user_id is None or can_view_all is None:
        current_user_id, can_view_all = await _resolve_sensitive_access_context(
            repo=repo,
            permission_code="accounts.view_sensitive_unowned",
        )
    if can_view_all:
        return True
    if current_user_id is None:
        return False
    if owner_user_id is not None and current_user_id == owner_user_id:
        return True
    return False


def _apply_contact_visibility_mask(
    record: dict[str, Any],
    *,
    can_view_sensitive_fields: bool,
) -> dict[str, Any]:
    payload = dict(record)
    payload["can_view_sensitive_fields"] = can_view_sensitive_fields
    if can_view_sensitive_fields:
        return payload
    return _mask_record_fields(payload, _CONTACT_SENSITIVE_FIELDS)


def _apply_account_visibility_mask(
    record: dict[str, Any],
    *,
    can_view_sensitive_fields: bool,
) -> dict[str, Any]:
    payload = dict(record)
    payload["can_view_sensitive_fields"] = can_view_sensitive_fields
    if can_view_sensitive_fields:
        return payload
    return _mask_record_fields(payload, _ACCOUNT_SENSITIVE_FIELDS)


def _normalize_contact_search_value(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).strip().lower()
    if not text:
        return ""
    normalized = unicodedata.normalize("NFD", text)
    return "".join(ch for ch in normalized if not unicodedata.combining(ch))


def _contact_matches_search(row: Mapping[str, Any], term: str) -> bool:
    if not term:
        return True
    values = [
        row.get("nombre"),
        row.get("codigo_contacto"),
        row.get("codigo_cuenta"),
        row.get("correo"),
        row.get("telefono"),
        row.get("estado"),
        row.get("captura_estado"),
        row.get("origen"),
        row.get("company_name"),
        row.get("propietario_nombre"),
        row.get("rfc"),
        row.get("puesto"),
        row.get("area"),
        row.get("rol_decision"),
        row.get("codigo_postal"),
        row.get("entidad"),
        row.get("municipio"),
        row.get("pais"),
        row.get("website"),
        row.get("tipo_establecimiento"),
        row.get("notes"),
        row.get("contacto_id"),
    ]
    return any(term in _normalize_contact_search_value(value) for value in values)


def _render_contacts_csv(rows: Sequence[Mapping[str, Any]]) -> str:
    output = io.StringIO()
    writer = csv.writer(output)
    output.write("\ufeff")
    writer.writerow(_CONTACTS_EXPORT_HEADERS)
    for row in rows:
        writer.writerow(
            [
                _contact_export_value(row.get("codigo_contacto")),
                _contact_export_value(row.get("codigo_cuenta")),
                _contact_export_value(row.get("nombre")),
                _contact_export_value(row.get("correo")),
                _contact_export_value(row.get("telefono")),
                _contact_export_value(row.get("estado")),
                _contact_export_value(
                    "completo" if _contact_capture_complete(row) else "incompleto"
                ),
                _contact_export_value(row.get("origen")),
                _contact_export_value(row.get("creado_en")),
                _contact_export_value(row.get("actualizado_en")),
                _contact_export_value(row.get("company_name")),
                _contact_export_value(row.get("propietario_id")),
                _contact_export_value(row.get("propietario_nombre")),
                _contact_export_value(row.get("ultimo_contacto_en")),
                _contact_export_value(row.get("conversaciones")),
                _contact_export_value(row.get("notes")),
                _contact_export_value(row.get("rfc")),
                _contact_export_value(row.get("puesto")),
                _contact_export_value(row.get("area")),
                _contact_export_value(row.get("rol_decision")),
                _contact_export_value(row.get("codigo_postal")),
                _contact_export_value(row.get("entidad")),
                _contact_export_value(row.get("municipio")),
                _contact_export_value(row.get("pais")),
                _contact_export_value(row.get("website")),
                _contact_export_value(row.get("tipo_establecimiento")),
                _contact_export_value(row.get("fecha_incorporacion")),
            ]
        )
    return output.getvalue()


def _contact_capture_complete(row: Mapping[str, Any]) -> bool:
    required_values = [
        row.get("cuenta_tipo"),
        row.get("tamano"),
        row.get("tipo_establecimiento"),
        row.get("estado"),
        row.get("origen"),
        row.get("puesto"),
        row.get("rol_decision"),
        row.get("area"),
    ]
    return all(str(value or "").strip() for value in required_values)


async def _load_all_contacts_for_export(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    usuario_token: str,
    search: str | None = None,
    estado: str | None = None,
    captura: str | None = None,
    origen: str | None = None,
    propietario: UUID | None = None,
    date_from: datetime | None = None,
    date_to: datetime | None = None,
    puesto: str | None = None,
    rol_decision: str | None = None,
    estado_contacto: str | None = None,
    ligado: str | None = None,
    tipo_cuenta: str | None = None,
    tamano: str | None = None,
    clasificacion: str | None = None,
    cuenta_from: datetime | None = None,
    cuenta_to: datetime | None = None,
    fecha_incorporacion_from: datetime | None = None,
    fecha_incorporacion_to: datetime | None = None,
    fusionada: str | None = None,
    pais: str | None = None,
    estado_direccion: str | None = None,
    municipio: str | None = None,
) -> list[dict[str, Any]]:
    page_size = 500
    offset = 0
    rows: list[dict[str, Any]] = []
    normalized_search = _normalize_contact_search_value(search)

    while True:
        batch = await repo.contactos_list(
            usuario_token=usuario_token,
            organizacion_id=organizacion_id,
            limit=page_size,
            offset=offset,
            estado=estado,
            captura=captura,
            origen=origen,
            propietario=propietario,
            date_from=date_from,
            date_to=date_to,
            puesto=puesto,
            rol_decision=rol_decision,
            estado_contacto=estado_contacto,
            ligado=ligado,
            tipo_cuenta=tipo_cuenta,
            tamano=tamano,
            clasificacion=clasificacion,
            cuenta_from=cuenta_from,
            cuenta_to=cuenta_to,
            fecha_incorporacion_from=fecha_incorporacion_from,
            fecha_incorporacion_to=fecha_incorporacion_to,
            fusionada=fusionada,
            pais=pais,
            estado_direccion=estado_direccion,
            municipio=municipio,
        )
        rows.extend(batch)
        if len(batch) < page_size:
            break
        offset += page_size
        if offset > 100000:
            logger.warning(
                "contacts_export.stopped_after_safety_limit",
                extra={"offset": offset, "rows": len(rows)},
            )
            break

    if normalized_search:
        rows = [row for row in rows if _contact_matches_search(row, normalized_search)]

    return rows


