def _looks_like_template_identifier(value: str | None) -> bool:
    text = _clean_text(value)
    if not text:
        return False
    if _UUID_TEXT_RE.match(text):
        return True
    lowered = text.lower()
    if lowered.startswith("hx") and len(lowered) >= 12:
        return True
    return False


def _is_generic_historic_template_label(value: str | None) -> bool:
    text = (_clean_text(value) or "").strip().lower()
    return text in {"plantilla historica", "plantilla histórica"}


def _whatsapp_phone_lookup_candidates(phone_value: str | None) -> list[str]:
    normalized = _clean_text(phone_value)
    if not normalized:
        return []
    lowered = normalized.lower()
    if lowered.startswith("whatsapp"):
        normalized = normalized[len("whatsapp"):].lstrip(":").strip()
    normalized = normalized.replace("whatsapp:", "").strip()
    candidates: list[str] = []

    def _push(value: str | None) -> None:
        text = _clean_text(value)
        if not text:
            return
        if text not in candidates:
            candidates.append(text)

    _push(normalized)
    if normalized.startswith("+521") and len(normalized) > 4:
        _push("+52" + normalized[4:])
    if normalized.startswith("+52") and not normalized.startswith("+521") and len(normalized) > 3:
        _push("+521" + normalized[3:])

    digits = re.sub(r"\D", "", normalized)
    if digits:
        _push(digits)
    if len(digits) == 10:
        _push("+52" + digits)
        _push("+521" + digits)
    elif len(digits) == 11 and digits.startswith("1"):
        _push("+52" + digits[1:])
        _push("+521" + digits[1:])
    elif len(digits) == 12 and digits.startswith("52"):
        _push("+52" + digits[2:])
        _push("+521" + digits[2:])
    elif len(digits) == 13 and digits.startswith("521"):
        _push("+521" + digits[3:])
        _push("+52" + digits[3:])
    return candidates


def _collect_thread_template_external_keys(row: dict[str, Any]) -> list[str]:
    keys: list[str] = []

    def _push(value: Any) -> None:
        text = _clean_text(value)
        if not text:
            return
        lowered = text.lower()
        if lowered not in keys:
            keys.append(lowered)

    _push(row.get("template_slug"))
    _push(row.get("template_sid"))
    _push(row.get("twilio_content_sid"))

    messages = row.get("messages")
    if isinstance(messages, list):
        for message in reversed(messages):
            if not isinstance(message, dict):
                continue
            datos = message.get("datos")
            if not isinstance(datos, dict):
                continue
            metadata = datos.get("metadata") if isinstance(datos.get("metadata"), dict) else {}
            _push(datos.get("twilio_content_sid"))
            _push(metadata.get("twilio_content_sid"))
            _push(datos.get("template_sid"))
            _push(metadata.get("template_sid"))
            _push(datos.get("template_sid_snapshot"))
            _push(metadata.get("template_sid_snapshot"))
            _push(datos.get("external_template_id"))
            _push(metadata.get("external_template_id"))
    return keys


def _apply_persisted_inbox_context(row: dict[str, Any]) -> None:
    context = _ensure_dict(row.get("inbox_context"), default={})
    if not context:
        return

    source_value = _clean_text(context.get("source"))
    if source_value:
        row["source"] = source_value

    source_detail = context.get("source_detail")
    if isinstance(source_detail, dict) and source_detail:
        row["source_detail"] = source_detail

    sender_name = _clean_text(context.get("sender_name"))
    sender_email = _clean_text(context.get("sender_email"))
    if sender_name and not _clean_text(row.get("contacto_nombre")):
        row["contacto_nombre"] = sender_name
    if sender_email and not _clean_text(row.get("contacto_correo")):
        row["contacto_correo"] = sender_email.lower()

    for field in (
        "batch_id",
        "batch_label",
        "campana_id",
        "campana_label",
        "template_id",
        "template_slug",
        "template_label",
        "contacto_telefono",
        "contacto_country_code",
        "contacto_country_name",
        "contacto_state_name",
        "contacto_city_name",
        "contacto_lada",
    ):
        value = context.get(field)
        text_value = _clean_text(value)
        if not text_value:
            continue
        row[field] = text_value.lower() if field == "template_slug" else text_value


def _apply_inbox_phone_location(row: dict[str, Any]) -> None:
    phone_value = _clean_text(row.get("contacto_telefono"))
    if not phone_value:
        return
    phone_location = leads_geo.phone_location_from_number(phone_value)
    if phone_location.country_code:
        row["contacto_country_code"] = phone_location.country_code
    if phone_location.country_name:
        row["contacto_country_name"] = phone_location.country_name
    if phone_location.estado_nombre:
        row["contacto_state_name"] = phone_location.estado_nombre
    if phone_location.municipio_nombre:
        row["contacto_city_name"] = phone_location.municipio_nombre
    if phone_location.lada:
        row["contacto_lada"] = phone_location.lada


def _extract_thread_prospeccion_hints(
    row: dict[str, Any],
) -> tuple[str | None, str | None, str | None, str | None, str | None]:
    batch_id = _clean_text(row.get("batch_id"))
    campana_id = _clean_text(row.get("campana_id"))
    template_id = _clean_text(row.get("template_id"))
    template_slug = _clean_text(row.get("template_slug"))
    template_label = _clean_text(row.get("template_label"))

    messages = row.get("messages")
    if not isinstance(messages, list):
        return batch_id, campana_id, template_id, template_slug.lower() if template_slug else None, template_label

    for message in reversed(messages):
        if not isinstance(message, dict):
            continue
        datos = message.get("datos")
        if not isinstance(datos, dict):
            continue
        metadata = datos.get("metadata") if isinstance(datos.get("metadata"), dict) else {}
        candidate_batch = _clean_text(
            datos.get("batch_id") or metadata.get("batch_id")
        )
        candidate_campana = _clean_text(
            datos.get("campana_id") or metadata.get("campana_id")
        )
        candidate_id = _clean_text(
            datos.get("template_id")
            or metadata.get("template_id")
            or datos.get("template_uuid")
            or metadata.get("template_uuid")
            or datos.get("template_id_snapshot")
            or metadata.get("template_id_snapshot")
        )
        candidate_slug = _clean_text(
            datos.get("template_slug")
            or metadata.get("template_slug")
            or datos.get("template_slug_snapshot")
            or metadata.get("template_slug_snapshot")
            or datos.get("kw")
            or metadata.get("kw")
            or datos.get("twilio_content_sid")
            or metadata.get("twilio_content_sid")
            or datos.get("template_sid")
            or metadata.get("template_sid")
            or datos.get("template_sid_snapshot")
            or metadata.get("template_sid_snapshot")
        )
        candidate_label = _clean_text(
            datos.get("template_nombre")
            or metadata.get("template_nombre")
            or datos.get("template_name")
            or metadata.get("template_name")
            or datos.get("template_label")
            or metadata.get("template_label")
            or datos.get("template_nombre_snapshot")
            or metadata.get("template_nombre_snapshot")
            or datos.get("template_name_snapshot")
            or metadata.get("template_name_snapshot")
            or datos.get("template_label_snapshot")
            or metadata.get("template_label_snapshot")
        )
        if candidate_batch and not batch_id:
            batch_id = candidate_batch
        if candidate_campana and not campana_id:
            campana_id = candidate_campana
        if candidate_id and not template_id:
            template_id = candidate_id
        if candidate_slug and not template_slug:
            template_slug = candidate_slug
        if candidate_label and not template_label:
            template_label = candidate_label
        if batch_id and campana_id and template_id and template_slug and template_label:
            break

    return (
        batch_id,
        campana_id,
        template_id,
        template_slug.lower() if template_slug else None,
        template_label,
    )


def _extract_envio_prospeccion_hints(
    envio: dict[str, Any] | None,
) -> tuple[str | None, str | None, str | None, str | None, str | None]:
    if not isinstance(envio, dict):
        return None, None, None, None, None
    payload = envio.get("payload") if isinstance(envio.get("payload"), dict) else {}
    payload_meta = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    detalle = envio.get("detalle") if isinstance(envio.get("detalle"), dict) else {}
    batch_id = _clean_text(envio.get("batch_id"))
    campana_id = _clean_text(envio.get("campana_id")) or _clean_text(payload_meta.get("campana_id"))
    template_id = _clean_text(
        payload.get("template_id")
        or payload_meta.get("template_id")
        or payload_meta.get("template_id_snapshot")
    )
    template_slug = _clean_text(
        payload.get("template_slug")
        or payload_meta.get("template_slug")
        or payload_meta.get("template_slug_snapshot")
        or payload_meta.get("kw")
        or payload_meta.get("twilio_content_sid")
        or detalle.get("template_sid")
        or payload_meta.get("template_sid_snapshot")
    )
    template_label = _clean_text(
        payload.get("template_label")
        or payload_meta.get("template_label")
        or payload_meta.get("template_nombre")
        or payload_meta.get("template_name")
        or payload_meta.get("template_nombre_snapshot")
        or payload_meta.get("template_name_snapshot")
        or payload_meta.get("template_label_snapshot")
    )
    return (
        batch_id,
        campana_id,
        template_id,
        template_slug.lower() if template_slug else None,
        template_label,
    )


