@router.post("/cuentas", response_model=CRMAccount, status_code=status.HTTP_201_CREATED)
async def create_account(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    payload: CRMAccountCreate,
) -> CRMAccount:
    expected_rfc_length = _expected_rfc_length_for_account_type(payload.tipo)
    normalized_rfc = _normalize_rfc_text(payload.rfc)
    if normalized_rfc:
        if expected_rfc_length is not None and len(normalized_rfc) != expected_rfc_length:
            raise HTTPException(status_code=400, detail=_rfc_length_error_message(expected_rfc_length))
        if expected_rfc_length is None and len(normalized_rfc) not in {12, 13}:
            raise HTTPException(
                status_code=400,
                detail="El RFC debe tener 12 o 13 caracteres alfanuméricos.",
            )
    body = payload.model_dump(mode="json", exclude_unset=True)
    duplicate_candidates, _ = await _find_account_duplicate_candidates(
        repo=repo,
        organizacion_id=organizacion_id,
        account_like=body,
    )
    if duplicate_candidates:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "duplicate_account_detected",
                "message": "La empresa ya existe con el mismo correo, teléfono o RFC.",
                "candidatos_cuenta": duplicate_candidates,
                "sugerencia_cuenta_reutilizar_id": duplicate_candidates[0].get("id"),
            },
        )
    direccion_fiscal, direccion_principal = _extract_account_direction_blocks(body)
    try:
        row = await repo.create_account(
            organizacion_id=organizacion_id,
            payload=body,
        )
    except CRMRepositoryError as exc:
        detail = str(exc).lower()
        if "duplicate_rfc" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_account_detected",
                    "message": "La empresa ya existe con el mismo RFC.",
                },
            ) from exc
        if "duplicate_contact_method" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_contact_detected",
                    "message": "Ya existe un registro con el mismo correo o teléfono.",
                },
            ) from exc
        if "duplicate_account_detected" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_account_detected",
                    "message": "La empresa ya existe con el mismo correo, teléfono o RFC.",
                },
            ) from exc
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    cuenta_id = _safe_uuid(row.get("id"))
    if cuenta_id:
        try:
            if direccion_fiscal:
                await _sync_account_direction_block(
                    repo=repo,
                    organizacion_id=organizacion_id,
                    cuenta_id=cuenta_id,
                    direction_payload=direccion_fiscal,
                    tipo_relacion="fiscal",
                )
            if direccion_principal:
                await _sync_account_direction_block(
                    repo=repo,
                    organizacion_id=organizacion_id,
                    cuenta_id=cuenta_id,
                    direction_payload=direccion_principal,
                    tipo_relacion="principal",
                )
        except CRMRepositoryError:
            pass
    try:
        direction_rows = (
            await repo.list_account_address_relations(
                organizacion_id=organizacion_id,
                cuenta_id=cuenta_id,
                activo=None,
            )
            if cuenta_id
            else []
        )
    except CRMRepositoryError:
        direction_rows = []
    return CRMAccount.model_validate(
        _materialize_account_directions(
            row,
            relation_rows=direction_rows,
            include_direcciones=True,
        )
    )


@router.get("/cuentas/{cuenta_id}", response_model=CRMAccount)
async def get_account(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.read")),
    cuenta_id: UUID,
) -> CRMAccount:
    try:
        row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta_id)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not row:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="cuenta_no_encontrada")
    try:
        direction_rows = await repo.list_account_address_relations(
            organizacion_id=organizacion_id,
            cuenta_id=cuenta_id,
            activo=None,
        )
    except CRMRepositoryError:
        direction_rows = []
    current_user_id, can_view_all_sensitive = await _resolve_sensitive_access_context(
        repo=repo,
        permission_code="accounts.view_sensitive_unowned",
    )
    owner_user_id = _account_owner_user_id(row)
    can_view_sensitive_fields = bool(
        can_view_all_sensitive
        or (
            current_user_id is not None
            and owner_user_id is not None
            and current_user_id == owner_user_id
        )
    )
    payload = _materialize_account_directions(
        row,
        relation_rows=direction_rows,
        include_direcciones=True,
    )
    payload = _apply_account_visibility_mask(
        payload,
        can_view_sensitive_fields=can_view_sensitive_fields,
    )
    if not can_view_sensitive_fields:
        payload["contacto_principal_correo"] = None
        payload["contacto_principal_telefono"] = None
    return CRMAccount.model_validate(payload)


@router.patch("/cuentas/{cuenta_id}", response_model=CRMAccount)
async def update_account(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    cuenta_id: UUID,
    payload: CRMAccountUpdate,
) -> CRMAccount:
    try:
        existing_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta_id)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not existing_row:
        raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
    await _require_record_owner_or_privileged(
        repo=repo,
        owner_user_id=_safe_uuid(existing_row.get("propietario_usuario_id")),
    )
    account_type = payload.tipo or str(existing_row.get("tipo") or "")
    expected_rfc_length = _expected_rfc_length_for_account_type(account_type)
    normalized_rfc = _normalize_rfc_text(payload.rfc)
    if normalized_rfc:
        if expected_rfc_length is not None and len(normalized_rfc) != expected_rfc_length:
            raise HTTPException(status_code=400, detail=_rfc_length_error_message(expected_rfc_length))
        if expected_rfc_length is None and len(normalized_rfc) not in {12, 13}:
            raise HTTPException(
                status_code=400,
                detail="El RFC debe tener 12 o 13 caracteres alfanuméricos.",
            )
    body = payload.model_dump(mode="json", exclude_unset=True)
    duplicate_probe = dict(existing_row)
    duplicate_probe.update(body)
    duplicate_candidates, _ = await _find_account_duplicate_candidates(
        repo=repo,
        organizacion_id=organizacion_id,
        account_like=duplicate_probe,
        exclude_account_id=cuenta_id,
    )
    if duplicate_candidates:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "duplicate_account_detected",
                "message": "La empresa ya existe con el mismo correo, teléfono o RFC.",
                "candidatos_cuenta": duplicate_candidates,
                "sugerencia_cuenta_reutilizar_id": duplicate_candidates[0].get("id"),
            },
        )
    direccion_fiscal, direccion_principal = _extract_account_direction_blocks(body)
    try:
        row = await repo.update_account(
            organizacion_id=organizacion_id,
            account_id=cuenta_id,
            payload=body,
        )
    except CRMRepositoryError as exc:
        detail = str(exc).lower()
        if "duplicate_rfc" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_account_detected",
                    "message": "La empresa ya existe con el mismo RFC.",
                },
            ) from exc
        if "duplicate_contact_method" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_contact_detected",
                    "message": "Ya existe un registro con el mismo correo o teléfono.",
                },
            ) from exc
        if "duplicate_account_detected" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_account_detected",
                    "message": "La empresa ya existe con el mismo correo, teléfono o RFC.",
                },
            ) from exc
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    try:
        if direccion_fiscal:
            await _sync_account_direction_block(
                repo=repo,
                organizacion_id=organizacion_id,
                cuenta_id=cuenta_id,
                direction_payload=direccion_fiscal,
                tipo_relacion="fiscal",
            )
        if direccion_principal:
            await _sync_account_direction_block(
                repo=repo,
                organizacion_id=organizacion_id,
                cuenta_id=cuenta_id,
                direction_payload=direccion_principal,
                tipo_relacion="principal",
            )
    except CRMRepositoryError:
        pass
    try:
        direction_rows = await repo.list_account_address_relations(
            organizacion_id=organizacion_id,
            cuenta_id=cuenta_id,
            activo=None,
        )
    except CRMRepositoryError:
        direction_rows = []
    return CRMAccount.model_validate(
        _materialize_account_directions(
            row,
            relation_rows=direction_rows,
            include_direcciones=True,
        )
    )


@router.delete(
    "/cuentas/{cuenta_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    response_class=Response,
)
async def delete_account(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    cuenta_id: UUID,
) -> Response:
    try:
        existing_row = await repo.get_account(
            organizacion_id=organizacion_id,
            account_id=cuenta_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not existing_row:
        raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
    await _require_delete_scope(
        repo=repo,
        owner_user_id=_safe_uuid(existing_row.get("propietario_usuario_id")),
    )
    try:
        await repo.delete_account(
            organizacion_id=organizacion_id,
            account_id=cuenta_id,
        )
    except CRMRepositoryError as exc:
        detail = str(exc)
        if "cuenta_tiene_contactos" in detail:
            raise HTTPException(status_code=409, detail=detail) from exc
        if "cuenta_tiene_oportunidades" in detail:
            raise HTTPException(status_code=409, detail=detail) from exc
        raise HTTPException(status_code=502, detail=detail) from exc
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@router.post("/cuentas/{cuenta_id}/merge", response_model=CRMCuentaMergeResponse)
async def merge_account(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    cuenta_id: UUID,
    payload: CRMCuentaMergeRequest,
) -> CRMCuentaMergeResponse:
    try:
        merged = await repo.merge_account(
            organizacion_id=organizacion_id,
            source_account_id=cuenta_id,
            target_account_id=payload.target_cuenta_id,
            merge_metadata={
                "merge_reason": "manual_merge",
                "source_cuenta_id": str(cuenta_id),
                "target_cuenta_id": str(payload.target_cuenta_id),
            },
        )
    except CRMRepositoryError as exc:
        detail = str(exc)
        if "cuenta_source_not_found" in detail:
            raise HTTPException(status_code=404, detail="cuenta_source_not_found") from exc
        if "cuenta_target_not_found" in detail:
            raise HTTPException(status_code=404, detail="cuenta_target_not_found") from exc
        if "cuenta_merge_same_record" in detail:
            raise HTTPException(status_code=400, detail="cuenta_merge_same_record") from exc
        raise HTTPException(status_code=502, detail=detail) from exc

    merge_summary = merged.pop("merge_summary", {}) if isinstance(merged, dict) else {}
    merged_cuenta = CRMAccount.model_validate(merged)
    return CRMCuentaMergeResponse(
        source_cuenta_id=cuenta_id,
        target_cuenta_id=payload.target_cuenta_id,
        merged_cuenta=merged_cuenta,
        opportunities_moved=int(merge_summary.get("opportunities_moved") or 0),
        relations_moved=int(merge_summary.get("relations_moved") or 0),
        relations_updated=int(merge_summary.get("relations_updated") or 0),
        addresses_moved=int(merge_summary.get("addresses_moved") or 0),
        addresses_updated=int(merge_summary.get("addresses_updated") or 0),
    )


