@router.get("/usuarios/vendedores", response_model=list[CRMUserSummary])
async def list_sales_reps(
    *,
    organizacion_id: UUID = Depends(require_organizacion_id),
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    scope: Literal["all", "team"] = Query(default="team"),
    limit: Annotated[int, Query(ge=1, le=500)] = 200,
) -> list[CRMUserSummary]:
    if usuario_id is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")
    repo = CRMRepository(user_token=user_token)

    can_any = await repo.current_user_has_perm(codigo="pipeline.reassign.any")
    can_team = await repo.current_user_has_perm(codigo="pipeline.reassign.team")
    if not can_any and not can_team:
        return []

    requested_scope = scope if scope in {"all", "team"} else "team"

    try:
        if requested_scope == "all":
            if not can_any:
                raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")
            rows = await repo.list_sales_reps(organizacion_id=organizacion_id, limit=limit)
        else:
            rows = await repo.list_supervised_sales_reps(
                organizacion_id=organizacion_id,
                supervisor_id=usuario_id,
                limit=limit,
            )
            # Si el supervisor también es vendedor, lo incluimos.
            self_entry = await repo.get_employee_vendor(
                organizacion_id=organizacion_id,
                usuario_id=usuario_id,
            )
            if isinstance(self_entry, dict) and self_entry.get("es_vendedor"):
                all_users = await repo.list_users(organizacion_id=organizacion_id, limit=limit)
                for user in all_users:
                    if isinstance(user, dict) and str(user.get("id")) == str(usuario_id):
                        rows.append(user)
                        break
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    # Deduplicar por id
    seen: set[str] = set()
    results: list[CRMUserSummary] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        user_id = row.get("id")
        if not isinstance(user_id, str) or not user_id:
            continue
        if user_id in seen:
            continue
        seen.add(user_id)
        results.append(CRMUserSummary.model_validate(row))
    return results


@router.get("/oportunidades", response_model=CRMOpportunitiesResponse)
async def list_opportunities(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    user_token: str = Depends(require_user_token),  # noqa: ARG001
    usuario_id: UUID | None = Depends(optional_usuario_id),
    persona_id: UUID | None = Query(default=None),
    etapa_id: UUID | None = Query(default=None),
    estado: str | None = Query(default=None),
    asignado_id: UUID | None = Query(default=None),
    cuenta_id: UUID | None = Query(default=None),
    canal: str | None = Query(default=None),
    q: str | None = Query(default=None),
    monto_min: float | None = Query(default=None),
    monto_max: float | None = Query(default=None),
    cierre_desde: str | None = Query(default=None),
    cierre_hasta: str | None = Query(default=None),
    creado_desde: str | None = Query(default=None),
    creado_hasta: str | None = Query(default=None),
    reinicio_min: int | None = Query(default=None),
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> CRMOpportunitiesResponse:
    permission_context = await _get_permission_context_or_raise(repo)
    if _is_sales_level_context(permission_context) and not _is_privileged_permission_context(permission_context):
        current_user_id = _safe_uuid(permission_context.get("usuario_id"))
        if current_user_id:
            asignado_id = current_user_id

    effective_timezone, _ = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    creado_desde_utc = _convert_date_filter_to_utc_iso(
        value=creado_desde,
        timezone_name=effective_timezone,
        is_end=False,
    )
    creado_hasta_utc = _convert_date_filter_to_utc_iso(
        value=creado_hasta,
        timezone_name=effective_timezone,
        is_end=True,
    )
    cierre_desde_utc = _convert_date_filter_to_utc_iso(
        value=cierre_desde,
        timezone_name=effective_timezone,
        is_end=False,
    )
    cierre_hasta_utc = _convert_date_filter_to_utc_iso(
        value=cierre_hasta,
        timezone_name=effective_timezone,
        is_end=True,
    )
    try:
        rows, total = await repo.list_opportunities(
            organizacion_id=organizacion_id,
            limit=limit,
            offset=offset,
            persona_id=persona_id,
            etapa_id=etapa_id,
            estado=estado,
            asignado_id=asignado_id,
            cuenta_id=cuenta_id,
            canal=canal,
            q=q,
            monto_min=monto_min,
            monto_max=monto_max,
            cierre_desde=cierre_desde_utc,
            cierre_hasta=cierre_hasta_utc,
            creado_desde=creado_desde_utc,
            creado_hasta=creado_hasta_utc,
            reinicio_min=reinicio_min,
            include_contact_rows=False,
            count_exact=True,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    items = [CRMOpportunity.model_validate(row) for row in rows]
    return CRMOpportunitiesResponse(items=items, limit=limit, offset=offset, total=total or len(items))


@router.post("/oportunidades/{oportunidad_id}/reasignar", response_model=CRMReassignOpportunityResponse)
async def reassign_opportunity(
    *,
    organizacion_id: UUID = Depends(require_organizacion_id),
    oportunidad_id: UUID,
    payload: CRMReassignOpportunityPayload,
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
) -> CRMReassignOpportunityResponse:
    if usuario_id is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")

    repo = CRMRepository(user_token=user_token)
    can_any = await repo.current_user_has_perm(codigo="pipeline.reassign.any")
    can_team = await repo.current_user_has_perm(codigo="pipeline.reassign.team")
    if not can_any and not can_team:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")

    if not can_any:
        allowed = await repo.is_in_current_user_scope(usuario_id=payload.asignado_usuario_id)
        if not allowed:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="target_out_of_scope")

    vendedor = await repo.get_employee_vendor(
        organizacion_id=organizacion_id,
        usuario_id=payload.asignado_usuario_id,
    )
    if not isinstance(vendedor, dict) or not vendedor.get("es_vendedor"):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="vendedor_invalid")

    oportunidad = await repo.get_opportunity(
        organizacion_id=organizacion_id,
        opportunity_id=oportunidad_id,
    )
    if not oportunidad:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="oportunidad_not_found")

    persona_id_raw = payload.persona_id or oportunidad.get("contacto_principal_id") or oportunidad.get(
        "contacto_id"
    )
    persona_id: UUID | None = None
    if persona_id_raw:
        try:
            persona_id = UUID(str(persona_id_raw))
        except (TypeError, ValueError):
            persona_id = None

    await repo.update_opportunity(
        organizacion_id=organizacion_id,
        oportunidad_id=oportunidad_id,
        payload={"asignado_a_usuario_id": str(payload.asignado_usuario_id)},
    )

    conversation_id: UUID | None = payload.conversacion_id
    if conversation_id is None:
        metadata = oportunidad.get("metadata") if isinstance(oportunidad, dict) else None
        if isinstance(metadata, dict):
            raw_conv = metadata.get("conversation_id") or metadata.get("conversacion_id")
            if raw_conv:
                try:
                    conversation_id = UUID(str(raw_conv))
                except (TypeError, ValueError):
                    conversation_id = None
    if conversation_id is None and persona_id:
        service_repo = CRMRepository()
        resolved = await service_repo.get_latest_conversation_id_by_contact(
            organizacion_id=organizacion_id,
            contacto_id=persona_id,
        )
        if resolved:
            try:
                conversation_id = UUID(str(resolved))
            except (TypeError, ValueError):
                conversation_id = None

    persona_actualizada = False
    if payload.alinear_persona and persona_id:
        can_contact_any = await repo.current_user_has_perm(codigo="contacts.reassign.any")
        can_contact_team = await repo.current_user_has_perm(codigo="contacts.reassign.team")
        if not can_contact_any and not can_contact_team:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="contacts_forbidden")
        if not can_contact_any:
            allowed = await repo.is_in_current_user_scope(usuario_id=payload.asignado_usuario_id)
            if not allowed:
                raise HTTPException(
                    status_code=status.HTTP_403_FORBIDDEN, detail="contact_target_out_of_scope"
                )
        await repo.update_persona(
            organizacion_id=organizacion_id,
            persona_id=persona_id,
            payload={"propietario_usuario_id": str(payload.asignado_usuario_id)},
        )
        persona_actualizada = True

    conversacion_actualizada = False
    if payload.alinear_conversacion and conversation_id:
        # Conversaciones usan RLS estricta; actualizamos con service role
        service_repo = CRMRepository()
        await service_repo.update_conversation(
            conversation_id=str(conversation_id),
            patch={"asignado_a_usuario_id": str(payload.asignado_usuario_id)},
        )
        conversacion_actualizada = True

    metadata: dict[str, Any] = {"actor_id": str(usuario_id)}
    if payload.motivo:
        metadata["motivo"] = payload.motivo
    if conversation_id:
        await repo.insert_sales_assignment_audit(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
            vendedor_id=payload.asignado_usuario_id,
            conversation_id=str(conversation_id),
            persona_id=str(persona_id) if persona_id else None,
            trigger="manual_reassign",
            metadata=metadata,
            canal="panel",
        )
    else:
        logger.warning(
            "crm.reassign.audit_skipped_no_conversation",
            extra={
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "persona_id": str(persona_id) if persona_id else None,
                "actor_id": str(usuario_id),
            },
        )

    return CRMReassignOpportunityResponse(
        oportunidad_id=oportunidad_id,
        asignado_usuario_id=payload.asignado_usuario_id,
        persona_id=persona_id,
        conversacion_id=conversation_id,
        persona_actualizada=persona_actualizada,
        conversacion_actualizada=conversacion_actualizada,
    )


