@router.patch(
    "/pipeline/opportunities/{oportunidad_id}",
    response_model=CRMPipelineCardResponse,
)
async def pipeline_update_opportunity(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    oportunidad_id: UUID,
    payload: CRMPipelineOpportunityPatch,
) -> CRMPipelineCardResponse:
    current = await repo.get_pipeline_opportunity(
        organizacion_id=organizacion_id,
        oportunidad_id=oportunidad_id,
    )
    if current is None:
        raise HTTPException(status_code=404, detail="opportunity_not_found")
    current_stage = _safe_uuid(current.get("etapa_id"))
    if payload.expected_etapa_id and current_stage and payload.expected_etapa_id != current_stage:
        raise HTTPException(status_code=409, detail="opportunity_stage_conflict")
    await _require_edit_scope(
        repo=repo,
        owner_user_id=_safe_uuid(current.get("propietario_usuario_id")),
        assigned_user_id=_safe_uuid(current.get("asignado_a_usuario_id")),
    )
    update_body = payload.model_dump(
        mode="json",
        exclude_none=True,
        exclude={"expected_etapa_id", "motivo", "fuente"},
    )
    current_metadata = _ensure_dict(current.get("metadata"), default={})
    previous_booking_id = _extract_demo_booking_id(current_metadata)
    merged_metadata = current_metadata
    if "metadata" in update_body:
        new_metadata = _ensure_dict(update_body.get("metadata"), default={})
        merged_metadata = {**current_metadata, **new_metadata}
        update_body["metadata"] = merged_metadata
    try:
        await repo.update_opportunity(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
            payload=update_body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    new_booking_id = _extract_demo_booking_id(merged_metadata)
    if new_booking_id and new_booking_id != previous_booking_id:
        await webchat_service.ensure_booking_invite_sent_for_opportunity(
            booking_id=new_booking_id,
            oportunidad_id=str(oportunidad_id),
        )
    if payload.etapa_id and current_stage and payload.etapa_id != current_stage:
        history_payload = {
            "oportunidad_id": str(oportunidad_id),
            "etapa_origen_id": str(current_stage),
            "etapa_destino_id": str(payload.etapa_id),
            "cambiado_por_usuario_id": str(usuario_id) if usuario_id else None,
            "motivo": payload.motivo,
            "fuente": payload.fuente or "humano",
            "metadata": payload.metadata or {},
        }
        await repo.append_stage_history(
            organizacion_id=organizacion_id,
            payload={k: v for k, v in history_payload.items() if v is not None},
        )
    return await _build_pipeline_card_response(
        repo=repo,
        organizacion_id=organizacion_id,
        oportunidad_id=oportunidad_id,
    )


@router.delete(
    "/pipeline/opportunities/{oportunidad_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    response_class=Response,
)
async def pipeline_delete_opportunity(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    oportunidad_id: UUID,
) -> Response:
    await _require_delete_scope(repo=repo, owner_user_id=None)

    try:
        bookings = await repo.list_calendar_bookings_by_opportunity(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
            include_cancelled=False,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    for booking in bookings:
        booking_id = booking.get("id")
        if not booking_id:
            continue
        try:
            await calendar_service.cancel_booking(
                booking_id=str(booking_id),
                reason="opportunity_deleted",
            )
        except CalendarError as exc:
            raise HTTPException(
                status_code=502,
                detail=f"booking_cancel_failed:{booking_id}:{exc}",
            ) from exc

    try:
        await repo.delete_opportunity(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@router.post(
    "/productos/importador/import",
    response_model=CRMProductImportSummary,
)
async def import_product_catalog_items(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("settings.manage")),
    scheme_id: UUID = Form(...),
    file: UploadFile = File(...),
    background_tasks: BackgroundTasks,
    usuario_id: UUID | None = Depends(optional_usuario_id),
) -> CRMProductImportSummary:
    try:
        scheme = await repo.get_product_metadata_scheme(
            organizacion_id=organizacion_id,
            scheme_id=scheme_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=404, detail=str(exc)) from exc
    scheme_fields = _normalize_scheme_fields(scheme.get("fields"))
    try:
        headers_map, rows = await _read_import_rows(file)
    except RuntimeError as exc:
        raise HTTPException(status_code=status.HTTP_501_NOT_IMPLEMENTED, detail=str(exc)) from exc
    if not rows:
        raise HTTPException(status_code=400, detail="empty_file")
    headers = list(headers_map.keys())
    field_header_map = _build_field_header_map(headers, scheme_fields)

    lineas_raw = await repo.list_lineas_de_negocio(
        organizacion_id=organizacion_id,
        include_inactive=True,
        limit=1000,
    )
    lineas_cache = {
        _normalize_column_value(str(linea.get("nombre"))): linea
        for linea in lineas_raw
        if linea.get("nombre")
    }
    familias_cache: dict[tuple[str, str], dict[str, Any]] = {}
    familias = await repo.list_familias_productos(
        organizacion_id=organizacion_id,
        include_inactive=True,
        limit=1000,
    )
    for familia in familias:
        linea_id = familia.get("linea_id")
        nombre = familia.get("nombre")
        if not linea_id or not nombre:
            continue
        familias_cache[(str(linea_id), _normalize_column_value(nombre))] = familia
    modelos_cache: dict[tuple[str, str], dict[str, Any]] = {}
    modelos_global: dict[str, dict[str, Any]] = {}
    modelos = await repo.list_modelos_productos(
        organizacion_id=organizacion_id,
        include_inactive=True,
        limit=1000,
    )
    for modelo in modelos:
        familia_id = modelo.get("familia_id")
        nombre = modelo.get("nombre")
        if not familia_id or not nombre:
            continue
        modelos_cache[(str(familia_id), _normalize_column_value(nombre))] = modelo
        modelos_global[_normalize_column_value(nombre)] = modelo

    async def ensure_linea(name: str) -> UUID:
        normalized = _normalize_column_value(name)
        if not normalized:
            raise ValueError("Línea vacía")
        cached = lineas_cache.get(normalized)
        if cached:
            return UUID(str(cached["id"]))
        payload = {"nombre": name, "activo": True}
        nueva = await repo.create_linea_de_negocio(
            organizacion_id=organizacion_id,
            payload=payload,
        )
        lineas_cache[_normalize_column_value(str(nueva.get("nombre", name)))] = nueva
        return UUID(str(nueva["id"]))

    async def ensure_familia(name: str, linea_id: UUID) -> UUID:
        normalized = _normalize_column_value(name)
        key = (str(linea_id), normalized)
        cached = familias_cache.get(key)
        if cached:
            return UUID(str(cached["id"]))
        payload = {"nombre": name, "linea_id": str(linea_id), "activo": True}
        nueva = await repo.create_familia_producto(
            organizacion_id=organizacion_id,
            payload=payload,
        )
        familias_cache[key] = nueva
        return UUID(str(nueva["id"]))

    async def ensure_model(name: str, familia_id: UUID) -> UUID:
        normalized = _normalize_column_value(name)
        key = (str(familia_id), normalized)
        cached = modelos_cache.get(key)
        if cached:
            return UUID(str(cached["id"]))
        global_cached = modelos_global.get(normalized)
        if global_cached:
            return UUID(str(global_cached["id"]))
        payload = {"nombre": name, "familia_id": str(familia_id), "activo": True}
        nuevo = await repo.create_modelo_producto(
            organizacion_id=organizacion_id,
            payload=payload,
        )
        modelos_cache[key] = nuevo
        modelos_global[normalized] = nuevo
        return UUID(str(nuevo["id"]))

    created = 0
    updated = 0
    errors: list[CRMProductImportRowError] = []
    for index, row in enumerate(rows, start=1):
        try:
            nombre = _pick_value(row, BASE_HEADER_CANDIDATES["nombre"])
            if not nombre:
                raise ValueError("Falta el nombre del producto.")
            descripcion_corta = _pick_value(row, BASE_HEADER_CANDIDATES["descripcion_corta"])
            descripcion_larga = _pick_value(row, BASE_HEADER_CANDIDATES["descripcion_larga"])
            precio_base = _parse_metadata_value(
                _pick_value(row, BASE_HEADER_CANDIDATES["precio_base"]),
                "number",
            )
            linea_name = _pick_value(row, BASE_HEADER_CANDIDATES["linea"])
            if not linea_name:
                raise ValueError("Falta la línea asociada.")
            familia_name = _pick_value(row, BASE_HEADER_CANDIDATES["familia"])
            if not familia_name:
                raise ValueError("Falta la familia asociada.")
            modelo_name = _pick_value(row, BASE_HEADER_CANDIDATES["modelo"])

            linea_id = await ensure_linea(linea_name)
            familia_id = await ensure_familia(familia_name, linea_id)
            modelo_id = None
            if modelo_name:
                modelo_id = await ensure_model(modelo_name, familia_id)

            metadata: dict[str, Any] = {}
            for field in scheme_fields:
                header = field_header_map.get(field["id"])
                if not header:
                    continue
                parsed_value = _parse_metadata_value(row.get(header), field["type"])
                if parsed_value is not None:
                    metadata[field["id"]] = parsed_value
            for key, value in row.items():
                if not value:
                    continue
                if key in field_header_map.values() or key in BASE_HEADER_KEYS:
                    continue
                metadata[headers_map.get(key, key)] = value
            metadata = _strip_catalog_reserved_metadata_keys(metadata)

            provided_slug = _pick_value(row, BASE_HEADER_CANDIDATES["slug"])
            slug = provided_slug or _slugify(nombre) or f"item-{uuid4().hex}"
            existing = await repo.get_catalog_item_by_slug(
                organizacion_id=organizacion_id,
                slug=slug,
            )
            payload: dict[str, Any] = {
                "nombre": nombre,
                "slug": slug,
                "linea_id": str(linea_id),
                "familia_id": str(familia_id),
                "activo": True,
                "tipo": "producto",
            }
            payload["organizacion_id"] = str(organizacion_id)
            if descripcion_corta:
                payload["descripcion_corta"] = descripcion_corta
            if descripcion_larga:
                payload["descripcion_larga"] = descripcion_larga
            if precio_base is not None:
                payload["precio_base"] = precio_base
            if modelo_id:
                payload["modelo_id"] = str(modelo_id)
            if metadata:
                payload["metadatos"] = metadata
            if existing:
                await repo.update_catalog_item(
                    item_id=UUID(str(existing["id"])),
                    payload=payload,
                )
                updated += 1
            else:
                await repo.create_catalog_item(payload=payload)
                created += 1
        except (ValueError, CRMRepositoryError) as exc:
            errors.append(
                CRMProductImportRowError(
                    row=index,
                    message=str(exc),
                    data=_build_error_payload(row, headers_map),
                )
            )
    _trigger_catalog_reindex(
        background_tasks,
        organizacion_id,
        usuario_id=usuario_id,
        canal="importador",
    )
    return CRMProductImportSummary(
        total=len(rows),
        created=created,
        updated=updated,
        errors=errors,
    )


