def _normalize_column_value(value: str | None) -> str:
    if not value:
        return ""
    normalized = unicodedata.normalize("NFKD", value)
    filtered = "".join(ch for ch in normalized if not unicodedata.combining(ch))
    return re.sub(r"\s+", " ", filtered).strip().lower()


def _slugify(value: str) -> str:
    text = unicodedata.normalize("NFKD", value or "")
    slug = "".join(ch if ch.isalnum() else "-" for ch in text.lower())
    slug = re.sub(r"-+", "-", slug).strip("-")
    return slug or ""


def _parse_metadata_value(raw_value: str | None, field_type: str) -> str | float | bool | None:
    if not raw_value:
        return None
    cleaned = raw_value.strip()
    if not cleaned:
        return None
    lowered = cleaned.lower()
    if field_type == "boolean":
        if lowered in {"1", "si", "sí", "true", "t", "yes", "y"}:
            return True
        if lowered in {"0", "no", "false", "f", "n"}:
            return False
        return None
    if field_type == "number":
        normalized = cleaned.replace(",", ".")
        try:
            return float(normalized)
        except ValueError:
            return None
    return cleaned


def _normalize_scheme_fields(raw_fields: Any) -> list[dict[str, Any]]:
    fields: list[dict[str, Any]] = []
    if not isinstance(raw_fields, list):
        return fields
    for raw in raw_fields:
        if not isinstance(raw, dict):
            continue
        field_id = str(raw.get("id") or raw.get("slug") or "").strip()
        if not field_id:
            continue
        field_type = str(raw.get("type") or "text").strip().lower()
        if field_type not in {"text", "number", "boolean", "select"}:
            field_type = "text"
        label = str(raw.get("label") or raw.get("name") or field_id).strip()
        fields.append(
            {
                "id": field_id,
                "label": label,
                "type": field_type,
                "required": bool(raw.get("required")),
            }
        )
    return fields


def _strip_catalog_reserved_metadata_keys(metadata: dict[str, Any] | None) -> dict[str, Any] | None:
    if not metadata:
        return metadata
    reserved_keys = {
        "linea",
        "familia",
        "modelo",
        "descripcion",
        "descripcion_corta",
        "descripcion_larga",
        "precio_base",
    }
    filtered = {key: value for key, value in metadata.items() if key not in reserved_keys}
    return filtered or None


def _build_field_header_map(
    headers: list[str], fields: list[dict[str, Any]]
) -> dict[str, str]:
    normalized_headers = set(headers)
    mapping: dict[str, str] = {}
    for field in fields:
        for candidate in filter(None, [field.get("id"), field.get("label")]):
            normalized_candidate = _normalize_column_value(str(candidate))
            if normalized_candidate in normalized_headers:
                mapping[field["id"]] = normalized_candidate
                break
    return mapping


def _normalize_product_metadata_fields(raw_fields: Any) -> list[dict[str, Any]]:
    custom_fields: list[dict[str, Any]] = []
    if isinstance(raw_fields, list):
        for raw in raw_fields:
            if not isinstance(raw, dict):
                continue
            custom_fields.append(dict(raw))
    defaults = _default_product_metadata_fields()
    default_ids = {field["id"] for field in defaults}
    legacy_ids = {"descripcion"}
    filtered_custom_fields: list[dict[str, Any]] = []
    for field in custom_fields:
        field_id = str(field.get("id") or field.get("slug") or "").strip().lower()
        if field_id in default_ids or field_id in legacy_ids:
            continue
        filtered_custom_fields.append(field)
    return defaults + filtered_custom_fields


def _merge_default_product_metadata_field(payload: dict[str, Any]) -> dict[str, Any]:
    merged = dict(payload)
    merged["fields"] = _normalize_product_metadata_fields(payload.get("fields"))
    return merged


def _ensure_default_product_metadata_field(row: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(row, dict):
        return row
    return _merge_default_product_metadata_field(row)


BASE_HEADER_CANDIDATES = {
    "nombre": ["nombre", "name"],
    "descripcion_corta": ["descripcion_corta", "descripcion corta", "desc_corta", "short_description"],
    "descripcion_larga": ["descripcion_larga", "descripcion larga", "desc_larga", "descripcion", "description", "desc"],
    "precio_base": ["precio_base", "precio base", "precio", "price", "base_price"],
    "linea": ["linea", "línea", "line", "linea_nombre", "línea_nombre"],
    "familia": ["familia", "family", "familia_nombre"],
    "modelo": ["modelo", "model", "modelo_nombre"],
    "slug": ["slug"],
}

BASE_HEADER_KEYS = {
    _normalize_column_value(candidate)
    for values in BASE_HEADER_CANDIDATES.values()
    for candidate in values
    if candidate
}


def _pick_value(row: Mapping[str, str], candidates: list[str]) -> str | None:
    for candidate in candidates:
        normalized = _normalize_column_value(candidate)
        if not normalized:
            continue
        value = row.get(normalized)
        if value:
            return value
    return None


async def _read_import_rows(
    file: UploadFile,
) -> tuple[dict[str, str], list[dict[str, str]]]:
    content = await file.read()
    filename = file.filename or ""
    suffix = Path(filename).suffix.lower()
    headers_map: dict[str, str] = {}
    rows: list[dict[str, str]] = []
    if suffix in {".xlsx", ".xls"}:
        if load_workbook is None:
            raise RuntimeError("openpyxl_required")
        workbook = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
        try:
            sheet = workbook.active
            iterator = sheet.iter_rows(values_only=True)
            header_row = next(iterator, None)
            if not header_row:
                return headers_map, []
            normalized_headers: list[str] = []
            for header in header_row:
                normalized = _normalize_column_value(str(header or ""))
                if not normalized:
                    continue
                normalized_headers.append(normalized)
                headers_map.setdefault(normalized, str(header or ""))
            for row in iterator:
                row_map: dict[str, str] = {}
                for idx, header in enumerate(normalized_headers):
                    cell_value = row[idx] if idx < len(row) else None
                    row_map[header] = str(cell_value).strip() if cell_value is not None else ""
                if any(value for value in row_map.values()):
                    rows.append(row_map)
        finally:
            workbook.close()
    else:
        text = content.decode("utf-8-sig", errors="replace")
        reader = csv.DictReader(io.StringIO(text))
        fieldnames = reader.fieldnames or []
        normalized_headers: list[str] = []
        for header in fieldnames:
            normalized = _normalize_column_value(header)
            if not normalized:
                continue
            normalized_headers.append(normalized)
            headers_map.setdefault(normalized, header or "")
        for raw_row in reader:
            row_map: dict[str, str] = {}
            for header, normalized in zip(fieldnames, normalized_headers):
                raw_value = raw_row.get(header, "")
                row_map[normalized] = (raw_value or "").strip()
            if any(value for value in row_map.values()):
                rows.append(row_map)
    return headers_map, rows


def _build_error_payload(row: Mapping[str, str], headers_map: dict[str, str]) -> dict[str, str]:
    return {
        headers_map.get(key, key): value
        for key, value in row.items()
        if value
    }


@router.get("/contacts/search", response_model=CRMPersonaSearchResponse)
async def search_personas_legacy(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.read")),
    query: Annotated[str, Query(min_length=2, alias="q")],
    limit: Annotated[int, Query(ge=1, le=25)] = 8,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> CRMPersonaSearchResponse:
    rows = await repo.search_personas(
        organizacion_id=organizacion_id,
        query=query,
        limit=limit,
        offset=offset,
    )
    items: list[CRMPersonaSearchItem] = []
    for row in rows:
        contacto_id = _safe_uuid(row.get("id"))
        if not contacto_id:
            continue
        items.append(
            CRMPersonaSearchItem(
                id=contacto_id,
                nombre=row.get("nombre_completo"),
                correo=row.get("correo_secundario") or row.get("correo_institucional") or row.get("correo_principal") or row.get("correo"),
                telefono=row.get("telefono_movil_1_e164") or row.get("telefono_principal_e164") or row.get("telefono_e164"),
                empresa=row.get("company_name"),
            )
        )
    return CRMPersonaSearchResponse(items=items, limit=limit, offset=offset)


