@router.post("/personas/alta/validar", response_model=CRMPersonaAltaValidationResponse)
async def validate_persona_alta(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    payload: CRMPersonaAltaRequest,
) -> CRMPersonaAltaValidationResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    dedupe = payload.dedupe

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal):
        raise HTTPException(status_code=400, detail="correo_principal_required")
    if not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="telefono_principal_required")
    if contexto.modo in {"empresa_nueva", "persona_fisica_actividad_empresarial"}:
        if not cuenta:
            raise HTTPException(status_code=400, detail="cuenta_required")
    if contexto.modo == "empresa_existente" and not cuenta:
        raise HTTPException(status_code=400, detail="cuenta_required")
    existing_account: CRMAccount | None = None
    if cuenta and cuenta.cuenta_id:
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
    if contexto.modo == "empresa_existente" and not existing_account:
        raise HTTPException(status_code=400, detail="cuenta_id_required")
    if cuenta:
        cuenta = cuenta.model_copy(
            update={
                "rfc": _validate_persona_alta_rfc_length(
                    contexto=contexto,
                    cuenta=cuenta,
                    existing_account=existing_account,
                    rfc=cuenta.rfc,
                )
            }
        )
    persona_candidates, account_candidates, suggested_persona_id, suggested_account_id, requires_confirmation = (
        await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
        )
    )

    return CRMPersonaAltaValidationResponse(
        requiere_confirmacion=requires_confirmation,
        candidatos_persona=persona_candidates,
        candidatos_cuenta=account_candidates,
        sugerencia_persona_reutilizar_id=suggested_persona_id,
        sugerencia_cuenta_reutilizar_id=suggested_account_id,
    )


@router.post("/personas/alta", response_model=CRMPersonaAltaResponse, status_code=status.HTTP_201_CREATED)
async def create_persona_alta(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    payload: CRMPersonaAltaRequest,
) -> CRMPersonaAltaResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    relacion = payload.relacion
    extras = _persona_alta_normalize_extras(payload.extras)
    dedupe = payload.dedupe

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal):
        raise HTTPException(status_code=400, detail="correo_principal_required")
    if not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="telefono_principal_required")
    if contexto.modo in {"empresa_nueva", "persona_fisica_actividad_empresarial"}:
        if not cuenta:
            raise HTTPException(status_code=400, detail="cuenta_required")
    if contexto.modo == "empresa_existente" and not cuenta:
        raise HTTPException(status_code=400, detail="cuenta_required")
    existing_account: CRMAccount | None = None
    persona_candidates: list[dict[str, Any]] = []
    account_candidates: list[dict[str, Any]] = []
    reused_account_id: UUID | None = None
    dedupe_contacto_id: UUID | None = dedupe.persona_reutilizar_id if dedupe else None

    if dedupe and dedupe.cuenta_reutilizar_id and cuenta:
        cuenta = cuenta.model_copy(update={"cuenta_id": dedupe.cuenta_reutilizar_id})

    try:
        (
            persona_candidates,
            account_candidates,
            suggested_persona_id,
            suggested_account_id,
            requires_confirmation,
        ) = await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    if requires_confirmation:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "dedupe_confirmation_required",
                "message": "Se detectaron posibles duplicados. Confirma si deseas reutilizar o crear uno nuevo.",
                "candidatos_persona": persona_candidates,
                "candidatos_cuenta": account_candidates,
                "sugerencia_persona_reutilizar_id": str(suggested_persona_id) if suggested_persona_id else None,
                "sugerencia_cuenta_reutilizar_id": str(suggested_account_id) if suggested_account_id else None,
            },
        )

    if contexto.modo == "empresa_existente":
        if not cuenta or not cuenta.cuenta_id:
            raise HTTPException(status_code=400, detail="cuenta_id_required")
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
    elif cuenta and cuenta.cuenta_id:
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
        reused_account_id = existing_account.id
    elif suggested_account_id and cuenta:
        cuenta = cuenta.model_copy(update={"cuenta_id": suggested_account_id})
        reused_account_id = suggested_account_id
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=suggested_account_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            existing_account = CRMAccount.model_validate(account_row)
    if cuenta:
        cuenta = cuenta.model_copy(
            update={
                "rfc": _validate_persona_alta_rfc_length(
                    contexto=contexto,
                    cuenta=cuenta,
                    existing_account=existing_account,
                    rfc=cuenta.rfc,
                )
            }
        )

    contact_payload = _persona_alta_to_contact_payload(
        persona=persona,
        contexto=contexto,
        cuenta=cuenta,
        extras=extras,
        existing_account=existing_account,
    )

    try:
        if dedupe_contacto_id:
            contact_row = await repo.update_persona(
                organizacion_id=organizacion_id,
                persona_id=dedupe_contacto_id,
                payload={key: value for key, value in contact_payload.items() if value is not None},
            )
        else:
            contact_row = await repo.create_persona(
                organizacion_id=organizacion_id,
                payload={key: value for key, value in contact_payload.items() if value is not None},
            )
    except CRMRepositoryError as exc:
        detail = str(exc).lower()
        if "dedupe_confirmation_required" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "dedupe_confirmation_required",
                    "message": "Se detectaron posibles duplicados. Reutiliza uno existente antes de continuar.",
                    "candidatos_persona": persona_candidates,
                    "candidatos_cuenta": account_candidates,
                    "sugerencia_persona_reutilizar_id": str(suggested_persona_id) if suggested_persona_id else None,
                    "sugerencia_cuenta_reutilizar_id": str(suggested_account_id) if suggested_account_id else None,
                },
            ) from exc
        if "duplicate_rfc" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_account_detected",
                    "message": "La empresa ya existe con el mismo RFC.",
                },
            ) from exc
        if "duplicate_contact_method" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_contact_detected",
                    "message": "Ya existe un registro con el mismo correo o teléfono.",
                },
            ) from exc
        if "duplicate_account_detected" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_account_detected",
                    "message": "La empresa ya existe con el mismo correo, teléfono o RFC.",
                },
            ) from exc
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    persona_out = _safe_model_from_row(
        CRMPersona,
        contact_row,
        label="persona",
        extra_context={"persona_id": str(contact_row.get("id") or ""), "modo": contexto.modo},
    )
    account_out: CRMAccount | None = None
    relation_out: CRMCuentaPersonaRelacion | None = None

    if persona_out.cuenta_id:
        if cuenta and cuenta.cuenta_id and existing_account:
            account_patch = {
                key: value
                for key, value in _persona_alta_to_account_payload(
                    persona=persona,
                    contexto=contexto,
                    cuenta=cuenta,
                    extras=extras,
                    existing_account=existing_account,
                ).items()
                if value not in (None, "", {}, [])
            }
            if account_patch:
                try:
                    await repo.update_account(
                        organizacion_id=organizacion_id,
                        account_id=persona_out.cuenta_id,
                        payload=account_patch,
                    )
                except CRMRepositoryError as exc:
                    raise HTTPException(status_code=502, detail=str(exc)) from exc

        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=persona_out.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            account_out = _safe_model_from_row(
                CRMAccount,
                account_row,
                label="account",
                extra_context={"persona_id": str(persona_out.id), "cuenta_id": str(persona_out.cuenta_id), "modo": contexto.modo},
            )

        relation_defaults = {
            "rol_en_cuenta": (
                relacion.rol_en_cuenta
                if relacion and _persona_alta_clean_text(relacion.rol_en_cuenta)
                else ("dueno" if contexto.modo == "persona_fisica_actividad_empresarial" else "contacto_principal")
            ),
                "es_contacto_principal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_contacto_principal if relacion else True),
            "es_contacto_facturacion": relacion.es_contacto_facturacion if relacion else False,
            "es_representante_legal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_representante_legal if relacion else False),
            "activo": relacion.activo if relacion else True,
            "fecha_inicio": relacion.fecha_inicio.isoformat() if relacion and relacion.fecha_inicio else None,
            "fecha_fin": relacion.fecha_fin.isoformat() if relacion and relacion.fecha_fin else None,
            "notas": relacion.notas if relacion else None,
            "metadata": (
                {**relacion.metadata, "contexto_modo": contexto.modo}
                if relacion and relacion.metadata
                else {"contexto_modo": contexto.modo}
            ),
        }
        try:
            relation_row = await repo.upsert_persona_account_relation(
                organizacion_id=organizacion_id,
                persona_id=persona_out.id,
                cuenta_id=persona_out.cuenta_id,
                payload=relation_defaults,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        relation_out = _safe_model_from_row(
            CRMCuentaPersonaRelacion,
            relation_row,
            label="relation",
            extra_context={"persona_id": str(persona_out.id), "cuenta_id": str(persona_out.cuenta_id), "modo": contexto.modo},
        )

    return CRMPersonaAltaResponse(
        persona=persona_out,
        cuenta=account_out,
        relacion=relation_out,
        resumen={
            "modo": contexto.modo,
            "persona_id": str(persona_out.id),
            "cuenta_id": str(persona_out.cuenta_id) if persona_out.cuenta_id else None,
            "deduplicado": bool(dedupe_contacto_id),
            "contacto_reutilizado_id": str(dedupe_contacto_id) if dedupe_contacto_id else None,
            "cuenta_reutilizada_id": str(reused_account_id) if reused_account_id else None,
            "candidatos_persona": persona_candidates,
            "candidatos_cuenta": account_candidates,
        },
    )


@router.patch("/personas/{contacto_id}", response_model=CRMPersonaAltaResponse)
async def update_persona(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    contacto_id: UUID,
    payload: CRMPersonaEditRequest,
) -> CRMPersonaAltaResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    relacion = payload.relacion
    extras = _persona_alta_normalize_extras(payload.extras)
    dedupe = payload.dedupe

    try:
        existing_row = await repo.get_persona(
            organizacion_id=organizacion_id,
            persona_id=contacto_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not existing_row:
        raise HTTPException(status_code=404, detail="contacto_no_encontrado")
    await _require_record_owner_or_privileged(
        repo=repo,
        owner_user_id=_safe_uuid(existing_row.get("propietario_usuario_id")),
    )

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal):
        raise HTTPException(status_code=400, detail="correo_principal_required")
    if not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="telefono_principal_required")
    if contexto.modo in {"empresa_nueva", "persona_fisica_actividad_empresarial"}:
        if not cuenta:
            raise HTTPException(status_code=400, detail="cuenta_required")
    if contexto.modo == "empresa_existente" and not cuenta:
        raise HTTPException(status_code=400, detail="cuenta_required")
    existing_account: CRMAccount | None = None
    persona_candidates: list[dict[str, Any]] = []
    account_candidates: list[dict[str, Any]] = []
    reused_account_id: UUID | None = None
    dedupe_contacto_id: UUID | None = dedupe.persona_reutilizar_id if dedupe else None

    if dedupe and dedupe.cuenta_reutilizar_id and cuenta:
        cuenta = cuenta.model_copy(update={"cuenta_id": dedupe.cuenta_reutilizar_id})

    exclude_account_id = cuenta.cuenta_id if cuenta and cuenta.cuenta_id else None
    try:
        (
            persona_candidates,
            account_candidates,
            suggested_persona_id,
            suggested_account_id,
            requires_confirmation,
        ) = await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
            exclude_contacto_id=contacto_id,
            exclude_account_id=exclude_account_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    if requires_confirmation:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "dedupe_confirmation_required",
                "message": "Se detectaron posibles duplicados. Confirma si deseas reutilizar o crear uno nuevo.",
                "candidatos_persona": persona_candidates,
                "candidatos_cuenta": account_candidates,
                "sugerencia_persona_reutilizar_id": str(suggested_persona_id) if suggested_persona_id else None,
                "sugerencia_cuenta_reutilizar_id": str(suggested_account_id) if suggested_account_id else None,
            },
        )

    if not dedupe_contacto_id:
        dedupe_contacto_id = suggested_persona_id

    if contexto.modo == "empresa_existente":
        if not cuenta or not cuenta.cuenta_id:
            raise HTTPException(status_code=400, detail="cuenta_id_required")
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
    elif cuenta and cuenta.cuenta_id:
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
        reused_account_id = existing_account.id
    elif suggested_account_id and cuenta:
        cuenta = cuenta.model_copy(update={"cuenta_id": suggested_account_id})
        reused_account_id = suggested_account_id
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=suggested_account_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            existing_account = CRMAccount.model_validate(account_row)
    if cuenta:
        cuenta = cuenta.model_copy(
            update={
                "rfc": _validate_persona_alta_rfc_length(
                    contexto=contexto,
                    cuenta=cuenta,
                    existing_account=existing_account,
                    rfc=cuenta.rfc,
                )
            }
        )

    contact_payload = _persona_alta_to_contact_payload(
        persona=persona,
        contexto=contexto,
        cuenta=cuenta,
        extras=extras,
        existing_account=existing_account,
    )
    if contexto.modo == "solo_persona":
        contact_payload["cuenta_id"] = None
        contact_payload["company_name"] = None

    try:
        contact_row = await repo.update_persona(
            organizacion_id=organizacion_id,
            persona_id=contacto_id,
            payload=contact_payload,
        )
    except CRMRepositoryError as exc:
        detail = str(exc).lower()
        if "contacto_no_encontrado" in str(exc):
            raise HTTPException(status_code=404, detail="contacto_no_encontrado") from exc
        if "dedupe_confirmation_required" in detail:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "dedupe_confirmation_required",
                    "message": "Se detectaron posibles duplicados. Reutiliza uno existente antes de continuar.",
                    "candidatos_persona": persona_candidates,
                    "candidatos_cuenta": account_candidates,
                    "sugerencia_persona_reutilizar_id": str(suggested_persona_id) if suggested_persona_id else None,
                    "sugerencia_cuenta_reutilizar_id": str(suggested_account_id) if suggested_account_id else None,
                },
            ) from exc
        if (
            "duplicate_account_detected" in detail
            or "duplicate_contact_method" in detail
            or "duplicate_rfc" in detail
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "duplicate_account_detected",
                    "message": "La empresa ya existe con el mismo correo, teléfono o RFC.",
                },
            ) from exc
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    persona_out = _safe_model_from_row(
        CRMPersona,
        contact_row,
        label="persona",
        extra_context={"contacto_id": str(contacto_id), "modo": contexto.modo},
    )
    account_out: CRMAccount | None = None
    relation_out: CRMCuentaPersonaRelacion | None = None

    if persona_out.cuenta_id:
        # Si la UI mandó datos de cuenta, los aplicamos también sobre cuentas existentes.
        if cuenta and cuenta.cuenta_id and existing_account:
            account_patch = {
                key: value
                for key, value in _persona_alta_to_account_payload(
                    persona=persona,
                    contexto=contexto,
                    cuenta=cuenta,
                    extras=extras,
                    existing_account=existing_account,
                ).items()
                if value not in (None, "", {}, [])
            }
            if account_patch:
                try:
                    await repo.update_account(
                        organizacion_id=organizacion_id,
                        account_id=persona_out.cuenta_id,
                        payload=account_patch,
                    )
                except CRMRepositoryError as exc:
                    raise HTTPException(status_code=502, detail=str(exc)) from exc

        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=persona_out.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            account_out = _safe_model_from_row(
                CRMAccount,
                account_row,
                label="account",
                extra_context={"contacto_id": str(contacto_id), "cuenta_id": str(persona_out.cuenta_id), "modo": contexto.modo},
            )

        relation_defaults = {
            "rol_en_cuenta": (
                relacion.rol_en_cuenta
                if relacion and _persona_alta_clean_text(relacion.rol_en_cuenta)
                else ("dueno" if contexto.modo == "persona_fisica_actividad_empresarial" else "contacto_principal")
            ),
                "es_contacto_principal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_contacto_principal if relacion else True),
            "es_contacto_facturacion": relacion.es_contacto_facturacion if relacion else False,
            "es_representante_legal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_representante_legal if relacion else False),
            "activo": relacion.activo if relacion else True,
            "fecha_inicio": relacion.fecha_inicio.isoformat() if relacion and relacion.fecha_inicio else None,
            "fecha_fin": relacion.fecha_fin.isoformat() if relacion and relacion.fecha_fin else None,
            "notas": relacion.notas if relacion else None,
            "metadata": (
                {**relacion.metadata, "contexto_modo": contexto.modo}
                if relacion and relacion.metadata
                else {"contexto_modo": contexto.modo}
            ),
        }
        try:
            relation_row = await repo.upsert_persona_account_relation(
                organizacion_id=organizacion_id,
                persona_id=contacto_id,
                cuenta_id=persona_out.cuenta_id,
                payload=relation_defaults,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        relation_out = _safe_model_from_row(
            CRMCuentaPersonaRelacion,
            relation_row,
            label="relation",
            extra_context={"contacto_id": str(contacto_id), "cuenta_id": str(persona_out.cuenta_id), "modo": contexto.modo},
        )

    return CRMPersonaAltaResponse(
        persona=persona_out,
        cuenta=account_out,
        relacion=relation_out,
        resumen={
            "modo": contexto.modo,
            "persona_id": str(persona_out.id),
            "cuenta_id": str(persona_out.cuenta_id) if persona_out.cuenta_id else None,
            "deduplicado": bool(dedupe_contacto_id),
            "contacto_reutilizado_id": str(dedupe_contacto_id) if dedupe_contacto_id else None,
            "cuenta_reutilizada_id": str(reused_account_id) if reused_account_id else None,
            "candidatos_persona": persona_candidates,
            "candidatos_cuenta": account_candidates,
        },
    )


@router.post("/personas/{contacto_id}/merge", response_model=CRMPersonaMergeResponse)
async def merge_persona(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    contacto_id: UUID,
    payload: CRMPersonaMergeRequest,
) -> CRMPersonaMergeResponse:
    source_persona = await repo.get_persona_by_id(persona_id=str(contacto_id))
    if not source_persona:
        raise HTTPException(status_code=404, detail="persona_source_not_found")
    target_persona = await repo.get_persona_by_id(persona_id=str(payload.target_persona_id))
    if not target_persona:
        raise HTTPException(status_code=404, detail="persona_target_not_found")

    source_org = _safe_uuid(source_persona.get("organizacion_id"))
    target_org = _safe_uuid(target_persona.get("organizacion_id"))
    if source_org and source_org != organizacion_id:
        raise HTTPException(status_code=400, detail="persona_source_org_mismatch")
    if target_org and target_org != organizacion_id:
        raise HTTPException(status_code=400, detail="persona_target_org_mismatch")
    if str(source_persona.get("id") or "").strip() == str(target_persona.get("id") or "").strip():
        raise HTTPException(status_code=400, detail="persona_merge_same_record")

    source_id = _safe_uuid(source_persona.get("id"))
    target_id = _safe_uuid(target_persona.get("id"))
    if not source_id or not target_id:
        raise HTTPException(status_code=400, detail="persona_merge_invalid_id")

    def _pick_missing(target_value: Any, source_value: Any) -> Any:
        if target_value not in (None, "", [], {}):
            return target_value
        return source_value

    target_patch: dict[str, Any] = {}
    for key in (
        "nombre",
        "apellido_paterno",
        "apellido_materno",
        "nombre_completo",
        "correo",
        "correo_principal",
        "telefono",
        "telefono_e164",
        "telefono_principal_e164",
        "area",
        "rol_decision",
        "estado",
        "origen",
        "company_name",
        "notas",
        "necesidad_proposito",
        "persona_datos",
        "metadata",
    ):
        target_value = target_persona.get(key)
        source_value = source_persona.get(key)
        if key == "metadata":
            source_meta = source_value if isinstance(source_value, dict) else {}
            target_meta = target_value if isinstance(target_value, dict) else {}
            merged_meta = dict(source_meta)
            merged_meta.update(target_meta)
            merged_meta["merged_from_persona_id"] = str(source_id)
            merged_meta["merge_reason"] = "manual_merge"
            merged_meta["merge_status"] = "merged"
            target_patch[key] = merged_meta
            continue
        picked = _pick_missing(target_value, source_value)
        if picked not in (None, "", [], {}):
            target_patch[key] = picked
    target_patch.setdefault("estado", target_persona.get("estado") or "lead")
    target_patch["actualizado_en"] = datetime.now(timezone.utc).isoformat()
    try:
        updated_target_row = await repo.update_persona(
            organizacion_id=organizacion_id,
            persona_id=target_id,
            payload=target_patch,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    source_relations = await repo.list_persona_account_relations(
        organizacion_id=organizacion_id,
        persona_id=source_id,
        activo=None,
    )
    target_relations = await repo.list_persona_account_relations(
        organizacion_id=organizacion_id,
        persona_id=target_id,
        activo=None,
    )
    target_relations_by_account = {
        str(row.get("cuenta_id") or ""): row
        for row in target_relations
        if str(row.get("cuenta_id") or "").strip()
    }
    relations_moved = 0
    relations_updated = 0
    for relation in source_relations:
        account_id_raw = str(relation.get("cuenta_id") or "").strip()
        if not account_id_raw:
            continue
        target_relation = target_relations_by_account.get(account_id_raw)
        relation_payload = {
            "rol_en_cuenta": relation.get("rol_en_cuenta"),
            "es_contacto_principal": bool(relation.get("es_contacto_principal")),
            "es_contacto_facturacion": bool(relation.get("es_contacto_facturacion")),
            "es_representante_legal": bool(relation.get("es_representante_legal")),
            "activo": bool(relation.get("activo", True)),
            "fecha_inicio": relation.get("fecha_inicio"),
            "fecha_fin": relation.get("fecha_fin"),
            "notas": relation.get("notas"),
            "metadata": relation.get("metadata"),
        }
        if target_relation and target_relation.get("id"):
            merged_relation_payload = {
                "rol_en_cuenta": target_relation.get("rol_en_cuenta") or relation_payload["rol_en_cuenta"],
                "es_contacto_principal": bool(target_relation.get("es_contacto_principal")) or relation_payload["es_contacto_principal"],
                "es_contacto_facturacion": bool(target_relation.get("es_contacto_facturacion")) or relation_payload["es_contacto_facturacion"],
                "es_representante_legal": bool(target_relation.get("es_representante_legal")) or relation_payload["es_representante_legal"],
                "activo": bool(target_relation.get("activo", True)) or relation_payload["activo"],
                "fecha_inicio": target_relation.get("fecha_inicio") or relation_payload["fecha_inicio"],
                "fecha_fin": target_relation.get("fecha_fin") or relation_payload["fecha_fin"],
                "notas": target_relation.get("notas") or relation_payload["notas"],
                "metadata": {
                    **(relation_payload["metadata"] if isinstance(relation_payload["metadata"], dict) else {}),
                    **(target_relation.get("metadata") if isinstance(target_relation.get("metadata"), dict) else {}),
                    "merged_from_persona_id": str(source_id),
                },
            }
            try:
                await repo.update_persona_account_relation(
                    organizacion_id=organizacion_id,
                    persona_id=target_id,
                    relacion_id=_safe_uuid(target_relation["id"]),
                    payload=merged_relation_payload,
                )
                relations_updated += 1
            except CRMRepositoryError as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc
        else:
            relation_payload["metadata"] = {
                **(relation_payload["metadata"] if isinstance(relation_payload["metadata"], dict) else {}),
                "merged_from_persona_id": str(source_id),
            }
            try:
                await repo.create_persona_account_relation(
                    organizacion_id=organizacion_id,
                    persona_id=target_id,
                    payload={
                        key: value
                        for key, value in relation_payload.items()
                        if value not in (None, "", {}, [])
                    },
                )
                relations_moved += 1
            except CRMRepositoryError as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc
        try:
            await repo.delete_persona_account_relation(
                organizacion_id=organizacion_id,
                persona_id=source_id,
                relacion_id=_safe_uuid(relation["id"]),
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc

    opportunities_moved = 0
    offset = 0
    limit = 200
    while True:
        rows, _ = await repo.list_opportunities(
            organizacion_id=organizacion_id,
            limit=limit,
            offset=offset,
            persona_id=source_id,
            include_contact_rows=False,
        )
        if not rows:
            break
        for opportunity in rows:
            opportunity_id = _safe_uuid(opportunity.get("id"))
            if not opportunity_id:
                continue
            metadata = _ensure_dict(opportunity.get("metadata"))
            metadata["merged_from_persona_id"] = str(source_id)
            metadata["merged_into_persona_id"] = str(target_id)
            metadata["merge_reason"] = "manual_merge"
            patch = {
                "contacto_principal_id": str(target_id),
                "metadata": metadata,
            }
            if not str(opportunity.get("contacto_nombre") or "").strip():
                target_name = _clean_text(target_persona.get("nombre_completo")) or _clean_text(target_persona.get("company_name"))
                if target_name:
                    patch["contacto_nombre"] = target_name
            try:
                await repo.update_opportunity(
                    organizacion_id=organizacion_id,
                    oportunidad_id=opportunity_id,
                    payload=patch,
                )
                opportunities_moved += 1
            except (CRMRepositoryError, ValueError) as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc
        if len(rows) < limit:
            break
        offset += limit

    source_patch = {
        "estado": "fusionado",
        "notas": "Fusionado manualmente con " + str(target_id),
        "metadata": {
            **_ensure_dict(source_persona.get("metadata")),
            "merged_into_persona_id": str(target_id),
            "merge_status": "archived",
            "merge_reason": "manual_merge",
        },
    }
    try:
        await repo.update_persona(
            organizacion_id=organizacion_id,
            persona_id=source_id,
            payload=source_patch,
        )
        await repo.mark_persona_merged(
            organizacion_id=organizacion_id,
            persona_id=source_id,
            merged_into_persona_id=target_id,
            merge_metadata={
                "merge_reason": "manual_merge",
                "merged_into_persona_id": str(target_id),
                "source_persona_id": str(source_id),
            },
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    try:
        merged_persona = await repo.get_persona_by_id(persona_id=str(target_id))
        if not merged_persona:
            raise HTTPException(status_code=502, detail="persona_merge_reload_failed")
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return CRMPersonaMergeResponse(
        source_persona_id=source_id,
        target_persona_id=target_id,
        merged_persona=CRMPersona.model_validate(merged_persona),
        opportunities_moved=opportunities_moved,
        relations_moved=relations_moved,
        relations_updated=relations_updated,
    )


@router.post("/personas/{contacto_id}/validar", response_model=CRMPersonaAltaValidationResponse)
async def validate_persona_update(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    contacto_id: UUID,
    payload: CRMPersonaEditRequest,
) -> CRMPersonaAltaValidationResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    dedupe = payload.dedupe

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal):
        raise HTTPException(status_code=400, detail="correo_principal_required")
    if not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="telefono_principal_required")
    if contexto.modo in {"empresa_nueva", "persona_fisica_actividad_empresarial"}:
        if not cuenta:
            raise HTTPException(status_code=400, detail="cuenta_required")
    if contexto.modo == "empresa_existente" and not cuenta:
        raise HTTPException(status_code=400, detail="cuenta_required")
    existing_account: CRMAccount | None = None
    if cuenta and cuenta.cuenta_id:
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
    if contexto.modo == "empresa_existente" and not existing_account:
        raise HTTPException(status_code=400, detail="cuenta_id_required")
    if cuenta:
        cuenta = cuenta.model_copy(
            update={
                "rfc": _validate_persona_alta_rfc_length(
                    contexto=contexto,
                    cuenta=cuenta,
                    existing_account=existing_account,
                    rfc=cuenta.rfc,
                )
            }
        )

    exclude_account_id = cuenta.cuenta_id if cuenta and cuenta.cuenta_id else None
    persona_candidates, account_candidates, suggested_persona_id, suggested_account_id, requires_confirmation = (
        await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
            exclude_contacto_id=contacto_id,
            exclude_account_id=exclude_account_id,
        )
    )

    return CRMPersonaAltaValidationResponse(
        requiere_confirmacion=requires_confirmation,
        candidatos_persona=persona_candidates,
        candidatos_cuenta=account_candidates,
        sugerencia_persona_reutilizar_id=suggested_persona_id,
        sugerencia_cuenta_reutilizar_id=suggested_account_id,
    )


@router.get("/personas/{contacto_id}/dedupe", response_model=CRMDedupePreviewResponse)
async def get_persona_dedupe_preview(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.read")),
    contacto_id: UUID,
) -> CRMDedupePreviewResponse:
    try:
        candidates, suggested_id, requires_confirmation = await _persona_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            persona_id=contacto_id,
        )
    except CRMRepositoryError as exc:
        if "persona_no_encontrada" in str(exc):
            raise HTTPException(status_code=404, detail="persona_no_encontrada_para_dedupe") from exc
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return CRMDedupePreviewResponse(
        requiere_confirmacion=requires_confirmation,
        candidatos=[CRMDedupeCandidate.model_validate(row) for row in candidates],
        sugerencia_reutilizar_id=suggested_id,
    )


