@router.get("/contacts/list", response_model=list[CRMPersonaListRow])
async def get_personas_list_legacy(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("contacts.read")),
    organizacion_id: UUID = Depends(require_organizacion_id),
    user_token: str = Depends(require_user_token),
    limit: Annotated[int, Query(ge=1, le=500)] = DEFAULT_CONTACTS_LIMIT,
    search: str | None = Query(default=None, min_length=1),
    offset: Annotated[int, Query(ge=0)] = 0,
    propietario: UUID | None = Query(default=None),
    date_from: Annotated[datetime | None, Query(alias="from")] = None,
    date_to: datetime | None = None,
    origen: str | None = Query(default=None),
    puesto: str | None = Query(default=None),
    rol_decision: str | None = Query(default=None),
    estado_contacto: str | None = Query(default=None),
    captura: str | None = Query(default=None),
    ligado: str | None = Query(default=None),
    tipo_cuenta: str | None = Query(default=None),
    tamano: str | None = Query(default=None),
    clasificacion: str | None = Query(default=None),
    cuenta_from: Annotated[datetime | None, Query(alias="cuenta_from")] = None,
    cuenta_to: Annotated[datetime | None, Query(alias="cuenta_to")] = None,
    fecha_incorporacion_from: Annotated[datetime | None, Query(alias="fecha_incorporacion_from")] = None,
    fecha_incorporacion_to: Annotated[datetime | None, Query(alias="fecha_incorporacion_to")] = None,
    fusionada: str | None = Query(default=None),
    pais: str | None = Query(default=None),
    estado_direccion: str | None = Query(default=None),
    municipio: str | None = Query(default=None),
) -> list[CRMPersonaListRow]:
    try:
        rows = await repo.personas_list(
            usuario_token=user_token,
            organizacion_id=organizacion_id,
            limit=limit,
            offset=offset,
            search=search,
            propietario=propietario,
            date_from=date_from,
            date_to=date_to,
            origen=origen,
            puesto=puesto,
            rol_decision=rol_decision,
            estado_contacto=estado_contacto,
            captura=captura,
            ligado=ligado,
            tipo_cuenta=tipo_cuenta,
            tamano=tamano,
            clasificacion=clasificacion,
            cuenta_from=cuenta_from,
            cuenta_to=cuenta_to,
            fecha_incorporacion_from=fecha_incorporacion_from,
            fecha_incorporacion_to=fecha_incorporacion_to,
            fusionada=fusionada,
            pais=pais,
            estado_direccion=estado_direccion,
            municipio=municipio,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    current_user_id, can_view_all_sensitive = await _resolve_sensitive_access_context(
        repo=repo,
        permission_code="contacts.view_sensitive_unowned",
    )
    payloads: list[dict[str, Any]] = []
    persona_ids = [
        persona_id
        for persona_id in (_safe_uuid(row.get("contacto_id") or row.get("id")) for row in rows)
        if persona_id
    ]
    relations_by_persona_id: dict[str, dict[str, Any]] = {}
    if persona_ids:
        try:
            account_relations = await repo.list_persona_account_relations_by_persona_ids(
                organizacion_id=organizacion_id,
                persona_ids=persona_ids,
            )
            for relation in account_relations:
                persona_key = str(relation.get("persona_id") or "").strip()
                if persona_key and persona_key not in relations_by_persona_id:
                    relations_by_persona_id[persona_key] = relation
        except (CRMRepositoryError, AttributeError):
            relations_by_persona_id = {}
    for row in rows:
        normalized_row = dict(row)
        persona_key = str(normalized_row.get("contacto_id") or normalized_row.get("id") or "").strip()
        relation = relations_by_persona_id.get(persona_key)
        if relation and not normalized_row.get("cuenta_id"):
            normalized_row["cuenta_id"] = relation.get("cuenta_id")
        owner_user_id = _contact_owner_user_id(row)
        persona_id = _safe_uuid(row.get("contacto_id") or row.get("id"))
        can_view_sensitive_fields = await _can_view_contact_sensitive_fields(
            repo=repo,
            persona_id=persona_id,
            owner_user_id=owner_user_id,
            current_user_id=current_user_id,
            can_view_all=can_view_all_sensitive,
        )
        payloads.append(
            _apply_contact_visibility_mask(
                normalized_row,
                can_view_sensitive_fields=can_view_sensitive_fields,
            )
        )
    return [CRMPersonaListRow.model_validate(row) for row in payloads]


