@router.post("/contactos/{contacto_id}/reasignar", response_model=CRMReassignContactResponse)
async def reassign_persona_legacy(
    *,
    organizacion_id: UUID = Depends(require_organizacion_id),
    contacto_id: UUID,
    payload: CRMReassignContactPayload,
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
) -> CRMReassignContactResponse:
    if usuario_id is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")

    repo = CRMRepository(user_token=user_token)
    can_any = await repo.current_user_has_perm(codigo="contacts.reassign.any")
    can_team = await repo.current_user_has_perm(codigo="contacts.reassign.team")
    if not can_any and not can_team:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")

    if not can_any:
        allowed = await repo.is_in_current_user_scope(usuario_id=payload.propietario_usuario_id)
        if not allowed:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="target_out_of_scope")

    vendedor = await repo.get_employee_vendor(
        organizacion_id=organizacion_id,
        usuario_id=payload.propietario_usuario_id,
    )
    if not isinstance(vendedor, dict) or not vendedor.get("es_vendedor"):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="vendedor_invalid")

    contacto = await repo.get_persona(
        organizacion_id=organizacion_id,
        persona_id=contacto_id,
    )
    if not contacto:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="contacto_not_found")

    await repo.update_persona(
        organizacion_id=organizacion_id,
        persona_id=contacto_id,
        payload={"propietario_usuario_id": str(payload.propietario_usuario_id)},
    )

    oportunidad_id: UUID | None = payload.oportunidad_id
    if oportunidad_id is None:
        maybe = await repo.get_contact_opportunity(contact_id=contacto_id)
        if isinstance(maybe, dict):
            try:
                oportunidad_id = UUID(str(maybe.get("id")))
            except (TypeError, ValueError):
                oportunidad_id = None

    conversacion_id: UUID | None = payload.conversacion_id
    if conversacion_id is None:
        service_repo = CRMRepository()
        resolved = await service_repo.get_latest_conversation_id_by_contact(
            organizacion_id=organizacion_id,
            contacto_id=contacto_id,
        )
        if resolved:
            try:
                conversacion_id = UUID(str(resolved))
            except (TypeError, ValueError):
                conversacion_id = None

    oportunidad_actualizada = False
    if payload.alinear_oportunidad and oportunidad_id:
        await repo.update_opportunity(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
            payload={"asignado_a_usuario_id": str(payload.propietario_usuario_id)},
        )
        oportunidad_actualizada = True

    conversacion_actualizada = False
    if payload.alinear_conversacion and conversacion_id:
        service_repo = CRMRepository()
        await service_repo.update_conversation(
            conversation_id=str(conversacion_id),
            patch={"asignado_a_usuario_id": str(payload.propietario_usuario_id)},
        )
        conversacion_actualizada = True

    metadata: dict[str, Any] = {"actor_id": str(usuario_id)}
    if payload.motivo:
        metadata["motivo"] = payload.motivo
    if conversacion_id:
        await repo.insert_sales_assignment_audit(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
            vendedor_id=payload.propietario_usuario_id,
            conversation_id=str(conversacion_id),
            persona_id=str(contacto_id),
            trigger="manual_reassign_contact",
            metadata=metadata,
            canal="panel",
        )
    else:
        logger.warning(
            "crm.contact_reassign.audit_skipped_no_conversation",
            extra={
                "organizacion_id": str(organizacion_id),
                "contacto_id": str(contacto_id),
                "oportunidad_id": str(oportunidad_id) if oportunidad_id else None,
                "actor_id": str(usuario_id),
            },
        )

    return CRMReassignContactResponse(
        contacto_id=contacto_id,
        propietario_usuario_id=payload.propietario_usuario_id,
        oportunidad_id=oportunidad_id,
        conversacion_id=conversacion_id,
        oportunidad_actualizada=oportunidad_actualizada,
        conversacion_actualizada=conversacion_actualizada,
    )


@router.post("/personas/{persona_id}/reasignar", response_model=CRMReassignContactResponse)
async def reassign_persona(
    *,
    organizacion_id: UUID = Depends(require_organizacion_id),
    persona_id: UUID,
    payload: CRMReassignContactPayload,
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
) -> CRMReassignContactResponse:
    return await reassign_persona_legacy(
        organizacion_id=organizacion_id,
        contacto_id=persona_id,
        payload=payload,
        user_token=user_token,
        usuario_id=usuario_id,
    )


@router.get("/inbox/summary", response_model=CRMInboxSummary)
async def get_inbox_summary(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ver_inbox")),
    user_token: str = Depends(require_user_token),
) -> CRMInboxSummary:
    row = await repo.inbox_summary(usuario_token=user_token)
    folders_payload = row.get("folders") if isinstance(row, dict) else None
    folders: list[CRMInboxFolder] = []
    if isinstance(folders_payload, list):
        for entry in folders_payload:
            if isinstance(entry, dict) and entry.get("id"):
                folders.append(
                    CRMInboxFolder(
                        id=str(entry.get("id")),
                        label=entry.get("label"),
                        count=int(entry.get("count") or 0),
                    )
                )
    return CRMInboxSummary(
        total=int(row.get("total") or 0),
        unread=int(row.get("unread") or 0),
        awaiting=int(row.get("awaiting") or 0),
        folders=folders,
    )


@router.get("/inbox/threads", response_model=list[CRMInboxThread])
async def get_inbox_threads(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ver_inbox")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    estado: str | None = Query(default=None, max_length=50),
    source: str | None = Query(default=None, max_length=80),
    channel: str | None = Query(default=None, max_length=30),
    date: str | None = Query(default=None, max_length=20),
    batch_id: UUID | None = Query(default=None),
    campana_id: UUID | None = Query(default=None),
    asignado_id: UUID | None = Query(default=None),
    limit: Annotated[int, Query(ge=1, le=200)] = 25,
    offset: Annotated[int, Query(ge=0)] = 0,
    message_limit: Annotated[int, Query(ge=1, le=50)] = 20,
    enrich: bool = Query(default=False),
) -> list[CRMInboxThread]:
    request_start = time.perf_counter()
    stage_timings: dict[str, float] = {}
    enrich_requested = bool(enrich)
    source_requested = _clean_text(source)
    source_for_repo = None if source_requested == "publicidad_whatsapp" else source
    high_demand_mode = await high_demand_controller.current_mode() if enrich_requested else {"active": False}
    # El enriquecimiento diferido solo aplica a listados interactivos. El detalle
    # de un hilo visible y la vista filtrada de publicidad WhatsApp deben seguir
    # resolviéndose con enrich completo para preservar contrato visual.
    defer_enrichment_due_to_high_demand = bool(
        enrich_requested
        and limit > 1
        and source_requested != "publicidad_whatsapp"
        and bool(high_demand_mode.get("active"))
        and bool(getattr(settings, "high_demand_inbox_enrichments_force_defer", True))
    )
    effective_enrich = enrich_requested and not defer_enrichment_due_to_high_demand
    effective_timezone, timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    date_from, date_to = _resolve_inbox_date_filter_range(
        date_filter=date,
        timezone_name=effective_timezone,
    )
    cache_key = _build_inbox_threads_cache_key(
        {
            "version": "geo_v3",
            "org": str(organizacion_id),
            "user": user_token,
            "estado": estado or "",
            "source_requested": source_requested or "",
            "source_repo": _clean_text(source_for_repo) or "",
            "channel": _clean_text(channel) or "",
            "date": (date or "").strip().lower(),
            "date_from": date_from.isoformat() if date_from else "",
            "date_to": date_to.isoformat() if date_to else "",
            "batch_id": str(batch_id) if batch_id else "",
            "campana_id": str(campana_id) if campana_id else "",
            "asignado_id": str(asignado_id) if asignado_id else "",
            "limit": limit,
            "offset": offset,
            "message_limit": message_limit,
            "enrich": effective_enrich,
            "enrich_requested": enrich_requested,
            "defer_enrichment_due_to_high_demand": defer_enrichment_due_to_high_demand,
        }
    )
    cache_lookup_start = time.perf_counter()
    cached_threads = await _read_inbox_threads_cache(cache_key)
    stage_timings["cache_lookup_ms"] = round((time.perf_counter() - cache_lookup_start) * 1000, 2)
    if cached_threads is not None:
        total_duration_ms = (time.perf_counter() - request_start) * 1000
        stage_timings["total_ms"] = round(total_duration_ms, 2)
        await _record_inbox_threads_metrics(duration_ms=total_duration_ms, cache_hit=True)
        await _record_inbox_threads_stage_metrics(stage_timings=stage_timings)
        logger.info(
            "crm.inbox.threads.cache_hit",
            extra={
                "duration_ms": round(total_duration_ms, 2),
                "rows": len(cached_threads),
                "estado": estado,
                "source": source_requested,
                "channel": channel,
                "date": date,
                "effective_timezone": effective_timezone,
                "timezone_source": timezone_source,
                "has_batch": bool(batch_id),
                "has_campana": bool(campana_id),
                "limit": limit,
                "offset": offset,
                "enrich_requested": enrich_requested,
                "enrich_effective": effective_enrich,
                "enrich_deferred_due_to_high_demand": defer_enrichment_due_to_high_demand,
                "stages": stage_timings,
            },
        )
        return [thread for thread in cached_threads if isinstance(thread, CRMInboxThread)]

    start = time.perf_counter()
    rows = await repo.inbox_threads(
        usuario_token=user_token,
        estado=estado,
        source=source_for_repo,
        channel=channel,
        batch_id=batch_id,
        campana_id=campana_id,
        asignado_id=asignado_id,
        date_from=date_from,
        date_to=date_to,
        limit=limit,
        offset=offset,
        message_limit=message_limit,
    )
    for row in rows:
        if isinstance(row, dict):
            _apply_persisted_inbox_context(row)
            _apply_inbox_phone_location(row)
    duration_ms = (time.perf_counter() - start) * 1000
    stage_timings["rpc_threads_ms"] = round(duration_ms, 2)
    log_payload = {
        "duration_ms": round(duration_ms, 2),
        "rows": len(rows),
        "estado": estado,
        "source": source_requested,
        "channel": channel,
        "date": date,
        "effective_timezone": effective_timezone,
        "timezone_source": timezone_source,
        "has_batch": bool(batch_id),
        "has_campana": bool(campana_id),
        "limit": limit,
        "offset": offset,
        "enrich_requested": enrich_requested,
        "enrich_effective": effective_enrich,
        "enrich_deferred_due_to_high_demand": defer_enrichment_due_to_high_demand,
    }
    if duration_ms >= 700:
        logger.warning("crm.inbox.threads.slow_query", extra=log_payload)
    else:
        logger.info("crm.inbox.threads.query", extra=log_payload)

    if source_requested == "publicidad_whatsapp" and not enrich_requested:
        raise HTTPException(
            status_code=400,
            detail="inbox_threads_enrich_required_for_publicidad_whatsapp",
        )

    contact_profile_name_map: dict[str, str] = {}
    contact_phone_map: dict[str, str] = {}
    contact_state_name_map: dict[str, str] = {}
    contact_city_name_map: dict[str, str] = {}
    contact_country_code_map: dict[str, str] = {}
    contact_country_name_map: dict[str, str] = {}
    contact_lada_map: dict[str, str] = {}
    missing_contact_name_ids: set[UUID] = set()
    missing_contact_data_ids: set[UUID] = set()
    missing_contact_location_ids: set[UUID] = set()

    if not effective_enrich:
        conversation_ids = [
            _clean_text(row.get("conversacion_id"))
            for row in rows
            if _clean_text(row.get("conversacion_id"))
        ]
        if conversation_ids:
            try:
                wa_atribucion_rows = await repo.worker_list_whatsapp_atribucion_events_by_conversations(
                    organizacion_id=organizacion_id,
                    conversation_ids=conversation_ids,
                )
            except CRMRepositoryError:
                wa_atribucion_rows = []
            wa_atribucion_by_conversation: dict[str, dict[str, Any]] = {}
            for event_row in wa_atribucion_rows:
                conversation_id_value = _clean_text(event_row.get("conversacion_id"))
                if not conversation_id_value or conversation_id_value in wa_atribucion_by_conversation:
                    continue
                wa_atribucion_by_conversation[conversation_id_value] = event_row
            if wa_atribucion_by_conversation:
                for row in rows:
                    conversacion_value = _clean_text(row.get("conversacion_id"))
                    if not conversacion_value:
                        continue
                    conversation_attribution = wa_atribucion_by_conversation.get(conversacion_value)
                    if not isinstance(conversation_attribution, dict):
                        continue
                    current_source = _clean_text(row.get("source"))
                    if not current_source or current_source in {
                        "prospeccion",
                        "prospeccion_whatsapp",
                        "whatsapp",
                        "assistant",
                        "whatsapp_inbound",
                    }:
                        row["source"] = "publicidad_whatsapp"
                    row["source_detail"] = {
                        "canal_publicitario": _clean_text(conversation_attribution.get("canal_publicitario")),
                        "campana_publicitaria": _clean_text(
                            conversation_attribution.get("campana_publicitaria")
                        ),
                        "adset": _clean_text(conversation_attribution.get("adset")),
                        "anuncio": _clean_text(conversation_attribution.get("anuncio")),
                        "regla_id": _clean_text(conversation_attribution.get("regla_id")),
                        "atribuido_en": _clean_text(conversation_attribution.get("creado_en")),
                    }
        for row in rows:
            if not isinstance(row, dict):
                continue
            contact_id_value = _clean_text(row.get("contacto_id"))
            if not contact_id_value:
                continue
            if contact_profile_name_map.get(contact_id_value) and not _clean_text(row.get("contacto_profile_name")):
                row["contacto_profile_name"] = contact_profile_name_map[contact_id_value]
            if contact_phone_map.get(contact_id_value) and not _clean_text(row.get("contacto_telefono")):
                row["contacto_telefono"] = contact_phone_map[contact_id_value]
            if contact_state_name_map.get(contact_id_value) and not _clean_text(row.get("contacto_state_name")):
                row["contacto_state_name"] = contact_state_name_map[contact_id_value]
            if contact_city_name_map.get(contact_id_value) and not _clean_text(row.get("contacto_city_name")):
                row["contacto_city_name"] = contact_city_name_map[contact_id_value]
            if contact_country_code_map.get(contact_id_value) and not _clean_text(row.get("contacto_country_code")):
                row["contacto_country_code"] = contact_country_code_map[contact_id_value]
            if contact_country_name_map.get(contact_id_value) and not _clean_text(row.get("contacto_country_name")):
                row["contacto_country_name"] = contact_country_name_map[contact_id_value]
            if contact_lada_map.get(contact_id_value) and not _clean_text(row.get("contacto_lada")):
                row["contacto_lada"] = contact_lada_map[contact_id_value]
            _apply_inbox_phone_location(row)
        validate_start = time.perf_counter()
        result_threads = [CRMInboxThread.model_validate(row) for row in rows]
        stage_timings["model_validate_ms"] = round((time.perf_counter() - validate_start) * 1000, 2)
        stage_timings["enrich_skipped"] = 1.0
        if defer_enrichment_due_to_high_demand:
            stage_timings["enrich_deferred_due_to_high_demand"] = 1.0
        cache_write_start = time.perf_counter()
        await _write_inbox_threads_cache(cache_key, result_threads)
        stage_timings["cache_write_ms"] = round((time.perf_counter() - cache_write_start) * 1000, 2)
        total_duration_ms = (time.perf_counter() - request_start) * 1000
        stage_timings["total_ms"] = round(total_duration_ms, 2)
        await _record_inbox_threads_metrics(duration_ms=total_duration_ms, cache_hit=False)
        await _record_inbox_threads_stage_metrics(stage_timings=stage_timings)
        logger.info(
            "crm.inbox.threads.base_only",
            extra={
                "rows": len(rows),
                "result_rows": len(result_threads),
                "source": source_requested,
                "limit": limit,
                "offset": offset,
                "enrich_requested": enrich_requested,
                "enrich_effective": effective_enrich,
                "enrich_deferred_due_to_high_demand": defer_enrichment_due_to_high_demand,
                "stages": stage_timings,
            },
        )
        return result_threads
    batch_ids: set[str] = set()
    campana_ids: set[str] = set()
    template_ids: set[str] = set()
    template_slugs: set[str] = set()
    should_resolve_whatsapp_hints = bool(
        limit <= 1
        or source_requested in {"publicidad_whatsapp", "prospeccion", "prospeccion_whatsapp"}
    )
    thread_prospeccion_hints: dict[
        str, tuple[str | None, str | None, str | None, str | None, str | None]
    ] = {}
    thread_channel_map: dict[str, str] = {}
    thread_phone_map: dict[str, str | None] = {}
    thread_contact_map: dict[str, str | None] = {}

    thread_scan_start = time.perf_counter()
    for row in rows:
        conversacion_id = _clean_text(row.get("conversacion_id"))
        if not conversacion_id:
            continue
        thread_channel_map[conversacion_id] = (_clean_text(row.get("canal")) or "").lower()
        thread_phone_map[conversacion_id] = _clean_text(row.get("contacto_telefono"))
        thread_contact_map[conversacion_id] = _clean_text(row.get("contacto_id"))
        if not _clean_text(row.get("contacto_nombre")):
            contacto_uuid = _safe_uuid(row.get("contacto_id"))
            if contacto_uuid:
                missing_contact_name_ids.add(contacto_uuid)
                missing_contact_data_ids.add(contacto_uuid)
        if not _clean_text(row.get("contacto_telefono")):
            contacto_uuid = _safe_uuid(row.get("contacto_id"))
            if contacto_uuid:
                missing_contact_data_ids.add(contacto_uuid)
        if not (
            _clean_text(row.get("contacto_state_name"))
            and _clean_text(row.get("contacto_city_name"))
            and _clean_text(row.get("contacto_country_code"))
            and _clean_text(row.get("contacto_country_name"))
            and _clean_text(row.get("contacto_lada"))
        ):
            contacto_uuid = _safe_uuid(row.get("contacto_id"))
        else:
            contacto_uuid = None
        if contacto_uuid:
            missing_contact_location_ids.add(contacto_uuid)
        batch_value = _clean_text(row.get("batch_id"))
        campana_value = _clean_text(row.get("campana_id"))
        (
            batch_hint,
            campana_hint,
            template_id_hint,
            template_slug_hint,
            template_label_hint,
        ) = _extract_thread_prospeccion_hints(row)
        if not batch_value and batch_hint and _safe_uuid(batch_hint):
            batch_value = batch_hint
        if not campana_value and campana_hint and _safe_uuid(campana_hint):
            campana_value = campana_hint
        if batch_value:
            batch_ids.add(batch_value)
        if campana_value:
            campana_ids.add(campana_value)
        thread_prospeccion_hints[conversacion_id] = (
            batch_hint,
            campana_hint,
            template_id_hint,
            template_slug_hint,
            template_label_hint,
        )
        if template_id_hint and _safe_uuid(template_id_hint):
            template_ids.add(template_id_hint)
        if template_slug_hint:
            template_slugs.add(template_slug_hint)
    contact_fallback_start = time.perf_counter()
    if missing_contact_data_ids or missing_contact_location_ids:
        lookup_ids = sorted(missing_contact_data_ids | missing_contact_location_ids, key=str)
        try:
            contacts_rows = await repo.get_contacts_by_ids(
                organizacion_id=organizacion_id,
                contacto_ids=lookup_ids,
            )
        except CRMRepositoryError:
            contacts_rows = []
        for contact_row in contacts_rows:
            contact_id_value = _clean_text(contact_row.get("id"))
            if not contact_id_value:
                continue
            contact_data = _ensure_dict(
                contact_row.get("persona_datos") or contact_row.get("contacto_datos"),
                default={},
            )
            profile_name = _clean_text(contact_data.get("profile_name"))
            if profile_name:
                contact_profile_name_map[contact_id_value] = profile_name
            phone_value = _clean_text(contact_row.get("telefono_e164"))
            if phone_value:
                contact_phone_map[contact_id_value] = phone_value
            state_name = _clean_text(contact_row.get("entidad"))
            city_name = _clean_text(contact_row.get("municipio") or contact_row.get("localidad"))
            country_code = _clean_text(contact_row.get("pais"))
            if state_name:
                contact_state_name_map[contact_id_value] = state_name
            if city_name:
                contact_city_name_map[contact_id_value] = city_name
            if country_code:
                contact_country_code_map[contact_id_value] = country_code.upper()
                if country_code.upper() == "MX":
                    contact_country_name_map[contact_id_value] = "Mexico"
                else:
                    contact_country_name_map[contact_id_value] = country_code.upper()
            if phone_value:
                location = leads_geo.phone_location_from_number(phone_value)
                if location.lada:
                    contact_lada_map[contact_id_value] = location.lada
    stage_timings["contact_fallback_ms"] = round(
        (time.perf_counter() - contact_fallback_start) * 1000, 2
    )
    stage_timings["thread_scan_ms"] = round((time.perf_counter() - thread_scan_start) * 1000, 2)

    # Fallback costoso: solo se resuelve en detalle de hilo o vistas enfocadas en
    # prospección/publicidad. En el listado general priorizamos latencia y
    # confiamos en inbox_context / snapshot persistidos.
    whatsapp_phone_cache: dict[str, tuple[str | None, str | None, str | None, str | None, str | None]] = {}
    phones_needing_fallback: set[str] = set()
    if should_resolve_whatsapp_hints:
        for conversacion_id, hints in list(thread_prospeccion_hints.items()):
            batch_hint, campana_hint, template_id_hint, template_slug_hint, _template_label_hint = hints
            # Aunque exista template_id, seguimos buscando fallback por telefono cuando
            # no hay slug/campana/lote; el id puede ser historico y no resoluble.
            if batch_hint or campana_hint or template_slug_hint:
                continue
            if thread_channel_map.get(conversacion_id) != "whatsapp":
                continue
            phone_value = thread_phone_map.get(conversacion_id)
            if not phone_value:
                contacto_id_value = thread_contact_map.get(conversacion_id)
                if contacto_id_value:
                    phone_value = contact_phone_map.get(contacto_id_value)
            if phone_value:
                phones_needing_fallback.add(phone_value)

    phones_to_lookup: list[str] = []
    for phone_value in sorted(phones_needing_fallback):
        cached_hint = await _read_whatsapp_envio_hint_cache(phone_value)
        if cached_hint is not None and not (any(cached_hint[:4]) or cached_hint[4]):
            cached_hint = None
        if cached_hint is not None:
            whatsapp_phone_cache[phone_value] = cached_hint
        else:
            phones_to_lookup.append(phone_value)

    fallback_lookup_start = time.perf_counter()
    if should_resolve_whatsapp_hints and phones_to_lookup:
        phone_candidates_map = {
            phone_value: _whatsapp_phone_lookup_candidates(phone_value)
            for phone_value in phones_to_lookup
        }
        all_lookup_candidates: set[str] = set()
        for candidates in phone_candidates_map.values():
            all_lookup_candidates.update(candidates)

        latest_envios_by_phone: dict[str, dict[str, Any]] = {}
        if all_lookup_candidates:
            try:
                latest_envios_by_phone = await repo.worker_get_latest_envios_by_phones(
                    phone_values=all_lookup_candidates,
                    organizacion_id=organizacion_id,
                    canal="whatsapp",
                )
            except CRMRepositoryError:
                latest_envios_by_phone = {}

        unresolved_phones: list[str] = []
        for phone_value in phones_to_lookup:
            candidates = phone_candidates_map.get(phone_value, [])
            hint: tuple[str | None, str | None, str | None, str | None, str | None] = (
                None,
                None,
                None,
                None,
                None,
            )
            for lookup_phone in candidates:
                envio_row = latest_envios_by_phone.get(lookup_phone)
                candidate_hint = _extract_envio_prospeccion_hints(envio_row)
                if any(candidate_hint[:4]) or candidate_hint[4]:
                    hint = candidate_hint
                    break
            if any(hint[:4]) or hint[4]:
                await _write_whatsapp_envio_hint_cache(phone_value, hint)
                whatsapp_phone_cache[phone_value] = hint
            else:
                unresolved_phones.append(phone_value)

        allow_individual_hint_fallback = bool(
            getattr(settings, "inbox_whatsapp_hint_enable_individual_fallback", False)
        )
        # Fallback individual opcional: puede ser costoso en requests interactivos.
        if unresolved_phones and allow_individual_hint_fallback:
            semaphore = asyncio.Semaphore(INBOX_THREADS_WHATSAPP_HINT_LOOKUP_CONCURRENCY)

            async def _lookup_hint_by_phone_fallback(
                phone_value: str,
            ) -> tuple[str, tuple[str | None, str | None, str | None, str | None, str | None]]:
                async with semaphore:
                    hint: tuple[str | None, str | None, str | None, str | None, str | None] = (
                        None,
                        None,
                        None,
                        None,
                        None,
                    )
                    for lookup_phone in _whatsapp_phone_lookup_candidates(phone_value):
                        try:
                            linked_envio = await repo.worker_get_latest_envio_by_phone(
                                phone_e164=lookup_phone,
                                canal="whatsapp",
                            )
                        except CRMRepositoryError:
                            linked_envio = None
                        candidate_hint = _extract_envio_prospeccion_hints(linked_envio)
                        if any(candidate_hint[:4]) or candidate_hint[4]:
                            hint = candidate_hint
                            break
                    await _write_whatsapp_envio_hint_cache(phone_value, hint)
                    return phone_value, hint

            lookup_results = await asyncio.gather(
                *(_lookup_hint_by_phone_fallback(phone_value) for phone_value in unresolved_phones),
                return_exceptions=True,
            )
            for result in lookup_results:
                if isinstance(result, Exception):
                    continue
                phone_value, hint = result
                whatsapp_phone_cache[phone_value] = hint
        elif unresolved_phones:
            stage_timings["whatsapp_hint_individual_fallback_skipped"] = float(len(unresolved_phones))
    stage_timings["whatsapp_hint_lookup_ms"] = round(
        (time.perf_counter() - fallback_lookup_start) * 1000, 2
    )

    if should_resolve_whatsapp_hints:
        for conversacion_id, hints in list(thread_prospeccion_hints.items()):
            batch_hint, campana_hint, template_id_hint, template_slug_hint, template_label_hint = hints
            if batch_hint or campana_hint or template_slug_hint:
                continue
            if thread_channel_map.get(conversacion_id) != "whatsapp":
                continue
            phone_value = thread_phone_map.get(conversacion_id)
            if not phone_value:
                contacto_id_value = thread_contact_map.get(conversacion_id)
                if contacto_id_value:
                    phone_value = contact_phone_map.get(contacto_id_value)
            if not phone_value:
                continue
            fallback_hints = whatsapp_phone_cache.get(phone_value)
            if not fallback_hints:
                for candidate_phone in _whatsapp_phone_lookup_candidates(phone_value):
                    cached_hint = whatsapp_phone_cache.get(candidate_phone)
                    if cached_hint:
                        fallback_hints = cached_hint
                        break
            if not fallback_hints:
                fallback_hints = (None, None, None, None, None)
            merged_hints = (
                batch_hint or fallback_hints[0],
                campana_hint or fallback_hints[1],
                template_id_hint or fallback_hints[2],
                template_slug_hint or fallback_hints[3],
                template_label_hint or fallback_hints[4],
            )
            thread_prospeccion_hints[conversacion_id] = merged_hints
            if merged_hints[0] and _safe_uuid(merged_hints[0]):
                batch_ids.add(merged_hints[0])
            if merged_hints[1] and _safe_uuid(merged_hints[1]):
                campana_ids.add(merged_hints[1])
            if merged_hints[2] and _safe_uuid(merged_hints[2]):
                template_ids.add(merged_hints[2])
            if merged_hints[3]:
                template_slugs.add(merged_hints[3])

    batch_label_map: dict[str, str] = {}
    batch_number_map: dict[str, int] = {}
    batch_template_hint_map: dict[str, tuple[str | None, str | None, str | None]] = {}
    batch_catalog_start = time.perf_counter()
    if batch_ids:
        batch_catalog_cache_key = _build_inbox_catalog_cache_key(
            {
                "type": "contact_batches",
                "org": str(organizacion_id),
                "ids": sorted(batch_ids),
            }
        )
        batch_rows = await _read_inbox_catalog_cache(batch_catalog_cache_key)
        if batch_rows is None:
            try:
                batch_rows = await repo.list_contact_batches_by_ids(
                    usuario_token=user_token,
                    batch_ids=batch_ids,
                )
            except CRMRepositoryError:
                # Fallback defensivo por compatibilidad.
                try:
                    batch_rows, _ = await repo.list_contact_batches(
                        usuario_token=user_token,
                        limit=max(300, min(1000, len(batch_ids) * 3)),
                        offset=0,
                        order="campana_id.asc,creado_en.asc,id.asc",
                    )
                except CRMRepositoryError:
                    batch_rows = []
            else:
                await _write_inbox_catalog_cache(batch_catalog_cache_key, batch_rows)
        batches_by_campaign: dict[str, list[tuple[str, datetime | None]]] = {}
        for batch in batch_rows:
            batch_id_value = _clean_text(batch.get("id"))
            if not batch_id_value or batch_id_value not in batch_ids:
                continue
            title = _clean_text(batch.get("titulo"))
            metadata = batch.get("metadata") if isinstance(batch.get("metadata"), dict) else {}
            if not title:
                title = _clean_text(metadata.get("campana_nombre")) or _clean_text(
                    metadata.get("lista_nombre")
                )
            if title:
                batch_label_map[batch_id_value] = title
            campaign_key = _clean_text(batch.get("campana_id")) or "__sin_campana__"
            batches_by_campaign.setdefault(campaign_key, []).append(
                (batch_id_value, _parse_datetime(batch.get("creado_en")))
            )

            batch_template_id = _clean_text(
                metadata.get("template_id") or metadata.get("contact_template_id")
            )
            batch_template_slug = _clean_text(
                metadata.get("template_slug") or metadata.get("kw")
            )
            batch_template_name = _clean_text(
                metadata.get("template_nombre") or metadata.get("template_name")
            )
            canales_config_meta = _ensure_dict(metadata.get("canales_config"), default={})
            for channel_key in ("whatsapp", "correo"):
                channel_cfg = _ensure_dict(canales_config_meta.get(channel_key), default={})
                channel_meta = _ensure_dict(channel_cfg.get("metadata"), default={})
                if not batch_template_id:
                    batch_template_id = _clean_text(
                        channel_meta.get("template_id") or channel_cfg.get("template_id")
                    )
                if not batch_template_slug:
                    batch_template_slug = _clean_text(
                        channel_meta.get("template_slug")
                        or channel_meta.get("kw")
                        or channel_cfg.get("template_slug")
                        or channel_cfg.get("kw")
                    )
                if not batch_template_name:
                    batch_template_name = _clean_text(
                        channel_meta.get("template_label")
                        or channel_meta.get("template_nombre")
                        or channel_meta.get("template_name")
                        or channel_cfg.get("template_label")
                    )
                if batch_template_id and batch_template_slug and batch_template_name:
                    break
            if batch_template_id:
                template_ids.add(batch_template_id)
            if batch_template_slug:
                normalized_slug = batch_template_slug.lower()
                template_slugs.add(normalized_slug)
                batch_template_slug = normalized_slug
            batch_template_hint_map[batch_id_value] = (
                batch_template_id,
                batch_template_slug,
                batch_template_name,
            )
        for campaign_key, campaign_batches in batches_by_campaign.items():
            sorted_batches = sorted(
                campaign_batches,
                key=lambda item: (
                    item[1] is None,
                    item[1] or datetime.max.replace(tzinfo=timezone.utc),
                    item[0],
                ),
            )
            for index, (batch_id_value, _) in enumerate(sorted_batches, start=1):
                batch_number_map[batch_id_value] = index
    stage_timings["batch_catalog_ms"] = round((time.perf_counter() - batch_catalog_start) * 1000, 2)

    campana_label_map: dict[str, str] = {}
    campaign_catalog_start = time.perf_counter()
    if campana_ids:
        campaign_cache_key = _build_inbox_catalog_cache_key(
            {
                "type": "campaigns",
                "org": str(organizacion_id),
            }
        )
        campaign_rows = await _read_inbox_catalog_cache(campaign_cache_key)
        if campaign_rows is None:
            try:
                campaign_rows = await repo.list_campaigns(organizacion_id=organizacion_id)
            except CRMRepositoryError:
                campaign_rows = []
            else:
                await _write_inbox_catalog_cache(campaign_cache_key, campaign_rows)
        for campaign in campaign_rows:
            campaign_id_value = _clean_text(campaign.get("id"))
            if not campaign_id_value or campaign_id_value not in campana_ids:
                continue
            name = _clean_text(campaign.get("nombre"))
            if name:
                campana_label_map[campaign_id_value] = name
    stage_timings["campaign_catalog_ms"] = round(
        (time.perf_counter() - campaign_catalog_start) * 1000, 2
    )

    template_label_by_id: dict[str, str] = {}
    template_label_by_slug: dict[str, str] = {}
    template_label_by_external_key: dict[str, str] = {}
    template_catalog_start = time.perf_counter()
    if template_ids or template_slugs:
        template_cache_key = _build_inbox_catalog_cache_key(
            {
                "type": "contact_templates",
                "org": str(organizacion_id),
            }
        )
        template_rows = await _read_inbox_catalog_cache(template_cache_key)
        if template_rows is None:
            try:
                template_rows = await repo.list_contact_templates(usuario_token=user_token)
            except CRMRepositoryError:
                template_rows = []
            else:
                await _write_inbox_catalog_cache(template_cache_key, template_rows)
        for template in template_rows:
            template_id_value = _clean_text(template.get("id"))
            metadata = template.get("metadata") if isinstance(template.get("metadata"), dict) else {}
            template_slug_value = _clean_text(
                template.get("slug") or metadata.get("template_slug")
            )
            template_label = _clean_text(template.get("nombre")) or template_slug_value
            if not template_label:
                continue
            if template_id_value:
                template_label_by_id[template_id_value] = template_label
            if template_slug_value:
                template_label_by_slug[template_slug_value.lower()] = template_label
            external_keys = (
                _clean_text(metadata.get("twilio_content_sid")),
                _clean_text(metadata.get("template_sid")),
                _clean_text(metadata.get("brevo_template_id")),
                _clean_text(metadata.get("external_template_id")),
            )
            for external_key in external_keys:
                if external_key:
                    template_label_by_external_key[external_key.lower()] = template_label
    stage_timings["template_catalog_ms"] = round(
        (time.perf_counter() - template_catalog_start) * 1000, 2
    )

    conversation_ids = [
        _clean_text(row.get("conversacion_id"))
        for row in rows
        if _clean_text(row.get("conversacion_id"))
    ]
    wa_atribucion_by_conversation: dict[str, dict[str, Any]] = {}
    wa_rule_ids: set[str] = set()
    attribution_lookup_start = time.perf_counter()
    if should_resolve_whatsapp_hints and conversation_ids:
        try:
            wa_atribucion_rows = await repo.worker_list_whatsapp_atribucion_events_by_conversations(
                organizacion_id=organizacion_id,
                conversation_ids=conversation_ids,
            )
        except CRMRepositoryError:
            wa_atribucion_rows = []
        for event_row in wa_atribucion_rows:
            conversation_id_value = _clean_text(event_row.get("conversacion_id"))
            if not conversation_id_value or conversation_id_value in wa_atribucion_by_conversation:
                continue
            wa_atribucion_by_conversation[conversation_id_value] = event_row
            rule_id_value = _clean_text(event_row.get("regla_id"))
            if rule_id_value:
                wa_rule_ids.add(rule_id_value)

    wa_rule_label_map: dict[str, str] = {}
    wa_rule_channel_map: dict[str, str] = {}
    if wa_rule_ids:
        wa_rules_cache_key = _build_inbox_catalog_cache_key(
            {
                "type": "wa_atribucion_rules",
                "org": str(organizacion_id),
                "include_historial": True,
                "limit": 500,
            }
        )
        wa_rules_rows = await _read_inbox_catalog_cache(wa_rules_cache_key)
        if wa_rules_rows is None:
            try:
                wa_rules_rows, _ = await repo.list_whatsapp_atribucion_reglas(
                    usuario_token=user_token,
                    limit=500,
                    offset=0,
                    include_historial=True,
                )
            except CRMRepositoryError:
                wa_rules_rows = []
            else:
                await _write_inbox_catalog_cache(wa_rules_cache_key, wa_rules_rows)
        for rule_row in wa_rules_rows:
            rule_id_value = _clean_text(rule_row.get("id"))
            if not rule_id_value or rule_id_value not in wa_rule_ids:
                continue
            rule_name = _clean_text(rule_row.get("nombre_regla"))
            if rule_name:
                wa_rule_label_map[rule_id_value] = rule_name
            channel_name = _clean_text(rule_row.get("canal_publicitario"))
            if channel_name:
                wa_rule_channel_map[rule_id_value] = channel_name
    stage_timings["attribution_lookup_ms"] = round(
        (time.perf_counter() - attribution_lookup_start) * 1000, 2
    )

    # contact_profile_name_map/contact_phone_map ya están listos

    row_enrichment_start = time.perf_counter()
    enriched_rows: list[dict[str, Any]] = []
    for row in rows:
        row_payload = dict(row)
        existing_row_template_label = _clean_text(row_payload.get("template_label"))
        if _is_generic_historic_template_label(existing_row_template_label):
            existing_row_template_label = None
            row_payload.pop("template_label", None)
        batch_value = _clean_text(row_payload.get("batch_id"))
        campana_value = _clean_text(row_payload.get("campana_id"))
        conversacion_value = _clean_text(row_payload.get("conversacion_id"))
        (
            batch_hint,
            campana_hint,
            template_id_hint,
            template_slug_hint,
            template_label_hint,
        ) = thread_prospeccion_hints.get(
            conversacion_value or "",
            (None, None, None, None, None),
        )
        if not batch_value and batch_hint and _safe_uuid(batch_hint):
            batch_value = batch_hint
            row_payload["batch_id"] = batch_value
        if not campana_value and campana_hint and _safe_uuid(campana_hint):
            campana_value = campana_hint
            row_payload["campana_id"] = campana_value
        batch_template_hint = (
            batch_template_hint_map.get(batch_value) if batch_value else (None, None, None)
        )
        batch_template_id, batch_template_slug, batch_template_name = batch_template_hint
        resolved_template_id = template_id_hint or batch_template_id
        resolved_template_slug = template_slug_hint or batch_template_slug
        resolved_external_candidates: list[str] = []
        if resolved_template_slug:
            resolved_external_candidates.append(resolved_template_slug.lower())
        for key in _collect_thread_template_external_keys(row_payload):
            if key not in resolved_external_candidates:
                resolved_external_candidates.append(key)
        resolved_external_label = next(
            (
                template_label_by_external_key.get(candidate)
                for candidate in resolved_external_candidates
                if template_label_by_external_key.get(candidate)
            ),
            None,
        )
        normalized_template_label_hint = (
            None if _is_generic_historic_template_label(template_label_hint) else template_label_hint
        )
        template_label = (
            (template_label_by_id.get(resolved_template_id) if resolved_template_id else None)
            or (
                template_label_by_slug.get(resolved_template_slug)
                if resolved_template_slug
                else None
            )
            or resolved_external_label
            or normalized_template_label_hint
            or batch_template_name
            or existing_row_template_label
        )

        if batch_value:
            batch_number = batch_number_map.get(batch_value)
            row_payload["batch_label"] = (
                f"Lote {batch_number}"
                if batch_number is not None
                else (batch_label_map.get(batch_value) or f"Lote {batch_value[:8]}")
            )
        if campana_value:
            row_payload["campana_label"] = (
                campana_label_map.get(campana_value) or f"Campaña {campana_value[:8]}"
            )
        if resolved_template_id and _safe_uuid(resolved_template_id):
            row_payload["template_id"] = resolved_template_id
        if resolved_template_slug:
            row_payload["template_slug"] = resolved_template_slug
        if template_label:
            row_payload["template_label"] = template_label
        elif resolved_template_slug:
            if _looks_like_template_identifier(resolved_template_slug):
                row_payload["template_label"] = "Plantilla WhatsApp"
            else:
                row_payload["template_label"] = f"Plantilla {resolved_template_slug}"
        elif resolved_template_id:
            row_payload["template_label"] = "Plantilla WhatsApp"
        elif any(_looks_like_template_identifier(value) for value in resolved_external_candidates):
            row_payload["template_label"] = "Plantilla WhatsApp"
        current_source = _clean_text(row_payload.get("source"))
        conversation_attribution = (
            wa_atribucion_by_conversation.get(conversacion_value or "")
            if conversacion_value
            else None
        )
        if isinstance(conversation_attribution, dict):
            if not current_source or current_source in {
                "prospeccion",
                "prospeccion_whatsapp",
                "whatsapp",
                "assistant",
                "whatsapp_inbound",
            }:
                row_payload["source"] = "publicidad_whatsapp"
            rule_id_value = _clean_text(conversation_attribution.get("regla_id"))
            channel_publicitario = _clean_text(conversation_attribution.get("canal_publicitario"))
            row_payload["source_detail"] = {
                "canal_publicitario": (
                    channel_publicitario
                    or wa_rule_channel_map.get(rule_id_value or "")
                ),
                "campana_publicitaria": _clean_text(conversation_attribution.get("campana_publicitaria")),
                "adset": _clean_text(conversation_attribution.get("adset")),
                "anuncio": _clean_text(conversation_attribution.get("anuncio")),
                "regla_id": rule_id_value,
                "regla_nombre": wa_rule_label_map.get(rule_id_value or ""),
                "atribuido_en": _clean_text(conversation_attribution.get("creado_en")),
            }
            current_source = _clean_text(row_payload.get("source"))
        if not current_source and (batch_value or campana_value or resolved_template_id or resolved_template_slug):
            row_payload["source"] = "prospeccion"
        contact_id_value = _clean_text(row_payload.get("contacto_id"))
        if contact_id_value:
            profile_name = contact_profile_name_map.get(contact_id_value)
            if profile_name and not _clean_text(row_payload.get("contacto_nombre")):
                row_payload["contacto_profile_name"] = profile_name
            elif profile_name:
                row_payload["contacto_profile_name"] = profile_name
            if not _clean_text(row_payload.get("contacto_telefono")):
                fallback_phone = contact_phone_map.get(contact_id_value)
                if fallback_phone:
                    row_payload["contacto_telefono"] = fallback_phone
            if contact_state_name_map.get(contact_id_value) and not _clean_text(row_payload.get("contacto_state_name")):
                row_payload["contacto_state_name"] = contact_state_name_map[contact_id_value]
            if contact_city_name_map.get(contact_id_value) and not _clean_text(row_payload.get("contacto_city_name")):
                row_payload["contacto_city_name"] = contact_city_name_map[contact_id_value]
            if contact_country_code_map.get(contact_id_value) and not _clean_text(row_payload.get("contacto_country_code")):
                row_payload["contacto_country_code"] = contact_country_code_map[contact_id_value]
            if contact_country_name_map.get(contact_id_value) and not _clean_text(row_payload.get("contacto_country_name")):
                row_payload["contacto_country_name"] = contact_country_name_map[contact_id_value]
            if contact_lada_map.get(contact_id_value) and not _clean_text(row_payload.get("contacto_lada")):
                row_payload["contacto_lada"] = contact_lada_map[contact_id_value]

        phone_value = _clean_text(row_payload.get("contacto_telefono"))
        if phone_value:
            _apply_inbox_phone_location(row_payload)

        enriched_rows.append(row_payload)
    stage_timings["row_enrichment_ms"] = round((time.perf_counter() - row_enrichment_start) * 1000, 2)

    model_validate_start = time.perf_counter()
    if source_requested == "publicidad_whatsapp":
        result_threads = [
            CRMInboxThread.model_validate(row)
            for row in enriched_rows
            if _clean_text(row.get("source")) == "publicidad_whatsapp"
        ]
    else:
        result_threads = [CRMInboxThread.model_validate(row) for row in enriched_rows]
    stage_timings["model_validate_ms"] = round((time.perf_counter() - model_validate_start) * 1000, 2)

    cache_write_start = time.perf_counter()
    await _write_inbox_threads_cache(cache_key, result_threads)
    stage_timings["cache_write_ms"] = round((time.perf_counter() - cache_write_start) * 1000, 2)
    total_duration_ms = (time.perf_counter() - request_start) * 1000
    stage_timings["total_ms"] = round(total_duration_ms, 2)
    await _record_inbox_threads_metrics(duration_ms=total_duration_ms, cache_hit=False)
    await _record_inbox_threads_stage_metrics(stage_timings=stage_timings)
    logger.info(
        "crm.inbox.threads.stage_profile",
        extra={
            "rows": len(rows),
            "result_rows": len(result_threads),
            "phones_fallback": len(phones_to_lookup),
            "batch_ids": len(batch_ids),
            "campana_ids": len(campana_ids),
            "template_hints": len(template_ids) + len(template_slugs),
            "conversation_ids": len(conversation_ids),
            "missing_contact_names": len(missing_contact_name_ids),
            "enrich_requested": enrich_requested,
            "enrich_effective": effective_enrich,
            "enrich_deferred_due_to_high_demand": defer_enrichment_due_to_high_demand,
            "stages": stage_timings,
        },
    )
    return result_threads


@router.get("/inbox/filter-options", response_model=CRMInboxContextFilters)
async def get_inbox_filter_options(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ver_inbox")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    source: str | None = Query(default=None, max_length=80),
    channel: str | None = Query(default=None, max_length=30),
    limit: Annotated[int, Query(ge=25, le=500)] = 200,
) -> CRMInboxContextFilters:
    """Devuelve catálogos de batch/campaña para los filtros del inbox."""

    start = time.perf_counter()
    cache_key = _build_inbox_filter_options_cache_key(
        {
            "org": str(organizacion_id),
            "user": user_token,
            "source": _clean_text(source) or "",
            "channel": _clean_text(channel) or "",
            "limit": limit,
        }
    )
    cached_payload = await _read_inbox_filter_options_cache(cache_key)
    if cached_payload is not None:
        duration_ms = (time.perf_counter() - start) * 1000
        logger.info(
            "crm.inbox.filter_options.cache_hit",
            extra={
                "duration_ms": round(duration_ms, 2),
                "batch_options": len(cached_payload.batches),
                "campana_options": len(cached_payload.campanas),
                "source": source,
                "channel": channel,
                "limit": limit,
            },
        )
        return cached_payload

    rows = await repo.inbox_threads(
        usuario_token=user_token,
        source=source,
        channel=channel,
        limit=limit,
        offset=0,
        message_limit=1,
    )

    batch_ids: set[str] = set()
    campana_ids: set[str] = set()
    for row in rows:
        batch_value = _clean_text(row.get("batch_id"))
        if batch_value:
            batch_ids.add(batch_value)
        campana_value = _clean_text(row.get("campana_id"))
        if campana_value:
            campana_ids.add(campana_value)

    batch_label_map: dict[str, str] = {}
    if batch_ids:
        try:
            batch_rows, _ = await repo.list_contact_batches(
                usuario_token=user_token,
                limit=max(limit, 300),
                offset=0,
            )
        except CRMRepositoryError:
            batch_rows = []
        for batch in batch_rows:
            batch_id_value = _clean_text(batch.get("id"))
            if not batch_id_value or batch_id_value not in batch_ids:
                continue
            title = _clean_text(batch.get("titulo"))
            if not title:
                metadata = batch.get("metadata") if isinstance(batch.get("metadata"), dict) else {}
                title = _clean_text(metadata.get("campana_nombre")) or _clean_text(
                    metadata.get("lista_nombre")
                )
            if title:
                batch_label_map[batch_id_value] = title

    campana_label_map: dict[str, str] = {}
    if campana_ids:
        campaign_cache_key = _build_inbox_catalog_cache_key(
            {
                "type": "campaigns",
                "org": str(organizacion_id),
            }
        )
        campaign_rows = await _read_inbox_catalog_cache(campaign_cache_key)
        if campaign_rows is None:
            try:
                campaign_rows = await repo.list_campaigns(organizacion_id=organizacion_id)
            except CRMRepositoryError:
                campaign_rows = []
            else:
                await _write_inbox_catalog_cache(campaign_cache_key, campaign_rows)
        for campaign in campaign_rows:
            campaign_id_value = _clean_text(campaign.get("id"))
            if not campaign_id_value or campaign_id_value not in campana_ids:
                continue
            name = _clean_text(campaign.get("nombre"))
            if name:
                campana_label_map[campaign_id_value] = name

    batches = []
    for value in sorted(batch_ids):
        label = batch_label_map.get(value) or f"Batch {value[:8]}"
        batches.append(CRMInboxContextOption(value=value, label=label))

    campanas = []
    for value in sorted(campana_ids):
        label = campana_label_map.get(value) or f"Campaña {value[:8]}"
        campanas.append(CRMInboxContextOption(value=value, label=label))

    duration_ms = (time.perf_counter() - start) * 1000
    log_payload = {
        "duration_ms": round(duration_ms, 2),
        "threads_scanned": len(rows),
        "batch_options": len(batches),
        "campana_options": len(campanas),
        "source": source,
        "channel": channel,
        "limit": limit,
    }
    if duration_ms >= 700:
        logger.warning("crm.inbox.filter_options.slow_query", extra=log_payload)
    else:
        logger.info("crm.inbox.filter_options.query", extra=log_payload)

    payload = CRMInboxContextFilters(batches=batches, campanas=campanas)
    await _write_inbox_filter_options_cache(cache_key, payload)
    return payload


