@router.get("/inbox/runtime-profile")
async def get_inbox_runtime_profile(
    *,
    _: str = Depends(require_permission("conv.read")),
) -> dict[str, Any]:
    mode = await high_demand_controller.current_mode()
    high_demand_active = bool(mode.get("active"))
    if high_demand_active:
        recommended_seconds = max(
            5,
            int(mode.get("recommended_inbox_poll_seconds") or settings.high_demand_recommended_inbox_poll_seconds),
        )
        source = "high_demand"
    else:
        recommended_seconds = max(5, int(settings.inbox_threads_default_poll_seconds))
        source = "default"
    return {
        "ok": True,
        "high_demand_mode": high_demand_active,
        "recommended_threads_poll_seconds": int(recommended_seconds),
        "source": source,
        "defer_enrichments": bool(
            high_demand_active
            and bool(getattr(settings, "high_demand_inbox_enrichments_force_defer", True))
        ),
    }


@router.get("/inbox/stream")
async def stream_inbox_updates(
    *,
    _: str = Depends(require_permission("ver_inbox")),
    organizacion_id: UUID = Depends(require_organizacion_id),
) -> StreamingResponse:
    """Stream SSE para invalidaciones incrementales de Inbox."""

    topic = inbox_topic_for_org(organizacion_id=str(organizacion_id))
    queue = await ui_realtime_hub.subscribe(topic)

    async def event_generator() -> Any:
        try:
            yield _sse_payload(
                {
                    "type": "connected",
                    "scope": "inbox",
                    "organizacion_id": str(organizacion_id),
                    "at": datetime.now(timezone.utc).isoformat(),
                }
            )
            while True:
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=25)
                except asyncio.TimeoutError:
                    yield _sse_payload({"type": "ping", "scope": "inbox"})
                    continue
                yield _sse_payload(event)
        finally:
            await ui_realtime_hub.unsubscribe(topic, queue)

    headers = {
        "Cache-Control": "no-cache",
        "Content-Type": "text/event-stream",
        "Connection": "keep-alive",
    }
    return StreamingResponse(event_generator(), media_type="text/event-stream", headers=headers)


@router.get("/inbox/bootstrap")
async def get_inbox_bootstrap(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ver_inbox")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    include_summary: bool = Query(default=True),
    include_filter_options: bool = Query(default=True),
    estado: str | None = Query(default=None, max_length=50),
    source: str | None = Query(default=None, max_length=80),
    channel: str | None = Query(default=None, max_length=30),
    date: str | None = Query(default=None, max_length=20),
    batch_id: UUID | None = Query(default=None),
    campana_id: UUID | None = Query(default=None),
    asignado_id: UUID | None = Query(default=None),
    limit: Annotated[int, Query(ge=1, le=200)] = 25,
    offset: Annotated[int, Query(ge=0)] = 0,
    message_limit: Annotated[int, Query(ge=1, le=50)] = 20,
    enrich: bool = Query(default=False),
) -> dict[str, Any]:
    """BFF agregador para Inbox: runtime + summary + threads + filtros."""

    started = time.perf_counter()
    tasks: list[Awaitable[Any]] = []
    task_labels: list[str] = []

    if include_summary:
        tasks.append(repo.inbox_summary(usuario_token=user_token))
        task_labels.append("summary")

    tasks.append(
        get_inbox_threads(
            repo=repo,
            _="",
            user_token=user_token,
            organizacion_id=organizacion_id,
            usuario_id=usuario_id,
            estado=estado,
            source=source,
            channel=channel,
            date=date,
            batch_id=batch_id,
            campana_id=campana_id,
            asignado_id=asignado_id,
            limit=limit,
            offset=offset,
            message_limit=message_limit,
            enrich=enrich,
        )
    )
    task_labels.append("threads")

    if include_filter_options:
        tasks.append(
            get_inbox_filter_options(
                repo=repo,
                _="",
                user_token=user_token,
                organizacion_id=organizacion_id,
                source=source,
                channel=channel,
                limit=max(200, limit),
            )
        )
        task_labels.append("filter_options")

    runtime_profile = await get_inbox_runtime_profile(_="")
    results = await asyncio.gather(*tasks)
    payload_by_label = {label: value for label, value in zip(task_labels, results, strict=False)}

    summary_payload = payload_by_label.get("summary")
    summary = (
        CRMInboxSummary(
            total=int(summary_payload.get("total") or 0),
            unread=int(summary_payload.get("unread") or 0),
            awaiting=int(summary_payload.get("awaiting") or 0),
            folders=[
                CRMInboxFolder(
                    id=str(entry.get("id")),
                    label=str(entry.get("label") or ""),
                    count=int(entry.get("count") or 0),
                )
                for entry in (summary_payload.get("folders") or [])
                if isinstance(entry, dict) and entry.get("id")
            ],
        ).model_dump()
        if isinstance(summary_payload, dict)
        else None
    )

    threads = [
        item.model_dump(mode="json") if isinstance(item, CRMInboxThread) else item
        for item in (payload_by_label.get("threads") or [])
    ]
    filter_options_payload = payload_by_label.get("filter_options")
    filter_options = (
        filter_options_payload.model_dump(mode="json")
        if isinstance(filter_options_payload, CRMInboxContextFilters)
        else None
    )

    duration_ms = (time.perf_counter() - started) * 1000
    logger.info(
        "crm.inbox.bootstrap",
        extra={
            "duration_ms": round(duration_ms, 2),
            "rows": len(threads),
            "include_summary": include_summary,
            "include_filter_options": include_filter_options,
            "limit": limit,
            "offset": offset,
            "enrich_requested": bool(enrich),
        },
    )
    return {
        "ok": True,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "runtime_profile": runtime_profile,
        "summary": summary,
        "threads": {
            "items": threads,
            "limit": int(limit),
            "offset": int(offset),
        },
        "filter_options": filter_options,
    }


@router.get("/inbox/conversations/{conversacion_id}/detail", response_model=CRMInboxThread)
async def get_inbox_conversation_detail(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ver_inbox")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    conversacion_id: UUID,
    estado: str | None = Query(default=None, max_length=50),
    source: str | None = Query(default=None, max_length=80),
    channel: str | None = Query(default=None, max_length=30),
    date: str | None = Query(default=None, max_length=20),
    batch_id: UUID | None = Query(default=None),
    campana_id: UUID | None = Query(default=None),
    asignado_id: UUID | None = Query(default=None),
    thread_offset: Annotated[int, Query(ge=0)] = 0,
    message_limit: Annotated[int, Query(ge=1, le=50)] = 20,
) -> CRMInboxThread:
    threads = await get_inbox_threads(
        repo=repo,
        _="",
        user_token=user_token,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
        estado=estado,
        source=source,
        channel=channel,
        date=date,
        batch_id=batch_id,
        campana_id=campana_id,
        asignado_id=asignado_id,
        limit=1,
        offset=thread_offset,
        message_limit=message_limit,
        enrich=True,
    )
    if not threads:
        raise HTTPException(status_code=404, detail="inbox_thread_detail_not_found")
    thread = threads[0]
    if thread.conversacion_id != conversacion_id:
        raise HTTPException(status_code=404, detail="inbox_thread_detail_not_found")
    return thread


@router.get("/inbox/messages/{conversacion_id}", response_model=list[CRMInboxMessage])
async def get_inbox_messages(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("messages.read")),
    user_token: str = Depends(require_user_token),
    conversacion_id: UUID,
    limit: Annotated[int, Query(ge=1, le=500)] = 100,
    before: str | None = Query(default=None, max_length=64),
) -> list[CRMInboxMessage]:
    rows = await repo.inbox_messages(
        usuario_token=user_token,
        conversacion_id=conversacion_id,
        limit=limit,
        before=before,
    )
    return [CRMInboxMessage.model_validate(row) for row in rows]


@router.post("/inbox/conversations/{conversacion_id}/manual")
async def set_inbox_manual_mode(
    *,
    _: str = Depends(require_permission("conv.assign")),
    user_token: str = Depends(require_user_token),  # noqa: ARG001
    conversacion_id: UUID,
    payload: ManualOverridePayload,
) -> dict[str, Any]:
    try:
        await storage.set_manual_override(str(conversacion_id), payload.manual)
    except StorageError as exc:
        detail = str(exc) or "No se pudo actualizar el modo manual"
        lowered = detail.lower()
        status_code = 502 if ("error de red" in lowered or "respondió error" in lowered) else 400
        raise HTTPException(status_code=status_code, detail=detail) from exc
    return {"ok": True, "manual": payload.manual}


@router.post("/inbox/conversations/{conversacion_id}/promote")
async def promote_inbox_conversation_to_opportunity(
    *,
    repo: CRMRepository = Depends(get_repository),
    _pipeline_permission: str = Depends(require_permission("pipeline.view")),
    _contacts_permission: str = Depends(require_permission("contacts.write")),
    conversacion_id: UUID,
    payload: InboxPromoteOpportunityPayload | None = None,
) -> dict[str, Any]:
    try:
        conversation_meta = await storage.fetch_webchat_conversation(str(conversacion_id))
    except StorageError as exc:
        raise HTTPException(status_code=502, detail=f"conversation_lookup_failed:{exc}") from exc

    persona_id_value = conversation_meta.get("persona_id") or conversation_meta.get("contact_id")
    org_value = conversation_meta.get("organizacion_id")
    try:
        organizacion_id = UUID(str(org_value))
    except (TypeError, ValueError):
        raise HTTPException(status_code=409, detail="conversation_org_missing")

    form_nombre = _clean_text(payload.nombre) if payload else None
    form_apellido_paterno = _clean_text(payload.apellido_paterno) if payload else None
    form_apellido_materno = _clean_text(payload.apellido_materno) if payload else None
    explicit_name = " ".join(
        part for part in (form_nombre, form_apellido_paterno, form_apellido_materno) if part
    ).strip() or None
    form_nombre_completo = explicit_name or (_clean_text(payload.nombre_completo) if payload else None)
    form_correo = _normalize_email(payload.correo) if payload else None
    form_telefono = _clean_text(payload.telefono_e164) if payload else None
    form_company = _clean_text(payload.company_name) if payload else None
    form_proyecto = _clean_text(payload.proyecto_nombre) if payload else None
    form_necesidad = _clean_text(payload.necesidad) if payload else None
    form_monto = payload.monto_estimado if payload and payload.monto_estimado is not None else None

    conversation_persona_missing = not persona_id_value
    persona_row: dict[str, Any] | None = None
    if not persona_id_value and form_correo:
        try:
            persona_row = await repo.get_persona_by_email(
                email=form_correo,
                organizacion_id=organizacion_id,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=f"contact_lookup_failed:{exc}") from exc
        if persona_row:
            persona_id_value = persona_row.get("id")

    if not persona_id_value:
        if not form_nombre or not form_apellido_paterno or not form_correo or not form_telefono:
            raise HTTPException(status_code=422, detail="contact_identity_required")
        try:
            persona_row = await repo.create_persona(
                organizacion_id=organizacion_id,
                payload={
                    "nombre": form_nombre,
                    "nombre_nombres": form_nombre,
                    "apellido_paterno": form_apellido_paterno,
                    "apellido_materno": form_apellido_materno,
                    "nombre_completo": form_nombre_completo,
                    "correo_principal": form_correo,
                    "telefono_principal_e164": form_telefono,
                    "company_name": form_company,
                    "necesidad_proposito": form_necesidad,
                    "origen": "inbox_promote_modal",
                },
            )
            persona_id_value = persona_row.get("id")
            if not persona_id_value:
                raise CRMRepositoryError("persona_create_missing_id")
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=f"contact_create_failed:{exc}") from exc
    else:
        try:
            if persona_row is None:
                persona_row = await storage.fetch_persona(str(persona_id_value))
        except StorageError as exc:
            raise HTTPException(status_code=502, detail=f"contact_lookup_failed:{exc}") from exc

        if not persona_row:
            raise HTTPException(status_code=404, detail="conversation_contact_not_found")
        persona_org_value = persona_row.get("organizacion_id")
        if persona_org_value and str(persona_org_value) != str(organizacion_id):
            raise HTTPException(status_code=404, detail="conversation_contact_not_found")

    if conversation_persona_missing:
        try:
            await repo.update_conversation(
                conversation_id=str(conversacion_id),
                patch={
                    "persona_id": str(persona_id_value),
                    "contacto_id": str(persona_id_value),
                },
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=f"conversation_link_failed:{exc}") from exc

    existing = await repo.find_open_opportunity_by_conversation(
        organizacion_id=organizacion_id,
        conversation_id=str(conversacion_id),
    )
    had_existing = bool(existing and existing.get("id"))

    try:
        contact_uuid = UUID(str(persona_id_value))
    except (TypeError, ValueError):
        raise HTTPException(status_code=409, detail="conversation_contact_invalid")

    persona_patch: dict[str, Any] = {}
    if form_nombre:
        persona_patch["nombre"] = form_nombre
    if form_apellido_paterno:
        persona_patch["apellido_paterno"] = form_apellido_paterno
    if form_apellido_materno is not None:
        persona_patch["apellido_materno"] = form_apellido_materno
    if form_nombre_completo:
        persona_patch["nombre_completo"] = form_nombre_completo
    if form_correo is not None:
        persona_patch["correo_principal"] = form_correo
    if form_telefono:
        persona_patch["telefono_principal_e164"] = form_telefono
    if form_company:
        persona_patch["company_name"] = form_company
    if form_necesidad:
        persona_patch["necesidad_proposito"] = form_necesidad
    if persona_patch:
        try:
            persona_row = await repo.update_persona(
                organizacion_id=organizacion_id,
                persona_id=contact_uuid,
                payload=persona_patch,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=f"contact_update_failed:{exc}") from exc

    persona_name = _clean_text(persona_row.get("nombre_completo")) or "Contacto"
    recent_messages = await storage.fetch_recent_messages(conversation_id=str(conversacion_id), limit=20)
    latest_subject: str | None = None
    latest_inbound_text: str | None = None
    for message_row in reversed(recent_messages):
        if not isinstance(message_row, dict):
            continue
        datos = message_row.get("datos")
        if isinstance(datos, str):
            try:
                datos = json.loads(datos)
            except json.JSONDecodeError:
                datos = {}
        if isinstance(datos, dict) and latest_subject is None:
            latest_subject = _clean_text(datos.get("subject"))
        if message_row.get("direccion") == "entrante":
            latest_inbound_text = _clean_text(message_row.get("texto"))
            if latest_inbound_text:
                break

    title = form_proyecto or latest_subject or f"Inbound correo - {persona_name}"
    description = form_necesidad or latest_inbound_text or "Conversación iniciada desde correo entrante en Inbox."
    channel = _clean_text(conversation_meta.get("channel")) or "correo"
    try:
        ensured_opportunity_id, _, _ = await repo.ensure_conversation_opportunity(
            organizacion_id=organizacion_id,
            contacto_id=contact_uuid,
            conversation_id=str(conversacion_id),
            canal=channel,
            contacto_nombre=persona_name,
            contacto_empresa=_clean_text(persona_row.get("company_name")),
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=f"opportunity_ensure_failed:{exc}") from exc

    ensured_row = await repo.get_opportunity(
        organizacion_id=organizacion_id,
        opportunity_id=ensured_opportunity_id,
    )
    if not ensured_row:
        raise HTTPException(status_code=502, detail="opportunity_not_found_after_ensure")

    current_metadata = _ensure_dict(ensured_row.get("metadata"), default={})
    current_metadata.update(
        {
            "source": "inbox_email",
            "created_via": "inbox_promote_modal",
            "conversation_id": str(conversacion_id),
            "channel": channel,
            "contact_id": str(contact_uuid),
            **({"project_name": title} if title else {}),
            **({"proyecto_necesidades": description} if description else {}),
        }
    )
    opportunity_patch: dict[str, Any] = {
        "titulo": title,
        "descripcion": description,
        "metadata": current_metadata,
    }
    if form_monto is not None:
        opportunity_patch["monto_estimado"] = form_monto
    try:
        updated = await repo.update_opportunity(
            organizacion_id=organizacion_id,
            oportunidad_id=ensured_opportunity_id,
            payload=opportunity_patch,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=f"opportunity_update_failed:{exc}") from exc

    return {
        "ok": True,
        "created": not had_existing,
        "oportunidad_id": str(updated.get("id")) if updated.get("id") else str(ensured_opportunity_id),
        "titulo": updated.get("titulo") or title,
        "estado": updated.get("estado"),
    }


@router.post("/inbox/conversations/{conversacion_id}/reply")
async def reply_inbox_conversation(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("messages.write")),
    user_token: str = Depends(require_user_token),
    conversacion_id: UUID,
    payload: ConversationReplyPayload,
) -> dict[str, Any]:
    content = (payload.content or "").strip()
    attachments_payload = [
        attachment.model_dump(mode="json") for attachment in (payload.attachments or [])
    ]
    if not content and not attachments_payload:
        raise HTTPException(status_code=422, detail="message_required")

    try:
        conversation_meta = await storage.fetch_webchat_conversation(str(conversacion_id))
    except StorageError as exc:
        message = str(exc)
        lowered = message.lower()
        log_extra = {"conversation_id": str(conversacion_id), "error": message}
        if "no encontrada" in lowered or "not found" in lowered:
            logger.warning("panel.inbox.conversation_not_found", extra=log_extra)
            raise HTTPException(status_code=404, detail="conversation_not_found") from exc
        logger.exception("panel.inbox.fetch_conversation_failed", extra=log_extra)
        raise HTTPException(status_code=502, detail="No se pudo recuperar la conversación") from exc

    channel = (conversation_meta.get("channel") or "").lower()

    persona_id = conversation_meta.get("persona_id") or conversation_meta.get("contact_id")
    if channel not in {"webchat", "whatsapp", "correo"}:
        raise HTTPException(status_code=400, detail="unsupported_channel")
    if not persona_id:
        raise HTTPException(status_code=500, detail="conversation_contact_missing")

    session_id: str | None = None
    message_payload: webchat_schemas.MessageRequest | None = None
    if channel == "webchat":
        session_id = await _resolve_webchat_session_id(str(persona_id))
        if not session_id:
            raise HTTPException(status_code=409, detail="session_id_not_found")
        client_message_id = payload.client_message_id or uuid4().hex
        message_payload = webchat_schemas.MessageRequest(
            session_id=session_id,
            author="user",
            content=content,
            client_message_id=client_message_id,
            locale=payload.locale,
            metadata=payload.metadata,
            attachments=payload.attachments,
        )
    else:
        client_message_id = payload.client_message_id or uuid4().hex

    manual_override = bool(conversation_meta.get("manual_override"))
    if not manual_override:
        try:
            manual_override = await storage.get_manual_override(str(conversacion_id))
        except StorageError as exc:
            logger.exception(
                "panel.inbox.manual_check_failed",
                extra={"conversation_id": str(conversacion_id), "error": str(exc)},
            )

    logger.info(
        "panel.inbox.manual_state",
        extra={
            "conversation_id": str(conversacion_id),
            "manual_override": manual_override,
        },
    )

    if manual_override:
        extra_metadata: dict[str, Any] = {
            "conversation_id": str(conversacion_id),
            "client_message_id": client_message_id,
            "manual_override": True,
            "manual_mode": True,
            "origin": "panel_manual",
            "sender_type": "human",
            "author_type": "human",
            "channel": channel,
        }
        if payload.locale:
            extra_metadata["locale"] = payload.locale
        manual_user_id = _jwt_verify_and_sub(user_token)
        manual_user_id = manual_user_id.strip() if isinstance(manual_user_id, str) else None

        agent_payload: dict[str, Any] = {}
        if payload.metadata and isinstance(payload.metadata, dict):
            agent_payload.update(payload.metadata)

        manual_name = _extract_agent_name(agent_payload) if agent_payload else None
        if manual_name and manual_name.strip().lower() in {"agent", "agente"}:
            manual_name = None
        manual_email = _extract_agent_email(agent_payload) if agent_payload else None

        if manual_user_id:
            for key in (
                "user_id",
                "userId",
                "manual_user_id",
                "manualUserId",
                "agent_id",
                "agentId",
            ):
                agent_payload.setdefault(key, manual_user_id)

        profile = await _fetch_panel_user_profile(repo, manual_user_id)

        if profile:
            if manual_name is None:
                profile_name = _clean_text(profile.get("nombre_completo")) or _clean_text(
                    profile.get("correo")
                )
                if profile_name:
                    manual_name = profile_name
            if manual_email is None:
                profile_email = _clean_text(profile.get("correo"))
                if profile_email:
                    manual_email = profile_email

        if manual_name is None and manual_email:
            local_part = manual_email.split("@")[0]
            fallback_name = local_part.strip() or manual_email
            manual_name = fallback_name

        if manual_name:
            for key in ("manual_author", "manualAuthor", "agent_name", "agentName"):
                agent_payload.setdefault(key, manual_name)
        if manual_email:
            for key in ("manual_email", "manualEmail", "agent_email", "agentEmail"):
                agent_payload.setdefault(key, manual_email)

        if manual_user_id or manual_name or manual_email:
            user_section = agent_payload.get("user")
            if isinstance(user_section, dict):
                user_payload = dict(user_section)
            else:
                user_payload = {}
            if manual_user_id and "id" not in user_payload:
                user_payload["id"] = manual_user_id
            if manual_name and "name" not in user_payload:
                user_payload["name"] = manual_name
            if manual_email and "email" not in user_payload:
                user_payload["email"] = manual_email
            if user_payload:
                user_payload.setdefault("type", "human")
                agent_payload["user"] = user_payload

        if channel in {"whatsapp", "correo"} and attachments_payload:
            raise HTTPException(status_code=415, detail="attachments_not_supported")

        if agent_payload:
            agent_payload.setdefault("origin", agent_payload.get("origin") or "panel_manual")
            agent_payload.setdefault("source", agent_payload.get("source") or "panel_manual")
            agent_payload.setdefault("sender_type", agent_payload.get("sender_type") or "human")
            agent_payload.setdefault("senderType", agent_payload.get("senderType") or "human")
            agent_payload.setdefault("author_type", agent_payload.get("author_type") or "human")
            agent_payload.setdefault("authorType", agent_payload.get("authorType") or "human")

            for key, value in agent_payload.items():
                if key not in extra_metadata and key != "attachments":
                    extra_metadata[key] = value
            extra_metadata["extra"] = agent_payload
            resolved_name = manual_name or _extract_agent_name(agent_payload)
            if resolved_name:
                extra_metadata.setdefault("manual_author", resolved_name)
                extra_metadata.setdefault("agent_name", resolved_name)
            else:
                agent_name = agent_payload.get("agent_name") or agent_payload.get("agentName")
                if isinstance(agent_name, str) and agent_name.strip():
                    extra_metadata.setdefault("agent_name", agent_name.strip())
            resolved_email = manual_email or _extract_agent_email(agent_payload)
            if resolved_email:
                extra_metadata.setdefault("manual_email", resolved_email)
                extra_metadata.setdefault("agent_email", resolved_email)

        contact_org_id: str | None = None
        if str(persona_id).strip():
            try:
                persona_row = await storage.fetch_persona(str(persona_id))
            except StorageError as exc:
                logger.warning(
                    "panel.inbox.contact_lookup_failed",
                    extra={"persona_id": str(persona_id), "error": str(exc)},
                )
            else:
                org_value = persona_row.get("organizacion_id") if isinstance(persona_row, dict) else None
                if org_value:
                    try:
                        contact_org_id = str(org_value).strip() or None
                    except Exception:  # pragma: no cover - str conversion defensiva
                        contact_org_id = None

        if channel == "webchat":
            try:
                await storage.register_webchat_message(
                    session_id=session_id or "",
                    author="agent",
                    content=content,
                    inactivity_minutes=(
                        settings.webchat_inactivity_minutes
                        if settings.webchat_inactivity_minutes is not None
                        else (
                            settings.webchat_inactivity_hours * 60
                            if settings.webchat_inactivity_hours is not None
                            else None
                        )
                    ),
                    metadata=extra_metadata,
                    attachments=attachments_payload,
                    organizacion_id=contact_org_id,
                )
            except StorageError as exc:
                logger.exception(
                    "panel.inbox.manual_register_failed",
                    extra={"conversation_id": str(conversacion_id), "error": str(exc)},
                )
                raise HTTPException(
                    status_code=502, detail="No se pudo registrar el mensaje"
                ) from exc

            try:
                await webchat_service.append_manual_agent_context(
                    conversation_meta=conversation_meta,
                    session_id=session_id or "",
                    content=content,
                    locale=payload.locale,
                )
            except Exception as exc:  # pragma: no cover - logging defensivo
                logger.exception(
                    "panel.inbox.manual_context_append_failed",
                    extra={"conversation_id": str(conversacion_id), "error": str(exc)},
                )

            logger.info(
                "panel.inbox.manual_message_recorded",
                extra={
                    "conversation_id": str(conversacion_id),
                    "session_id": session_id,
                    "client_message_id": client_message_id,
                },
            )

            metadata: dict[str, Any] = {
                "conversation_id": str(conversacion_id),
                "client_message_id": client_message_id,
                "manual_mode": True,
                "session_id": session_id,
                "persona_id": str(persona_id),
                "contact_id": str(persona_id),
                "sender_type": "human",
                "author_type": "human",
            }
            if attachments_payload:
                metadata["attachments"] = attachments_payload
            if agent_payload:
                metadata["extra"] = agent_payload
                manual_name_resp = agent_payload.get("manual_author") or agent_payload.get(
                    "manualAuthor"
                )
                agent_name_resp = agent_payload.get("agent_name") or agent_payload.get("agentName")
                manual_email_resp = (
                    agent_payload.get("manual_email")
                    or agent_payload.get("manualEmail")
                    or agent_payload.get("agent_email")
                    or agent_payload.get("agentEmail")
                )
                if isinstance(agent_name_resp, str) and agent_name_resp.strip():
                    metadata["agent_name"] = agent_name_resp.strip()
                elif isinstance(manual_name_resp, str) and manual_name_resp.strip():
                    metadata["agent_name"] = manual_name_resp.strip()
                if isinstance(manual_name_resp, str) and manual_name_resp.strip():
                    metadata["manual_author"] = manual_name_resp.strip()
                if isinstance(manual_email_resp, str) and manual_email_resp.strip():
                    cleaned_email = manual_email_resp.strip()
                    metadata["manual_email"] = cleaned_email
                    metadata.setdefault("agent_email", cleaned_email)
            return {
                "ok": True,
                "reply": None,
                "metadata": metadata,
            }

        if channel == "whatsapp":
            metadata = await _send_manual_whatsapp_message(
                conversation_id=str(conversacion_id),
                contact_id=str(persona_id),
                content=content,
                metadata=extra_metadata,
            )
            return {
                "ok": True,
                "reply": None,
                "metadata": metadata,
            }

        if channel == "correo":
            try:
                persona_row = await storage.fetch_persona(str(persona_id))
            except StorageError as exc:
                raise HTTPException(status_code=502, detail="contact_lookup_failed") from exc
            recipient_email = _clean_text(persona_row.get("correo"))
            if not recipient_email:
                raise HTTPException(status_code=409, detail="contact_email_not_found")
            org_value = persona_row.get("organizacion_id")
            org_uuid: UUID | None = None
            if org_value:
                try:
                    org_uuid = UUID(str(org_value))
                except (TypeError, ValueError):
                    org_uuid = None
            runtime_org_id = org_uuid or tenant_runtime.MASTER_ORGANIZACION_ID

            subject = _clean_text(payload.metadata.get("subject")) if isinstance(payload.metadata, dict) else None
            recent_messages = await storage.fetch_recent_messages(conversation_id=str(conversacion_id), limit=20)
            latest_subject: str | None = None
            in_reply_to: str | None = None
            references: list[str] = []
            for message_row in reversed(recent_messages):
                if not isinstance(message_row, dict):
                    continue
                datos = message_row.get("datos")
                if isinstance(datos, str):
                    try:
                        datos = json.loads(datos)
                    except json.JSONDecodeError:
                        datos = {}
                if not isinstance(datos, dict):
                    continue
                if latest_subject is None:
                    latest_subject = _clean_text(datos.get("subject"))
                message_id_value = _clean_text(datos.get("message_id"))
                if message_id_value and message_id_value not in references:
                    references.append(message_id_value)
                if in_reply_to is None and message_id_value and message_row.get("direccion") == "entrante":
                    in_reply_to = message_id_value

            resolved_subject = subject or latest_subject or "Seguimiento"
            if resolved_subject.lower().startswith("re:"):
                mail_subject = resolved_subject
            else:
                mail_subject = f"Re: {resolved_subject}"
            headers: dict[str, str] = {}
            if in_reply_to:
                headers["In-Reply-To"] = f"<{in_reply_to}>"
            if references:
                headers["References"] = " ".join(f"<{value}>" for value in references[:15])
            try:
                mail_settings, brevo_settings = await asyncio.gather(
                    tenant_runtime.get_mail_runtime_settings(organizacion_id=runtime_org_id),
                    tenant_runtime.get_brevo_runtime_settings(organizacion_id=runtime_org_id),
                )
            except Exception as exc:
                raise HTTPException(status_code=502, detail=f"mail_runtime_error:{exc}") from exc
            reply_to_value = _clean_text(getattr(mail_settings, "reply_to", None))
            if reply_to_value and "Reply-To" not in headers:
                headers["Reply-To"] = reply_to_value

            try:
                send_result = send_email_detailed(
                    subject=mail_subject,
                    body_text=content,
                    recipients=[recipient_email],
                    headers=headers or None,
                    mail_settings=mail_settings,
                    brevo_settings=brevo_settings,
                )
            except EmailSendError as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc
            sent_message_id = send_result.provider_message_id

            message_metadata = {
                "channel": "correo",
                "source": "operativo",
                "action": "reply_manual",
                "subject": mail_subject,
                "recipient_email": recipient_email,
                "message_id": sent_message_id,
                "local_message_id": send_result.local_message_id,
                "in_reply_to": in_reply_to,
                "references": references,
            }
            try:
                system_repo = CRMRepository()
                inserted = await system_repo.insert_inbox_message(
                    conversation_id=conversacion_id,
                    direction="saliente",
                    text=content,
                    datos=message_metadata,
                    estado="enviada",
                    provider_message_id=sent_message_id,
                    organizacion_id=org_uuid,
                )
            except CRMRepositoryError as exc:
                raise HTTPException(status_code=502, detail=f"inbox_message_save_failed:{exc}") from exc

            return {
                "ok": True,
                "reply": None,
                "metadata": {
                    "conversation_id": str(conversacion_id),
                    "client_message_id": client_message_id,
                    "manual_mode": True,
                    "persona_id": str(persona_id),
                    "contact_id": str(persona_id),
                    "channel": "correo",
                    "message_id": sent_message_id,
                    "inbox_message_id": inserted.get("id"),
                    "recipient_email": recipient_email,
                },
            }

        raise HTTPException(status_code=400, detail="unsupported_channel")

    if channel != "webchat":
        raise HTTPException(status_code=400, detail="unsupported_channel")

    try:
        logger.info(
            "panel.inbox.manual_state_auto_reply",
            extra={
                "conversation_id": str(conversacion_id),
                "manual_override": manual_override,
                "client_message_id": client_message_id,
            },
        )
        assistant_response = await webchat_service.handle_message(
            message_payload,
            request=None,
        )
    except HTTPException:
        raise
    except Exception as exc:  # pragma: no cover - logging y error genérico
        logger.exception(
            "panel.inbox.assistant_failed",
            extra={"conversation_id": str(conversacion_id), "error": str(exc)},
        )
        raise HTTPException(status_code=502, detail="Error al invocar al asistente") from exc

    metadata_model = assistant_response.metadata
    metadata = (
        metadata_model.model_dump(exclude_none=True)
        if isinstance(metadata_model, BaseModel)
        else {}
    )
    metadata.setdefault("conversation_id", str(conversacion_id))
    metadata.setdefault("client_message_id", client_message_id)
    metadata.setdefault(
        "manual_mode",
        (
            bool(metadata_model.manual_mode)
            if isinstance(metadata_model, webchat_schemas.MessageMetadata)
            else False
        ),
    )
    metadata.setdefault("session_id", session_id)
    metadata.setdefault("persona_id", str(persona_id))
    metadata.setdefault("contact_id", str(persona_id))

    return {
        "ok": True,
        "reply": assistant_response.reply,
        "metadata": metadata,
    }


@router.post("/inbox/conversations/{conversacion_id}/attachments")
async def upload_inbox_attachment(
    *,
    _: str = Depends(require_permission("messages.write")),
    user_token: str = Depends(require_user_token),  # noqa: ARG001
    conversacion_id: UUID,
    file: UploadFile = File(...),
) -> dict[str, Any]:
    try:
        conversation_meta = await storage.fetch_webchat_conversation(str(conversacion_id))
    except StorageError as exc:
        logger.exception(
            "panel.inbox.fetch_conversation_failed",
            extra={"conversation_id": str(conversacion_id), "error": str(exc)},
        )
        raise HTTPException(status_code=502, detail="conversation_lookup_failed") from exc

    channel = (conversation_meta.get("channel") or "").lower()
    if channel != "webchat":
        raise HTTPException(status_code=400, detail="unsupported_channel")

    persona_id = conversation_meta.get("persona_id") or conversation_meta.get("contact_id")
    session_id = None
    if persona_id:
        session_id = await _resolve_webchat_session_id(str(persona_id))

    try:
        uploaded = await storage.upload_webchat_attachment(
            file=file,
            session_id=session_id,
            conversation_id=str(conversacion_id),
        )
    except StorageError as exc:
        raise HTTPException(status_code=502, detail="upload_failed") from exc

    return {"ok": True, "attachment": uploaded}


@router.get("/inbox/attachments/{attachment_id}")
async def download_inbox_attachment(
    *,
    attachment_id: UUID,
    _: str = Depends(require_permission("ver_inbox")),
) -> Response:
    repo = CRMRepository()
    try:
        attachment = await repo.worker_get_attachment_by_id(
            attachment_id=str(attachment_id),
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"attachment_lookup_failed:{exc}") from exc

    if not isinstance(attachment, dict):
        raise HTTPException(status_code=404, detail="attachment_not_found")

    stored_url = str(attachment.get("url") or "").strip()
    stored_path = str(attachment.get("path") or "").strip()
    source_url = stored_path if stored_path.startswith("http://") or stored_path.startswith("https://") else stored_url
    filename = str(attachment.get("nombre") or attachment_id).strip() or str(attachment_id)
    mime = str(attachment.get("mime") or "application/octet-stream").strip() or "application/octet-stream"

    if stored_path and not stored_path.startswith("http://") and not stored_path.startswith("https://"):
        bucket_name, separator, object_key = stored_path.partition("/")
        if separator and bucket_name:
            if bucket_name == "webchat":
                base_url = settings.supabase_url.rstrip("/") if settings.supabase_url else ""
                if base_url:
                    return RedirectResponse(
                        url=f"{base_url}/storage/v1/object/public/{stored_path}",
                        status_code=status.HTTP_307_TEMPORARY_REDIRECT,
                    )
            try:
                signed_url = await repo.create_signed_storage_url(
                    bucket=bucket_name,
                    object_path=object_key,
                    expires_in=300,
                )
            except Exception as exc:
                raise HTTPException(status_code=502, detail=f"attachment_signed_url_failed:{exc}") from exc
            return RedirectResponse(url=signed_url, status_code=status.HTTP_307_TEMPORARY_REDIRECT)

    if source_url.startswith("http://") or source_url.startswith("https://"):
        parsed = urlparse(source_url)
        if "twilio.com" not in parsed.netloc:
            return RedirectResponse(url=source_url, status_code=status.HTTP_307_TEMPORARY_REDIRECT)

        organizacion_id_value = attachment.get("organizacion_id")
        if not organizacion_id_value:
            raise HTTPException(status_code=502, detail="attachment_org_missing")
        try:
            org_uuid = UUID(str(organizacion_id_value))
        except ValueError as exc:
            raise HTTPException(status_code=502, detail="attachment_org_invalid") from exc
        whatsapp_settings = await tenant_runtime.get_whatsapp_runtime_settings(organizacion_id=org_uuid)
        account_sid = getattr(whatsapp_settings, "twilio_account_sid", None)
        auth_token = getattr(whatsapp_settings, "twilio_auth_token", None)
        if not account_sid or not auth_token:
            raise HTTPException(status_code=502, detail="twilio_attachment_not_configured")
        try:
            async with httpx.AsyncClient(timeout=20.0, follow_redirects=True) as client:
                response = await client.get(source_url, auth=(account_sid, auth_token))
        except Exception as exc:
            raise HTTPException(status_code=502, detail=f"attachment_download_failed:{exc}") from exc
        if response.status_code >= 400:
            raise HTTPException(
                status_code=502,
                detail=f"attachment_download_failed:http_{response.status_code}",
            )
        headers = {
            "Content-Disposition": f'inline; filename="{filename}"',
        }
        return Response(content=response.content, media_type=mime, headers=headers)

    if stored_url.startswith("http://") or stored_url.startswith("https://"):
        return RedirectResponse(url=stored_url, status_code=status.HTTP_307_TEMPORARY_REDIRECT)

    if stored_path.startswith("http://") or stored_path.startswith("https://"):
        return RedirectResponse(url=stored_path, status_code=status.HTTP_307_TEMPORARY_REDIRECT)

    raise HTTPException(status_code=404, detail="attachment_not_found")


def _assistant_document_delivery_secret() -> str | None:
    candidates = [
        getattr(settings, "secrets_master_key_high", None),
        getattr(settings, "secrets_master_key", None),
        getattr(settings, "supabase_jwt_secret", None),
    ]
    for candidate in candidates:
        if candidate:
            value = str(candidate).strip()
            if value:
                return value
    return None


def _decode_assistant_document_delivery_token(token: str) -> dict[str, Any] | None:
    raw_token = (token or "").strip()
    if not raw_token:
        return None
    parts = raw_token.split(".", 1)
    if len(parts) != 2:
        return None
    payload_b64, signature_b64 = parts
    secret = _assistant_document_delivery_secret()
    if not secret:
        return None
    try:
        payload_bytes = base64.urlsafe_b64decode(payload_b64 + "=" * (-len(payload_b64) % 4))
        signature_bytes = base64.urlsafe_b64decode(signature_b64 + "=" * (-len(signature_b64) % 4))
    except Exception:
        return None
    expected_signature = hmac.new(
        secret.encode("utf-8"),
        payload_b64.encode("ascii"),
        hashlib.sha256,
    ).digest()
    if not hmac.compare_digest(expected_signature, signature_bytes):
        return None
    try:
        payload = json.loads(payload_bytes.decode("utf-8"))
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    exp = payload.get("exp")
    try:
        if int(exp) < int(datetime.now(timezone.utc).timestamp()):
            return None
    except Exception:
        return None
    return payload


async def _public_assistant_document_download_impl(
    *,
    document_id: UUID,
    token: str = Query(..., min_length=10),
) -> Response:
    payload = _decode_assistant_document_delivery_token(token)
    if not payload:
        raise HTTPException(status_code=403, detail="assistant_document_token_invalid")

    payload_document_id = str(payload.get("document_id") or "").strip()
    payload_organizacion_id = str(payload.get("organizacion_id") or "").strip()
    if payload_document_id != str(document_id):
        raise HTTPException(status_code=403, detail="assistant_document_token_mismatch")

    try:
        org_uuid = UUID(payload_organizacion_id)
    except ValueError as exc:
        raise HTTPException(status_code=403, detail="assistant_document_token_org_invalid") from exc

    repo = CRMRepository()
    try:
        document = await repo.get_assistant_document(
            organizacion_id=org_uuid,
            document_id=document_id,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"assistant_document_lookup_failed:{exc}") from exc

    if not isinstance(document, dict):
        raise HTTPException(status_code=404, detail="assistant_document_not_found")

    storage_bucket = str(document.get("storage_bucket") or "").strip()
    storage_path = str(document.get("storage_path") or "").strip()
    if not storage_bucket or not storage_path:
        raise HTTPException(status_code=404, detail="assistant_document_storage_missing")

    try:
        content = await repo.download_storage_object(
            bucket=storage_bucket,
            object_path=storage_path,
        )
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"assistant_document_download_failed:{exc}") from exc

    filename = str(document.get("title") or document_id).strip() or str(document_id)
    if not filename.lower().endswith(".pdf"):
        filename = f"{filename}.pdf"
    headers = {
        "Content-Disposition": f'inline; filename="{filename}"',
        "Cache-Control": "no-store",
    }
    return Response(content=content, media_type="application/pdf", headers=headers)


@router.get("/public/assistant-documents/{document_id}")
async def public_assistant_document_download(
    *,
    document_id: UUID,
    token: str = Query(..., min_length=10),
) -> Response:
    return await _public_assistant_document_download_impl(document_id=document_id, token=token)


@router.head("/public/assistant-documents/{document_id}")
async def public_assistant_document_download_head(
    *,
    document_id: UUID,
    token: str = Query(..., min_length=10),
) -> Response:
    response = await _public_assistant_document_download_impl(document_id=document_id, token=token)
    return Response(
        content=b"",
        status_code=response.status_code,
        headers={
            key: value
            for key, value in response.headers.items()
            if key.lower() in {"content-type", "content-disposition", "cache-control"}
        },
    )


def _stringify_uuid(value: UUID | str | None) -> str | None:
    if isinstance(value, UUID):
        return str(value)
    if isinstance(value, str):
        trimmed = value.strip()
        return trimmed or None
    return None


def _extract_opportunity_contact_id(opportunity: dict[str, Any] | None) -> UUID | None:
    if not isinstance(opportunity, dict):
        return None
    for key in ("contacto_principal_id", "contacto_id"):
        candidate = _safe_uuid(opportunity.get(key))
        if candidate:
            return candidate
    contact = opportunity.get("contacto")
    if isinstance(contact, dict):
        candidate = _safe_uuid(contact.get("id"))
        if candidate:
            return candidate
    return None


def _extract_opportunity_conversation_id(opportunity: dict[str, Any] | None) -> str | None:
    if not isinstance(opportunity, dict):
        return None
    metadata = _ensure_dict(opportunity.get("metadata"), default={})
    for key in ("conversation_id", "conversacion_id"):
        value = metadata.get(key)
        if isinstance(value, str):
            trimmed = value.strip()
            if trimmed:
                return trimmed
    return None


def _extract_opportunity_assignment_id(opportunity: dict[str, Any] | None) -> UUID | None:
    if not isinstance(opportunity, dict):
        return None
    for key in ("asignado_a_usuario_id", "propietario_usuario_id"):
        candidate = _safe_uuid(opportunity.get(key))
        if candidate:
            return candidate
    asignado = opportunity.get("asignado")
    if isinstance(asignado, dict):
        candidate = _safe_uuid(asignado.get("id"))
        if candidate:
            return candidate
    propietario = opportunity.get("propietario")
    if isinstance(propietario, dict):
        candidate = _safe_uuid(propietario.get("id"))
        if candidate:
            return candidate
    return None


def _resolve_conversation_channel(
    preferred: str | None,
    opportunity: dict[str, Any] | None,
) -> str:
    candidates: list[str | None] = [preferred]
    if isinstance(opportunity, dict):
        candidates.append(opportunity.get("canal"))
        metadata = _ensure_dict(opportunity.get("metadata"), default={})
        candidates.append(metadata.get("channel"))
        candidates.append(metadata.get("canal"))
    for candidate in candidates:
        if isinstance(candidate, str):
            trimmed = candidate.strip()
            if trimmed:
                return trimmed
    return "manual"


async def _persist_opportunity_conversation_metadata(
    *,
    repo: CRMRepository,
    opportunity: dict[str, Any] | None,
    conversation_id: str,
) -> None:
    if not isinstance(opportunity, dict):
        return
    org_uuid = _safe_uuid(opportunity.get("organizacion_id"))
    opp_uuid = _safe_uuid(opportunity.get("id"))
    if not org_uuid or not opp_uuid:
        return
    metadata = _ensure_dict(opportunity.get("metadata"), default={})
    existing = metadata.get("conversation_id")
    if isinstance(existing, str) and existing.strip() == conversation_id:
        return
    metadata["conversation_id"] = conversation_id
    if "conversacion_id" in metadata:
        metadata["conversacion_id"] = conversation_id
    try:
        await repo.update_opportunity(
            organizacion_id=org_uuid,
            oportunidad_id=opp_uuid,
            payload={"metadata": metadata},
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "agenda.booking.metadata_patch_failed",
            extra={
                "oportunidad_id": str(opp_uuid),
                "error": str(exc),
            },
        )


@router.get("/agenda/bookings")
async def list_agenda_bookings(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("agenda.view")),
    user_token: str = Depends(require_user_token),
    rango: str | None = Query(default=None),
    fecha_desde: str | None = Query(default=None, alias="from"),
    fecha_hasta: str | None = Query(default=None, alias="to"),
    estado: list[str] | None = Query(default=None),
    assigned: list[str] | None = Query(default=None),
    provider: list[str] | None = Query(default=None),
    search: str | None = Query(default=None),
    limit: Annotated[int, Query(ge=1, le=500)] = 200,
    cursor: Annotated[int, Query(ge=0)] = 0,
) -> dict[str, Any]:
    limit = max(1, min(limit, 500))
    offset = max(cursor, 0)

    date_from, date_to = _resolve_date_range(rango, fecha_desde, fecha_hasta)
    if not date_from and not date_to:
        now = datetime.now(timezone.utc)
        date_from = now - timedelta(days=30)
        date_to = now + timedelta(days=30)

    select_clause = (
        "id,resource_id,hold_id,tarjeta_id,conversacion_id,"
        "persona_id,contact_id,contacto_id:contact_id,"
        "start_at,end_at,timezone,status,notes,meeting_url,external_join_url,metadata,"
        "created_at,updated_at,tarjeta_canal,tarjeta_lead_score,"
        "etapa_nombre,asignado_a_usuario_id,asignado_nombre,"
        "propietario_usuario_id,propietario_nombre,"
        "contacto_nombre,contacto_correo,contacto_telefono,contacto_empresa,contacto_origen,"
        "conversacion_canal"
    )

    params: dict[str, str] = {
        "select": select_clause,
        "order": "start_at.asc.nullslast,created_at.asc",
        "limit": str(limit),
        "offset": str(offset),
    }

    and_filters: list[str] = []
    if date_from:
        and_filters.append(f"start_at.gte.{_format_utc(date_from)}")
    if date_to:
        and_filters.append(f"start_at.lte.{_format_utc(date_to)}")
    if and_filters:
        params["and"] = f"({','.join(and_filters)})"

    estado_filters = {
        value.strip().lower()
        for value in (estado or [])
        if isinstance(value, str) and value.strip()
    }
    status_filters: set[str] = set()
    for value in estado_filters:
        if value in {"cancelada"}:
            status_filters.add("cancelled")
        elif value in {"confirmada", "pendiente", "reprogramada"}:
            status_filters.add("confirmed")
    if status_filters:
        if len(status_filters) == 1:
            params["status"] = f"eq.{next(iter(status_filters))}"
        else:
            joined = ",".join(sorted(status_filters))
            params["status"] = f"in.({joined})"

    assigned_uuid_filters = {
        value.strip()
        for value in (assigned or [])
        if isinstance(value, str) and _looks_like_uuid(value.strip())
    }
    if assigned_uuid_filters:
        if len(assigned_uuid_filters) == 1:
            params["asignado_a_usuario_id"] = f"eq.{next(iter(assigned_uuid_filters))}"
        else:
            params["asignado_a_usuario_id"] = f"in.({','.join(sorted(assigned_uuid_filters))})"

    if search:
        cleaned = " ".join(search.strip().split())
        sanitized = "".join(ch for ch in cleaned if ch.isalnum() or ch in "@._+- ")
        if sanitized:
            like = sanitized
            params["or"] = (
                f"(contacto_nombre.ilike.*{like}*,contacto_correo.ilike.*{like}*,"
                f"contacto_telefono.ilike.*{like}*,notes.ilike.*{like}*)"
            )

    provider_filters = {
        value.strip().lower()
        for value in (provider or [])
        if isinstance(value, str) and value.strip()
    }
    if provider_filters and "calendar" not in provider_filters:
        empty_metrics = {
            "total": 0,
            "activas": 0,
            "proximas24h": 0,
            "canceladas": 0,
            "realizadas": 0,
        }
        return {
            "ok": True,
            "items": [],
            "metrics": empty_metrics,
            "total": 0,
            "limit": limit,
            "offset": offset,
            "has_more": False,
        }

    try:
        raw, total = await repo.list_agenda_bookings(
            usuario_token=user_token,
            params=params,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    items = [_map_agenda_row(row) for row in raw if isinstance(row, dict)]
    filtered_items: list[dict[str, Any]] = []
    assigned_name_filters = {
        value.strip().lower()
        for value in (assigned or [])
        if isinstance(value, str) and not _looks_like_uuid(value.strip()) and value.strip()
    }

    for item in items:
        estado_value = (item.get("estado") or "").lower()
        if estado_filters and estado_value not in estado_filters:
            continue
        if assigned_name_filters:
            assigned_payload = item.get("asignado") or {}
            candidate_id = (assigned_payload.get("id") or "").lower()
            candidate_name = (assigned_payload.get("nombre") or "").lower()
            if (
                candidate_id not in assigned_name_filters
                and candidate_name not in assigned_name_filters
            ):
                continue
        filtered_items.append(item)

    metrics = _compute_agenda_metrics(filtered_items)
    raw_count = len(raw)
    computed_total = total if total is not None else offset + raw_count

    return {
        "ok": True,
        "items": filtered_items,
        "metrics": metrics,
        "total": computed_total,
        "limit": limit,
        "offset": offset,
        "has_more": computed_total > offset + raw_count,
    }


@router.post("/agenda/bookings")
async def create_agenda_booking(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("agenda.view")),
    organizacion_id: UUID = Depends(require_organizacion_id),
    user_token: str = Depends(require_user_token),  # noqa: ARG001
    payload: AgendaBookingCreatePayload,
) -> dict[str, Any]:
    start_dt = _parse_datetime_input(payload.start_at, field="start_at")
    crear_oportunidad = False

    opportunity_row: dict[str, Any] | None = None
    if payload.oportunidad_id:
        try:
            opportunity_row = await repo.get_pipeline_opportunity_by_id(
                oportunidad_id=payload.oportunidad_id,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if opportunity_row is None:
            raise HTTPException(status_code=404, detail="oportunidad_no_encontrada")

    contact_uuid = payload.persona_id or payload.contacto_id
    if opportunity_row:
        if contact_uuid is None:
            contact_uuid = _extract_opportunity_contact_id(opportunity_row)
    if payload.sin_contacto:
        contact_uuid = None
        opportunity_row = None
    elif contact_uuid is None:
        raise HTTPException(status_code=400, detail="contacto_id_requerido")

    contact_id = str(contact_uuid) if contact_uuid else None
    asunto_value = (payload.asunto or "").strip() or "Cita manual"
    persona_data: dict[str, Any] | None = None
    org_uuid = organizacion_id
    if contact_id:
        try:
            persona_data = await repo.get_persona_by_id(persona_id=contact_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not persona_data:
            raise HTTPException(status_code=404, detail="contacto_no_encontrado")

        contact_org_uuid = _safe_uuid(persona_data.get("organizacion_id"))
        if contact_org_uuid is not None:
            org_uuid = contact_org_uuid

    calendar_settings = await tenant_runtime.get_calendar_runtime_settings(
        organizacion_id=org_uuid
    )
    resource_id = (calendar_settings.resource_id or "").strip()
    if not resource_id:
        raise HTTPException(status_code=400, detail="calendar_resource_missing")

    tarjeta_id = str(payload.oportunidad_id) if payload.oportunidad_id else None
    modalidad_value = (payload.modalidad or "virtual").strip().lower()
    if modalidad_value not in {"virtual", "presencial", "hibrida"}:
        raise HTTPException(status_code=400, detail="modalidad_invalid")
    zoom_meeting_url: str | None = None
    zoom_external_join_url: str | None = None
    zoom_metadata: dict[str, Any] = {}
    if modalidad_value != "presencial":
        booking_topic_name = "Cita manual"
        if persona_data:
            booking_topic_name = str(persona_data.get("nombre_completo") or "").strip() or "Cita manual"
        elif payload.sin_contacto and asunto_value:
            booking_topic_name = asunto_value
        zoom_meeting_url, zoom_external_join_url, zoom_metadata = (
            await webchat_service.create_zoom_meeting_for_booking_if_enabled(
                organizacion_id=org_uuid,
                start_at=start_dt,
                timezone_name=calendar_settings.timezone,
                topic=f"Demo Tal-IA - {booking_topic_name}",
                agenda=payload.notes,
            )
        )
    hold_metadata: dict[str, Any] = {
        "source": "panel_agenda",
        "session_id": payload.session_id,
        "persona_id": contact_id,
        "contact_id": contact_id,
        "tarjeta_id": tarjeta_id,
        "crear_oportunidad": crear_oportunidad,
        "sin_contacto": contact_id is None,
        "asunto": asunto_value if payload.sin_contacto else None,
        "modalidad": modalidad_value,
        "canal": (payload.canal or "manual"),
        "organizacion_id": str(org_uuid),
    }
    if zoom_metadata:
        hold_metadata.update(zoom_metadata)
    booking_metadata: dict[str, Any] = {
        "source": "panel_agenda",
        "session_id": payload.session_id,
        "persona_id": contact_id,
        "contact_id": contact_id,
        "tarjeta_id": tarjeta_id,
        "crear_oportunidad": crear_oportunidad,
        "sin_contacto": contact_id is None,
        "asunto": asunto_value if payload.sin_contacto else None,
        "modalidad": modalidad_value,
        "canal": (payload.canal or "manual"),
        "organizacion_id": str(org_uuid),
    }
    if zoom_metadata:
        booking_metadata.update(zoom_metadata)
    try:
        hold = await calendar_service.hold_slot(
            resource_id=resource_id,
            slot_start=start_dt,
            conversation_id=None,
            contact_id=contact_id,
            tarjeta_id=tarjeta_id,
            hold_minutes=max(1, int(calendar_settings.hold_minutes or 10)),
            metadata=hold_metadata,
        )
        booking_raw = await calendar_service.confirm_slot(
            hold_id=str(hold.get("hold_id")),
            notes=payload.notes,
            metadata=booking_metadata,
            meeting_url=zoom_meeting_url,
            external_join_url=zoom_external_join_url,
        )
    except CalendarError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    booking_response = webchat_service._build_booking_response(booking_raw)
    if tarjeta_id and persona_data:
        await webchat_service._sync_booking_with_opportunity(
            booking=booking_response,
            tarjeta_id=tarjeta_id,
            persona=persona_data,
            channel=(payload.canal or "manual"),
        )
    if contact_id or persona_data:
        try:
            await webchat_service._send_booking_confirmation_email(
                booking=booking_response,
                persona_id=contact_id,
                conversation_id=None,
                tarjeta_id=tarjeta_id,
                persona=persona_data,
            )
        except Exception as exc:  # pragma: no cover - defensivo
            logger.exception(
                "crm.agenda.booking.confirmation_email_failed",
                extra={
                    "booking_id": booking_response.booking_id,
                    "persona_id": contact_id,
                    "tarjeta_id": tarjeta_id,
                    "error": str(exc),
                },
            )
    booking = booking_response

    return {"ok": True, "booking": booking}


@router.get("/agenda/availability")
async def get_agenda_availability(
    *,
    _: str = Depends(require_permission("agenda.view")),
    user_token: str = Depends(require_user_token),  # noqa: ARG001
    resource_id: str | None = Query(default=None),
    fecha_desde: str | None = Query(default=None, alias="from"),
    fecha_hasta: str | None = Query(default=None, alias="to"),
    timezone_hint: str | None = Query(default=None, alias="timezone"),
    max_days: Annotated[int, Query(ge=1, le=60)] = 14,
) -> dict[str, Any]:
    calendar_resource = resource_id or settings.webchat_calendar_resource_id
    if not calendar_resource:
        raise HTTPException(status_code=400, detail="calendar_resource_missing")

    today = datetime.now(timezone.utc).date()
    if fecha_desde:
        start_date = _parse_date_value(fecha_desde, field="from")
        if not start_date:
            raise HTTPException(status_code=400, detail="from_invalid")
        start_day = start_date.date()
    else:
        start_day = today
    if fecha_hasta:
        end_date_parsed = _parse_date_value(fecha_hasta, field="to")
        if not end_date_parsed:
            raise HTTPException(status_code=400, detail="to_invalid")
        end_day = end_date_parsed.date()
    else:
        end_day = start_day + timedelta(days=max_days)

    if start_day > end_day:
        raise HTTPException(status_code=400, detail="range_invalid")

    allowed_span = timedelta(days=min(max_days, 60))
    if end_day - start_day > allowed_span:
        end_day = start_day + allowed_span

    tz_hint = (timezone_hint or settings.webchat_calendar_timezone or "UTC").strip()
    try:
        payload = await calendar_service.list_slots(
            resource_id=calendar_resource,
            start_date=start_day,
            end_date=end_day,
            timezone_hint=tz_hint,
            max_days=min(max_days, 60),
        )
    except CalendarError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return {"ok": True, "availability": payload}


