@router.post(
    "/oportunidades/{oportunidad_id}/quotes",
    response_model=LeadQuoteResponse,
    status_code=status.HTTP_201_CREATED,
)
async def create_lead_quote(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("propuesta.view")),
    oportunidad_id: UUID,
    payload: LeadQuoteCreatePayload,
    usuario_id: UUID | None = Depends(optional_usuario_id),
) -> LeadQuoteResponse:
    opportunity = await repo.get_opportunity_with_contact(
        organizacion_id=organizacion_id,
        oportunidad_id=oportunidad_id,
    )
    if opportunity is None:
        raise HTTPException(status_code=404, detail="oportunidad_no_encontrada")
    contact = _single_related(opportunity.get("contacto")) or {}
    cuenta = _single_related(opportunity.get("cuenta")) or {}
    oportunidad_metadata = _ensure_dict(opportunity.get("metadata"), default={})
    lead_label = (
        opportunity.get("titulo")
        or contact.get("nombre_completo")
        or cuenta.get("nombre")
        or "Oportunidad sin nombre"
    )
    body = _quote_payload_from_body(payload)
    metadata = _quote_metadata_from_payload(body)
    repo_items = _quote_items_to_repository_payload(body.pop("items", None))
    currency = (body.get("moneda") or "MXN").upper()
    normalized_items = _normalize_quote_items(payload.items or [])
    totals = _quote_totals_from_items(normalized_items)
    if totals:
        body["subtotal"] = totals["subtotal"]
        body["impuestos"] = totals["impuestos"]
        body["total"] = totals["total"]
    conceptos_context = body.get("conceptos") or _concepts_from_items(normalized_items)
    project_description = _clean_text(body.get("descripcion")) or None
    vendor_context, mail_settings = await _resolve_quote_sender_runtime(
        repo=repo,
        organizacion_id=organizacion_id,
        opportunity=opportunity,
        usuario_id=usuario_id,
    )
    quote_display_timezone = await _resolve_quote_display_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    quote_vendor_settings = _resolve_effective_quote_vendor_settings(
        payload_settings=metadata.get("quote_vendedores")
        if isinstance(metadata.get("quote_vendedores"), Mapping)
        else None,
        tenant_settings=vendor_context.get("quote_vendor_settings"),
    )
    quote_vendor_notes = _clean_text(quote_vendor_settings.get("notesBody")) or (
        oportunidad_metadata.get("proyecto_necesidades") or contact.get("necesidad_proposito")
    )
    logo_url = await _resolve_quote_logo_url(organizacion_id=organizacion_id)
    quote_folio = _normalize_quote_folio_value(body.get("folio"))
    if not quote_folio:
        quote_folio = str(
            (
                await _reserve_quote_folio_for_opportunity(
                    repo=repo,
                    organizacion_id=organizacion_id,
                    vendor_context=vendor_context,
                )
            )["folio"]
        )

    issuer_name = mail_settings.from_name or mail_settings.username or "Tal-IA"
    issuer_email = mail_settings.username
    quote_context = quotes_service.QuoteRenderContext(
        folio=quote_folio,
        lead_label=lead_label,
        reference=str(oportunidad_id).split("-")[0],
        issuer_name=issuer_name,
        issuer_email=issuer_email,
        contact_name=_clean_text(contact.get("nombre_completo")),
        contact_company=_clean_text(contact.get("company_name")),
        contact_email=_clean_text(contact.get("correo")),
        contact_phone=_clean_text(contact.get("telefono_e164")),
        conceptos=conceptos_context,
        subtotal=_as_number(body.get("subtotal")),
        impuestos=_as_number(body.get("impuestos")),
        total=_as_number(body.get("total")),
        moneda=currency,
        valido_hasta=_resolve_quote_valid_until(body.get("valido_hasta"), quote_vendor_settings),
        descripcion=project_description,
        notes=quote_vendor_notes,
        items=normalized_items,
        quote_vendor_settings=quote_vendor_settings,
        organization_name=vendor_context["organization_name"],
        organization_slogan=vendor_context["organization_slogan"],
        organization_razon_social=vendor_context["organization_razon_social"],
        organization_rfc=vendor_context["organization_rfc"],
        organization_street=vendor_context["organization_street"],
        organization_exterior_number=vendor_context["organization_exterior_number"],
        organization_interior_number=vendor_context["organization_interior_number"],
        organization_colonia=vendor_context["organization_colonia"],
        organization_postal_code=vendor_context["organization_postal_code"],
        organization_state=vendor_context["organization_state"],
        organization_city=vendor_context["organization_city"],
        organization_country=vendor_context["organization_country"],
        organization_website=vendor_context["organization_website"],
        display_timezone=quote_display_timezone,
        vendor_company_name=vendor_context["vendor_company_name"],
        vendor_razon_social=vendor_context["vendor_razon_social"],
        vendor_assessor_name=vendor_context["vendor_assessor_name"],
        vendor_assessor_phone=vendor_context["vendor_assessor_phone"],
        vendor_assessor_email=vendor_context["vendor_assessor_email"],
        logo_url=logo_url,
    )

    try:
        pdf_doc = await quotes_service.render_quote_pdf(quote_context)
    except Exception as exc:
        raise HTTPException(status_code=502, detail="quote_pdf_render_failed") from exc

    try:
        valido_hasta = _to_iso_date(body.get("valido_hasta"))
        upload = await storage.upload_quote_document(
            content=pdf_doc.content,
            filename=pdf_doc.filename,
            lead_id=str(oportunidad_id),
            content_type="application/pdf",
        )
    except StorageError as exc:
        raise HTTPException(status_code=502, detail="quote_upload_failed") from exc

    body["pdf_url"] = upload["url"]
    body["pdf_path"] = upload["path"]
    metadata = _quote_metadata_from_payload(body)
    try:
        created_row = await repo.create_quote_entry(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
        cuenta_id=_safe_uuid(opportunity.get("cuenta_id")),
        contacto_id=_safe_uuid(opportunity.get("contacto_principal_id")),
        folio=quote_folio,
        estatus=body.pop("estado", None) or body.pop("estatus", None) or "borrador",
        total=_as_number(body.get("total")),
            moneda=(body.get("moneda") or "MXN").upper(),
            valida_hasta=valido_hasta.isoformat() if valido_hasta else None,
            metadata=metadata,
            items=repo_items,
            usuario_id=usuario_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    quote = _quote_from_row(created_row)
    return LeadQuoteResponse(quote=quote)


