@router.post("/prospeccion/google/busquedas")
async def crear_busqueda_google(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("busquedas.view")),
    __: str = Depends(require_permission("busquedas.run")),
    user_token: str = Depends(require_user_token),
    payload: GoogleProspeccionBusquedaPayload,
) -> dict[str, Any]:
    dense_mode = bool(payload.dense_mode)
    query_value = payload.query or ", ".join(payload.included_types or []) or "google_places"
    meta_payload: dict[str, Any] = {
        "strategy": payload.strategy,
        "included_types": payload.included_types,
        "dense_mode": dense_mode,
    }
    if payload.meta:
        meta_payload.update(payload.meta)
    if payload.language_code:
        meta_payload["language_code"] = payload.language_code
    if payload.region_code:
        meta_payload["region_code"] = payload.region_code

    job_meta = dict(meta_payload)
    job_meta["status"] = "queued"

    crear_body = {
        "p_fuente": "google_places",
        "p_query": query_value,
        "p_radio_m": payload.radio_m,
        "p_lat": payload.lat,
        "p_lng": payload.lng,
        "p_total": 0,
        "p_meta": job_meta,
    }
    try:
        crear_data = await repo.create_prospeccion_busqueda(
            usuario_token=user_token,
            payload=crear_body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    busqueda_value = _rpc_field(crear_data, "crear_busqueda", "id")
    try:
        busqueda_uuid = UUID(str(busqueda_value))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=502, detail="busqueda_id_invalid") from exc

    busqueda_row = await repo.get_prospeccion_busqueda(busqueda_id=busqueda_uuid, select="organizacion_id")
    organizacion_id = None
    if busqueda_row:
        raw_organizacion = busqueda_row.get("organizacion_id")
        if raw_organizacion:
            organizacion_id = str(raw_organizacion)
            job_meta["organizacion_id"] = organizacion_id

    job_payload: dict[str, Any] = {
        "query": payload.query,
        "lat": payload.lat,
        "lng": payload.lng,
        "radio_m": payload.radio_m,
        "included_types": payload.included_types,
        "strategy": payload.strategy,
        "language_code": payload.language_code,
        "region_code": payload.region_code,
        "dense_mode": dense_mode,
    }
    GOOGLE_SEARCH_JOB_MANAGER.schedule_job(
        repo=repo,
        job=GoogleSearchJob(busqueda_id=busqueda_uuid, payload=job_payload, meta=job_meta),
    )
    return {
        "ok": True,
        "busqueda_id": str(busqueda_uuid),
        "status": "queued",
    }


@router.post("/prospeccion/denue/busquedas")
async def crear_busqueda_denue(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("busquedas.view")),
    __: str = Depends(require_permission("busquedas.run")),
    user_token: str = Depends(require_user_token),
    payload: DenueBusquedaPayload,
) -> dict[str, Any]:
    tenant_organizacion_id: UUID | None = None
    user_sub = _jwt_verify_and_sub(user_token)
    if user_sub:
        try:
            user_uuid = UUID(user_sub)
        except (TypeError, ValueError):
            user_uuid = None
        if user_uuid:
            tenant_organizacion_id = await repo.get_usuario_organizacion_id(usuario_id=user_uuid)

    denue_settings = await tenant_runtime.get_denue_runtime_settings(
        organizacion_id=tenant_organizacion_id
    )
    if not (denue_settings.token or "").strip():
        raise HTTPException(
            status_code=400,
            detail="DENUE no está configurado para este tenant. Falta el token denue.token en settings/variables.",
        )
    client = DenueClient(token=denue_settings.token, base_url=denue_settings.base_url)
    advanced_meta = await _build_advanced_meta(payload, repo)
    modo = payload.modo or "radio"
    text_query = (payload.texto_busqueda or "").strip()
    search_logger.info(
        "denue.search_requested",
        extra={
            "modo": modo,
            "meta": payload.meta or {},
            "filters": advanced_meta,
            "texto_busqueda": payload.texto_busqueda,
            "actividad_codigos": payload.actividad_codigos,
            "geo_estados": payload.geo_estados,
            "geo_municipios": payload.geo_municipios,
            "estrato_ids": payload.estrato_ids,
        },
    )
    batch_base_size = max(payload.registro_final - payload.registro_inicial + 1, 1)
    batch_size = min(batch_base_size, settings.denue_batch_size)
    if batch_size <= 0:
        batch_size = settings.denue_batch_size
    max_batches = settings.denue_max_batches or None

    def _build_meta_payload(total: int) -> dict[str, Any]:
        meta: dict[str, Any] = {"query": payload.query}
        if payload.meta:
            meta.update(payload.meta)
        meta["modo"] = modo
        if modo != "radio" and advanced_meta:
            meta["advanced_filters"] = advanced_meta
        meta["denue_batch_size"] = batch_size
        meta["total_encontrados"] = total
        return meta

    crear_body = {
        "p_fuente": "denue",
        "p_query": payload.query,
        "p_radio_m": payload.radio_m,
        "p_lat": payload.lat,
        "p_lng": payload.lng,
        "p_total": 0,
        "p_meta": _build_meta_payload(0),
    }
    try:
        crear_data = await repo.create_prospeccion_busqueda(
            usuario_token=user_token,
            payload=crear_body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    busqueda_value = _rpc_field(crear_data, "crear_busqueda", "id")
    try:
        busqueda_uuid = UUID(str(busqueda_value))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=502, detail="busqueda_id_invalid") from exc

    busqueda_row = await repo.get_prospeccion_busqueda(busqueda_id=busqueda_uuid, select="organizacion_id,meta")
    organizacion_id: UUID | None = tenant_organizacion_id
    if not organizacion_id and isinstance(busqueda_row, dict):
        org_value = busqueda_row.get("organizacion_id")
        if org_value:
            try:
                organizacion_id = UUID(str(org_value))
            except (TypeError, ValueError):
                organizacion_id = None

    if payload.async_mode:
        if modo == "entidad" and not text_query:
            raise HTTPException(status_code=400, detail="texto_busqueda_required")
        if modo in {"area_act", "area_act_estr"} and not _activity_codes_from_payload(payload):
            raise HTTPException(status_code=400, detail="actividad_required")
        if modo == "area_act_estr":
            if not payload.estrato_ids:
                raise HTTPException(status_code=400, detail="estrato_required")
            cleaned_estratos = [
                str(value).strip()
                for value in payload.estrato_ids
                if value and str(value).strip() and str(value).strip() != "0"
            ]
            if not cleaned_estratos:
                raise HTTPException(status_code=400, detail="estrato_required")

        job_payload: dict[str, Any] = {
            "status": "pending",
            "busqueda_id": str(busqueda_uuid),
            "params": payload.model_dump(exclude_none=True),
            "metadata": {
                "source": (payload.meta or {}).get("source"),
                "modo": modo,
                "advanced_filters": advanced_meta,
            },
        }
        if organizacion_id:
            job_payload["organizacion_id"] = str(organizacion_id)
        try:
            job_row = await repo.create_denue_job(usuario_token=user_token, payload=job_payload)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc

        job_id_value = job_row.get("id") if isinstance(job_row, dict) else None
        try:
            job_uuid = UUID(str(job_id_value))
        except (TypeError, ValueError) as exc:
            raise HTTPException(status_code=502, detail="denue_job_id_invalid") from exc

        if isinstance(busqueda_row, dict):
            meta_value = busqueda_row.get("meta")
            meta = dict(meta_value) if isinstance(meta_value, dict) else {}
            meta.update({"status": "queued", "denue_job_id": str(job_uuid)})
            await repo.worker_update_busqueda(busqueda_id=busqueda_uuid, payload={"meta": meta})
        else:
            await repo.worker_update_busqueda(
                busqueda_id=busqueda_uuid,
                payload={"meta": {"status": "queued", "denue_job_id": str(job_uuid)}},
            )

        DENUE_SEARCH_JOB_MANAGER.schedule_job(
            repo=repo,
            job=DenueSearchJob(
                job_id=job_uuid,
                busqueda_id=busqueda_uuid,
                organizacion_id=organizacion_id,
                payload=payload.model_dump(exclude_none=True),
            ),
        )
        return {
            "ok": True,
            "busqueda_id": str(busqueda_uuid),
            "job_id": str(job_uuid),
            "status": "queued",
        }

    preview_items: list[dict[str, Any]] = []
    total_records = 0
    upserted = 0

    async def _upsert_normals(items: list[dict[str, Any]]) -> int:
        if not items:
            return 0
        try:
            upsert_data = await repo.upsert_prospeccion_resultados(
                usuario_token=user_token,
                payload={
                    "p_busqueda_id": str(busqueda_uuid),
                    "p_fuente": "denue",
                    "p_items": items,
                    "p_organizacion_id": str(organizacion_id),
                },
                organizacion_id=organizacion_id,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if isinstance(upsert_data, dict):
            return upsert_data.get("upserted") or upsert_data.get("total") or len(items)
        try:
            return int(upsert_data or 0)
        except (TypeError, ValueError):
            return len(items)

    async def _iterate_batches(
        search_fn: Callable[[int, int], Awaitable[list[dict[str, Any]]]],
        *,
        start: int,
    ):
        batch_index = 0
        while True:
            registro_final = start + batch_size - 1
            batch = await search_fn(registro_inicial=start, registro_final=registro_final)
            yield batch, start, registro_final, batch_index + 1
            if len(batch) < batch_size:
                break
            batch_index += 1
            if max_batches and batch_index >= max_batches:
                search_logger.warning(
                    "denue.batch_limit_reached",
                    extra={
                        "modo": modo,
                        "batches": batch_index,
                        "batch_size": batch_size,
                    },
                )
                break
            start += batch_size

    seen_external_ids: set[str] = set()

    async def _process_batches(
        search_fn: Callable[[int, int], Awaitable[list[dict[str, Any]]]],
        *,
        extra: dict[str, Any],
    ) -> None:
        nonlocal total_records, upserted, preview_items
        async for batch_records, start, end, batch_index in _iterate_batches(
            search_fn,
            start=payload.registro_inicial,
        ):
            normalized_batch = [normalize_denue_place(item) for item in batch_records]
            unique_batch: list[dict[str, Any]] = []
            for item in normalized_batch:
                external_id = item.get("external_id")
                if not external_id:
                    unique_batch.append(item)
                    continue
                if external_id in seen_external_ids:
                    continue
                seen_external_ids.add(str(external_id))
                unique_batch.append(item)

            total_records += len(unique_batch)
            if len(preview_items) < 10 and unique_batch:
                preview_items.extend(unique_batch[: max(0, 10 - len(preview_items))])
            if unique_batch:
                upserted += await _upsert_normals(unique_batch)
            search_logger.info(
                "denue.batch_processed",
                extra={
                    "modo": modo,
                    "batch_index": batch_index,
                    "start": start,
                    "end": end,
                    "batch_size": len(batch_records),
                    "unique": len(unique_batch),
                    **extra,
                },
            )

    try:
        if modo == "radio":
            records = await client.search(
                query=payload.query,
                latitude=payload.lat,
                longitude=payload.lng,
                radius_m=payload.radio_m,
            )
            normalized_items = [normalize_denue_place(item) for item in records]
            total_records = len(normalized_items)
            if normalized_items:
                upserted += await _upsert_normals(normalized_items)
            preview_items = normalized_items[:10]
        else:
            combo_limit = 20
            if modo == "entidad":
                if not text_query:
                    raise HTTPException(status_code=400, detail="texto_busqueda_required")
                geo_targets = _geo_targets_from_payload(payload)
                entidades = _unique_preserve_order([estado for estado, _ in geo_targets if estado])
                if not entidades:
                    raise HTTPException(status_code=400, detail="entidad_required")
                if len(entidades) > combo_limit:
                    search_logger.warning(
                        "denue.combo_limit_reached",
                        extra={"modo": modo, "limit": combo_limit, "combos": len(entidades)},
                    )
                    entidades = entidades[:combo_limit]

                for entidad in entidades:
                    async def search_batch(
                        registro_inicial: int,
                        registro_final: int,
                        *,
                        _entidad: str = entidad,
                    ) -> list[dict[str, Any]]:
                        return await client.search_by_entidad(
                            condicion=text_query,
                            entidad=_entidad,
                            registro_inicial=registro_inicial,
                            registro_final=registro_final,
                        )

                    await _process_batches(search_batch, extra={"entidad": entidad})
            elif modo == "area_act" or modo == "area_act_estr":
                activity_codes = _activity_codes_from_payload(payload)
                if not activity_codes:
                    raise HTTPException(status_code=400, detail="actividad_required")
                geo_targets = _geo_targets_from_payload(payload)
                geo_targets = expand_targets_for_area_act(geo_targets)
                estratos: list[str | None]
                if modo == "area_act_estr":
                    if not payload.estrato_ids:
                        raise HTTPException(status_code=400, detail="estrato_required")
                    estratos = [
                        str(value).strip()
                        for value in payload.estrato_ids
                        if value and str(value).strip() and str(value).strip() != "0"
                    ]
                    if not estratos:
                        raise HTTPException(status_code=400, detail="estrato_required")
                else:
                    estratos = [None]

                combos: list[tuple[str, str | None, str | None, str | None]] = []
                for activity in activity_codes:
                    for entidad, municipio in geo_targets:
                        for estrato in estratos:
                            combos.append((activity, entidad, municipio, estrato))

                if len(combos) > combo_limit:
                    search_logger.warning(
                        "denue.combo_limit_reached",
                        extra={"modo": modo, "limit": combo_limit, "combos": len(combos)},
                    )
                    combos = combos[:combo_limit]

                for activity, entidad, municipio, estrato in combos:
                    async def _run_combo(
                        *,
                        _activity: str = activity,
                        _entidad: str | None = entidad,
                        _municipio: str | None = municipio,
                        _estrato: str | None = estrato,
                    ) -> None:
                        if modo == "area_act_estr":
                            async def search_batch(
                                registro_inicial: int,
                                registro_final: int,
                                *,
                                _activity_inner: str = _activity,
                                _entidad_inner: str | None = _entidad,
                                _municipio_inner: str | None = _municipio,
                                _estrato_inner: str | None = _estrato,
                            ) -> list[dict[str, Any]]:
                                return await client.search_area_act_estr(
                                    entidad=_entidad_inner,
                                    municipio=_municipio_inner,
                                    actividad_codigo=_activity_inner,
                                    texto=text_query or None,
                                    registro_inicial=registro_inicial,
                                    registro_final=registro_final,
                                    estrato=_estrato_inner,
                                )
                        else:
                            async def search_batch(
                                registro_inicial: int,
                                registro_final: int,
                                *,
                                _activity_inner: str = _activity,
                                _entidad_inner: str | None = _entidad,
                                _municipio_inner: str | None = _municipio,
                            ) -> list[dict[str, Any]]:
                                return await client.search_area_act(
                                    entidad=_entidad_inner,
                                    municipio=_municipio_inner,
                                    actividad_codigo=_activity_inner,
                                    texto=text_query or None,
                                    registro_inicial=registro_inicial,
                                    registro_final=registro_final,
                                )

                        await _process_batches(
                            search_batch,
                            extra={
                                "entidad": _entidad,
                                "municipio": _municipio,
                                "actividad_codigo": _activity,
                                "estrato": _estrato,
                            },
                        )

                    try:
                        await _run_combo()
                    except DenueError as exc:
                        if municipio is not None:
                            raise
                        fallback_targets = expand_state_to_municipalities(entidad)
                        if not fallback_targets:
                            raise
                        search_logger.warning(
                            "denue.state_municipality_fallback",
                            extra={
                                "modo": modo,
                                "entidad": entidad,
                                "actividad_codigo": activity,
                                "estrato": estrato,
                                "error": str(exc),
                                "municipios": len(fallback_targets),
                            },
                        )
                        fallback_success = False
                        last_fallback_exc: DenueError | None = None
                        for fallback_entidad, fallback_municipio in fallback_targets:
                            try:
                                await _run_combo(
                                    _entidad=fallback_entidad,
                                    _municipio=fallback_municipio,
                                    _estrato=estrato,
                                )
                                fallback_success = True
                            except DenueError as fallback_exc:
                                last_fallback_exc = fallback_exc
                                search_logger.warning(
                                    "denue.state_municipality_fallback_target_failed",
                                    extra={
                                        "modo": modo,
                                        "entidad": fallback_entidad,
                                        "municipio": fallback_municipio,
                                        "actividad_codigo": activity,
                                        "estrato": estrato,
                                        "error": str(fallback_exc),
                                    },
                                )
                        if not fallback_success and last_fallback_exc is not None:
                            raise last_fallback_exc
            else:
                raise HTTPException(status_code=400, detail="modo_desconocido")
    except DenueError as exc:
        detail = str(exc) or "denue_error"
        search_logger.error("denue.search_failed", extra={"modo": modo, "detail": detail})
        raise HTTPException(status_code=502, detail=detail) from exc

    await repo.update_prospeccion_busqueda_total(
        usuario_token=user_token,
        busqueda_id=busqueda_uuid,
        total_encontrados=total_records,
    )

    preview = [_result_preview(item) for item in preview_items[: min(10, len(preview_items))]]
    return {
        "ok": True,
        "busqueda_id": str(busqueda_uuid),
        "denue_results": total_records,
        "upserted": upserted,
        "preview": preview,
    }


@router.get("/prospeccion/google/busquedas")
async def listar_busquedas_google(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("busquedas.view")),
    user_token: str = Depends(require_user_token),
    limit: Annotated[int, Query(ge=1, le=100)] = 20,
    offset: Annotated[int, Query(ge=0)] = 0,
    search: str | None = Query(default=None),
) -> dict[str, Any]:
    params: dict[str, str] = {
        "select": "id,fuente,query,radio_m,lat,lng,status,modo,source,recovered_at,denue_job_id,denue_batch_size,advanced_filters,meta,total_encontrados,creado_en",
        "order": "creado_en.desc",
        "limit": str(limit),
        "offset": str(offset),
        "fuente": "eq.google_places",
        "deleted_at": "is.null",
    }
    if search:
        params["query"] = _ilike_param(search)
    try:
        rows, total = await repo.list_prospeccion_busquedas(
            usuario_token=user_token,
            params=params,
        )
        # Fallback defensivo: si por alguna inconsistencia histórica no existen
        # filas en `busquedas`, reconstruimos una lista mínima desde `resultados`
        # sin resucitar búsquedas marcadas como eliminadas.
        if not rows:
            rows, total = await _listar_busquedas_google_desde_resultados(
                repo=repo,
                user_token=user_token,
                limit=limit,
                offset=offset,
            )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {
        "ok": True,
        "items": rows,
        "limit": limit,
        "offset": offset,
        "total": total or len(rows),
    }


async def _listar_busquedas_google_desde_resultados(
    *,
    repo: CRMRepository,
    user_token: str,
    limit: int,
    offset: int,
) -> tuple[list[dict[str, Any]], int]:
    target_unique = offset + limit
    page_size = 1000
    scan_offset = 0
    max_scan_rows = 200_000
    unique_rows: list[dict[str, Any]] = []
    seen_ids: set[str] = set()

    while len(unique_rows) < target_unique and scan_offset <= max_scan_rows:
        source_params: dict[str, str] = {
            "select": "busqueda_id,creado_en,lat,lng",
            "order": "creado_en.desc",
            "limit": str(page_size),
            "offset": str(scan_offset),
            "fuente": "eq.google_places",
        }
        source_rows, _ = await repo.list_prospeccion_resultados(
            usuario_token=user_token,
            path="/rest/v1/resultados",
            params=source_params,
        )
        if not source_rows:
            break
        for row in source_rows:
            busqueda_id = str(row.get("busqueda_id") or "").strip()
            if not busqueda_id or busqueda_id in seen_ids:
                continue
            seen_ids.add(busqueda_id)
            unique_rows.append(
                {
                    "id": busqueda_id,
                    "fuente": "google_places",
                    "query": "Busqueda Google",
                    "radio_m": None,
                    "lat": row.get("lat"),
                    "lng": row.get("lng"),
                    "meta": {"source": "fallback_resultados"},
                    "total_encontrados": None,
                    "creado_en": row.get("creado_en"),
                }
            )
            if len(unique_rows) >= target_unique:
                break
        if len(source_rows) < page_size:
            break
        scan_offset += page_size

    if unique_rows:
        ids = [str(row.get("id") or "").strip() for row in unique_rows]
        ids = [value for value in ids if value]
        visible_ids = set(ids)
        if ids:
            lookup_params: dict[str, str] = {
                "select": "id,deleted_at",
                "id": f"in.({','.join(ids)})",
                "fuente": "eq.google_places",
                "limit": str(len(ids)),
            }
            lookup_rows, _ = await repo.list_prospeccion_busquedas(
                usuario_token=user_token,
                params=lookup_params,
            )
            deleted_ids = {
                str(item.get("id") or "").strip()
                for item in lookup_rows
                if isinstance(item, dict) and item.get("deleted_at")
            }
            visible_ids = {value for value in ids if value and value not in deleted_ids}
        unique_rows = [row for row in unique_rows if str(row.get("id") or "").strip() in visible_ids]

    total = len(unique_rows)
    paged = unique_rows[offset : offset + limit]
    return paged, total


