@router.post("/prospeccion/denue/jobs/{job_id}/cancel")
async def cancelar_denue_job(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("busquedas.run")),
    user_token: str = Depends(require_user_token),
    job_id: UUID,
) -> dict[str, Any]:
    # Validamos que el job exista y pertenezca a la organización del usuario (RLS).
    try:
        row = await repo.get_denue_job(job_id=job_id, usuario_token=user_token)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not row:
        raise HTTPException(status_code=404, detail="denue_job_not_found")

    requested = DENUE_SEARCH_JOB_MANAGER.request_cancel(job_id)
    finished_iso = datetime.now(timezone.utc).isoformat()
    try:
        await repo.worker_update_denue_job(
            job_id=job_id,
            payload={"status": "canceled", "finished_at": finished_iso},
            strict=False,
            extra_filters={"status": "in.(pending,running)"},
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    busqueda_id_value = row.get("busqueda_id")
    try:
        busqueda_uuid = UUID(str(busqueda_id_value))
    except (TypeError, ValueError):
        busqueda_uuid = None
    if busqueda_uuid:
        busqueda_row = await repo.get_prospeccion_busqueda(busqueda_id=busqueda_uuid, select="meta")
        meta_value = busqueda_row.get("meta") if isinstance(busqueda_row, dict) else None
        meta = dict(meta_value) if isinstance(meta_value, dict) else {}
        meta.update({"status": "canceled", "denue_job_id": str(job_id)})
        await repo.worker_update_busqueda(busqueda_id=busqueda_uuid, payload={"meta": meta})

    return {"ok": True, "requested": requested}


@router.get("/prospeccion/google/resultados")
async def listar_resultados_google(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("busquedas.view")),
    user_token: str = Depends(require_user_token),
    busqueda_id: UUID | None = Query(default=None),
    q: str | None = Query(default=None),
    tipo: str | None = Query(default=None),
    max_distancia_m: Annotated[int | None, Query(ge=1, le=50000)] = None,
    min_rating: Annotated[float | None, Query(ge=0, le=5)] = None,
    phone_present: bool | None = Query(default=None),
    website_present: bool | None = Query(default=None),
    actividades: list[str] | None = Query(default=None),
    limit: Annotated[int, Query(ge=1, le=5000)] = 250,
    offset: Annotated[int, Query(ge=0)] = 0,
    order: Literal["recientes", "rating", "distancia"] = Query(default="recientes"),
) -> dict[str, Any]:
    order_map = {
        "recientes": "resultado_creado_en.desc",
        "rating": "rating.desc.nullslast",
        "distancia": "distancia_m.asc.nullslast",
    }
    params: dict[str, str] = {
        "select": "*",
        "order": order_map.get(order, "resultado_creado_en.desc"),
    }
    if busqueda_id:
        params["busqueda_id"] = f"eq.{busqueda_id}"
    if tipo:
        params["google_primary_type"] = f"eq.{tipo}"
    if max_distancia_m:
        params["distancia_m"] = f"lte.{max_distancia_m}"
    if min_rating is not None:
        params["rating"] = f"gte.{min_rating}"
    required_groups: list[str] = []
    if phone_present is True:
        required_groups.append(
            "("
            + ",".join(f"{field}.not.is.null" for field in GOOGLE_RESULT_PHONE_FIELDS)
            + ")"
        )
    elif phone_present is False:
        for field in GOOGLE_RESULT_PHONE_FIELDS:
            params[field] = "is.null"
    if website_present is True:
        required_groups.append(
            "("
            + ",".join(f"{field}.not.is.null" for field in GOOGLE_RESULT_WEBSITE_FIELDS)
            + ")"
        )
    elif website_present is False:
        for field in GOOGLE_RESULT_WEBSITE_FIELDS:
            params[field] = "is.null"
    if actividades:
        unique_activities: list[str] = []
        seen_activities: set[str] = set()
        for activity in actividades:
            candidate = str(activity or "").strip()
            if not candidate or candidate in seen_activities:
                continue
            seen_activities.add(candidate)
            unique_activities.append(candidate)
        if unique_activities:
            quoted = ",".join(f'"{value.replace(chr(34), chr(34) * 2)}"' for value in unique_activities)
            params["actividad"] = f"in.({quoted})"
    if q:
        sanitized = q.replace("*", "").replace("%", "")
        search_group = (
            "("
            + ",".join(
                f"{field}.ilike.*{sanitized}*"
                for field in GOOGLE_RESULT_SEARCH_FIELDS
            )
            + ")"
        )
        required_groups.insert(0, search_group)
    if required_groups:
        if len(required_groups) == 1:
            params["or"] = required_groups[0]
        else:
            params["and"] = "(" + ",".join(required_groups) + ")"
    effective_limit = min(limit, 5000)
    params["limit"] = str(effective_limit)
    params["offset"] = str(offset)
    try:
        rows, total = await repo.list_prospeccion_resultados(
            usuario_token=user_token,
            path="/rest/v1/v_google_places_contactables",
            params=params,
            count_exact=True,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {
        "ok": True,
        "items": rows,
        "limit": effective_limit,
        "offset": offset,
        "total": total or len(rows),
    }

@router.get("/prospeccion/google/resultados/map")
async def listar_resultados_google_map(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("busquedas.view")),
    user_token: str = Depends(require_user_token),
    busqueda_id: UUID = Query(...),
    bbox_w: float = Query(...),
    bbox_s: float = Query(...),
    bbox_e: float = Query(...),
    bbox_n: float = Query(...),
    zoom: Annotated[int, Query(ge=0, le=22)] = 12,
    q: str | None = Query(default=None),
    phone_present: bool | None = Query(default=None),
    website_present: bool | None = Query(default=None),
    min_rating: Annotated[float | None, Query(ge=0, le=5)] = None,
    actividades: list[str] | None = Query(default=None),
    limit: Annotated[int, Query(ge=1, le=10000)] = 5000,
) -> dict[str, Any]:
    effective_limit = min(limit, 5000)
    payload: dict[str, Any] = {
        "p_busqueda_id": str(busqueda_id),
        "p_bbox_w": bbox_w,
        "p_bbox_s": bbox_s,
        "p_bbox_e": bbox_e,
        "p_bbox_n": bbox_n,
        "p_zoom": zoom,
        "p_q": q,
        "p_phone_present": phone_present,
        "p_website_present": website_present,
        "p_min_rating": min_rating,
        "p_actividades": actividades,
        # Pedimos +1 para detectar truncado en modo points (sin contar exacto en cada pan/zoom).
        "p_limit": effective_limit + 1,
    }
    try:
        rows = await repo.google_resultados_map(usuario_token=user_token, payload=payload)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    truncated = len(rows) > effective_limit
    items = rows[:effective_limit]
    return {"ok": True, "items": items, "limit": effective_limit, "truncated": truncated}


