@router.get("/prospeccion/prospectos")
async def listar_prospectos(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    params: ProspectoListQuery = Depends(),
    con_envio_canal: Annotated[
        list[Literal["correo", "whatsapp", "llamada"]] | None,
        Query(alias="con_envio_canal"),
    ] = None,
    con_envio_canales: Annotated[str | None, Query(alias="con_envio_canales")] = None,
    envios_correo_min: Annotated[int | None, Query(alias="envios_correo_min")] = None,
    envios_correo_max: Annotated[int | None, Query(alias="envios_correo_max")] = None,
    envios_whatsapp_min: Annotated[int | None, Query(alias="envios_whatsapp_min")] = None,
    envios_whatsapp_max: Annotated[int | None, Query(alias="envios_whatsapp_max")] = None,
    envios_voz_min: Annotated[int | None, Query(alias="envios_voz_min")] = None,
    envios_voz_max: Annotated[int | None, Query(alias="envios_voz_max")] = None,
    metadata_query: Annotated[list[str] | None, Query(alias="metadata_query")] = None,
    actividad: Annotated[list[str] | None, Query(alias="actividad")] = None,
) -> dict[str, Any]:
    """Devuelve prospectos guardados con paginación y filtros básicos."""

    request_started = time.perf_counter()
    rows: list[dict[str, Any]] = []
    total = 0
    request_failed = False
    con_envio_canales_values = sorted(
        set((con_envio_canal or []) + _parse_con_envio_canales_param(con_envio_canales))
    )
    try:
        order_value = "display_name.asc.nullslast" if params.order == "nombre" else None
        effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
            repo=repo,
            organizacion_id=organizacion_id,
            usuario_id=usuario_id,
        )
        try:
            rows, total = await repo.list_prospectos(
                usuario_token=user_token,
                organizacion_id=organizacion_id,
                limit=params.limit,
                offset=params.offset,
                search=params.search,
                fuente=params.fuente or None,
                lookup_status=params.lookup_status,
                email_lookup_status=params.email_lookup_status,
                website_lookup_status=params.website_lookup_status,
                email_domain_relation=params.email_domain_relation or None,
                segmento=params.segmento,
                carrier_type=params.carrier_type or None,
                order=order_value,
                stage=params.stage or None,
                whatsapp_permitido=params.whatsapp_permitido,
                llamada_permitida=params.llamada_permitida,
                phone_present=params.phone_present,
                email_present=params.email_present,
                website_present=params.website_present,
                date_from=params.date_from,
                date_to=params.date_to,
                geo_estado=params.geo_estado,
                geo_municipio=params.geo_municipio,
                min_rating=params.min_rating,
                estrato_group=params.estrato_group,
                metadata_queries=metadata_query,
                actividades=actividad,
                campana_id=params.campana_id,
                con_envio=params.con_envio,
                con_envio_canales=con_envio_canales_values or None,
                con_scraper=params.con_scraper,
                envios_correo_min=envios_correo_min,
                envios_correo_max=envios_correo_max,
                envios_whatsapp_min=envios_whatsapp_min,
                envios_whatsapp_max=envios_whatsapp_max,
                envios_voz_min=envios_voz_min,
                envios_voz_max=envios_voz_max,
                timezone_name=effective_timezone,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc

        if rows:
            prospecto_ids = [str(row.get("id") or "").strip() for row in rows if str(row.get("id") or "").strip()]
            contact_indicator_map: dict[str, dict[str, Any]] = {}
            if prospecto_ids:
                valid_ids: list[UUID] = []
                for value in prospecto_ids:
                    try:
                        valid_ids.append(UUID(value))
                    except (TypeError, ValueError):
                        continue
                if valid_ids:
                    try:
                        indicator_rows = await repo.list_prospecto_contact_indicators(
                            usuario_token=user_token,
                            prospecto_ids=valid_ids,
                        )
                    except CRMRepositoryError as exc:
                        raise HTTPException(status_code=502, detail=str(exc)) from exc
                    normalized_indicator_rows = _normalize_total_envios_without_cancelled(
                        [row for row in indicator_rows if isinstance(row, dict)]
                    )
                    contact_indicator_map = {
                        str(row.get("prospecto_id") or "").strip(): row
                        for row in normalized_indicator_rows
                        if str(row.get("prospecto_id") or "").strip()
                    }
            scraper_status_map: dict[str, dict[str, Any]] = {}
            if params.include_scraper_status and prospecto_ids:
                try:
                    scraper_status_map = await repo.list_scraper_status_by_prospectos(
                        usuario_token=user_token,
                        prospecto_ids=prospecto_ids,
                    )
                except CRMRepositoryError as exc:
                    raise HTTPException(status_code=502, detail=str(exc)) from exc

            for row in rows:
                prospecto_id = str(row.get("id") or "").strip()
                row["contact_indicators"] = contact_indicator_map.get(prospecto_id)
                status_info = scraper_status_map.get(prospecto_id)
                row["scraper_ejecutado"] = bool(status_info)
                row["scraper_ultimo_en"] = status_info.get("ultimo_en") if status_info else None
                row["scraper_ultimo_estado"] = status_info.get("estado") if status_info else None

        return {
            "ok": True,
            "items": rows,
            "total": total,
            "limit": params.limit,
            "offset": params.offset,
        }
    except Exception:
        request_failed = True
        raise
    finally:
        duration_ms = (time.perf_counter() - request_started) * 1000
        await _record_prospectos_process_metrics(
            endpoint="prospeccion.prospectos.list",
            duration_ms=duration_ms,
            flags={
                "include_scraper_status": bool(params.include_scraper_status),
                "geo_filter": bool(params.geo_estado or params.geo_municipio),
                "con_envio_filter": params.con_envio is not None,
                "con_envio_canal_filter": bool(con_envio_canales_values),
                "con_scraper_filter": params.con_scraper is not None,
                "envios_count_filter": any(
                    value is not None
                    for value in (
                        envios_correo_min,
                        envios_correo_max,
                        envios_whatsapp_min,
                        envios_whatsapp_max,
                        envios_voz_min,
                        envios_voz_max,
                    )
                ),
                "metadata_query_filter": bool(metadata_query),
                "actividad_filter": bool(actividad),
                "rows_returned": len(rows),
                "failed": request_failed,
            },
        )


@router.get("/prospeccion/prospectos/queries")
async def listar_prospectos_query_metadata(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    query: Annotated[list[str] | None, Query(alias="query")] = None,
    fuente: Annotated[Literal["google_places", "denue", "usuario", ""] | None, Query(alias="fuente")] = None,
    date_from: Annotated[date | None, Query(alias="date_from")] = None,
    date_to: Annotated[date | None, Query(alias="date_to")] = None,
) -> dict[str, Any]:
    """Lista nombres de consulta y actividades asociadas para los prospectos guardados."""

    request_started = time.perf_counter()
    request_failed = False
    cache_hit = False
    normalized_query_filters = sorted(
        {
            value.strip()
            for value in (query or [])
            if isinstance(value, str) and value.strip()
        }
    )
    query_signature = hashlib.sha1(
        json.dumps(normalized_query_filters, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()[:12]
    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    cache_key = _build_prospecto_queries_cache_key(
        {
            "org": str(organizacion_id),
            "query": normalized_query_filters,
            "fuente": fuente or "",
            "date_from": date_from.isoformat() if date_from else "",
            "date_to": date_to.isoformat() if date_to else "",
            "timezone": effective_timezone,
        }
    )
    inflight_future, is_inflight_leader = await _get_prospecto_queries_inflight_future(cache_key)
    if not is_inflight_leader:
        try:
            payload = await inflight_future
            logger.info(
                "crm.prospectos.queries.singleflight_join",
                extra={
                    "cache_key": cache_key[:12],
                    "query_signature": query_signature,
                    "query_filters": len(normalized_query_filters),
                    "fuente": fuente or "",
                    "has_date_from": bool(date_from),
                    "has_date_to": bool(date_to),
                },
            )
            return payload
        except Exception:
            logger.exception(
                "crm.prospectos.queries.singleflight_wait_failed",
                extra={
                    "cache_key": cache_key[:12],
                    "query_signature": query_signature,
                },
            )
    try:
        logger.info(
            "crm.prospectos.queries.resolve_fresh",
            extra={
                "cache_key": cache_key[:12],
                "query_signature": query_signature,
                "query_filters": len(normalized_query_filters),
                "fuente": fuente or "",
                "has_date_from": bool(date_from),
                "has_date_to": bool(date_to),
            },
        )

        try:
            metadata = await repo.list_prospecto_query_metadata(
                usuario_token=user_token,
                organizacion_id=organizacion_id,
                query_filters=normalized_query_filters,
                fuente=fuente or None,
                date_from=date_from,
                date_to=date_to,
                timezone_name=effective_timezone,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        payload = {
            "ok": True,
            "queries": metadata.get("queries", []),
            "activities": metadata.get("activities", []),
            "segmentos": metadata.get("segmentos", []),
        }
        if not inflight_future.done():
            inflight_future.set_result(payload)
        return payload
    except Exception:
        request_failed = True
        if not inflight_future.done():
            inflight_future.set_exception(RuntimeError("prospecto_queries_resolution_failed"))
            _ = inflight_future.exception()
        raise
    finally:
        if is_inflight_leader:
            await _release_prospecto_queries_inflight_future(cache_key, inflight_future)
        duration_ms = (time.perf_counter() - request_started) * 1000
        await _record_prospectos_process_metrics(
            endpoint="prospeccion.prospectos.queries",
            duration_ms=duration_ms,
            flags={
                "cache_hit": cache_hit,
                "has_query_filters": bool(normalized_query_filters),
                "has_date_filter": bool(date_from or date_to),
                "failed": request_failed,
            },
        )


@router.get("/prospeccion/prospectos/bootstrap")
async def listar_prospectos_bootstrap(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    params: ProspectoListQuery = Depends(),
    con_envio_canal: Annotated[
        list[Literal["correo", "whatsapp", "llamada"]] | None,
        Query(alias="con_envio_canal"),
    ] = None,
    con_envio_canales: Annotated[str | None, Query(alias="con_envio_canales")] = None,
    metadata_query: Annotated[list[str] | None, Query(alias="metadata_query")] = None,
    actividad: Annotated[list[str] | None, Query(alias="actividad")] = None,
    query: Annotated[list[str] | None, Query(alias="query")] = None,
    include_preferences: bool = Query(default=False),
) -> dict[str, Any]:
    """BFF agregador para Prospección: lista + metadatos + preferencias."""

    started = time.perf_counter()
    results: list[Any] = []
    degraded = False
    for attempt in range(2):
        list_task = listar_prospectos(
            repo=repo,
            _="",
            user_token=user_token,
            organizacion_id=organizacion_id,
            usuario_id=usuario_id,
            params=params,
            con_envio_canal=con_envio_canal,
            con_envio_canales=con_envio_canales,
            envios_correo_min=params.envios_correo_min,
            envios_correo_max=params.envios_correo_max,
            envios_whatsapp_min=params.envios_whatsapp_min,
            envios_whatsapp_max=params.envios_whatsapp_max,
            envios_voz_min=params.envios_voz_min,
            envios_voz_max=params.envios_voz_max,
            metadata_query=metadata_query,
            actividad=actividad,
        )
        query_task = listar_prospectos_query_metadata(
            repo=repo,
            _="",
            user_token=user_token,
            organizacion_id=organizacion_id,
            usuario_id=usuario_id,
            query=query,
            fuente=params.fuente,
            date_from=params.date_from,
            date_to=params.date_to,
        )
        tasks: list[Awaitable[Any]] = [list_task, query_task]
        if include_preferences:
            tasks.append(
                obtener_preferencias_tabla_prospectos(
                    repo=repo,
                    _="",
                    user_token=user_token,
                )
            )
        try:
            results = await asyncio.gather(*tasks)
            break
        except HTTPException as exc:
            should_retry = (
                attempt == 0
                and int(exc.status_code) == 502
                and _is_transient_supabase_error(exc.detail)
            )
            if not should_retry:
                if int(exc.status_code) == 502 and _is_transient_supabase_error(exc.detail):
                    logger.warning(
                        "crm.prospectos.bootstrap.degraded_fallback",
                        extra={"attempt": attempt + 1, "error": str(exc.detail)},
                    )
                    degraded = True
                    results = [
                        {
                            "ok": True,
                            "items": [],
                            "total": 0,
                            "limit": params.limit,
                            "offset": params.offset,
                        },
                        {"ok": True, "queries": [], "activities": [], "segmentos": []},
                    ]
                    if include_preferences:
                        results.append({"ok": True, "preferences": None})
                    break
                raise
            logger.warning(
                "crm.prospectos.bootstrap.retry_transient",
                extra={"attempt": attempt + 1, "error": str(exc.detail)},
            )
            await asyncio.sleep(0.35)
    list_payload = results[0] if isinstance(results[0], dict) else {"ok": False}
    query_payload = results[1] if isinstance(results[1], dict) else {"ok": False}
    preferences_payload = (
        results[2] if include_preferences and len(results) >= 3 and isinstance(results[2], dict) else None
    )
    duration_ms = (time.perf_counter() - started) * 1000
    logger.info(
        "crm.prospectos.bootstrap",
        extra={
            "duration_ms": round(duration_ms, 2),
            "items": len(list_payload.get("items") or []),
            "queries": len(query_payload.get("queries") or []),
            "activities": len(query_payload.get("activities") or []),
            "segmentos": len(query_payload.get("segmentos") or []),
            "limit": params.limit,
            "offset": params.offset,
            "include_preferences": include_preferences,
        },
    )
    return {
        "ok": True,
        "degraded": degraded,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "prospectos": list_payload,
        "metadata": query_payload,
        "preferences": preferences_payload.get("preferences")
        if isinstance(preferences_payload, dict)
        else None,
    }


@router.get("/prospeccion/prospectos/stream")
async def stream_prospectos_updates(
    *,
    _: str = Depends(require_permission("ejecutar_busquedas")),
    organizacion_id: UUID = Depends(require_organizacion_id),
) -> StreamingResponse:
    """Stream SSE para invalidaciones incrementales de vista Prospectos."""

    topic = prospectos_topic_for_org(organizacion_id=str(organizacion_id))
    queue = await ui_realtime_hub.subscribe(topic)

    async def event_generator() -> Any:
        try:
            yield _sse_payload(
                {
                    "type": "connected",
                    "scope": "prospeccion_prospectos",
                    "organizacion_id": str(organizacion_id),
                    "at": datetime.now(timezone.utc).isoformat(),
                }
            )
            while True:
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=25)
                except asyncio.TimeoutError:
                    yield _sse_payload({"type": "ping", "scope": "prospeccion_prospectos"})
                    continue
                yield _sse_payload(event)
        finally:
            await ui_realtime_hub.unsubscribe(topic, queue)

    headers = {
        "Cache-Control": "no-cache",
        "Content-Type": "text/event-stream",
        "Connection": "keep-alive",
    }
    return StreamingResponse(event_generator(), media_type="text/event-stream", headers=headers)


@router.get("/me/notifications/stream")
async def stream_my_notifications(
    *,
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
) -> StreamingResponse:
    """Stream SSE global de notificaciones dirigidas al usuario autenticado."""

    user_sub = _jwt_verify_and_sub(user_token)
    try:
        usuario_id = UUID(str(user_sub))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required") from exc

    topic = user_notifications_topic_for_user(
        organizacion_id=str(organizacion_id),
        usuario_id=str(usuario_id),
    )
    queue = await ui_realtime_hub.subscribe(topic)

    async def event_generator() -> Any:
        try:
            yield _sse_payload(
                {
                    "type": "connected",
                    "scope": "user_notifications",
                    "usuario_id": str(usuario_id),
                    "at": datetime.now(timezone.utc).isoformat(),
                }
            )
            while True:
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=25)
                except asyncio.TimeoutError:
                    yield _sse_payload({"type": "ping", "scope": "user_notifications"})
                    continue
                yield _sse_payload(event)
        finally:
            await ui_realtime_hub.unsubscribe(topic, queue)

    headers = {
        "Cache-Control": "no-cache",
        "Content-Type": "text/event-stream",
        "Connection": "keep-alive",
    }
    return StreamingResponse(event_generator(), media_type="text/event-stream", headers=headers)


