@router.get("/prospeccion/contacto/templates")
async def listar_templates_prospeccion_contacto_legacy(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    params: ContactTemplateQuery = Depends(),
) -> dict[str, Any]:
    """Lista plantillas disponibles para envíos."""

    try:
        items = await _retry_transient_repo_error(
            operation="list_contact_templates",
            func=lambda: repo.list_contact_templates(
                usuario_token=user_token,
                canal=params.canal or None,
            ),
            retries=1,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    persisted_items = [
        item for item in items
        if isinstance(item, dict) and _clean_text(item.get("id")) and not str(item.get("id")).startswith("runtime:")
    ]
    if persisted_items:
        try:
            image_rows = await repo.list_contact_template_images(
                usuario_token=user_token,
                template_ids=[str(item["id"]) for item in persisted_items],
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        _attach_contact_template_images(persisted_items, image_rows)
    if params.campana_id:
        campana_key = str(params.campana_id)
        filtered_items: list[dict[str, Any]] = []
        for item in items:
            if not isinstance(item, dict):
                continue
            metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
            linked = _clean_text(metadata.get("campana_id"))
            if linked == campana_key:
                filtered_items.append(item)
        items = filtered_items

    if (not params.canal or params.canal == "whatsapp") and not params.campana_id:
        runtime_settings = await tenant_runtime.get_whatsapp_runtime_settings(organizacion_id=organizacion_id)
        twilio_runtime = await tenant_runtime.get_twilio_runtime_settings(organizacion_id=organizacion_id)
        runtime_sids = runtime_settings.prospeccion_template_sids
        if runtime_sids:
            existing_whatsapp_sids: set[str] = set()
            for item in items:
                if not isinstance(item, dict):
                    continue
                if _clean_text(item.get("canal")) != "whatsapp":
                    continue
                metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
                sid = _clean_text(metadata.get("twilio_content_sid"))
                if sid:
                    existing_whatsapp_sids.add(sid)
            for idx, sid in enumerate(runtime_sids, start=1):
                if sid in existing_whatsapp_sids:
                    continue
                twilio_payload: dict[str, Any] | None = None
                if twilio_runtime.account_sid and twilio_runtime.auth_token:
                    twilio_payload = await _fetch_twilio_content_template(
                        account_sid=twilio_runtime.account_sid,
                        auth_token=twilio_runtime.auth_token,
                        content_sid=sid,
                    )
                template_name = _clean_text((twilio_payload or {}).get("friendly_name")) or f"Whats-Prosp {idx}"
                template_body = _extract_twilio_content_body(twilio_payload or {})
                template_language = _clean_text((twilio_payload or {}).get("language"))
                template_variables = _extract_twilio_variable_keys(twilio_payload or {})
                items.append(
                    {
                        "id": f"runtime:whatsapp:prospeccion:{idx}",
                        "canal": "whatsapp",
                        "slug": f"runtime-whats-prosp-{idx}",
                        "nombre": template_name,
                        "descripcion": "SID configurado desde settings/tenants",
                        "asunto": None,
                        "cuerpo_texto": template_body,
                        "cuerpo_html": None,
                        "activo": True,
                        "metadata": {
                            "twilio_content_sid": sid,
                            "runtime_template": True,
                            "template_source": "whatsapp.templates.prospeccion",
                            **({"twilio_language": template_language} if template_language else {}),
                            **({"twilio_content_variables_keys": template_variables} if template_variables else {}),
                        },
                    }
                )

    return {"ok": True, "items": items}


@router.get("/prospeccion/contacto/templates/brevo-catalog")
async def listar_catalogo_brevo_templates_contacto_legacy(
    *,
    _: str = Depends(require_permission("ejecutar_busquedas")),
    organizacion_id: UUID = Depends(require_organizacion_id),
    params: BrevoTemplateCatalogQuery = Depends(),
) -> dict[str, Any]:
    """Lista plantillas SMTP disponibles en Brevo para importación."""

    brevo_settings = await tenant_runtime.get_brevo_runtime_settings(organizacion_id=organizacion_id)
    if not _clean_text(brevo_settings.api_key):
        raise HTTPException(status_code=400, detail="brevo_not_configured")
    try:
        items = await list_brevo_smtp_templates(
            api_key=str(brevo_settings.api_key),
            base_url=brevo_settings.base_url,
            limit=params.limit,
        )
    except BrevoTemplateServiceError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    search = _clean_text(params.search)
    if search:
        search_lower = search.lower()
        items = [
            item
            for item in items
            if search_lower in str(item.get("name") or "").lower()
            or search_lower in str(item.get("subject") or "").lower()
        ]

    return {"ok": True, "items": items}


@router.post("/prospeccion/contacto/templates/import-brevo")
async def importar_template_brevo_contacto_legacy(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    payload: BrevoTemplateImportPayload,
) -> dict[str, Any]:
    """Importa o sincroniza una plantilla Brevo dentro de plantillas de contacto."""

    campana = await repo.get_campaign(organizacion_id=organizacion_id, campana_id=payload.campana_id)
    if not campana:
        raise HTTPException(status_code=404, detail="campana_not_found")
    campana_canal = _clean_text(campana.get("canal")).lower()
    if campana_canal != "correo":
        raise HTTPException(status_code=400, detail="template_canal_mismatch_with_campana")

    brevo_settings = await tenant_runtime.get_brevo_runtime_settings(organizacion_id=organizacion_id)
    if not _clean_text(brevo_settings.api_key):
        raise HTTPException(status_code=400, detail="brevo_not_configured")

    try:
        remote = await get_brevo_smtp_template(
            api_key=str(brevo_settings.api_key),
            base_url=brevo_settings.base_url,
            template_id=payload.brevo_template_id,
        )
    except BrevoTemplateServiceError as exc:
        detail = str(exc)
        if detail == "brevo_template_not_found":
            raise HTTPException(status_code=404, detail=detail) from exc
        raise HTTPException(status_code=502, detail=detail) from exc

    nombre = _clean_text(payload.nombre) or _clean_text(remote.get("name")) or f"Brevo {payload.brevo_template_id}"
    slug = _clean_text(payload.slug) or _slugify(nombre) or f"brevo-{payload.brevo_template_id}"
    html_content = _clean_text(remote.get("html_content"))
    text_content = _html_to_text(html_content) if html_content else None
    metadata = {
        "campana_id": str(payload.campana_id),
        "template_source": "brevo.smtp",
        "brevo_template_id": str(payload.brevo_template_id),
        "brevo_template_name": _clean_text(remote.get("name")),
        "brevo_updated_at": _clean_text(remote.get("updated_at")),
        "brevo_is_active": bool(remote.get("is_active")),
        "brevo_synced_at": datetime.now(timezone.utc).isoformat(),
    }

    local_templates = await repo.list_contact_templates(usuario_token=user_token, canal="correo")
    current_template: dict[str, Any] | None = None
    for item in local_templates:
        if not isinstance(item, dict):
            continue
        current_meta = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
        if _clean_text(current_meta.get("campana_id")) != str(payload.campana_id):
            continue
        if _clean_text(current_meta.get("brevo_template_id")) != str(payload.brevo_template_id):
            continue
        current_template = item
        break

    template_payload = _build_contact_template_payload(
        {
            "canal": "correo",
            "nombre": nombre,
            "slug": slug,
            "descripcion": _clean_text(payload.descripcion) or "Importada desde Brevo",
            "asunto": _clean_text(remote.get("subject")),
            "cuerpo_texto": text_content,
            "cuerpo_html": html_content,
            "metadata": metadata,
            "activo": True,
        },
        include_metadata=True,
    )

    try:
        if current_template and current_template.get("id"):
            template = await repo.update_contact_template(
                usuario_token=user_token,
                template_id=UUID(str(current_template["id"])),
                payload=template_payload,
            )
        else:
            template = await repo.create_contact_template(
                usuario_token=user_token,
                payload=template_payload,
            )
    except (ValueError, CRMRepositoryError) as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return {"ok": True, "template": template}


@router.get(
    "/prospeccion/whatsapp/readiness",
    response_model=ProspeccionWhatsappReadiness,
)
async def prospeccion_whatsapp_readiness(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
) -> ProspeccionWhatsappReadiness:
    """Diagnóstico rápido para habilitar campañas WhatsApp de prospección en frío."""

    twilio_runtime = await tenant_runtime.get_twilio_runtime_settings(organizacion_id=organizacion_id)
    whatsapp_runtime = await tenant_runtime.get_whatsapp_runtime_settings(organizacion_id=organizacion_id)

    has_twilio_account_sid = bool(_clean_text(twilio_runtime.account_sid))
    has_twilio_auth_token = bool(_clean_text(twilio_runtime.auth_token))
    has_twilio_phone_number = bool(_clean_text(twilio_runtime.phone_number))
    has_runtime_sales_template = bool(_clean_text(whatsapp_runtime.sales_template_sid))
    has_prospeccion_prompt_id = bool(_clean_text(whatsapp_runtime.prospeccion_prompt_id))
    has_prospeccion_prompt_version = bool(_clean_text(whatsapp_runtime.prospeccion_prompt_version))

    try:
        whatsapp_templates = await repo.list_contact_templates(
            usuario_token=user_token,
            canal="whatsapp",
        )
    except CRMRepositoryError:
        whatsapp_templates = []

    templates_with_twilio_sid = 0
    for template in whatsapp_templates:
        metadata = template.get("metadata") if isinstance(template.get("metadata"), dict) else {}
        sid = _clean_text(metadata.get("twilio_content_sid"))
        if sid:
            templates_with_twilio_sid += 1

    has_template_source = has_runtime_sales_template or templates_with_twilio_sid > 0
    checks = {
        "twilio_account_sid": has_twilio_account_sid,
        "twilio_auth_token": has_twilio_auth_token,
        "twilio_phone_number": has_twilio_phone_number,
        "whatsapp_template_source": has_template_source,
        "whatsapp_prospeccion_prompt_id": has_prospeccion_prompt_id,
        "whatsapp_prospeccion_prompt_version": has_prospeccion_prompt_version,
    }
    missing: list[str] = []
    if not has_twilio_account_sid:
        missing.append("twilio.account_sid")
    if not has_twilio_auth_token:
        missing.append("twilio.auth_token")
    if not has_twilio_phone_number:
        missing.append("twilio.phone_number")
    if not has_template_source:
        missing.append("whatsapp.templates.sales or template.metadata.twilio_content_sid")
    if not has_prospeccion_prompt_id:
        missing.append("whatsapp.prospeccion.prompt_id")
    if not has_prospeccion_prompt_version:
        missing.append("whatsapp.prospeccion.prompt_version")

    details = {
        "runtime_sales_template_sid": whatsapp_runtime.sales_template_sid,
        "runtime_prospeccion_prompt_id": whatsapp_runtime.prospeccion_prompt_id,
        "runtime_prospeccion_prompt_version": whatsapp_runtime.prospeccion_prompt_version,
        "whatsapp_templates_total": len(whatsapp_templates),
        "whatsapp_templates_with_twilio_sid": templates_with_twilio_sid,
    }
    return ProspeccionWhatsappReadiness(
        ok=all(checks.values()),
        organizacion_id=organizacion_id,
        checks=checks,
        missing=missing,
        details=details,
    )


