@router.get("/visitas/web-sessions")
async def get_visits_web_sessions(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("reports.view")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    limit: Annotated[int, Query(ge=1, le=5000)] = 1000,
    offset: Annotated[int, Query(ge=0)] = 0,
    source_class: str | None = Query(default=None),
    estado: str | None = Query(default=None),
    utm_source: str | None = Query(default=None),
    utm_medium: str | None = Query(default=None),
    utm_campaign: str | None = Query(default=None),
    template_id: str | None = Query(default=None),
    rango: str | None = Query(default=None),
    desde: str | None = Query(default=None),
    hasta: str | None = Query(default=None),
) -> list[dict[str, Any]]:
    source_class_value = (source_class or "").strip().lower() or None
    state_code = _ensure_state_code(estado) if estado else None
    utm_source_value = (utm_source or "").strip().lower() or None
    utm_medium_value = (utm_medium or "").strip().lower() or None
    utm_campaign_value = (utm_campaign or "").strip().lower() or None
    template_uuid_value: UUID | None = None
    template_id_raw = (template_id or "").strip() or None
    if template_id_raw:
        try:
            template_uuid_value = UUID(template_id_raw)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail="template_id_invalid") from exc

    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    date_from, date_to = _resolve_date_range(
        rango,
        desde,
        hasta,
        timezone_name=effective_timezone,
    )
    def _row_tracking_param(row: dict[str, Any], key: str) -> str | None:
        normalized_key = key.strip().lower()
        direct_value = _clean_text(row.get(normalized_key))
        if direct_value:
            return direct_value
        metadata = _ensure_dict(row.get("metadata"), default={})
        metadata_candidates = (
            metadata,
            _ensure_dict(metadata.get("utm"), default={}),
            _ensure_dict(metadata.get("campaign"), default={}),
            _ensure_dict(metadata.get("attribution"), default={}),
        )
        for candidate_meta in metadata_candidates:
            value = _clean_text(candidate_meta.get(normalized_key))
            if value:
                return value
        for url_key in ("landing_url", "referrer"):
            raw_url = _clean_text(row.get(url_key))
            if not raw_url:
                continue
            try:
                parsed = urlparse(raw_url)
                query_values = parse_qs(parsed.query or "", keep_blank_values=False)
            except Exception:
                continue
            for param_key, values in query_values.items():
                clean_key = param_key.strip().lower()
                if clean_key.startswith("amp;"):
                    clean_key = clean_key[4:]
                if clean_key != normalized_key:
                    continue
                for value in values:
                    cleaned = _clean_text(value)
                    if cleaned:
                        return cleaned
        return None

    try:
        rows = await repo.list_web_sessions_attribution_detail(
            organizacion_id=organizacion_id,
            date_from=date_from,
            date_to=date_to,
            state_code=state_code,
            source_class=source_class_value,
            utm_source=utm_source_value,
            utm_medium=utm_medium_value,
            utm_campaign=utm_campaign_value,
            template_id=template_uuid_value,
            limit=limit,
            offset=offset,
        )
        envio_ids: list[str] = []
        seen_envios: set[str] = set()
        contact_ids: list[UUID] = []
        seen_contacts: set[str] = set()
        prospecto_ids: list[UUID] = []
        seen_prospectos: set[str] = set()
        template_ids: list[str] = []
        seen_templates: set[str] = set()
        for row in rows:
            envio_id_value = _row_tracking_param(row, "eid") or ""
            if envio_id_value and envio_id_value not in seen_envios:
                seen_envios.add(envio_id_value)
                envio_ids.append(envio_id_value)
            prospecto_id_value = (
                _row_tracking_param(row, "pid")
                or _row_tracking_param(row, "prospecto_id")
                or ""
            )
            if prospecto_id_value and prospecto_id_value not in seen_prospectos:
                parsed_prospecto = _safe_uuid(prospecto_id_value)
                if parsed_prospecto:
                    seen_prospectos.add(prospecto_id_value)
                    prospecto_ids.append(parsed_prospecto)
            contact_id_raw = str(row.get("contacto_id") or "").strip()
            if contact_id_raw and contact_id_raw not in seen_contacts:
                parsed_contact = _safe_uuid(contact_id_raw)
                if parsed_contact:
                    seen_contacts.add(contact_id_raw)
                    contact_ids.append(parsed_contact)
            template_id_value = _row_tracking_param(row, "tid") or ""
            if template_id_value and template_id_value not in seen_templates:
                seen_templates.add(template_id_value)
                template_ids.append(template_id_value)

        envios_map: dict[str, dict[str, Any]] = {}
        prospectos_map: dict[str, dict[str, Any]] = {}
        if envio_ids:
            envios = await repo.list_contact_envios_by_ids(
                organizacion_id=organizacion_id,
                envio_ids=envio_ids,
            )
            envios_map = {
                str(item.get("id")): item
                for item in envios
                if isinstance(item, dict) and item.get("id")
            }
            for item in envios:
                if not isinstance(item, dict):
                    continue
                prospecto_id_raw = str(item.get("prospecto_id") or "").strip()
                if not prospecto_id_raw or prospecto_id_raw in seen_prospectos:
                    continue
                parsed_prospecto = _safe_uuid(prospecto_id_raw)
                if parsed_prospecto:
                    seen_prospectos.add(prospecto_id_raw)
                    prospecto_ids.append(parsed_prospecto)

        if prospecto_ids:
            prospectos = await repo.list_prospectos_by_ids(
                organizacion_id=organizacion_id,
                prospecto_ids=prospecto_ids,
            )
            prospectos_map = {
                str(item.get("id")): item
                for item in prospectos
                if isinstance(item, dict) and item.get("id")
            }
            missing_prospecto_ids = [
                prospecto_id
                for prospecto_id in prospecto_ids
                if str(prospecto_id) not in prospectos_map
            ]
            if missing_prospecto_ids:
                audit_rows = await repo.list_latest_prospectos_audit_by_ids(
                    organizacion_id=organizacion_id,
                    prospecto_ids=missing_prospecto_ids,
                )
                for audit_row in audit_rows:
                    prospecto_id = str(audit_row.get("prospecto_id") or "").strip()
                    if not prospecto_id or prospecto_id in prospectos_map:
                        continue
                    cambios = _ensure_dict(audit_row.get("cambios"), default={})
                    snapshot = _ensure_dict(cambios.get("after"), default={}) or _ensure_dict(
                        cambios.get("before"),
                        default={},
                    )
                    if not snapshot:
                        snapshot = cambios
                    if snapshot:
                        snapshot.setdefault("id", prospecto_id)
                        prospectos_map[prospecto_id] = snapshot

        contacts_map: dict[str, dict[str, Any]] = {}
        if contact_ids:
            contacts = await repo.get_contacts_by_ids(
                organizacion_id=organizacion_id,
                contacto_ids=contact_ids,
            )
            contacts_map = {
                str(item.get("id")): item
                for item in contacts
                if isinstance(item, dict) and item.get("id")
            }

        templates_map: dict[str, dict[str, Any]] = {}
        if template_ids:
            templates = await repo.list_contact_templates_by_ids(
                organizacion_id=organizacion_id,
                template_ids=template_ids,
            )
            templates_map = {
                str(item.get("id")): item
                for item in templates
                if isinstance(item, dict) and item.get("id")
            }
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    items: list[dict[str, Any]] = []
    for row in rows:
        row_metadata = _ensure_dict(row.get("metadata"), default={})
        def _pick_envio_email(envio_row: dict[str, Any] | None) -> str | None:
            if not isinstance(envio_row, dict):
                return None
            detalle = _ensure_dict(envio_row.get("detalle"), default={})
            payload = _ensure_dict(envio_row.get("payload"), default={})
            brevo = _ensure_dict(detalle.get("brevo"), default={})
            candidates = (
                detalle.get("email"),
                detalle.get("correo"),
                brevo.get("email"),
                payload.get("email"),
                payload.get("correo"),
                payload.get("to"),
                payload.get("recipient"),
                payload.get("destinatario"),
            )
            for candidate in candidates:
                value = _clean_text(candidate)
                if value:
                    return value
            return None

        envio_id_value = _row_tracking_param(row, "eid")
        envio_row = envios_map.get(envio_id_value) if envio_id_value else None
        correo_envio = _pick_envio_email(envio_row)
        prospecto_id_value = (
            str(envio_row.get("prospecto_id") or "").strip()
            if isinstance(envio_row, dict)
            else None
        ) or _row_tracking_param(row, "pid") or _row_tracking_param(row, "prospecto_id")
        prospecto_row = prospectos_map.get(prospecto_id_value) if prospecto_id_value else None
        contact_id_value = str(row.get("contacto_id") or "").strip() or None
        template_id_value = _row_tracking_param(row, "tid")
        contact_row = contacts_map.get(contact_id_value) if contact_id_value else None
        template_row = templates_map.get(template_id_value) if template_id_value else None
        template_slug = (
            str(template_row.get("slug") or "").strip() if isinstance(template_row, dict) else ""
        ) or None
        template_name = (
            str(template_row.get("nombre") or "").strip() if isinstance(template_row, dict) else ""
        ) or None
        prospect_name = (
            str(prospecto_row.get("display_name") or "").strip()
            if isinstance(prospecto_row, dict)
            else ""
        ) or None
        prospect_email = (
            str(
                prospecto_row.get("correo_principal")
                or prospecto_row.get("correo_secundario")
                or prospecto_row.get("email")
                or ""
            ).strip()
            if isinstance(prospecto_row, dict)
            else ""
        ) or None
        prospect_phone = (
            str(
                prospecto_row.get("telefono_principal_e164")
                or prospecto_row.get("telefono_movil_1_e164")
                or prospecto_row.get("phone_e164")
                or prospecto_row.get("phone")
                or ""
            ).strip()
            if isinstance(prospecto_row, dict)
            else ""
        ) or None
        prospect_origin = (
            str(prospecto_row.get("fuente") or "").strip()
            if isinstance(prospecto_row, dict)
            else ""
        ) or None
        metadata_contact_name = _clean_text(row_metadata.get("contacto_nombre")) or None
        metadata_contact_email = _clean_text(row_metadata.get("contacto_correo")) or None
        metadata_contact_phone = _clean_text(row_metadata.get("contacto_telefono")) or None
        metadata_contact_origin = _clean_text(
            row_metadata.get("contacto_origen")
            or row_metadata.get("contact_origin")
            or row_metadata.get("origen_contacto")
            or row_metadata.get("contact_source")
        ) or None
        contact_name = (
            str(contact_row.get("nombre_completo") or "").strip()
            if isinstance(contact_row, dict)
            else None
        ) or prospect_name or metadata_contact_name or None
        contact_origin = (
            str(contact_row.get("origen") or "").strip()
            if isinstance(contact_row, dict)
            else None
        ) or prospect_origin or metadata_contact_origin or None
        contact_phone = (
            str(
                contact_row.get("telefono_movil_1_e164")
                or contact_row.get("telefono_principal_e164")
                or contact_row.get("telefono_e164")
                or contact_row.get("phone_e164")
                or contact_row.get("telefono")
                or ""
            ).strip()
            if isinstance(contact_row, dict)
            else None
        ) or prospect_phone or metadata_contact_phone or None
        contact_email = (
            str(
                contact_row.get("correo_principal")
                or contact_row.get("correo_secundario")
                or contact_row.get("correo_institucional")
                or contact_row.get("correo")
                or ""
            ).strip()
            if isinstance(contact_row, dict)
            else None
        ) or correo_envio or prospect_email or metadata_contact_email or None

        items.append(
            {
                "session_id": row.get("session_id"),
                "contacto_id": contact_id_value or prospecto_id_value,
                "contacto_nombre": contact_name,
                "contacto_origen": contact_origin,
                "contacto_telefono": contact_phone,
                "contacto_correo": contact_email,
                "correo_envio": correo_envio,
                "first_seen_at": row.get("first_seen_at"),
                "last_seen_at": row.get("last_seen_at"),
                "visit_count": row.get("visit_count"),
                "ip": row.get("ip"),
                "device_type": row.get("device_type"),
                "country_code": row.get("country_code"),
                "country_name": row.get("country_name"),
                "cve_ent": row.get("cve_ent"),
                "nom_ent": row.get("nom_ent"),
                "cve_mun": row.get("cve_mun"),
                "nom_mun": row.get("nom_mun"),
                "cvegeo": row.get("cvegeo"),
                "referrer": row.get("referrer"),
                "landing_url": row.get("landing_url"),
                "utm_source": row.get("utm_source"),
                "utm_medium": row.get("utm_medium"),
                "utm_campaign": row.get("utm_campaign"),
                "source_class": row.get("source_class"),
                "eid": envio_id_value,
                "template_id": template_id_value,
                "template_slug": template_slug,
                "template_nombre": template_name,
                "metadata": row.get("metadata"),
            }
        )
    logger.info(
        "visitas.web_sessions.summary",
        extra={
            "organizacion_id": str(organizacion_id),
            "rows_raw": len(rows),
            "rows_items": len(items),
            "limit": limit,
            "offset": offset,
            "state_code": state_code,
            "source_class": source_class_value,
            "utm_source": utm_source_value,
            "utm_medium": utm_medium_value,
            "utm_campaign": utm_campaign_value,
            "template_id": str(template_uuid_value) if template_uuid_value else None,
            "date_from": date_from.isoformat() if date_from else None,
            "date_to": date_to.isoformat() if date_to else None,
        },
    )
    return items


@router.get("/visitas/whatsapp/total")
async def get_visits_whatsapp_total(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("reports.view")),
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    rango: str | None = Query(default=None),
    desde: str | None = Query(default=None),
    hasta: str | None = Query(default=None),
) -> dict[str, int]:
    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    date_from, date_to = _resolve_date_range(
        rango,
        desde,
        hasta,
        timezone_name=effective_timezone,
    )
    try:
        total = await repo.visitas_whatsapp_total(
            usuario_token=_normalize_reports_user_token(user_token),
            date_from=date_from,
            date_to=date_to,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {"total": total}


@router.get("/visitas/whatsapp/conversaciones")
async def get_visits_whatsapp_conversations(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("reports.view")),
    user_token: str | None = Depends(optional_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    limit: Annotated[int, Query(ge=1, le=500)] = 200,
    rango: str | None = Query(default=None),
    desde: str | None = Query(default=None),
    hasta: str | None = Query(default=None),
    wa_canal_publicitario: str | None = Query(default=None),
    wa_campana_publicitaria: str | None = Query(default=None),
    wa_regla_id: str | None = Query(default=None),
    campana_id: str | None = Query(default=None),
    campana_tipo: str | None = Query(default=None),
    template_id: str | None = Query(default=None),
) -> list[dict[str, Any]]:
    request_started = time.perf_counter()
    stage_timings: dict[str, float] = {}
    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    date_from, date_to = _resolve_date_range(
        rango,
        desde,
        hasta,
        timezone_name=effective_timezone,
    )
    def _normalize_match(value: Any) -> str | None:
        cleaned = _clean_text(value)
        return cleaned.lower() if cleaned else None

    wa_canal_value = _normalize_match(wa_canal_publicitario)
    wa_campana_value = _normalize_match(wa_campana_publicitaria)
    wa_regla_id_value = (wa_regla_id or "").strip() or None
    campana_id_value = (campana_id or "").strip() or None
    campana_tipo_value = (campana_tipo or "").strip().lower() or None
    template_id_value = (template_id or "").strip().lower() or None
    wa_regla_uuid: UUID | None = None
    if wa_regla_id_value:
        try:
            wa_regla_uuid = UUID(wa_regla_id_value)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail="wa_regla_id_invalid") from exc

    try:
        fetch_rows_started = time.perf_counter()
        rows = await repo.visitas_persona_whatsapp_conversaciones(
            usuario_token=_normalize_reports_user_token(user_token),
            organizacion_id=organizacion_id,
            limit=limit,
            date_from=date_from,
            date_to=date_to,
        )
        stage_timings["fetch_rows_ms"] = round((time.perf_counter() - fetch_rows_started) * 1000, 2)
        events_started = time.perf_counter()
        conversation_ids = [
            str(row.get("id") or "").strip()
            for row in rows
            if isinstance(row, dict) and str(row.get("id") or "").strip()
        ]
        wa_events = await repo.worker_list_whatsapp_atribucion_events_by_conversations(
            organizacion_id=organizacion_id,
            conversation_ids=conversation_ids,
        )
        stage_timings["wa_events_ms"] = round((time.perf_counter() - events_started) * 1000, 2)
        rules_started = time.perf_counter()
        wa_by_conversation: dict[str, dict[str, Any]] = {}
        for event_row in wa_events:
            conv_id = str(event_row.get("conversacion_id") or "").strip()
            if not conv_id or conv_id in wa_by_conversation:
                continue
            wa_by_conversation[conv_id] = event_row
        regla_ids = [
            str(event_row.get("regla_id") or "").strip()
            for event_row in wa_events
            if str(event_row.get("regla_id") or "").strip()
        ]
        reglas_rows = await repo.worker_list_whatsapp_atribucion_reglas_by_ids(
            organizacion_id=organizacion_id,
            regla_ids=regla_ids,
        )
        stage_timings["wa_rules_ms"] = round((time.perf_counter() - rules_started) * 1000, 2)
        phone_lookup_started = time.perf_counter()
        regla_by_id = {
            str(rule_row.get("id") or "").strip(): rule_row
            for rule_row in reglas_rows
            if isinstance(rule_row, dict) and str(rule_row.get("id") or "").strip()
        }
        phone_candidates_map: dict[str, list[str]] = {}
        all_lookup_candidates: set[str] = set()
        for row in rows:
            if not isinstance(row, dict):
                continue
            contacto = row.get("contacto") if isinstance(row.get("contacto"), dict) else {}
            telefono = _clean_text(contacto.get("telefono_e164"))
            if not telefono:
                continue
            candidates = _whatsapp_phone_lookup_candidates(telefono)
            if not candidates:
                continue
            row_id = str(row.get("id") or "").strip()
            if not row_id:
                continue
            phone_candidates_map[row_id] = candidates
            all_lookup_candidates.update(candidates)

        latest_envios_by_phone: dict[str, dict[str, Any]] = {}
        if all_lookup_candidates:
            latest_envios_by_phone = await repo.worker_get_latest_envios_by_phones(
                phone_values=all_lookup_candidates,
                organizacion_id=organizacion_id,
                canal="whatsapp",
            )
        stage_timings["phone_lookup_ms"] = round((time.perf_counter() - phone_lookup_started) * 1000, 2)

        catalog_started = time.perf_counter()
        hints_by_conversation: dict[str, tuple[str | None, str | None, str | None, str | None, str | None]] = {}
        batch_ids: set[str] = set()
        campana_ids: set[str] = set()
        template_ids: set[str] = set()
        template_slugs: set[str] = set()
        for row in rows:
            if not isinstance(row, dict):
                continue
            row_id = str(row.get("id") or "").strip()
            if not row_id:
                continue
            hint: tuple[str | None, str | None, str | None, str | None, str | None] = (None, None, None, None, None)
            for lookup_phone in phone_candidates_map.get(row_id, []):
                envio_row = latest_envios_by_phone.get(lookup_phone)
                candidate_hint = _extract_envio_prospeccion_hints(envio_row)
                if any(candidate_hint[:4]) or candidate_hint[4]:
                    hint = candidate_hint
                    break
            hints_by_conversation[row_id] = hint
            if hint[0] and _safe_uuid(hint[0]):
                batch_ids.add(hint[0])
            if hint[1] and _safe_uuid(hint[1]):
                campana_ids.add(hint[1])
            if hint[2] and _safe_uuid(hint[2]):
                template_ids.add(hint[2])
            if hint[3]:
                template_slugs.add(hint[3])

        batch_label_map: dict[str, str] = {}
        batch_template_hint_map: dict[str, tuple[str | None, str | None, str | None]] = {}
        batch_campaign_map: dict[str, str | None] = {}
        if batch_ids:
            try:
                batch_rows = await repo.list_contact_batches_by_ids(
                    usuario_token=_normalize_reports_user_token(user_token),
                    batch_ids=batch_ids,
                )
            except CRMRepositoryError:
                batch_rows = []
            for batch in batch_rows:
                batch_id_row = _clean_text(batch.get("id"))
                if not batch_id_row or batch_id_row not in batch_ids:
                    continue
                metadata = batch.get("metadata") if isinstance(batch.get("metadata"), dict) else {}
                title = _clean_text(batch.get("titulo")) or _clean_text(metadata.get("campana_nombre")) or _clean_text(metadata.get("lista_nombre"))
                if title:
                    batch_label_map[batch_id_row] = title
                batch_campaign_map[batch_id_row] = _clean_text(batch.get("campana_id"))
                batch_template_id = _clean_text(metadata.get("template_id") or metadata.get("contact_template_id"))
                batch_template_slug = _clean_text(metadata.get("template_slug") or metadata.get("kw"))
                batch_template_name = _clean_text(metadata.get("template_nombre") or metadata.get("template_name"))
                batch_template_hint_map[batch_id_row] = (
                    batch_template_id,
                    batch_template_slug.lower() if batch_template_slug else None,
                    batch_template_name,
                )
                if batch_template_id and _safe_uuid(batch_template_id):
                    template_ids.add(batch_template_id)
                if batch_template_slug:
                    template_slugs.add(batch_template_slug.lower())

        campana_label_map: dict[str, str] = {}
        campana_canal_map: dict[str, str | None] = {}
        if campana_ids or campana_tipo_value:
            campaign_rows = await repo.list_campaigns(organizacion_id=organizacion_id)
            for campaign_row in campaign_rows:
                campaign_id_row = _clean_text(campaign_row.get("id"))
                if not campaign_id_row:
                    continue
                campana_canal_map[campaign_id_row] = _clean_text(campaign_row.get("canal"))
                campaign_name = _clean_text(campaign_row.get("nombre"))
                if campaign_name:
                    campana_label_map[campaign_id_row] = campaign_name

        template_label_by_id: dict[str, str] = {}
        template_label_by_slug: dict[str, str] = {}
        if template_ids or template_slugs:
            templates = await repo.list_contact_templates(usuario_token=_normalize_reports_user_token(user_token))
            for template_row in templates:
                template_id_row = _clean_text(template_row.get("id"))
                template_slug_row = _clean_text(template_row.get("slug"))
                template_name = _clean_text(template_row.get("nombre"))
                if template_id_row and template_name:
                    template_label_by_id[template_id_row] = template_name
                if template_slug_row and template_name:
                    template_label_by_slug[template_slug_row.lower()] = template_name
        stage_timings["catalogs_ms"] = round((time.perf_counter() - catalog_started) * 1000, 2)

        enrich_started = time.perf_counter()
        enriched_rows: list[dict[str, Any]] = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            conv_id = str(row.get("id") or "").strip()
            contacto = row.get("contacto") if isinstance(row.get("contacto"), dict) else {}
            telefono = str(contacto.get("telefono_e164") or "").strip() or None
            location = leads_geo.phone_location_from_number(telefono)
            location_ok = bool(location.country_code or location.estado_clave or location.estado_nombre)
            if not telefono:
                logger.warning(
                    "whatsapp.phone_location_missing_phone",
                    extra={"conversation_id": conv_id, "organizacion_id": str(organizacion_id)},
                )
            elif not location_ok:
                logger.warning(
                    "whatsapp.phone_location_unresolved",
                    extra={"conversation_id": conv_id, "telefono_e164": telefono},
                )
            row["phone_location"] = {
                "country_code": location.country_code,
                "country_name": location.country_name,
                "state_code": location.estado_clave,
                "state_name": location.estado_nombre,
                "municipality_name": location.municipio_nombre,
                "lada": location.lada,
                "ok": location_ok,
            }
            event_row = wa_by_conversation.get(conv_id)
            batch_hint, campana_hint, template_id_hint, template_slug_hint, template_label_hint = hints_by_conversation.get(
                conv_id,
                (None, None, None, None, None),
            )
            if batch_hint and not campana_hint:
                campana_hint = batch_campaign_map.get(batch_hint)
            batch_template_hint = batch_template_hint_map.get(batch_hint or "", (None, None, None))
            resolved_template_id = template_id_hint or batch_template_hint[0]
            resolved_template_slug = template_slug_hint or batch_template_hint[1]
            resolved_template_label = (
                template_label_by_id.get(resolved_template_id or "")
                or template_label_by_slug.get((resolved_template_slug or "").lower())
                or template_label_hint
                or batch_template_hint[2]
            )
            resolved_campana_label = campana_label_map.get(campana_hint or "")
            resolved_campana_canal = _clean_text(campana_canal_map.get(campana_hint or ""))
            if batch_hint or campana_hint or resolved_template_id or resolved_template_slug or resolved_template_label:
                row["whatsapp_prospeccion"] = {
                    "batch_id": batch_hint,
                    "batch_label": batch_label_map.get(batch_hint or ""),
                    "campana_id": campana_hint,
                    "campana_nombre": resolved_campana_label,
                    "campana_tipo": resolved_campana_canal,
                    "template_id": resolved_template_id,
                    "template_slug": resolved_template_slug,
                    "template_nombre": resolved_template_label,
                }
            if event_row:
                regla_id_value = str(event_row.get("regla_id") or "").strip()
                regla_row = regla_by_id.get(regla_id_value, {})
                row["whatsapp_atribucion"] = {
                    "canal_publicitario": _clean_text(event_row.get("canal_publicitario")),
                    "campana_publicitaria": _clean_text(event_row.get("campana_publicitaria")),
                    "regla_id": regla_id_value or None,
                    "regla_nombre": _clean_text(regla_row.get("nombre_regla")),
                    "regla_frase": _clean_text(regla_row.get("frase_objetivo")),
                    "adset": _clean_text(event_row.get("adset")),
                    "anuncio": _clean_text(event_row.get("anuncio")),
                    "creado_en": event_row.get("creado_en"),
                }
            if wa_canal_value or wa_campana_value or wa_regla_uuid:
                if not event_row:
                    continue
                if wa_canal_value and _normalize_match(event_row.get("canal_publicitario")) != wa_canal_value:
                    continue
                if wa_campana_value and _normalize_match(event_row.get("campana_publicitaria")) != wa_campana_value:
                    continue
                if wa_regla_uuid and str(event_row.get("regla_id") or "").strip() != str(wa_regla_uuid):
                    continue
            if campana_tipo_value:
                if (resolved_campana_canal or "").strip().lower() != campana_tipo_value:
                    continue
            if campana_id_value:
                if (campana_hint or "") != campana_id_value:
                    continue
            if template_id_value:
                template_id_match = (resolved_template_id or "").strip().lower()
                template_slug_match = (resolved_template_slug or "").strip().lower()
                if template_id_match != template_id_value and template_slug_match != template_id_value:
                    continue
            enriched_rows.append(row)
        rows = enriched_rows
        stage_timings["enrichment_ms"] = round((time.perf_counter() - enrich_started) * 1000, 2)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    stage_timings["total_ms"] = round((time.perf_counter() - request_started) * 1000, 2)
    logger.info(
        "crm.visitas.whatsapp.conversaciones.done",
        extra={
            "limit": limit,
            "rows": len(rows),
            "stage_timings": stage_timings,
        },
    )
    return rows


@router.get("/actividades", response_model=CRMActivitiesResponse)
async def list_activities(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("activities.view")),
    oportunidad_id: UUID | None = Query(default=None),
    cuenta_id: UUID | None = Query(default=None),
    persona_id: UUID | None = Query(default=None),
    contacto_id: UUID | None = Query(default=None),
    asignado_a_usuario_id: UUID | None = Query(default=None),
    estado: str | None = Query(default=None),
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> CRMActivitiesResponse:
    try:
        rows = await repo.list_activities(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
            cuenta_id=cuenta_id,
            persona_id=persona_id,
            contacto_id=contacto_id,
            asignado_a_usuario_id=asignado_a_usuario_id,
            estado=estado,
            limit=limit,
            offset=offset,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    user_ids = sorted(
        {
            str(row.get("creado_por_usuario_id") or "").strip()
            for row in rows
            if isinstance(row, dict) and str(row.get("creado_por_usuario_id") or "").strip()
        }
        | {
            str(row.get("asignado_a_usuario_id") or "").strip()
            for row in rows
            if isinstance(row, dict) and str(row.get("asignado_a_usuario_id") or "").strip()
        }
    )
    users_by_id: dict[str, dict[str, Any]] = {}
    if user_ids:
        try:
            users = await repo.list_users_with_primary_role_by_ids(
                organizacion_id=organizacion_id,
                user_ids=[UUID(user_id) for user_id in user_ids],
            )
            users_by_id = {
                str(user.get("id")): user
                for user in users
                if isinstance(user, dict) and str(user.get("id") or "").strip()
            }
        except CRMRepositoryError:
            users_by_id = {}
    payload: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        created_by_id = str(row.get("creado_por_usuario_id") or "").strip()
        assigned_by_id = str(row.get("asignado_a_usuario_id") or "").strip()
        payload.append(
            {
                **row,
                "creado_por_usuario": users_by_id.get(created_by_id) if created_by_id else None,
                "asignado_a_usuario": users_by_id.get(assigned_by_id) if assigned_by_id else None,
            },
        )
    items = [CRMActivity.model_validate(row) for row in payload]
    return CRMActivitiesResponse(items=items, limit=limit, offset=offset)


@router.post("/actividades", response_model=CRMActivity, status_code=status.HTTP_201_CREATED)
async def create_activity(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("activities.view")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    payload: CRMActivityCreate,
) -> CRMActivity:
    body = payload.model_dump(mode="json", exclude_unset=True)
    if "creado_por_usuario_id" not in body and usuario_id:
        body["creado_por_usuario_id"] = str(usuario_id)
    if body.get("oportunidad_id") and (not body.get("persona_id") or not body.get("cuenta_id")):
        try:
            opportunity_row = await repo.get_opportunity(
                organizacion_id=organizacion_id,
                opportunity_id=UUID(str(body["oportunidad_id"])),
            )
        except CRMRepositoryError:
            opportunity_row = None
        if isinstance(opportunity_row, dict):
            body.setdefault("persona_id", opportunity_row.get("persona_id"))
            body.setdefault("cuenta_id", opportunity_row.get("cuenta_id"))
    # Las actividades independientes de una oportunidad pertenecen al usuario
    # que las crea por defecto. Así el recordatorio no queda sin destinatario.
    if (
        usuario_id
        and not body.get("asignado_a_usuario_id")
        and not body.get("oportunidad_id")
        and (body.get("persona_id") or body.get("cuenta_id"))
    ):
        body["asignado_a_usuario_id"] = str(usuario_id)
    try:
        row = await repo.create_activity(
            organizacion_id=organizacion_id,
            payload=body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if usuario_id:
        try:
            await notify_activity_created(
                repo=repo,
                organizacion_id=organizacion_id,
                activity_row=row,
                actor_user_id=usuario_id,
            )
        except CRMRepositoryError as exc:
            logger.warning(
                "crm.activity_created_notification_failed",
                extra={"error": str(exc), "activity_id": str(row.get("id") or "")},
            )
    return CRMActivity.model_validate(row)


