@router.get("/notas", response_model=list[CRMNote])
async def list_notes(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("notes.view")),
    relacion_tipo: str | None = Query(default=None),
    relacion_id: UUID | None = Query(default=None),
    actividad_id: UUID | None = Query(default=None),
) -> list[CRMNote]:
    try:
        rows = await repo.list_notes(
            organizacion_id=organizacion_id,
            relacion_tipo=relacion_tipo,
            relacion_id=relacion_id,
            actividad_id=actividad_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    user_ids = sorted(
        {
            str(row.get("creado_por_usuario_id") or "").strip()
            for row in rows
            if isinstance(row, dict) and str(row.get("creado_por_usuario_id") or "").strip()
        }
    )
    users_by_id: dict[str, dict[str, Any]] = {}
    if user_ids:
        try:
            users = await repo.list_users_with_primary_role_by_ids(
                organizacion_id=organizacion_id,
                user_ids=[UUID(user_id) for user_id in user_ids],
            )
            users_by_id = {
                str(user.get("id")): user
                for user in users
                if isinstance(user, dict) and str(user.get("id") or "").strip()
            }
        except CRMRepositoryError:
            users_by_id = {}
    payload: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        created_by_id = str(row.get("creado_por_usuario_id") or "").strip()
        payload.append(
            {
                **row,
                "creado_por_usuario": users_by_id.get(created_by_id) if created_by_id else None,
            },
        )
    return [CRMNote.model_validate(row) for row in payload]


@router.post("/notas", response_model=CRMNote, status_code=status.HTTP_201_CREATED)
async def create_note(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("notes.view")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    payload: CRMNoteCreate,
) -> CRMNote:
    body = payload.model_dump(mode="json", exclude_unset=True)
    if not body.get("creado_por_usuario_id") and usuario_id:
        body["creado_por_usuario_id"] = str(usuario_id)
    if payload.actividad_id:
        try:
            activity_row = await repo.get_activity(
                organizacion_id=organizacion_id,
                activity_id=payload.actividad_id,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not activity_row:
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="actividad_no_encontrada")
    try:
        row = await repo.create_note(
            organizacion_id=organizacion_id,
            payload=body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if usuario_id:
        try:
            await notify_note_created(
                repo=repo,
                organizacion_id=organizacion_id,
                note_row=row,
                actor_user_id=usuario_id,
            )
        except CRMRepositoryError as exc:
            logger.warning(
                "crm.note_created_notification_failed",
                extra={"error": str(exc), "note_id": str(row.get("id") or "")},
            )
    return CRMNote.model_validate(row)


