@router.post(
    "/web/visit",
    status_code=204,
    summary="Registra una visita web first-party para mapa de conversión",
)
async def register_web_visit(
    payload: WebVisitPayload,
    request: Request,
) -> Response:
    session_id = (payload.session_id or "").strip()
    if not session_id:
        raise HTTPException(status_code=400, detail="session_id_required")

    raw_metadata = payload.metadata if isinstance(payload.metadata, dict) else {}
    metadata = dict(raw_metadata)

    tenant_alias = (payload.tenant_alias or "").strip().lower()
    if not tenant_alias:
        meta_alias = raw_metadata.get("tenant_alias")
        if isinstance(meta_alias, str) and meta_alias.strip():
            tenant_alias = meta_alias.strip().lower()
    if not tenant_alias:
        header_alias = request.headers.get("x-tenant-alias")
        if header_alias and header_alias.strip():
            tenant_alias = header_alias.strip().lower()

    organizacion_id: str | None = None
    if tenant_alias:
        organizacion_id = await resolve_organizacion_id(canal="webchat", clave=tenant_alias)
    # Nunca aceptamos organizacion_id desde metadata pública: sería falsificable
    # y permitiría atribuir tráfico a otro tenant. El alias se resuelve en backend.
    if not organizacion_id:
        organizacion_id = str(tenant_runtime.MASTER_ORGANIZACION_ID)

    user_agent = (payload.user_agent or request.headers.get("user-agent") or "").strip() or None
    # Para atribucion web usamos referrer first-party enviado por frontend (document.referrer).
    # El Referer del request HTTP suele apuntar a talia.mx y distorsiona "entrada directa".
    referrer = (payload.referrer or "").strip() or None
    landing_url = (payload.landing_url or payload.location_href or "").strip() or None
    device_type = (payload.device_type or _infer_device_type(user_agent) or "").strip() or None
    source_class = _classify_source_class(
        source_class=payload.source_class,
        referrer=referrer,
        landing_url=landing_url,
        utm_source=payload.utm_source,
        utm_medium=payload.utm_medium,
        utm_campaign=payload.utm_campaign,
    )
    ip_value = _request_ip(request)
    cf_country = (request.headers.get("cf-ipcountry") or "").strip().upper() or None
    referrer_host: str | None = None
    if referrer:
        parsed_ref = urlparse(referrer)
        referrer_host = (parsed_ref.hostname or "").strip().lower() or None

    client_context = raw_metadata.get("client") if isinstance(raw_metadata.get("client"), dict) else {}
    client_geo = client_context.get("geo") if isinstance(client_context.get("geo"), dict) else {}

    geo_ip_data: dict[str, Any] | None = None
    if ip_value:
        try:
            geo_ip_data = await geolocation.lookup_ip(ip_value)
        except Exception:
            logger.exception(
                "crm.web.visit_geo_lookup_failed",
                extra={"session_id": session_id, "ip": ip_value},
            )
            geo_ip_data = None

    geo_source: dict[str, Any] = {}
    if isinstance(geo_ip_data, dict):
        country_ip = geo_ip_data.get("country")
        if country_ip:
            geo_source["country"] = str(country_ip).upper()
        region_ip = geo_ip_data.get("region")
        if region_ip:
            geo_source["region"] = region_ip
            geo_source.setdefault("state", region_ip)
        city_ip = geo_ip_data.get("city")
        if city_ip:
            geo_source["city"] = city_ip
    if isinstance(client_geo, dict):
        country_client = client_geo.get("country_code") or client_geo.get("country")
        if country_client:
            geo_source["country"] = str(country_client).upper()
        for key in ("region", "state", "nom_ent", "city", "nom_mun"):
            value = client_geo.get(key)
            if value:
                geo_source[key] = value

    estado_clave: str | None
    estado_nombre: str | None
    municipio_clave: str | None
    municipio_nombre: str | None
    cvegeo_resolved: str | None
    estado_clave, estado_nombre, municipio_clave, municipio_nombre, cvegeo_resolved = (
        leads_geo.location_from_geo_metadata(geo_source or None)
    )

    country_code = payload.country_code or (
        str((geo_ip_data or {}).get("country_code") or (geo_ip_data or {}).get("country")).upper()
        if isinstance((geo_ip_data or {}).get("country_code") or (geo_ip_data or {}).get("country"), str)
        else (
            str(client_geo.get("country_code") or client_geo.get("country")).upper()
            if isinstance(client_geo, dict)
            and isinstance(client_geo.get("country_code") or client_geo.get("country"), str)
            else None
        )
    )
    if not country_code and cf_country and cf_country not in {"XX", "ZZ", "T1"}:
        country_code = cf_country
    country_name = payload.country_name or (
        str((geo_ip_data or {}).get("country_name"))
        if isinstance((geo_ip_data or {}).get("country_name"), str)
        else (
            str(client_geo.get("country_name"))
            if isinstance(client_geo, dict) and isinstance(client_geo.get("country_name"), str)
            else None
        )
    )
    cve_ent = payload.cve_ent or estado_clave
    nom_ent = payload.nom_ent or estado_nombre
    cve_mun = payload.cve_mun or municipio_clave
    nom_mun = payload.nom_mun or municipio_nombre
    cvegeo = payload.cvegeo or cvegeo_resolved

    metadata.setdefault("tenant_alias", tenant_alias or None)
    metadata.setdefault("request_ip", ip_value)
    metadata.setdefault(
        "request_headers",
        {
            "x_forwarded_for": request.headers.get("x-forwarded-for"),
            "x_real_ip": request.headers.get("x-real-ip"),
            "cf_connecting_ip": request.headers.get("cf-connecting-ip"),
            "cf_ipcountry": cf_country,
            "referer": request.headers.get("referer"),
            "origin": request.headers.get("origin"),
            "accept_language": request.headers.get("accept-language"),
            "sec_ch_ua": request.headers.get("sec-ch-ua"),
            "sec_ch_ua_mobile": request.headers.get("sec-ch-ua-mobile"),
            "sec_ch_ua_platform": request.headers.get("sec-ch-ua-platform"),
        },
    )
    metadata.setdefault("referrer_host", referrer_host)
    metadata.setdefault("path", request.url.path if request else None)
    visitor_seed = "|".join(
        [
            (ip_value or "").strip(),
            (user_agent or "").strip(),
            (tenant_alias or "").strip(),
            (payload.session_id or "").strip(),
        ]
    )
    if visitor_seed.strip():
        metadata.setdefault("visitor_hash", hashlib.sha256(visitor_seed.encode("utf-8")).hexdigest())
    if geo_ip_data:
        metadata.setdefault("ip_lookup", geo_ip_data)
    if client_geo:
        metadata.setdefault("client_geo", client_geo)
    metadata.setdefault(
        "resolved_location",
        {
            "country_code": country_code,
            "country_name": country_name,
            "cve_ent": cve_ent,
            "nom_ent": nom_ent,
            "cve_mun": cve_mun,
            "nom_mun": nom_mun,
            "cvegeo": cvegeo,
        },
    )

    rpc_payload: dict[str, Any] = {
        "p_ip": ip_value,
        "p_user_agent": user_agent,
        "p_device_type": device_type,
        "p_country_code": country_code or None,
        "p_country_name": country_name or None,
        "p_cve_ent": cve_ent or None,
        "p_nom_ent": nom_ent or None,
        "p_cve_mun": cve_mun or None,
        "p_nom_mun": nom_mun or None,
        "p_cvegeo": cvegeo or None,
        "p_landing_url": landing_url,
        "p_referrer": referrer,
        "p_utm_source": payload.utm_source or None,
        "p_utm_medium": payload.utm_medium or None,
        "p_utm_campaign": payload.utm_campaign or None,
        "p_utm_term": payload.utm_term or None,
        "p_utm_content": payload.utm_content or None,
        "p_eid": str(payload.eid) if payload.eid else None,
        "p_cid": str(payload.cid) if payload.cid else None,
        "p_tid": str(payload.tid) if payload.tid else None,
        "p_source_class": source_class,
        "p_contacto_id": str(payload.contacto_id) if payload.contacto_id else None,
        "p_metadata": metadata,
        "p_organizacion_id": organizacion_id,
    }
    rpc_payload = {key: value for key, value in rpc_payload.items() if value is not None}

    repo = CRMRepository()
    try:
        await repo.record_web_session(session_id=session_id, payload=rpc_payload)
    except CRMRepositoryError as exc:
        logger.exception(
            "crm.web.visit_failed",
            extra={"session_id": session_id, "tenant_alias": tenant_alias, "error": str(exc)},
        )
        raise HTTPException(status_code=502, detail="web_visit_register_failed") from exc

    return Response(status_code=204)


@router.post(
    "/web/cta-click",
    status_code=204,
    summary="Registra un click en CTA web (WhatsApp u otros).",
)
async def register_web_cta_click(
    payload: WebCtaClickPayload,
    request: Request,
) -> Response:
    session_id = (payload.session_id or "").strip()
    if not session_id:
        raise HTTPException(status_code=400, detail="session_id_required")

    raw_metadata = payload.metadata if isinstance(payload.metadata, dict) else {}
    metadata = dict(raw_metadata)

    tenant_alias = (payload.tenant_alias or "").strip().lower()
    if not tenant_alias:
        meta_alias = raw_metadata.get("tenant_alias")
        if isinstance(meta_alias, str) and meta_alias.strip():
            tenant_alias = meta_alias.strip().lower()
    if not tenant_alias:
        header_alias = request.headers.get("x-tenant-alias")
        if header_alias and header_alias.strip():
            tenant_alias = header_alias.strip().lower()

    organizacion_id: str | None = None
    if payload.organizacion_id:
        organizacion_id = str(payload.organizacion_id)
    if not organizacion_id and tenant_alias:
        organizacion_id = await resolve_organizacion_id(canal="webchat", clave=tenant_alias)
    if not organizacion_id:
        explicit_org = raw_metadata.get("organizacion_id")
        if isinstance(explicit_org, str) and explicit_org.strip():
            try:
                organizacion_id = str(UUID(explicit_org.strip()))
            except ValueError:
                organizacion_id = None
    if not organizacion_id:
        organizacion_id = str(tenant_runtime.MASTER_ORGANIZACION_ID)

    user_agent = (payload.user_agent or request.headers.get("user-agent") or "").strip() or None
    referrer = (payload.referrer or request.headers.get("referer") or "").strip() or None
    location_href = (payload.location_href or "").strip() or None

    metadata.setdefault("tenant_alias", tenant_alias or None)
    metadata.setdefault("request_ip", _request_ip(request))
    metadata.setdefault(
        "request_headers",
        {
            "x_forwarded_for": request.headers.get("x-forwarded-for"),
            "x_real_ip": request.headers.get("x-real-ip"),
            "cf_connecting_ip": request.headers.get("cf-connecting-ip"),
            "cf_ipcountry": request.headers.get("cf-ipcountry"),
            "referer": request.headers.get("referer"),
            "origin": request.headers.get("origin"),
            "accept_language": request.headers.get("accept-language"),
            "sec_ch_ua": request.headers.get("sec-ch-ua"),
            "sec_ch_ua_mobile": request.headers.get("sec-ch-ua-mobile"),
            "sec_ch_ua_platform": request.headers.get("sec-ch-ua-platform"),
        },
    )

    row_payload: dict[str, Any] = {
        "organizacion_id": organizacion_id,
        "session_id": session_id,
        "event_type": (payload.event_type or "whatsapp_cta_click"),
        "cta_id": payload.cta_id,
        "hero_variant": payload.hero_variant,
        "location_href": location_href,
        "referrer": referrer,
        "user_agent": user_agent,
        "metadata": metadata,
    }
    row_payload = {key: value for key, value in row_payload.items() if value is not None}

    repo = CRMRepository()
    try:
        await repo.create_web_session_event(
            organizacion_id=UUID(organizacion_id),
            payload=row_payload,
        )
    except CRMRepositoryError as exc:
        logger.exception(
            "crm.web.cta_click_failed",
            extra={"session_id": session_id, "tenant_alias": tenant_alias, "error": str(exc)},
        )
        raise HTTPException(status_code=502, detail="web_cta_click_register_failed") from exc

    return Response(status_code=204)


@router.get(
    "/web/cta-events",
    summary="Listado agregado de eventos CTA web (A/B/C).",
)
async def list_web_cta_events(
    *,
    repo: CRMRepository = Depends(get_repository),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    date_from: Annotated[str | None, Query(description="YYYY-MM-DD")] = None,
    date_to: Annotated[str | None, Query(description="YYYY-MM-DD")] = None,
    event_type: Annotated[str | None, Query(description="Tipo de evento")] = "whatsapp_cta_click",
    limit: Annotated[int, Query(ge=1, le=10000)] = 5000,
) -> dict[str, Any]:
    def normalize_date(value: str | None) -> date | None:
        if not value:
            return None
        try:
            return date.fromisoformat(value)
        except ValueError:
            raise HTTPException(status_code=400, detail="invalid_date_format") from None

    start = normalize_date(date_from)
    end = normalize_date(date_to)
    end_exclusive: str | None = None
    if end:
        end_exclusive = (end + timedelta(days=1)).isoformat()

    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    try:
        report_tz = ZoneInfo(effective_timezone)
    except Exception:
        report_tz = ZoneInfo("UTC")

    try:
        rows = await repo.list_web_session_events(
            usuario_token=user_token,
            event_type=event_type,
            date_from=start.isoformat() if start else None,
            date_to=end_exclusive,
            limit=limit,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    by_variant: dict[str, int] = {}
    by_cta: dict[str, int] = {}
    by_variant_cta: dict[tuple[str, str], int] = {}
    by_day_variant: dict[tuple[str, str], int] = {}
    by_hour: dict[int, int] = {}
    by_hour_variant: dict[tuple[int, str], int] = {}
    by_weekday: dict[int, int] = {}
    by_weekday_variant: dict[tuple[int, str], int] = {}
    by_path: dict[str, int] = {}
    by_path_variant: dict[tuple[str, str], int] = {}
    by_path_cta: dict[tuple[str, str], int] = {}
    by_ab_query: dict[str, int] = {}
    events: list[dict[str, Any]] = []

    def normalize_path_and_ab(location_href: Any) -> tuple[str, str]:
        raw = (str(location_href or "")).strip()
        if not raw:
            return ("UNKNOWN", "UNKNOWN")
        parsed = urlparse(raw)
        if not parsed.path and not parsed.netloc:
            parsed = urlparse(raw if raw.startswith("/") else f"/{raw}")
        path = (parsed.path or "/").strip() or "/"
        if len(path) > 1 and path.endswith("/"):
            path = path.rstrip("/")
        query_values = parse_qs(parsed.query or "", keep_blank_values=False)
        ab_value = (query_values.get("ab") or ["UNKNOWN"])[0]
        ab = str(ab_value or "UNKNOWN").strip().upper() or "UNKNOWN"
        return (path, ab)

    for row in rows:
        variant = str(row.get("hero_variant") or "unknown").upper()
        cta_id = str(row.get("cta_id") or "unknown")
        location_href = row.get("location_href")
        path, ab_query = normalize_path_and_ab(location_href)
        created_at = row.get("creado_en")
        day_key = None
        hour_key = None
        weekday_key = None
        created_dt = _parse_datetime(created_at)
        if created_dt:
            local_dt = created_dt.astimezone(report_tz)
            day_key = local_dt.date().isoformat()
            hour_key = local_dt.hour
            weekday_key = local_dt.weekday()
        elif isinstance(created_at, str) and len(created_at) >= 10:
            day_key = created_at[:10]

        by_variant[variant] = by_variant.get(variant, 0) + 1
        by_cta[cta_id] = by_cta.get(cta_id, 0) + 1
        by_variant_cta[(variant, cta_id)] = by_variant_cta.get((variant, cta_id), 0) + 1
        if day_key:
            by_day_variant[(day_key, variant)] = by_day_variant.get((day_key, variant), 0) + 1
        if hour_key is not None:
            by_hour[hour_key] = by_hour.get(hour_key, 0) + 1
            by_hour_variant[(hour_key, variant)] = by_hour_variant.get((hour_key, variant), 0) + 1
        if weekday_key is not None:
            by_weekday[weekday_key] = by_weekday.get(weekday_key, 0) + 1
            by_weekday_variant[(weekday_key, variant)] = by_weekday_variant.get((weekday_key, variant), 0) + 1
        by_path[path] = by_path.get(path, 0) + 1
        by_path_variant[(path, variant)] = by_path_variant.get((path, variant), 0) + 1
        by_path_cta[(path, cta_id)] = by_path_cta.get((path, cta_id), 0) + 1
        by_ab_query[ab_query] = by_ab_query.get(ab_query, 0) + 1

        events.append(
            {
                "created_at": created_dt.isoformat() if created_dt else str(created_at) if created_at else None,
                "created_at_local": local_dt.isoformat() if created_dt else None,
                "variant": variant,
                "ab_query": ab_query,
                "cta_id": cta_id,
                "location_href": location_href,
                "path": path,
                "referrer": row.get("referrer"),
            }
        )

    total = sum(by_variant.values()) if by_variant else 0
    by_variant_items = [
        {
            "variant": variant,
            "clicks": clicks,
            "share_pct": round((clicks / total) * 100, 2) if total else 0,
        }
        for variant, clicks in sorted(by_variant.items(), key=lambda item: item[0])
    ]
    by_cta_items = [
        {"cta_id": cta_id, "clicks": clicks}
        for cta_id, clicks in sorted(by_cta.items(), key=lambda item: item[1], reverse=True)
    ]
    by_variant_cta_items = [
        {"variant": variant, "cta_id": cta_id, "clicks": clicks}
        for (variant, cta_id), clicks in sorted(by_variant_cta.items(), key=lambda item: item[1], reverse=True)
    ]
    by_day_items = [
        {"date": day, "variant": variant, "clicks": clicks}
        for (day, variant), clicks in sorted(by_day_variant.items(), key=lambda item: (item[0][0], item[0][1]))
    ]
    by_hour_items = [
        {"hour": hour, "variant": variant, "clicks": clicks}
        for (hour, variant), clicks in sorted(by_hour_variant.items(), key=lambda item: (item[0][0], item[0][1]))
    ]
    by_weekday_items = [
        {"weekday": weekday, "variant": variant, "clicks": clicks}
        for (weekday, variant), clicks in sorted(by_weekday_variant.items(), key=lambda item: (item[0][0], item[0][1]))
    ]
    by_path_items = [
        {
            "path": path,
            "clicks": clicks,
            "share_pct": round((clicks / total) * 100, 2) if total else 0,
        }
        for path, clicks in sorted(by_path.items(), key=lambda item: item[1], reverse=True)
    ]
    by_path_variant_items = [
        {"path": path, "variant": variant, "clicks": clicks}
        for (path, variant), clicks in sorted(by_path_variant.items(), key=lambda item: item[1], reverse=True)
    ]
    by_path_cta_items = [
        {"path": path, "cta_id": cta_id, "clicks": clicks}
        for (path, cta_id), clicks in sorted(by_path_cta.items(), key=lambda item: item[1], reverse=True)
    ]
    by_ab_query_items = [
        {
            "ab_query": ab_query,
            "clicks": clicks,
            "share_pct": round((clicks / total) * 100, 2) if total else 0,
        }
        for ab_query, clicks in sorted(by_ab_query.items(), key=lambda item: item[1], reverse=True)
    ]

    return {
        "ok": True,
        "total": total,
        "by_variant": by_variant_items,
        "by_cta": by_cta_items,
        "by_variant_cta": by_variant_cta_items,
        "by_day": by_day_items,
        "by_hour": by_hour_items,
        "by_weekday": by_weekday_items,
        "by_path": by_path_items,
        "by_path_variant": by_path_variant_items,
        "by_path_cta": by_path_cta_items,
        "by_ab_query": by_ab_query_items,
        "events": events,
        "timezone": effective_timezone,
    }


@router.post(
    "/web/booking/prefill",
    summary="Obtiene datos sugeridos para precargar agenda pública",
)
async def public_web_booking_prefill(
    payload: PublicWebBookingPrefillPayload,
    request: Request,
) -> dict[str, Any]:
    metadata = dict(payload.metadata or {})
    organizacion_id = await _resolve_public_booking_organizacion_id(
        tenant_alias=payload.tenant_alias,
        explicit_organizacion_id=payload.organizacion_id,
        metadata=metadata,
        request=request,
    )

    prefill = await _resolve_booking_prefill_data(
        organizacion_id=organizacion_id,
        envio_id=payload.eid,
    )

    return {
        "ok": True,
        "prefill": prefill,
    }


async def _resolve_booking_prefill_data(
    *,
    organizacion_id: str,
    envio_id: UUID | None,
) -> dict[str, str | None]:
    empty = {"email": None, "company": None}
    if envio_id is None:
        return empty
    repo = CRMRepository()
    try:
        envio_row = await repo.worker_get_envio_by_id(envio_id=envio_id)
    except CRMRepositoryError as exc:
        logger.exception(
            "crm.web.booking.prefill_lookup_failed",
            extra={"eid": str(envio_id), "error": str(exc)},
        )
        return empty

    if not isinstance(envio_row, dict):
        return empty

    envio_org = _clean_text(envio_row.get("organizacion_id"))
    if not envio_org or envio_org != organizacion_id:
        return empty

    detalle = envio_row.get("detalle")
    if isinstance(detalle, str):
        try:
            detalle = json.loads(detalle)
        except json.JSONDecodeError:
            detalle = {}
    if not isinstance(detalle, dict):
        return empty

    suggested_email = _normalize_email(detalle.get("email") or detalle.get("correo") or detalle.get("mail"))
    suggested_company = _clean_text(
        detalle.get("company_name")
        or detalle.get("empresa")
        or detalle.get("company")
        or detalle.get("razon_social")
        or detalle.get("nombre_empresa")
        or detalle.get("display_name")
        or detalle.get("nombre")
        or detalle.get("full_name")
    )
    return {"email": suggested_email, "company": suggested_company}


@router.post(
    "/web/booking/availability",
    summary="Consulta disponibilidad pública para agenda y registra apertura",
)
async def public_web_booking_availability(
    payload: PublicWebBookingAvailabilityPayload,
    request: Request,
) -> dict[str, Any]:
    metadata = dict(payload.metadata or {})
    organizacion_id = await _resolve_public_booking_organizacion_id(
        tenant_alias=payload.tenant_alias,
        explicit_organizacion_id=payload.organizacion_id,
        metadata=metadata,
        request=request,
    )
    organizacion_uuid = UUID(organizacion_id)

    calendar_settings = await tenant_runtime.get_calendar_runtime_settings(
        organizacion_id=organizacion_uuid
    )
    resource_id = (calendar_settings.resource_id or "").strip()
    if not resource_id:
        raise HTTPException(status_code=400, detail="calendar_resource_missing")

    timezone_hint = (
        (payload.timezone or "").strip()
        or (calendar_settings.timezone or "").strip()
        or settings.webchat_calendar_timezone
        or "America/Mexico_City"
    )
    start_day = payload.start_date or datetime.now(timezone.utc).date()
    max_days = max(1, min(int(payload.window_days or 14), 60))
    end_day = start_day + timedelta(days=max_days)

    try:
        availability = await calendar_service.list_slots(
            resource_id=resource_id,
            start_date=start_day,
            end_date=end_day,
            timezone_hint=timezone_hint,
            max_days=max_days,
            fallback_hold_minutes=calendar_settings.hold_minutes,
        )
    except CalendarError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    referrer = (payload.referrer or "").strip() or None
    landing_url = (payload.landing_url or "").strip() or None
    metadata.setdefault("tenant_alias", (payload.tenant_alias or "").strip().lower() or None)
    metadata.setdefault("request_path", request.url.path)
    metadata.setdefault("request_headers", {"accept_language": request.headers.get("accept-language")})

    repo = CRMRepository()
    try:
        await repo.upsert_web_booking_session(
            booking_session_id=(payload.booking_session_id or "").strip(),
            payload={
                "organizacion_id": organizacion_id,
                "persona_id": str(payload.contacto_id) if payload.contacto_id else None,
                "contacto_id": str(payload.contacto_id) if payload.contacto_id else None,
                "campana_id": str(payload.cid) if payload.cid else None,
                "template_id": str(payload.tid) if payload.tid else None,
                "envio_id": str(payload.eid) if payload.eid else None,
                "source": (payload.source or "").strip().lower() or "public_demo",
                "landing_url": landing_url,
                "referrer": referrer,
                "ip": _request_ip(request),
                "user_agent": (payload.user_agent or request.headers.get("user-agent") or "").strip() or None,
                "accept_language": (request.headers.get("accept-language") or "").strip() or None,
                "country_code": payload.country_code,
                "country_name": payload.country_name,
                "cve_ent": payload.cve_ent,
                "nom_ent": payload.nom_ent,
                "cve_mun": payload.cve_mun,
                "nom_mun": payload.nom_mun,
                "cvegeo": payload.cvegeo,
                "utm_source": payload.utm_source,
                "utm_medium": payload.utm_medium,
                "utm_campaign": payload.utm_campaign,
                "utm_term": payload.utm_term,
                "utm_content": payload.utm_content,
                "opened_at": datetime.now(timezone.utc).isoformat(),
                "metadata": metadata,
            },
        )
    except CRMRepositoryError as exc:
        logger.exception(
            "crm.web.booking.availability_session_upsert_failed",
            extra={"booking_session_id": payload.booking_session_id, "error": str(exc)},
        )

    prefill = await _resolve_booking_prefill_data(
        organizacion_id=organizacion_id,
        envio_id=payload.eid,
    )

    return {
        "ok": True,
        "availability": availability,
        "prefill": prefill,
        "context": {
            "organizacion_id": organizacion_id,
            "resource_id": resource_id,
            "timezone": timezone_hint,
        },
    }


@router.post(
    "/web/booking/book",
    summary="Confirma una cita pública en agenda",
)
async def public_web_booking_create(
    payload: PublicWebBookingCreatePayload,
    request: Request,
) -> dict[str, Any]:
    metadata = dict(payload.metadata or {})
    organizacion_id = await _resolve_public_booking_organizacion_id(
        tenant_alias=payload.tenant_alias,
        explicit_organizacion_id=payload.organizacion_id,
        metadata=metadata,
        request=request,
    )
    organizacion_uuid = UUID(organizacion_id)
    start_at = _parse_datetime_input(payload.start_at, field="start_at")

    calendar_settings = await tenant_runtime.get_calendar_runtime_settings(
        organizacion_id=organizacion_uuid
    )
    resource_id = (calendar_settings.resource_id or "").strip()
    if not resource_id:
        raise HTTPException(status_code=400, detail="calendar_resource_missing")

    repo = CRMRepository()
    contact_uuid = payload.contacto_id
    persona_data: dict[str, Any] | None = None
    if contact_uuid:
        existing_contact = await repo.get_persona_by_id(persona_id=str(contact_uuid))
        if not existing_contact:
            raise HTTPException(status_code=404, detail="contacto_not_found")
        contact_org = _safe_uuid(existing_contact.get("organizacion_id"))
        if contact_org and contact_org != organizacion_uuid:
            raise HTTPException(status_code=400, detail="contacto_org_mismatch")
        persona_data = existing_contact
    else:
        attendee_name = (payload.attendee_name or "").strip()
        attendee_email = (payload.attendee_email or "").strip() or None
        attendee_phone = (payload.attendee_phone or "").strip() or None
        attendee_company = (payload.attendee_company or "").strip() or None
        if not attendee_name and not attendee_email and not attendee_phone:
            raise HTTPException(status_code=400, detail="attendee_identity_required")
        persona_row = await repo.create_persona(
            organizacion_id=organizacion_uuid,
            payload={
                "nombre_completo": attendee_name or "Lead agenda web",
                "correo": attendee_email,
                "telefono_e164": attendee_phone,
                "company_name": attendee_company,
                "origen": "agenda_publica",
                "estado": "lead",
                    "persona_datos": {
                        "booking_session_id": payload.booking_session_id,
                        "source": payload.source or "public_demo",
                    "utm_source": payload.utm_source,
                    "utm_medium": payload.utm_medium,
                    "utm_campaign": payload.utm_campaign,
                    "cid": str(payload.cid) if payload.cid else None,
                    "tid": str(payload.tid) if payload.tid else None,
                    "eid": str(payload.eid) if payload.eid else None,
                },
            },
        )
        contact_uuid = _safe_uuid(str(persona_row.get("id")))
        if not contact_uuid:
            raise HTTPException(status_code=502, detail="contact_create_failed")
        persona_data = persona_row

    try:
        stage_payload = await repo.get_stage_by_code(
            organizacion_id=organizacion_uuid,
            codigo="demo",
        )
        if stage_payload and stage_payload.get("id"):
            stage_id = _safe_uuid(stage_payload.get("id"))
        else:
            stage_id = await repo.get_default_stage_id(organizacion_id=organizacion_uuid)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=f"opportunity_stage_lookup_failed:{exc}") from exc
    if stage_id is None:
        raise HTTPException(status_code=502, detail="demo_stage_missing")

    display_name = (
        _clean_text((persona_data or {}).get("nombre_completo"))
        or _clean_text((persona_data or {}).get("company_name"))
        or _clean_text((persona_data or {}).get("correo"))
        or _clean_text((persona_data or {}).get("telefono_e164"))
        or "Cliente"
    )
    opportunity_title = f"Cita agendada por cliente - {display_name}"
    opportunity_metadata: dict[str, Any] = {
        "source": (payload.source or "").strip().lower() or "public_demo",
        "booking_session_id": payload.booking_session_id,
        "utm_source": payload.utm_source,
        "utm_medium": payload.utm_medium,
        "utm_campaign": payload.utm_campaign,
        "cid": str(payload.cid) if payload.cid else None,
        "tid": str(payload.tid) if payload.tid else None,
        "eid": str(payload.eid) if payload.eid else None,
        "prefill_origin": "public_demo",
    }
    opportunity_metadata = {k: v for k, v in opportunity_metadata.items() if v is not None}
    try:
        opportunity_row = await repo.create_opportunity(
            organizacion_id=organizacion_uuid,
            payload={
                "contacto_principal_id": str(contact_uuid),
                "etapa_id": str(stage_id),
                "titulo": opportunity_title,
                "descripcion": "Cita agendada desde página pública.",
                "moneda": "MXN",
                "estado": "abierta",
                "metadata": opportunity_metadata,
            },
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=f"opportunity_create_failed:{exc}") from exc
    opportunity_uuid = _safe_uuid(opportunity_row.get("id"))
    if opportunity_uuid is None:
        raise HTTPException(status_code=502, detail="opportunity_create_failed")
    try:
        await repo.append_stage_history(
            organizacion_id=organizacion_uuid,
            payload={
                "oportunidad_id": str(opportunity_uuid),
                "etapa_destino_id": str(stage_id),
                "fuente": "public_demo_booking",
            },
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "crm.web.booking.stage_history_failed",
            extra={"opportunity_id": str(opportunity_uuid), "error": str(exc)},
        )

    booking_context_id = str(uuid4())
    zoom_meeting_url, zoom_external_join_url, zoom_metadata = (
        await webchat_service.create_zoom_meeting_for_booking_if_enabled(
            organizacion_id=organizacion_uuid,
            start_at=start_at,
            timezone_name=calendar_settings.timezone,
            topic=f"Demo Tal-IA - {display_name}",
            agenda=payload.notes,
        )
    )

    try:
        hold_metadata: dict[str, Any] = {
            "source": (payload.source or "").strip().lower() or "public_demo",
            "booking_session_id": payload.booking_session_id,
            "tenant_alias": (payload.tenant_alias or "").strip().lower() or None,
            "organizacion_id": organizacion_id,
            "cid": str(payload.cid) if payload.cid else None,
            "tid": str(payload.tid) if payload.tid else None,
            "eid": str(payload.eid) if payload.eid else None,
        }
        if zoom_metadata:
            hold_metadata.update(zoom_metadata)
        hold = await calendar_service.hold_slot(
            resource_id=resource_id,
            slot_start=start_at,
            conversation_id=booking_context_id,
            contact_id=str(contact_uuid),
            tarjeta_id=str(opportunity_uuid),
            hold_minutes=max(1, int(calendar_settings.hold_minutes or 10)),
            metadata=hold_metadata,
        )
        booking_metadata: dict[str, Any] = {
            "source": (payload.source or "").strip().lower() or "public_demo",
            "booking_session_id": payload.booking_session_id,
            "organizacion_id": organizacion_id,
            "conversation_id": booking_context_id,
            "contact_id": str(contact_uuid),
            "tarjeta_id": str(opportunity_uuid),
            "cid": str(payload.cid) if payload.cid else None,
            "tid": str(payload.tid) if payload.tid else None,
            "eid": str(payload.eid) if payload.eid else None,
        }
        if zoom_metadata:
            booking_metadata.update(zoom_metadata)
        booking = await calendar_service.confirm_slot(
            hold_id=str(hold.get("hold_id")),
            notes=(payload.notes or "").strip() or None,
            metadata=booking_metadata,
            meeting_url=zoom_meeting_url,
            external_join_url=zoom_external_join_url,
        )
    except CalendarError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    try:
        await repo.upsert_web_booking_session(
            booking_session_id=(payload.booking_session_id or "").strip(),
            payload={
                "organizacion_id": organizacion_id,
                "persona_id": str(contact_uuid),
                "contacto_id": str(contact_uuid),
                "campana_id": str(payload.cid) if payload.cid else None,
                "template_id": str(payload.tid) if payload.tid else None,
                "envio_id": str(payload.eid) if payload.eid else None,
                "calendar_booking_id": booking.get("booking_id"),
                "source": (payload.source or "").strip().lower() or "public_demo",
                "landing_url": (payload.landing_url or "").strip() or None,
                "referrer": (payload.referrer or "").strip() or None,
                "ip": _request_ip(request),
                "user_agent": (payload.user_agent or request.headers.get("user-agent") or "").strip() or None,
                "accept_language": (request.headers.get("accept-language") or "").strip() or None,
                "country_code": payload.country_code,
                "country_name": payload.country_name,
                "cve_ent": payload.cve_ent,
                "nom_ent": payload.nom_ent,
                "cve_mun": payload.cve_mun,
                "nom_mun": payload.nom_mun,
                "cvegeo": payload.cvegeo,
                "utm_source": payload.utm_source,
                "utm_medium": payload.utm_medium,
                "utm_campaign": payload.utm_campaign,
                "utm_term": payload.utm_term,
                "utm_content": payload.utm_content,
                "booked_at": datetime.now(timezone.utc).isoformat(),
                "metadata": metadata,
            },
        )
    except CRMRepositoryError as exc:
        logger.exception(
            "crm.web.booking.book_session_upsert_failed",
            extra={"booking_session_id": payload.booking_session_id, "error": str(exc)},
        )

    try:
        booking_response = webchat_service._build_booking_response(booking)
        await webchat_service._sync_booking_with_opportunity(
            booking=booking_response,
            tarjeta_id=str(opportunity_uuid),
            persona=contact_data,
            channel="web",
        )
        await webchat_service._send_booking_confirmation_email(
            booking=booking_response,
            persona_id=str(contact_uuid),
            conversation_id=booking_context_id,
            tarjeta_id=str(opportunity_uuid),
        )
        if isinstance(booking_response.metadata, dict):
            booking["metadata"] = booking_response.metadata
    except Exception as exc:  # pragma: no cover - defensivo
        logger.exception(
            "crm.web.booking.confirmation_email_failed",
            extra={
                "booking_id": booking.get("booking_id"),
                "booking_session_id": payload.booking_session_id,
                "contacto_id": str(contact_uuid),
                "conversation_id": booking_context_id,
                "error": str(exc),
            },
        )

    return {
        "ok": True,
        "booking": booking,
        "contacto_id": str(contact_uuid),
        "opportunity_id": str(opportunity_uuid),
        "conversation_id": None,
    }


@router.get("/dashboard/kpis")
async def dashboard_kpis(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("ver_panel")),
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    rango: str | None = Query(default=None),
    desde: str | None = Query(default=None),
    hasta: str | None = Query(default=None),
) -> dict[str, Any]:
    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    date_from, date_to = _resolve_date_range(
        rango,
        desde,
        hasta,
        timezone_name=effective_timezone,
    )
    try:
        payload = await repo.visitas_dashboard_kpis(
            usuario_token=user_token,
            organizacion_id=organizacion_id,
            date_from=date_from,
            date_to=date_to,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {
        "ok": True,
        "kpis": payload,
        "range": {
            "preset": (rango or "").strip().lower() or None,
            "from": _format_utc(date_from) if date_from else None,
            "to": _format_utc(date_to) if date_to else None,
        },
    }


