@router.post("/propiedades")
async def crear_propiedad(
    *,
    payload: PropiedadUnidadCreateRequest,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    _: str = Depends(require_permission("settings.manage")),
) -> dict[str, Any]:
    body, _ = _build_propiedad_unidad_payload(payload)

    try:
        record = await repo.create_propiedad_unidad(organizacion_id=organizacion_id, payload=body)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    nivel_uuid = _safe_uuid(record.get("nivel_id"))
    capa_record: dict[str, Any] | None = None
    if nivel_uuid:
        capa_record = await repo.get_propiedad_capa(
            organizacion_id=organizacion_id,
            capa_id=nivel_uuid,
        )
    desarrollo_uuid = _safe_uuid(record.get("desarrollo_id")) or (
        capa_record and _safe_uuid(capa_record.get("desarrollo_id"))
    ) or _safe_uuid(payload.desarrollo_id)
    desarrollo_record: dict[str, Any] | None = None
    if desarrollo_uuid:
        desarrollo_record = await repo.get_propiedad_desarrollo(
            organizacion_id=organizacion_id,
            desarrollo_id=desarrollo_uuid,
        )
    desarrollo_record = desarrollo_record or {"id": str(desarrollo_uuid) if desarrollo_uuid else None}
    unidad_source = ImportUnidad(
        unidad=payload.unidad,
        nombre=payload.nombre,
        tipo_id=payload.tipo_id,
        status=payload.status,
        destino_inventario=payload.destino_inventario,
        precio_tipo=payload.precio_tipo,
        descripcion=payload.descripcion,
        precio=payload.precio,
        precio_m2=payload.precio_m2,
        area_m2=payload.area_m2,
        oportunidad_id=payload.oportunidad_id,
        linea_id=payload.linea_id,
        familia_id=payload.familia_id,
        modelo_id=payload.modelo_id,
        metadata=body["metadata"],
    )
    linea_uuid = payload.linea_id
    familia_uuid = payload.familia_id
    modelo_uuid = payload.modelo_id

    try:
        await _ensure_catalog_item_for_unidad(
            repo=repo,
            organizacion_id=organizacion_id,
            desarrollo_record=desarrollo_record,
            unidad_record=record,
            unidad_source=unidad_source,
            linea_id=linea_uuid,
            familia_id=familia_uuid,
            modelo_id=modelo_uuid,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return {"ok": True, "unidad": record}


@router.patch("/propiedad-unidades/{unidad_id}")
async def editar_propiedad_unidad(
    *,
    unidad_id: UUID,
    payload: PropiedadUnidadCreateRequest,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    _: str = Depends(require_permission("settings.manage")),
) -> dict[str, Any]:
    current_unidad = await repo.get_propiedad_unidad(unidad_id=unidad_id)
    body, computed = _build_propiedad_unidad_payload(payload, current_row=current_unidad)

    try:
        record = await repo.update_propiedad_unidad(
            organizacion_id=organizacion_id,
            unidad_id=unidad_id,
            payload=body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    nivel_uuid = _safe_uuid(record.get("nivel_id"))
    capa_record: dict[str, Any] | None = None
    if nivel_uuid:
        capa_record = await repo.get_propiedad_capa(
            organizacion_id=organizacion_id,
            capa_id=nivel_uuid,
        )
    desarrollo_uuid = _safe_uuid(record.get("desarrollo_id")) or (
        capa_record and _safe_uuid(capa_record.get("desarrollo_id"))
    ) or _safe_uuid(payload.desarrollo_id)
    desarrollo_record: dict[str, Any] | None = None
    if desarrollo_uuid:
        desarrollo_record = await repo.get_propiedad_desarrollo(
            organizacion_id=organizacion_id,
            desarrollo_id=desarrollo_uuid,
        )
    desarrollo_record = desarrollo_record or {"id": str(desarrollo_uuid) if desarrollo_uuid else None}
    unidad_source = ImportUnidad(
        unidad=payload.unidad,
        nombre=payload.nombre,
        tipo_id=payload.tipo_id,
        status=payload.status,
        destino_inventario=payload.destino_inventario,
        precio_tipo=payload.precio_tipo,
        descripcion=payload.descripcion,
        precio=computed["precio"],
        precio_m2=payload.precio_m2,
        area_m2=payload.area_m2,
        oportunidad_id=payload.oportunidad_id,
        linea_id=payload.linea_id,
        familia_id=payload.familia_id,
        modelo_id=payload.modelo_id,
        metadata=body["metadata"],
    )
    try:
        await _ensure_catalog_item_for_unidad(
            repo=repo,
            organizacion_id=organizacion_id,
            desarrollo_record=desarrollo_record,
            unidad_record=record,
            unidad_source=unidad_source,
            linea_id=payload.linea_id,
            familia_id=payload.familia_id,
            modelo_id=payload.modelo_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {"ok": True, "unidad": record}


@router.patch("/propiedad-unidades/{unidad_id}/status")
async def actualizar_status_propiedad_unidad(
    *,
    unidad_id: UUID,
    payload: PropiedadUnidadStatusUpdateRequest,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    _: str = Depends(require_permission("settings.manage")),
) -> dict[str, Any]:
    current_unidad = await repo.get_propiedad_unidad(unidad_id=unidad_id)
    current_destination = str(current_unidad.get("destino_inventario") or PropiedadDestinoInventario.comercial.value).strip().lower() if current_unidad else PropiedadDestinoInventario.comercial.value
    if current_destination == PropiedadDestinoInventario.patrimonial.value and payload.status.value != PropiedadStatus.bloqueado.value:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="patrimonial_property_must_remain_blocked",
        )
    previous_status = str(current_unidad.get("status") or PropiedadStatus.disponible.value) if current_unidad else PropiedadStatus.disponible.value
    resolved_oportunidad_id = payload.oportunidad_id or (
        _safe_uuid(current_unidad.get("oportunidad_id")) if current_unidad else None
    )
    resolved_persona_id = _safe_uuid(current_unidad.get("persona_id")) if current_unidad else None
    resolved_cuenta_id = _safe_uuid(current_unidad.get("cuenta_id")) if current_unidad else None
    if resolved_oportunidad_id:
        try:
            opportunity = await repo.get_pipeline_opportunity(
                organizacion_id=organizacion_id,
                oportunidad_id=resolved_oportunidad_id,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not opportunity:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail="opportunity_not_found",
            )
        if opportunity:
            if resolved_persona_id is None:
                resolved_persona_id = _safe_uuid(opportunity.get("contacto_principal_id"))
            if resolved_cuenta_id is None:
                resolved_cuenta_id = _safe_uuid(opportunity.get("cuenta_id"))
    if payload.status.value in SALE_TRACKED_PROPERTY_STATUSES and not resolved_oportunidad_id:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="opportunity_required_for_commercial_status",
        )
    update_payload: dict[str, Any] = {
        "status": payload.status.value,
    }
    if resolved_oportunidad_id:
        update_payload["oportunidad_id"] = str(resolved_oportunidad_id)
    try:
        record = await repo.update_propiedad_unidad(
            organizacion_id=organizacion_id,
            unidad_id=unidad_id,
            payload=update_payload,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    event_payload = {
        "organizacion_id": str(organizacion_id),
        "unidad_id": str(unidad_id),
        "status": payload.status.value,
        "usuario_id": str(usuario_id) if usuario_id else None,
        "source": "mapbox",
    }
    sale_logger.info("propiedad_unidad_status_manual", extra=event_payload)
    _write_propiedad_sale_event("unidad_status_manual", event_payload)
    if previous_status != payload.status.value:
        try:
            await repo.create_propiedad_unidad_movimiento(
                organizacion_id=organizacion_id,
                payload={
                    "organizacion_id": str(organizacion_id),
                    "unidad_id": str(unidad_id),
                    "oportunidad_id": str(resolved_oportunidad_id) if resolved_oportunidad_id else None,
                    "persona_id": str(resolved_persona_id) if resolved_persona_id else None,
                    "cuenta_id": str(resolved_cuenta_id) if resolved_cuenta_id else None,
                    "estado_anterior": previous_status,
                    "estado_nuevo": payload.status.value,
                    "precio": current_unidad.get("precio") if current_unidad else None,
                    "moneda": "MXN",
                    "motivo": "manual_status_update",
                    "metadata": {
                        "source": "mapbox",
                        "usuario_id": str(usuario_id) if usuario_id else None,
                    },
                    "creado_por": str(usuario_id) if usuario_id else None,
                }
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {"ok": True, "unidad": record}


@router.delete("/propiedad-unidades/{unidad_id}")
async def eliminar_propiedad_unidad(
    *,
    unidad_id: UUID,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    _: str = Depends(require_permission("settings.manage")),
) -> dict[str, Any]:
    # La tabla de unidades no contiene organizacion_id; el tenant se hereda
    # del desarrollo/capa. Validarlo antes del DELETE evita que un UUID válido
    # de otra organización pueda eliminarse usando el service role.
    current_unidad = await repo.get_propiedad_unidad(unidad_id=unidad_id)
    if not current_unidad:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="property_unit_not_found")
    desarrollo_uuid = _safe_uuid(current_unidad.get("desarrollo_id"))
    if desarrollo_uuid is None:
        nivel_uuid = _safe_uuid(current_unidad.get("nivel_id"))
        if nivel_uuid:
            capa = await repo.get_propiedad_capa(
                organizacion_id=organizacion_id,
                capa_id=nivel_uuid,
            )
            desarrollo_uuid = _safe_uuid(capa.get("desarrollo_id")) if capa else None
    if desarrollo_uuid is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="property_unit_not_found")
    desarrollo = await repo.get_propiedad_desarrollo(
        organizacion_id=organizacion_id,
        desarrollo_id=desarrollo_uuid,
    )
    if not desarrollo:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="property_unit_not_found")
    try:
        record = await repo.delete_propiedad_unidad(
            organizacion_id=organizacion_id,
            unidad_id=unidad_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {"ok": True, "unidad": record}


@router.post(
    "/ventas/propiedades",
    response_model=CRMQuote,
    status_code=status.HTTP_201_CREATED,
)
async def registrar_venta_propiedad(
    *,
    payload: CRMPropertySaleRequest,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    _: str = Depends(require_permission("settings.manage")),
) -> CRMQuote:
    catalog_item = await repo.get_catalog_item(
        organizacion_id=organizacion_id, item_id=payload.catalog_item_id
    )
    if not catalog_item:
        raise HTTPException(status_code=404, detail="catalog_item_not_found")
    current_unidad = await repo.get_propiedad_unidad(unidad_id=payload.unidad_id)
    current_destination = str(current_unidad.get("destino_inventario") or PropiedadDestinoInventario.comercial.value).strip().lower() if current_unidad else PropiedadDestinoInventario.comercial.value
    current_status = str(current_unidad.get("status") or PropiedadStatus.disponible.value).strip().lower() if current_unidad else PropiedadStatus.disponible.value
    if current_destination == PropiedadDestinoInventario.patrimonial.value:
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="sale_requires_commercial_inventory")
    if current_status == PropiedadStatus.bloqueado.value:
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="property_blocked_for_sale")
    if current_status == PropiedadStatus.vendido.value:
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="property_already_sold")
    opportunity: dict[str, Any] | None = None
    resolved_oportunidad_id = payload.oportunidad_id
    resolved_persona_id = payload.persona_id or payload.contacto_id
    resolved_cuenta_id = payload.cuenta_id
    if payload.lead_id:
        lead = await repo.get_lead_by_id(
            organizacion_id=organizacion_id,
            lead_id=payload.lead_id,
        )
        if lead:
            if resolved_oportunidad_id is None:
                resolved_oportunidad_id = _safe_uuid(lead.get("oportunidad_id"))
            if resolved_persona_id is None:
                resolved_persona_id = _safe_uuid(lead.get("persona_id") or lead.get("contacto_id"))
            if resolved_cuenta_id is None:
                resolved_cuenta_id = _safe_uuid(lead.get("cuenta_id"))
    if resolved_oportunidad_id:
        opportunity = await _ensure_opportunity_ready_for_sale(
            repo,
            organizacion_id,
            resolved_oportunidad_id,
            usuario_id,
        )
        if resolved_persona_id is None:
            resolved_persona_id = _safe_uuid(opportunity.get("contacto_principal_id"))
        if resolved_cuenta_id is None:
            resolved_cuenta_id = _safe_uuid(opportunity.get("cuenta_id"))
    else:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="sale_requires_opportunity",
        )
    price_value = _decimal_to_number(payload.precio_final)
    sale_refs = {
        "propiedad_id": str(payload.propiedad_id),
        "unidad_id": str(payload.unidad_id),
        "catalog_item_id": str(payload.catalog_item_id),
        "precio_final": price_value,
    }
    if resolved_oportunidad_id:
        sale_refs["oportunidad_id"] = str(resolved_oportunidad_id)
    if resolved_persona_id:
        sale_refs["persona_id"] = str(resolved_persona_id)
    if resolved_cuenta_id:
        sale_refs["cuenta_id"] = str(resolved_cuenta_id)
    if payload.lead_id:
        sale_refs["lead_id"] = str(payload.lead_id)
    quote_metadata = _normalize_metadata_value(payload.cotizacion_metadata) or {}
    quote_metadata = {**quote_metadata, **sale_refs}
    item_metadata = _normalize_metadata_value(payload.item_metadata) or {}
    item_metadata = {**item_metadata, **sale_refs}

    quote_payload: dict[str, Any] = {
        "estatus": "aceptada",
        "total": price_value,
        "moneda": payload.moneda,
        "metadata": quote_metadata,
    }
    if resolved_oportunidad_id:
        quote_payload["oportunidad_id"] = str(resolved_oportunidad_id)
    if resolved_cuenta_id:
        quote_payload["cuenta_id"] = str(resolved_cuenta_id)
    if resolved_persona_id:
        quote_payload["persona_id"] = str(resolved_persona_id)
    elif payload.contacto_id:
        quote_payload["contacto_id"] = str(payload.contacto_id)

    try:
        sale_logger.info(
            "propiedad_sale_started",
            extra={
                "organizacion_id": str(organizacion_id),
                "catalog_item_id": str(payload.catalog_item_id),
                "propiedad_id": str(payload.propiedad_id),
                "unidad_id": str(payload.unidad_id),
                "oportunidad_id": str(resolved_oportunidad_id) if resolved_oportunidad_id else None,
                "lead_id": str(payload.lead_id) if payload.lead_id else None,
                "persona_id": str(resolved_persona_id) if resolved_persona_id else None,
                "precio_final": price_value,
                "moneda": payload.moneda,
            },
        )
        _write_propiedad_sale_event(
            "sale_started",
            {
                "organizacion_id": str(organizacion_id),
                "catalog_item_id": str(payload.catalog_item_id),
                "propiedad_id": str(payload.propiedad_id),
                "unidad_id": str(payload.unidad_id),
                "oportunidad_id": str(resolved_oportunidad_id) if resolved_oportunidad_id else None,
                "lead_id": str(payload.lead_id) if payload.lead_id else None,
                "persona_id": str(resolved_persona_id) if resolved_persona_id else None,
                "precio_final": price_value,
                "moneda": payload.moneda,
            },
        )
        quote = await repo.create_quote(
            organizacion_id=organizacion_id,
            payload=quote_payload,
        )
        sale_logger.info(
            "propiedad_quote_created",
            extra={
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote["id"]),
                "total": quote.get("total"),
                "moneda": quote.get("moneda"),
            },
        )
        _write_propiedad_sale_event(
            "quote_created",
            {
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote["id"]),
                "total": quote.get("total"),
                "moneda": quote.get("moneda"),
            },
        )
        product = await _ensure_product_for_catalog_item(
            repo,
            organizacion_id,
            payload.catalog_item_id,
        )
        sale_logger.info(
            "propiedad_product_ensured",
            extra={
                "organizacion_id": str(organizacion_id),
                "product_id": str(product.get("id")),
                "catalog_item_id": str(payload.catalog_item_id),
            },
        )
        _write_propiedad_sale_event(
            "product_ensured",
            {
                "organizacion_id": str(organizacion_id),
                "product_id": str(product.get("id")),
                "catalog_item_id": str(payload.catalog_item_id),
            },
        )
        item_payload: dict[str, Any] = {
            "cotizacion_id": str(quote["id"]),
            "producto_id": str(product.get("id")),
            "descripcion": catalog_item.get("nombre") or "Unidad inmobiliaria",
            "cantidad": 1,
            "precio_unitario": price_value,
            "subtotal": price_value,
            "metadata": item_metadata,
        }
        await repo.add_quote_item(
            organizacion_id=organizacion_id,
            payload=item_payload,
        )
        sale_logger.info(
            "propiedad_quote_item_added",
            extra={
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote["id"]),
                "producto_id": str(product.get("id")),
                "cantidad": 1,
                "precio_unitario": price_value,
            },
        )
        _write_propiedad_sale_event(
            "quote_item_added",
            {
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote["id"]),
                "producto_id": str(product.get("id")),
                "cantidad": 1,
                "precio_unitario": price_value,
            },
        )
        if resolved_oportunidad_id:
            quote_uuid = _safe_uuid(quote.get("id")) or UUID(str(quote["id"]))
            await _render_quote_pdf_after_sale(
                repo,
                organizacion_id,
                quote_uuid,
                resolved_oportunidad_id,
                usuario_id,
            )
            await _mark_quote_as_accepted_from_mapbox(
                repo,
                organizacion_id,
                quote_uuid,
                usuario_id,
            )
        await repo.update_propiedad_unidad(
            organizacion_id=organizacion_id,
            unidad_id=payload.unidad_id,
            payload={
                "status": PropiedadStatus.vendido.value,
                "oportunidad_id": str(resolved_oportunidad_id) if resolved_oportunidad_id else None,
                "catalog_item_id": str(payload.catalog_item_id),
            },
        )
        try:
            await repo.create_propiedad_unidad_movimiento(
                organizacion_id=organizacion_id,
                payload={
                    "organizacion_id": str(organizacion_id),
                    "unidad_id": str(payload.unidad_id),
                    "oportunidad_id": str(resolved_oportunidad_id) if resolved_oportunidad_id else None,
                    "persona_id": str(resolved_persona_id) if resolved_persona_id else None,
                    "cuenta_id": str(resolved_cuenta_id) if resolved_cuenta_id else None,
                    "estado_anterior": str(current_unidad.get("status") if current_unidad and current_unidad.get("status") else PropiedadStatus.disponible.value),
                    "estado_nuevo": PropiedadStatus.vendido.value,
                    "precio": price_value,
                    "moneda": payload.moneda,
                    "motivo": "venta_registrada",
                    "metadata": {
                        "source": "venta_propiedades",
                        "catalog_item_id": str(payload.catalog_item_id),
                        "propiedad_id": str(payload.propiedad_id),
                        "lead_id": str(payload.lead_id) if payload.lead_id else None,
                        "quote_id": str(quote["id"]),
                    },
                    "creado_por": str(usuario_id) if usuario_id else None,
                }
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        sale_logger.info(
            "propiedad_unidad_status_updated",
            extra={
                "organizacion_id": str(organizacion_id),
                "unidad_id": str(payload.unidad_id),
                "status": PropiedadStatus.vendido.value,
            },
        )
        _write_propiedad_sale_event(
            "unidad_status_updated",
            {
                "organizacion_id": str(organizacion_id),
                "unidad_id": str(payload.unidad_id),
                "status": PropiedadStatus.vendido.value,
            },
        )
        catalog_metadata = dict(catalog_item.get("metadatos") or {})
        catalog_metadata.update(
            {
                "venta_registrada_en": datetime.now(timezone.utc).isoformat(),
                "venta_activa": False,
            }
        )
        catalog_update: dict[str, Any] = {
            "activo": False,
            "propiedad_id": str(payload.propiedad_id),
            "unidad_id": str(payload.unidad_id),
            "metadatos": catalog_metadata,
        }
        if resolved_oportunidad_id:
            catalog_update["oportunidad_id"] = str(resolved_oportunidad_id)
        if resolved_persona_id:
            catalog_update["persona_id"] = str(resolved_persona_id)
        await repo.update_catalog_item(
            item_id=payload.catalog_item_id,
            payload=catalog_update,
        )
        sale_logger.info(
            "propiedad_catalog_item_deactivated",
            extra={
                "organizacion_id": str(organizacion_id),
                "catalog_item_id": str(payload.catalog_item_id),
            },
        )
        _write_propiedad_sale_event(
            "catalog_item_deactivated",
            {
                "organizacion_id": str(organizacion_id),
                "catalog_item_id": str(payload.catalog_item_id),
            },
        )
        sale_entry = {
            "organizacion_id": str(organizacion_id),
            "catalog_item_id": str(payload.catalog_item_id),
            "propiedad_id": str(payload.propiedad_id),
            "unidad_id": str(payload.unidad_id),
            "lead_id": str(payload.lead_id) if payload.lead_id else None,
            "precio_final": price_value,
            "moneda": payload.moneda,
            "cotizacion_id": str(quote["id"]),
            "oportunidad_id": str(resolved_oportunidad_id) if resolved_oportunidad_id else None,
            "cuenta_id": str(resolved_cuenta_id) if resolved_cuenta_id else None,
            "contacto_id": str(payload.contacto_id) if payload.contacto_id else None,
            "persona_id": str(resolved_persona_id) if resolved_persona_id else None,
        }
        sale_logger.info("propiedad_sale_registered", extra=sale_entry)
        _write_propiedad_sale_log(sale_entry)
        if payload.lead_id:
            await _sync_lead_metrics_after_sale(repo, payload.lead_id)
        if resolved_oportunidad_id:
            await _advance_opportunity_to_won(
                repo,
                organizacion_id,
                resolved_oportunidad_id,
                _safe_uuid(opportunity.get("etapa_id")) if opportunity else None,
                usuario_id,
            )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return CRMQuote.model_validate(quote)


@router.get("/ventas/logs", response_model=CRMSaleLogsResponse)
async def list_propiedades_sale_logs(
    *,
    limit: Annotated[int, Query(ge=1, le=200)] = DEFAULT_SALE_LOG_LIMIT,
    _: str = Depends(require_permission("reports.view")),
) -> CRMSaleLogsResponse:
    try:
        logs = _read_propiedad_sale_log_records(limit)
    except Exception as exc:  # pragma: no cover - fallback
        raise HTTPException(status_code=502, detail="sale_logs_unavailable") from exc
    return CRMSaleLogsResponse(logs=logs)


@router.post(
    "/propiedades/ventas/vendedores",
    response_model=CRMPropertySalesVendorResponse,
)
async def propiedades_ventas_vendedores(
    *,
    payload: CRMPropertySalesVendorRequest,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    _: str = Depends(require_permission("propiedades.view")),
) -> CRMPropertySalesVendorResponse:
    try:
        rows = await repo.list_propiedades_ventas_vendedores(
            organizacion_id=organizacion_id,
            unidad_ids=payload.unidad_ids,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    vendedores = [CRMPropertySalesVendorEntry.model_validate(row) for row in rows]
    return CRMPropertySalesVendorResponse(vendedores=vendedores)


@router.post("/propiedades/importar")
async def importar_propiedades(
    *,
    payload: ImportPropiedadesRequest,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    _: str = Depends(require_permission("settings.manage")),
) -> dict[str, Any]:
    try:
        result = await _process_import_request(payload, repo, organizacion_id)
    except ValueError as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc)) from exc
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return {"ok": True, **result}


@router.post("/propiedades/importar/csv")
async def importar_propiedades_csv(
    *,
    file: UploadFile = File(...),
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_tenant_module_enabled("propiedades")),
    _: str = Depends(require_permission("settings.manage")),
) -> dict[str, Any]:
    start = time.perf_counter()
    file_name = getattr(file, "filename", "csv")
    try:
        raw = await file.read()
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        import_debug_logger.exception(
            "import_csv.invalid_encoding",
            extra={"file": file_name},
        )
        raise HTTPException(status_code=400, detail="El archivo CSV debe estar en UTF-8.") from None

    import_debug_logger.info(
        "import_csv.received",
        extra={"file": file_name, "size_bytes": len(raw)},
    )

    try:
        payload = _csv_to_import_request(text)
    except ValueError as exc:
        import_debug_logger.warning(
            "import_csv.invalid_payload",
            extra={"file": file_name, "error": str(exc)},
        )
        raise HTTPException(status_code=400, detail=str(exc)) from exc

    try:
        result = await _process_import_request(payload, repo, organizacion_id)
    except ValueError as exc:
        import_debug_logger.warning(
            "import_csv.invalid_tipo",
            extra={"file": file_name, "error": str(exc)},
        )
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc)) from exc
    except CRMRepositoryError as exc:
        import_debug_logger.error(
            "import_csv.repository_error",
            extra={"file": file_name, "error": str(exc)},
        )
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    duration_ms = (time.perf_counter() - start) * 1000
    import_debug_logger.info(
        "import_csv.completed",
        extra={"file": file_name, "duration_ms": duration_ms, "desarrollos": len(result.get("desarrollos", []))},
    )

    return {"ok": True, **result}


async def _process_import_request(
    payload: ImportPropiedadesRequest,
    repo: CRMRepository,
    organizacion_id: UUID,
) -> dict[str, list[dict[str, Any]]]:
    import_debug_logger.info(
        "import_process.start",
        extra={
            "organizacion_id": str(organizacion_id),
            "desarrollos_in_payload": len(payload.desarrollos or []),
            "mixtos_in_payload": len(payload.mixtos or []),
        },
    )
    start = time.perf_counter()
    tipo_lookup = await _build_tipo_lookup(repo, organizacion_id)
    catalog_lookup = await _PropertyCatalogLookup.build(repo, organizacion_id)
    desarrollos: list[dict[str, Any]] = []
    mixtos: list[dict[str, Any]] = []
    for desarrollo in payload.desarrollos or []:
        desarrollos.append(
            await _import_desarrollo_tree(
                repo,
                organizacion_id,
                desarrollo,
                tipo_lookup,
                catalog_lookup,
            )
        )
    for mixto in payload.mixtos or []:
        mixtos.append(
            await _import_desarrollo_mixto(
                repo,
                organizacion_id,
                mixto,
                tipo_lookup,
                catalog_lookup,
            )
        )
    duration_ms = (time.perf_counter() - start) * 1000
    import_debug_logger.info(
        "import_process.completed",
        extra={
            "organizacion_id": str(organizacion_id),
            "desarrollos": len(desarrollos),
            "mixtos": len(mixtos),
            "duration_ms": duration_ms,
        },
    )
    return {"desarrollos": desarrollos, "mixtos": mixtos}


ENTITY_DESCRIPTION_COLUMNS: dict[str, tuple[str, ...]] = {
    "desarrollo": ("descripcion_desarrollo", "descripcion"),
    "capa": ("descripcion_capa", "descripcion"),
    "unidad": ("descripcion_unidad", "descripcion"),
}


def _resolve_entity_description(row: dict[str, Any], entidad: str) -> str | None:
    for key in ENTITY_DESCRIPTION_COLUMNS.get(entidad, ("descripcion",)):
        value = _strip_value(row.get(key))
        if value:
            return value
    return None


def _resolve_import_capa_from_identifier(
    *,
    group: dict[str, Any],
    identifier: Any,
) -> ImportCapa | None:
    """Resolve a unit's capa using the stable hierarchy encoded in identificador.

    Horizontal developments commonly reuse nivel=0 for every capa. In that
    case the numeric level is not enough to identify the parent; the exported
    identifier ("grupo / capa / unidad") is the canonical fallback.
    """
    identifier_key = _normalize_column_value(_strip_value(identifier))
    if not identifier_key:
        return None
    capas = [capa for capa in group.get("capas", []) if isinstance(capa, ImportCapa) and capa.nombre]
    capas.sort(key=lambda capa: len(_normalize_column_value(capa.nombre)), reverse=True)
    for capa in capas:
        capa_key = _normalize_column_value(capa.nombre)
        # The export may use the development identifier (for example GPR)
        # instead of the display name (Gran Peñón Residencial).
        if f" / {capa_key} / " in identifier_key:
            return capa
    return None


def _resolve_import_manzana_from_identifier(
    *,
    group: dict[str, Any],
    identifier: Any,
) -> tuple[ImportCapa, ImportManzana] | None:
    identifier_key = _normalize_column_value(_strip_value(identifier))
    if not identifier_key:
        return None
    candidates: list[tuple[ImportCapa, ImportManzana]] = []
    for capa in group.get("capas", []):
        if not isinstance(capa, ImportCapa):
            continue
        for manzana in capa.manzanas or []:
            if f" / {_normalize_column_value(manzana.nombre)} / " in identifier_key:
                candidates.append((capa, manzana))
    if len(candidates) == 1:
        return candidates[0]
    return None


def _csv_to_import_request(content: str) -> ImportPropiedadesRequest:
    reader = csv.DictReader(io.StringIO(content), skipinitialspace=True)
    if not reader.fieldnames:
        raise ValueError("El CSV está vacío.")

    groups: dict[str, dict[str, Any]] = {}
    current_group_key: str | None = None
    group_aliases: dict[str, list[str]] = {}
    for line, raw in enumerate(reader, start=1):
        row = {key: (value or "") for key, value in raw.items()}
        normalized_row = {
            _normalize_column_value(key): value
            for key, value in row.items()
            if key
        }
        entidad = _strip_value(row.get("entidad") or row.get("tipo_entidad"))
        if not entidad:
            continue
        entidad = entidad.lower()
        if entidad not in {"desarrollo", "capa", "manzana", "unidad"}:
            raise ValueError(f"La entidad '{entidad}' en la línea {line} no es válida.")
        raw_group = _strip_value(row.get("grupo"))

        if entidad == "desarrollo":
            base_key = raw_group or _strip_value(row.get("nombre")) or f"fila-{line}"
            if not base_key:
                raise ValueError(f"Necesitas un identificador de grupo en la línea {line}.")
            group_key = base_key
            if group_key in groups and groups[group_key].get("desarrollo") is not None:
                suffix = 2
                candidate = f"{group_key}#{suffix}"
                while candidate in groups:
                    suffix += 1
                    candidate = f"{group_key}#{suffix}"
                group_key = candidate
            group = groups.setdefault(
                group_key,
                {
                    "desarrollo": None,
                    "capas": [],
                    "capas_lookup": {},
                    "capas_by_nivel": {},
                },
            )
            if raw_group:
                group_aliases.setdefault(raw_group, []).append(group_key)
            current_group_key = group_key
        else:
            if raw_group:
                aliases = group_aliases.get(raw_group)
                if aliases:
                    group_key = current_group_key if current_group_key in aliases else aliases[-1]
                else:
                    group_key = raw_group
            else:
                group_key = current_group_key or _strip_value(row.get("nombre")) or f"fila-{line}"
            if not group_key:
                raise ValueError(f"Necesitas un identificador de grupo en la línea {line}.")
            group = groups.get(group_key)
            if group is None:
                raise ValueError(
                    f"No se encontró el grupo '{group_key}' en la línea {line}. "
                    "Debes declarar primero el desarrollo correspondiente (o bien mantener el archivo ordenado: "
                    "desarrollo → capas → unidades)."
                )

        if entidad == "desarrollo":
            if group["desarrollo"] is not None:
                raise ValueError(f"Hay varios desarrollos para el grupo '{group_key}'.")
            group["desarrollo"] = ImportDesarrollo(
                nombre=_require_value(row.get("nombre"), "nombre", line),
                tipo=_parse_desarrollo_tipo(_resolve_desarrollo_tipo_value(row)),
                status=_parse_status_value(row.get("status")),
                pais_codigo=_strip_value(row.get("pais_codigo")) or "MX",
                estado_cve=_strip_value(row.get("estado_cve")),
                municipio_cve=_strip_value(row.get("municipio_cve")),
                codigo_postal=_strip_value(row.get("codigo_postal")),
                colonia=_strip_value(row.get("colonia")),
                descripcion=_resolve_entity_description(row, "desarrollo"),
                metadata=_merge_volume_metadata(row, _parse_metadata(row.get("metadata"))),
                poligono=_parse_geometry_value(row.get("poligono")),
            )
            continue

        if group["desarrollo"] is None and entidad != "desarrollo":
            raise ValueError(f"Debe definir un desarrollo antes de las filas de '{entidad}' (línea {line}).")

        if entidad == "capa":
            nivel = _parse_integer(row.get("nivel"), "nivel", line)
            capa = ImportCapa(
                nivel=nivel,
                nombre=_strip_value(row.get("nombre")),
                descripcion=_resolve_entity_description(row, "capa"),
                altura=_parse_decimal(row.get("altura")),
                status=_parse_status_value(row.get("status")),
                metadata=_merge_volume_metadata(row, _parse_metadata(row.get("metadata"))),
                poligono=_parse_geometry_value(row.get("poligono")),
            )
            group["capas"].append(capa)
            group["capas_by_nivel"].setdefault(nivel, []).append(capa)
            if capa.nombre:
                group["capas_lookup"][(group_key, capa.nombre.strip().lower())] = capa
            continue

        if entidad == "manzana":
            capa_nivel = _parse_integer(row.get("capa_nivel"), "capa_nivel", line)
            capa = _resolve_import_capa_from_identifier(
                group=group,
                identifier=row.get("identificador"),
            )
            if capa is None:
                capas_for_level = group["capas_by_nivel"].get(capa_nivel, [])
                if len(capas_for_level) == 1:
                    capa = capas_for_level[0]
                else:
                    raise ValueError(
                        f"La manzana en la línea {line} no identifica un macrolote de forma unívoca. "
                        "Usa el prefijo del macrolote en 'identificador'."
                    )
            manzana = ImportManzana(
                nombre=_require_value(row.get("nombre"), "nombre", line),
                descripcion=_resolve_entity_description(row, "capa"),
                status=_parse_status_value(row.get("status")),
                metadata=_merge_volume_metadata(row, _parse_metadata(row.get("metadata"))),
                poligono=_parse_geometry_value(row.get("poligono")),
            )
            capa.manzanas = capa.manzanas or []
            capa.manzanas.append(manzana)
            continue

        if entidad == "unidad":
            capa_nivel = _parse_integer(row.get("capa_nivel"), "capa_nivel", line)
            manzana_parent = _resolve_import_manzana_from_identifier(
                group=group,
                identifier=row.get("identificador"),
            )
            capa = _resolve_import_capa_from_identifier(
                group=group,
                identifier=row.get("identificador"),
            )
            if manzana_parent:
                capa = manzana_parent[0]
            if capa is None:
                capas_for_level = group["capas_by_nivel"].get(capa_nivel, [])
                if len(capas_for_level) == 1:
                    capa = capas_for_level[0]
                elif not capas_for_level:
                    raise ValueError(
                        f"No se encontró la capa de nivel {capa_nivel} para la unidad en la línea {line}."
                    )
                else:
                    raise ValueError(
                        f"La unidad en la línea {line} no identifica una capa de forma unívoca. "
                        "Usa el prefijo de capa en 'identificador'."
                    )
            linea_nombre_value = _pick_value(normalized_row, BASE_HEADER_CANDIDATES["linea"])
            familia_nombre_value = _pick_value(normalized_row, BASE_HEADER_CANDIDATES["familia"])
            modelo_nombre_value = _pick_value(normalized_row, BASE_HEADER_CANDIDATES["modelo"])
            unidad = ImportUnidad(
                unidad=_require_value(row.get("unidad"), "unidad", line),
                nombre=_strip_value(row.get("nombre")) or _strip_value(row.get("unidad")) or "",
                tipo_id=_parse_uuid_value(row.get("tipo_id") or row.get("tipo_unidad_id")),
                tipo_nombre=_strip_value(
                    row.get("tipo_nombre")
                    or row.get("tipo_unidad_nombre")
                    or row.get("tipo_unidad")
                ),
                status=_parse_status_value(row.get("status")),
                destino_inventario=PropiedadDestinoInventario(
                    _normalize_property_destination(row.get("destino_inventario"))
                ),
                precio_tipo=PropiedadPrecioTipo(_normalize_property_price_type(row.get("precio_tipo"))),
                descripcion=_resolve_entity_description(row, "unidad"),
                precio=_parse_decimal(row.get("precio")),
                precio_m2=_parse_decimal(row.get("precio_m2")),
                area_m2=_parse_decimal(row.get("area_m2")),
                oportunidad_id=_parse_uuid_value(row.get("oportunidad_id")),
                linea_id=_parse_uuid_value(row.get("linea_id")),
                familia_id=_parse_uuid_value(row.get("familia_id")),
                modelo_id=_parse_uuid_value(row.get("modelo_id")),
                linea_nombre=linea_nombre_value or None,
                familia_nombre=familia_nombre_value or None,
                modelo_nombre=modelo_nombre_value or None,
                metadata=_merge_volume_metadata(row, _parse_metadata(row.get("metadata"))),
                metadata_extra=_collect_metadata_extra_from_row(row),
                poligono=_parse_geometry_value(row.get("poligono")),
            )
            if manzana_parent:
                manzana_parent[1].unidades = manzana_parent[1].unidades or []
                manzana_parent[1].unidades.append(unidad)
            else:
                capa.unidades = capa.unidades or []
                capa.unidades.append(unidad)
            continue

    desarrollos = []
    for group in groups.values():
        desarrollo: ImportDesarrollo | None = group["desarrollo"]
        if not desarrollo:
            continue
        if group["capas"]:
            desarrollo.capas = group["capas"]
        desarrollos.append(desarrollo)

    if not desarrollos:
        raise ValueError("El CSV debe contener al menos un desarrollo.")

    return ImportPropiedadesRequest(desarrollos=desarrollos, mixtos=[])


_POLYGON_PREFIX = re.compile(r"^POLYGON(?:\s+([A-Za-z]+))?\s*(.*)", re.IGNORECASE)
def _strip_value(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip()


def _convert_polygon_to_multipolygon(body: str) -> str:
    trimmed = body.strip()
    match = _POLYGON_PREFIX.match(trimmed)
    if not match:
        return trimmed
    dim = match.group(1)
    inner = match.group(2).strip()
    if not inner:
        raise ValueError("El polígono no contiene coordenadas.")
    suffix = f" {dim.strip()}" if dim else ""
    import_debug_logger.debug(
        "geometry.convert_polygon_to_multipolygon",
        extra={"dim": dim or "<none>", "inner_length": len(inner)},
    )
    return f"MULTIPOLYGON{suffix} ({inner})"


def _resolve_desarrollo_tipo_value(row: dict[str, Any]) -> Any:
    for key in ("tipo_desarrollo", "tipo", "tipo_nombre"):
        if key in row and row[key] is not None:
            value = _strip_value(row[key])
            if value:
                return value
    return ""


def _require_value(value: Any, field: str, line: int) -> str:
    trimmed = _strip_value(value)
    if not trimmed:
        raise ValueError(f"El campo '{field}' es obligatorio en la línea {line}.")
    return trimmed


def _parse_integer(value: Any, field: str, line: int) -> int:
    trimmed = _strip_value(value)
    if not trimmed:
        raise ValueError(f"'{field}' es obligatorio y debe ser un número entero (línea {line}).")
    try:
        return int(trimmed)
    except ValueError as exc:
        raise ValueError(f"'{field}' debe ser un entero válido en la línea {line}.") from exc


def _parse_decimal(value: Any) -> Decimal | None:
    trimmed = _strip_value(value)
    if not trimmed:
        return None
    try:
        return Decimal(trimmed)
    except InvalidOperation as exc:
        raise ValueError(f"El valor '{trimmed}' no es un número válido.") from exc


def _parse_optional_decimal(value: Any) -> Decimal | None:
    trimmed = _strip_value(value)
    if not trimmed:
        return None
    try:
        return Decimal(trimmed)
    except InvalidOperation as exc:
        raise ValueError(f"El valor '{trimmed}' no es un número válido.") from exc


def _parse_optional_int(value: Any) -> int | None:
    trimmed = _strip_value(value)
    if not trimmed:
        return None
    try:
        return int(trimmed)
    except ValueError as exc:
        raise ValueError(f"'{trimmed}' debe ser un entero válido.") from exc


def _parse_status_value(value: Any) -> PropiedadStatus:
    trimmed = _strip_value(value)
    if not trimmed:
        return PropiedadStatus.disponible
    try:
        return PropiedadStatus(trimmed.lower())
    except ValueError as exc:
        raise ValueError(
            f"Estado '{trimmed}' inválido. Usa disponible/apartado/vendido/reservado/bloqueado."
        ) from exc


def _parse_desarrollo_tipo(value: Any) -> PropiedadDesarrolloTipo:
    trimmed = _strip_value(value)
    if not trimmed:
        return PropiedadDesarrolloTipo.horizontal
    try:
        return PropiedadDesarrolloTipo(trimmed.lower())
    except ValueError as exc:
        raise ValueError("Tipo de desarrollo inválido. Usa horizontal, vertical o mixto.") from exc


def _parse_geometry_value(value: Any) -> str | dict[str, Any] | None:
    trimmed = _strip_value(value)
    if not trimmed:
        return None
    if trimmed.startswith("{") or trimmed.startswith("["):
        try:
            parsed = json.loads(trimmed)
        except json.JSONDecodeError as exc:
            raise ValueError("La geometría debe ser GeoJSON válido o WKT.") from exc
        if isinstance(parsed, (dict, list)):
            return parsed
    return trimmed


def _parse_metadata(value: Any) -> dict[str, Any] | None:
    trimmed = _strip_value(value)
    if not trimmed:
        return None
    try:
        parsed = json.loads(trimmed)
    except json.JSONDecodeError as exc:
        raise ValueError("El metadata debe estar en formato JSON válido.") from exc
    if not isinstance(parsed, dict):
        raise ValueError("El metadata debe contener un objeto JSON.")
    return parsed


class _PropertyCatalogLookup:
    def __init__(
        self,
        repo: CRMRepository,
        organizacion_id: UUID,
        lineas_cache: dict[str, dict[str, Any]],
        familias_cache: dict[tuple[str, str], dict[str, Any]],
        modelos_cache: dict[tuple[str, str], dict[str, Any]],
        modelos_global: dict[str, dict[str, Any]],
    ) -> None:
        self.repo = repo
        self.organizacion_id = organizacion_id
        self.lineas_cache = lineas_cache
        self.familias_cache = familias_cache
        self.modelos_cache = modelos_cache
        self.modelos_global = modelos_global

    @classmethod
    async def build(cls, repo: CRMRepository, organizacion_id: UUID) -> "_PropertyCatalogLookup":
        lineas_raw = await repo.list_lineas_de_negocio(
            organizacion_id=organizacion_id,
            include_inactive=True,
            limit=1000,
        )
        lineas_cache = {
            _normalize_column_value(str(linea.get("nombre", ""))): linea
            for linea in lineas_raw
            if linea.get("nombre")
        }
        familias_cache: dict[tuple[str, str], dict[str, Any]] = {}
        familias = await repo.list_familias_productos(
            organizacion_id=organizacion_id,
            include_inactive=True,
            limit=1000,
        )
        for familia in familias:
            linea_id = familia.get("linea_id")
            nombre = familia.get("nombre")
            if not linea_id or not nombre:
                continue
            familias_cache[(str(linea_id), _normalize_column_value(nombre))] = familia
        modelos_cache: dict[tuple[str, str], dict[str, Any]] = {}
        modelos_global: dict[str, dict[str, Any]] = {}
        modelos = await repo.list_modelos_productos(
            organizacion_id=organizacion_id,
            include_inactive=True,
            limit=1000,
        )
        for modelo in modelos:
            familia_id = modelo.get("familia_id")
            nombre = modelo.get("nombre")
            if not familia_id or not nombre:
                continue
            modelos_cache[(str(familia_id), _normalize_column_value(nombre))] = modelo
            modelos_global[_normalize_column_value(nombre)] = modelo
        return cls(
            repo=repo,
            organizacion_id=organizacion_id,
            lineas_cache=lineas_cache,
            familias_cache=familias_cache,
            modelos_cache=modelos_cache,
            modelos_global=modelos_global,
        )

    async def ensure_linea(self, name: str) -> UUID:
        normalized = _normalize_column_value(name)
        if not normalized:
            raise ValueError("Línea vacía o inválida.")
        cached = self.lineas_cache.get(normalized)
        if cached:
            return UUID(str(cached["id"]))
        payload = {"nombre": name, "activo": True}
        nueva = await self.repo.create_linea_de_negocio(
            organizacion_id=self.organizacion_id,
            payload=payload,
        )
        normalized_nueva = _normalize_column_value(str(nueva.get("nombre", name)))
        self.lineas_cache[normalized_nueva] = nueva
        return UUID(str(nueva["id"]))

    async def ensure_familia(self, name: str, linea_id: UUID) -> UUID:
        normalized = _normalize_column_value(name)
        key = (str(linea_id), normalized)
        cached = self.familias_cache.get(key)
        if cached:
            return UUID(str(cached["id"]))
        payload = {"nombre": name, "linea_id": str(linea_id), "activo": True}
        nueva = await self.repo.create_familia_producto(
            organizacion_id=self.organizacion_id,
            payload=payload,
        )
        self.familias_cache[key] = nueva
        return UUID(str(nueva["id"]))

    async def ensure_model(self, name: str, familia_id: UUID) -> UUID:
        normalized = _normalize_column_value(name)
        key = (str(familia_id), normalized)
        cached = self.modelos_cache.get(key)
        if cached:
            return UUID(str(cached["id"]))
        global_cached = self.modelos_global.get(normalized)
        if global_cached:
            return UUID(str(global_cached["id"]))
        payload = {"nombre": name, "familia_id": str(familia_id), "activo": True}
        nuevo = await self.repo.create_modelo_producto(
            organizacion_id=self.organizacion_id,
            payload=payload,
        )
        self.modelos_cache[key] = nuevo
        self.modelos_global[normalized] = nuevo
        return UUID(str(nuevo["id"]))


def _merge_volume_metadata(row: dict[str, Any], base_metadata: dict[str, Any] | None) -> dict[str, Any] | None:
    meta = dict(base_metadata) if base_metadata else {}
    changes = False
    height = _parse_optional_decimal(row.get("height"))
    min_height = _parse_optional_decimal(row.get("min_height"))
    levels = _parse_optional_int(row.get("levels"))
    color = _strip_value(row.get("color"))

    def assign(key: str, value: Any) -> None:
        nonlocal changes
        if value is not None:
            if isinstance(value, Decimal):
                meta[key] = float(value)
            else:
                meta[key] = value
            changes = True

    assign("height", height)
    assign("min_height", min_height)
    assign("levels", levels)
    if color:
        assign("color", color)

    for suffix, value in _collect_metadata_columns_from_row(row).items():
        assign(suffix, value)

    return meta if changes or meta else None


def _collect_metadata_extra_from_row(row: dict[str, Any]) -> dict[str, Any] | None:
    extra: dict[str, Any] = {}

    def assign(key: str, value: Any | None) -> None:
        if value is None:
            return
        if isinstance(value, Decimal):
            extra[key] = float(value)
        else:
            extra[key] = value

    height = _parse_optional_decimal(row.get("height"))
    min_height = _parse_optional_decimal(row.get("min_height"))
    levels = _parse_optional_int(row.get("levels"))
    color = _strip_value(row.get("color"))

    assign("height", height)
    assign("min_height", min_height)
    assign("levels", levels)
    if color:
        assign("color", color)

    for suffix, value in _collect_metadata_columns_from_row(row).items():
        assign(suffix, value)

    return extra if extra else None


def _collect_metadata_columns_from_row(row: dict[str, Any]) -> dict[str, Any]:
    collected: dict[str, Any] = {}
    prefixes = ("metadata_", "metadata_unidad_")
    for raw_key, raw_value in row.items():
        normalized_key = raw_key.lower().strip()
        matched_prefix = next((prefix for prefix in prefixes if normalized_key.startswith(prefix)), None)
        if not matched_prefix:
            continue
        suffix = normalized_key[len(matched_prefix) :]
        if not suffix:
            continue
        value = _strip_value(raw_value)
        if value == "":
            continue
        collected[suffix] = value
    return collected


def _parse_uuid_value(value: Any) -> UUID | None:
    trimmed = _strip_value(value)
    if not trimmed:
        return None
    try:
        return UUID(trimmed)
    except ValueError:
        return None



async def _import_desarrollo_tree(
    repo: CRMRepository,
    organizacion_id: UUID,
    desarrollo: ImportDesarrollo,
    tipo_lookup: dict[str, str],
    catalog_lookup: _PropertyCatalogLookup,
) -> dict[str, Any]:
    # El CSV puede ser una carga incremental. Se consultan primero los niveles
    # existentes y se mantienen en memoria durante esta importación para que
    # cada fila reutilice la misma jerarquía en lugar de crear otra.
    desarrollo_nombre = _normalize_column_value(desarrollo.nombre)
    desarrollos_existentes = await repo.list_propiedad_desarrollos(
        organizacion_id=organizacion_id,
    )
    record = next(
        (
            item
            for item in desarrollos_existentes
            if _normalize_column_value(str(item.get("nombre") or "")) == desarrollo_nombre
        ),
        None,
    )
    desarrollo_metadata = _coerce_metadata(desarrollo.metadata)
    desarrollo_metadata = _strip_metadata_keys(
        desarrollo_metadata,
        {"status", "pais_codigo", "estado_cve", "municipio_cve", "codigo_postal", "colonia", "tipo", "nombre", "descripcion"},
    )
    desarrollo_metadata, _ = _split_poligono_volume_metadata(desarrollo_metadata)
    payload: dict[str, Any] = {
        "nombre": desarrollo.nombre.strip(),
        "tipo": desarrollo.tipo.value,
        "status": desarrollo.status.value,
        "metadata": desarrollo_metadata or {},
    }
    if desarrollo.descripcion:
        payload["descripcion"] = desarrollo.descripcion.strip()
    if desarrollo.pais_codigo:
        payload["pais_codigo"] = desarrollo.pais_codigo.strip()
    if desarrollo.estado_cve:
        payload["estado_cve"] = desarrollo.estado_cve.strip()
    if desarrollo.municipio_cve:
        payload["municipio_cve"] = desarrollo.municipio_cve.strip()
    if desarrollo.codigo_postal:
        payload["codigo_postal"] = desarrollo.codigo_postal.strip()
    if desarrollo.colonia:
        payload["colonia"] = desarrollo.colonia.strip()

    if record is None:
        record = await repo.create_propiedad_desarrollo(
            organizacion_id=organizacion_id,
            payload=payload,
        )
        desarrollos_existentes.append(record)
    summary: dict[str, Any] = {"id": record["id"], "nombre": record["nombre"], "tipo": record["tipo"]}

    desarrollo_poligono = await _create_poligono_if_present(
        repo,
        organizacion_id,
        PropiedadPoligonoTarget.desarrollo,
        record["id"],
        desarrollo.poligono,
        desarrollo.status,
        desarrollo.metadata,
    )
    if desarrollo_poligono:
        summary["poligono_id"] = desarrollo_poligono["id"]

    if desarrollo.capas:
        summary["capas"] = []
        capas_existentes = await repo.list_propiedad_capas_by_desarrollo(
            organizacion_id=organizacion_id,
            desarrollo_id=UUID(str(record["id"])),
        )
        unidades_por_capa: dict[str, list[dict[str, Any]]] = {}
        manzanas_por_capa: dict[str, list[dict[str, Any]]] = {}
        for capa in desarrollo.capas:
            capa_payload: dict[str, Any] = {
                "desarrollo_id": record["id"],
                "nivel": capa.nivel,
                "status": capa.status.value,
            }
            capa_metadata = _coerce_metadata(capa.metadata)
            capa_metadata, _ = _split_capa_status_metadata(capa_metadata)
            capa_metadata, _ = _split_poligono_volume_metadata(capa_metadata)
            capa_payload["metadata"] = capa_metadata or {}
            if capa.nombre:
                capa_payload["nombre"] = capa.nombre.strip()
            if capa.descripcion:
                capa_payload["descripcion"] = capa.descripcion.strip()
            if capa.altura is not None:
                capa_payload["altura"] = _decimal_to_number(capa.altura)

            capa_nombre = _normalize_column_value(capa.nombre or "")
            capa_record = next(
                (
                    item
                    for item in capas_existentes
                    if (
                        capa_nombre
                        and _normalize_column_value(str(item.get("nombre") or "")) == capa_nombre
                        and item.get("nivel") == capa.nivel
                    )
                    or (
                        not capa_nombre
                        and item.get("nivel") == capa.nivel
                    )
                ),
                None,
            )
            if capa_record is None:
                capa_record = await repo.create_propiedad_capa(
                    organizacion_id=organizacion_id,
                    payload=capa_payload,
                )
                capas_existentes.append(capa_record)
            capa_summary: dict[str, Any] = {
                "id": capa_record["id"],
                "nivel": capa_record.get("nivel"),
                "nombre": capa_record.get("nombre"),
            }

            capa_poligono = await _create_poligono_if_present(
                repo,
                organizacion_id,
                PropiedadPoligonoTarget.capa,
                capa_record["id"],
                capa.poligono,
                capa.status,
                capa.metadata,
            )
            if capa_poligono:
                capa_summary["poligono_id"] = capa_poligono["id"]

            unit_entries: list[tuple[ImportUnidad, dict[str, Any] | None]] = [
                (unidad, None) for unidad in (capa.unidades or [])
            ]
            if capa.manzanas:
                capa_summary["manzanas"] = []
                capa_id_key = str(capa_record["id"])
                manzanas_existentes = manzanas_por_capa.get(capa_id_key)
                if manzanas_existentes is None:
                    manzanas_existentes = await repo.list_propiedad_manzanas_by_capa(
                        organizacion_id=organizacion_id,
                        capa_id=UUID(capa_id_key),
                    )
                    manzanas_por_capa[capa_id_key] = manzanas_existentes
                for manzana in capa.manzanas:
                    manzana_nombre = _normalize_column_value(manzana.nombre)
                    manzana_record = next(
                        (
                            item
                            for item in manzanas_existentes
                            if _normalize_column_value(str(item.get("nombre") or "")) == manzana_nombre
                        ),
                        None,
                    )
                    if manzana_record is None:
                        manzana_record = await repo.create_propiedad_manzana(
                            organizacion_id=organizacion_id,
                            payload={
                                "macrolote_id": capa_record["id"],
                                "nombre": manzana.nombre.strip(),
                                "descripcion": manzana.descripcion.strip() if manzana.descripcion else None,
                                "status": manzana.status.value,
                                "metadata": _coerce_metadata(manzana.metadata) or {},
                            },
                        )
                        manzanas_existentes.append(manzana_record)
                    manzana_summary: dict[str, Any] = {
                        "id": manzana_record["id"],
                        "nombre": manzana_record["nombre"],
                        "unidades": [],
                    }
                    manzana_poligono = await _create_poligono_if_present(
                        repo,
                        organizacion_id,
                        PropiedadPoligonoTarget.manzana,
                        manzana_record["id"],
                        manzana.poligono,
                        manzana.status,
                        manzana.metadata,
                    )
                    if manzana_poligono:
                        manzana_summary["poligono_id"] = manzana_poligono["id"]
                    unit_entries.extend((unidad, manzana_record) for unidad in (manzana.unidades or []))
                    capa_summary["manzanas"].append(manzana_summary)

            if unit_entries:
                capa_summary["unidades"] = []
                for unidad, manzana_record in unit_entries:
                    tipo_id = await _resolve_tipo_id(
                        repo,
                        organizacion_id,
                        unidad.tipo_id,
                        unidad.tipo_nombre,
                        tipo_lookup,
                    )
                    unidad_payload: dict[str, Any] = {
                        "unidad": unidad.unidad.strip(),
                        "nombre": (unidad.nombre or unidad.unidad).strip(),
                        "tipo_id": tipo_id,
                        "nivel_id": capa_record["id"],
                        "desarrollo_id": record["id"],
                        "status": unidad.status.value,
                    }
                    if manzana_record:
                        unidad_payload["manzana_id"] = manzana_record["id"]
                    unidad_metadata = _coerce_metadata(unidad.metadata)
                    unidad_metadata, _ = _split_poligono_volume_metadata(unidad_metadata)
                    unidad_payload["metadata"] = unidad_metadata or {}
                    if unidad.descripcion:
                        unidad_payload["descripcion"] = unidad.descripcion.strip()
                    if unidad.precio is not None:
                        unidad_payload["precio"] = _decimal_to_number(unidad.precio)
                    if unidad.area_m2 is not None:
                        unidad_payload["area_m2"] = _decimal_to_number(unidad.area_m2)
                    resolved_linea_id = unidad.linea_id
                    if not resolved_linea_id and unidad.linea_nombre:
                        resolved_linea_id = await catalog_lookup.ensure_linea(unidad.linea_nombre)
                    resolved_familia_id = unidad.familia_id
                    if not resolved_familia_id and unidad.familia_nombre:
                        if not resolved_linea_id:
                            raise ValueError(
                                "Para usar 'familia_nombre' necesitas proporcionar 'linea_id' o 'linea_nombre'."
                            )
                        resolved_familia_id = await catalog_lookup.ensure_familia(
                            unidad.familia_nombre, resolved_linea_id
                        )
                    resolved_modelo_id = unidad.modelo_id
                    if not resolved_modelo_id and unidad.modelo_nombre:
                        if not resolved_familia_id:
                            raise ValueError(
                                "Para usar 'modelo_nombre' necesitas proporcionar 'familia_id' o 'familia_nombre'."
                            )
                        resolved_modelo_id = await catalog_lookup.ensure_model(
                            unidad.modelo_nombre, resolved_familia_id
                        )
                    if resolved_linea_id:
                        unidad_payload["linea_id"] = str(resolved_linea_id)
                    if resolved_familia_id:
                        unidad_payload["familia_id"] = str(resolved_familia_id)
                    if resolved_modelo_id:
                        unidad_payload["modelo_id"] = str(resolved_modelo_id)

                    capa_id_key = str(capa_record["id"])
                    unidades_existentes = unidades_por_capa.get(capa_id_key)
                    if unidades_existentes is None:
                        unidades_existentes = await repo.list_propiedad_unidades_by_capa(
                            organizacion_id=organizacion_id,
                            capa_id=UUID(capa_id_key),
                        )
                        unidades_por_capa[capa_id_key] = unidades_existentes
                    unidad_nombre = _normalize_column_value(unidad.unidad)
                    manzana_id = str(manzana_record["id"]) if manzana_record else None
                    unidad_record = next(
                        (
                            item
                            for item in unidades_existentes
                            if (
                                _normalize_column_value(str(item.get("unidad") or "")) == unidad_nombre
                                and str(item.get("manzana_id")) == manzana_id
                            )
                        ),
                        None,
                    )
                    if unidad_record is None:
                        unidad_record = await repo.create_propiedad_unidad(
                            organizacion_id=organizacion_id,
                            payload=unidad_payload,
                        )
                        unidades_existentes.append(unidad_record)
                    await _ensure_catalog_item_for_unidad(
                        repo=repo,
                        organizacion_id=organizacion_id,
                        desarrollo_record=record,
                        unidad_record=unidad_record,
                        unidad_source=unidad,
                        linea_id=resolved_linea_id,
                        familia_id=resolved_familia_id,
                        modelo_id=resolved_modelo_id,
                    )
                    unidad_summary: dict[str, Any] = {
                        "id": unidad_record["id"],
                        "unidad": unidad_record["unidad"],
                    }

                    unidad_poligono = await _create_poligono_if_present(
                        repo,
                        organizacion_id,
                        PropiedadPoligonoTarget.unidad,
                        unidad_record["id"],
                        unidad.poligono,
                        unidad.status,
                        unidad.metadata,
                    )
                    if unidad_poligono:
                        unidad_summary["poligono_id"] = unidad_poligono["id"]

                    capa_summary["unidades"].append(unidad_summary)

            summary["capas"].append(capa_summary)

    return summary


async def _import_desarrollo_mixto(
    repo: CRMRepository,
    organizacion_id: UUID,
    mixto: ImportDesarrolloMixto,
    tipo_lookup: dict[str, str],
    catalog_lookup: _PropertyCatalogLookup,
) -> dict[str, Any]:
    mixto_metadata = _coerce_metadata(mixto.metadata)
    mixto_metadata = _strip_metadata_keys(
        mixto_metadata,
        {"status", "pais_codigo", "estado_cve", "municipio_cve", "codigo_postal", "colonia", "tipo", "nombre", "descripcion"},
    )
    mixto_metadata, _ = _split_poligono_volume_metadata(mixto_metadata)
    payload: dict[str, Any] = {
        "nombre": mixto.nombre.strip(),
        "descripcion": mixto.descripcion.strip() if mixto.descripcion else None,
        "status": mixto.status.value,
        "metadata": mixto_metadata or {},
    }
    if mixto.pais_codigo:
        payload["pais_codigo"] = mixto.pais_codigo.strip()
    if mixto.estado_cve:
        payload["estado_cve"] = mixto.estado_cve.strip()
    if mixto.municipio_cve:
        payload["municipio_cve"] = mixto.municipio_cve.strip()
    if mixto.codigo_postal:
        payload["codigo_postal"] = mixto.codigo_postal.strip()
    if mixto.colonia:
        payload["colonia"] = mixto.colonia.strip()

    record = await repo.create_propiedad_desarrollo_mix(
        organizacion_id=organizacion_id,
        payload=payload,
    )
    summary: dict[str, Any] = {"id": record["id"], "nombre": record["nombre"], "items": []}

    mix_poligono = await _create_poligono_if_present(
        repo,
        organizacion_id,
        PropiedadPoligonoTarget.mix,
        record["id"],
        mixto.poligono,
        mixto.status,
        mixto.metadata,
    )
    if mix_poligono:
        summary["poligono_id"] = mix_poligono["id"]

    for item in mixto.items:
        child = await _import_desarrollo_tree(
            repo,
            organizacion_id,
            item.desarrollo,
            tipo_lookup,
            catalog_lookup,
        )
        mixto_payload: dict[str, Any] = {
            "mix_id": record["id"],
            "desarrollo_id": child["id"],
            "nombre": item.desarrollo.nombre.strip(),
            "modo": item.modo.value,
            "status": item.status.value,
        }
        item_metadata = _coerce_metadata(item.metadata)
        item_metadata = _strip_metadata_keys(
            item_metadata,
            {"status", "modo", "nivel", "altura", "nombre", "descripcion"},
        )
        item_metadata, _ = _split_poligono_volume_metadata(item_metadata)
        mixto_payload["metadata"] = item_metadata or {}
        if item.descripcion:
            mixto_payload["descripcion"] = item.descripcion.strip()
        if item.nivel is not None:
            mixto_payload["nivel"] = item.nivel
        if item.altura is not None:
            mixto_payload["altura"] = _decimal_to_number(item.altura)

        item_record = await repo.create_propiedad_desarrollo_mix_item(
            organizacion_id=organizacion_id,
            payload=mixto_payload,
        )
        summary["items"].append(
            {
                "id": item_record["id"],
                "modo": item.modo.value,
                "desarrollo": child,
            }
        )

    return summary


def _strip_catalog_volume_metadata(metadata: dict[str, Any] | None) -> dict[str, Any] | None:
    if not metadata:
        return metadata
    suppression = {"height", "min_height", "levels", "color"}
    filtered = {key: value for key, value in metadata.items() if key not in suppression}
    return filtered if filtered else None


def _strip_metadata_keys(
    metadata: dict[str, Any] | None,
    keys: set[str],
) -> dict[str, Any] | None:
    if not metadata:
        return metadata
    filtered = {key: value for key, value in metadata.items() if key not in keys}
    return filtered if filtered else None


def _split_poligono_volume_metadata(
    metadata: dict[str, Any] | None,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if not metadata:
        return None, None
    cleaned = dict(metadata)
    extracted: dict[str, Any] = {}

    def take_decimal(target: str, *aliases: str) -> None:
        for alias in aliases:
            if alias in cleaned:
                value = _parse_optional_decimal(cleaned.get(alias))
                if value is not None:
                    extracted[target] = _decimal_to_number(value)
                for key in aliases:
                    cleaned.pop(key, None)
                return

    def take_int(target: str, *aliases: str) -> None:
        for alias in aliases:
            if alias in cleaned:
                value = _parse_optional_int(cleaned.get(alias))
                if value is not None:
                    extracted[target] = value
                for key in aliases:
                    cleaned.pop(key, None)
                return

    def take_text(target: str, *aliases: str) -> None:
        for alias in aliases:
            if alias in cleaned:
                value = _strip_value(cleaned.get(alias))
                if value:
                    extracted[target] = value
                for key in aliases:
                    cleaned.pop(key, None)
                return

    take_decimal("height", "height")
    take_decimal("min_height", "min_height")
    take_int("levels", "levels")
    take_text("color", "color")

    return (cleaned or None), (extracted or None)


def _split_capa_status_metadata(
    metadata: dict[str, Any] | None,
) -> tuple[dict[str, Any] | None, PropiedadStatus | None]:
    if not metadata:
        return None, None
    cleaned = dict(metadata)
    raw_status = _strip_value(cleaned.pop("status", None))
    if raw_status is None:
        raw_status = _strip_value(cleaned.pop("estado", None))
    parsed_status = PropiedadStatus(raw_status) if raw_status else None
    return cleaned or None, parsed_status


async def _ensure_catalog_item_for_unidad(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    desarrollo_record: dict[str, Any],
    unidad_record: dict[str, Any],
    unidad_source: ImportUnidad,
    linea_id: UUID | None,
    familia_id: UUID | None,
    modelo_id: UUID | None,
) -> None:
    slug = _build_unidad_catalog_slug(development_name=desarrollo_record.get("nombre"), unidad_key=unidad_record.get("unidad"))
    metadata = _coerce_metadata(unidad_source.metadata)
    metadata = _strip_catalog_volume_metadata(metadata)
    metadata = {
        **(metadata or {}),
        "propiedad_id": str(desarrollo_record["id"]),
        "unidad_id": str(unidad_record["id"]),
        "destino_inventario": unidad_source.destino_inventario.value,
        "precio_tipo": unidad_source.precio_tipo.value,
    }
    destination = unidad_source.destino_inventario.value
    if destination == PropiedadDestinoInventario.patrimonial.value:
        existing = await repo.get_catalog_item_by_slug(
            organizacion_id=organizacion_id,
            slug=slug,
        )
        if existing:
            await repo.update_catalog_item(
                item_id=_safe_uuid(existing["id"]),
                payload={
                    "activo": False,
                    "maneja_inventario": False,
                    "activo_compra": False,
                    "metadatos": {
                        **metadata,
                        "venta_activa": False,
                        "inventario_destino": destination,
                    },
                },
            )
        _write_mapbox_debug_log(
            "catalog_item_skip_patrimonial",
            {
                "organizacion_id": str(organizacion_id),
                "unidad_id": str(unidad_record.get("id")),
                "destino_inventario": destination,
            },
        )
        return
    payload: dict[str, Any] = {
        "organizacion_id": str(organizacion_id),
        "nombre": f'{desarrollo_record.get("nombre") or "Propiedad"} · {unidad_record.get("unidad") or unidad_record.get("nombre") or ""}'.strip(" ·"),
        "unidad": str(unidad_record.get("unidad") or unidad_record.get("nombre") or ""),
        "tipo": "producto",
        "precio_base": _decimal_to_number(unidad_source.precio),
        "moneda": "MXN",
        "activo": True,
        "maneja_inventario": False,
        "activo_compra": False,
        "propiedad_id": str(desarrollo_record["id"]),
        "unidad_id": str(unidad_record["id"]),
        "metadatos": metadata,
    }
    if slug:
        payload["slug"] = slug
    if linea_id:
        payload["linea_id"] = str(linea_id)
    if familia_id:
        payload["familia_id"] = str(familia_id)
    if modelo_id:
        payload["modelo_id"] = str(modelo_id)
    if unidad_source.descripcion:
        payload["descripcion_corta"] = unidad_source.descripcion.strip()
    metadata_extra = unidad_source.metadata_extra or {}
    if metadata_extra:
        payload["metadatos_extra"] = metadata_extra
    existing = await repo.get_catalog_item_by_slug(
        organizacion_id=organizacion_id,
        slug=slug,
    )
    catalog_item_row: dict[str, Any] | None = None
    if existing:
        catalog_item_row = await repo.update_catalog_item(
            item_id=_safe_uuid(existing["id"]),
            payload=payload,
        )
    else:
        catalog_item_row = await repo.create_catalog_item(payload=payload)
    catalog_item_id = _safe_uuid(catalog_item_row.get("id"))
    unidad_uuid = _safe_uuid(unidad_record.get("id"))
    if catalog_item_id:
        metadata["catalog_item_id"] = str(catalog_item_id)
        if unidad_uuid:
            unidad_metadata = _ensure_dict(unidad_record.get("metadata"), default={})
            if unidad_metadata.get("catalog_item_id") != str(catalog_item_id):
                unidad_metadata["catalog_item_id"] = str(catalog_item_id)
                await repo.update_propiedad_unidad(
                    organizacion_id=organizacion_id,
                    unidad_id=unidad_uuid,
                    payload={
                        "catalog_item_id": str(catalog_item_id),
                        "metadata": unidad_metadata,
                    },
                )
    _write_mapbox_debug_log(
        "catalog_item_sync",
        {
            "organizacion_id": str(organizacion_id),
            "unidad_id": str(unidad_record.get("id")),
            "catalog_item_id": str(catalog_item_id) if catalog_item_id else None,
            "status": unidad_record.get("status"),
            "linea_id": unidad_record.get("linea_id"),
            "familia_id": unidad_record.get("familia_id"),
            "metadata_keys": sorted(list(metadata.keys())),
            "metadata_extra_keys": sorted(list((unidad_source.metadata_extra or {}).keys())),
        },
    )


def _build_unidad_catalog_slug(*, development_name: Any | None, unidad_key: Any | None) -> str:
    base_parts = []
    if development_name:
        base_parts.append(str(development_name))
    if unidad_key:
        base_parts.append(str(unidad_key))
    base = "-".join(base_parts)
    slug = _slugify(base)
    if slug:
        slug = f"{slug}-{uuid4().hex[:6]}"
    return slug or str(uuid4())


async def _create_poligono_if_present(
    repo: CRMRepository,
    organizacion_id: UUID,
    target_type: PropiedadPoligonoTarget,
    target_id: str,
    geometry: str | Mapping[str, Any] | None,
    status: PropiedadStatus,
    metadata: dict[str, Any] | None,
) -> dict[str, Any] | None:
    import_debug_logger.info(
        "poligono.create.start",
        extra={
            "target_type": target_type.value,
            "target_id": target_id,
            "status": status.value,
        },
    )
    normalize_start = time.perf_counter()
    geom = _normalize_geometry_input(geometry)
    normalize_duration_ms = (time.perf_counter() - normalize_start) * 1000
    geometry_preview = None
    if isinstance(geom, str):
        geometry_preview = geom if len(geom) <= 200 else f"{geom[:200]}..."
    import_debug_logger.info(
        "geometry.normalized",
        extra={
            "target_type": target_type.value,
            "target_id": target_id,
            "duration_ms": normalize_duration_ms,
            "geometry_is_none": geom is None,
            "geometry_preview": geometry_preview,
        },
    )
    if geom is None:
        return None
    metadata = _coerce_metadata(metadata)
    metadata, volume_fields = _split_poligono_volume_metadata(metadata)
    payload: dict[str, Any] = {
        "target_type": target_type.value,
        "target_id": target_id,
        "geom": geom,
        "status": status.value,
        "metadata": metadata or {},
    }
    if volume_fields:
        payload.update(volume_fields)
    existing = await repo.get_propiedad_poligono(
        organizacion_id=organizacion_id,
        target_type=target_type.value,
        target_id=UUID(str(target_id)),
    )
    if existing:
        record = await repo.update_propiedad_poligono(
            organizacion_id=organizacion_id,
            poligono_id=UUID(str(existing["id"])),
            payload=payload,
        )
    else:
        record = await repo.create_propiedad_poligono(
            organizacion_id=organizacion_id,
            payload=payload,
        )
    import_debug_logger.info(
        "poligono.create.finished",
        extra={
            "target_type": target_type.value,
            "target_id": target_id,
            "poligono_id": record["id"],
        },
    )
    return record


async def _resolve_tipo_id(
    repo: CRMRepository,
    organizacion_id: UUID,
    tipo_id: UUID | None,
    tipo_nombre: str | None,
    lookup: dict[str, str],
) -> str:
    if tipo_id:
        return str(tipo_id)
    if tipo_nombre:
        key = tipo_nombre.strip().lower()
        if not key:
            raise ValueError("El nombre del tipo no puede estar vacío.")
        match = lookup.get(key)
        if match:
            return match

        # El CSV es también un mecanismo de alta: si el tipo escrito no existe,
        # se crea dentro del tenant y queda disponible para las siguientes filas.
        created = await repo.create_propiedad_tipo(
            organizacion_id=organizacion_id,
            payload={
                "nombre": tipo_nombre.strip(),
                "descripcion": "Creado desde importación de propiedades.",
                "color": "#0F766E",
            },
        )
        created_id = str(created.get("id") or "")
        if not created_id:
            raise ValueError(f"No se pudo crear el tipo de propiedad '{tipo_nombre}'.")
        lookup[key] = created_id
        return created_id
    raise ValueError("Cada unidad requiere un tipo_id o tipo_nombre.")


def _find_tipo_alias(normalized_value: str, lookup: dict[str, str]) -> str | None:
    if not normalized_value:
        return None
    for alias, tipo_id in sorted(lookup.items(), key=lambda pair: -len(pair[0])):
        if not alias:
            continue
        if alias in normalized_value:
            return tipo_id
    return None


async def _build_tipo_lookup(repo: CRMRepository, organizacion_id: UUID) -> dict[str, str]:
    rows = await repo.list_propiedad_tipos(organizacion_id=organizacion_id)
    return {row["nombre"].strip().lower(): row["id"] for row in rows if row.get("id")}


def _coerce_metadata(value: dict[str, Any] | None) -> dict[str, Any]:
    return _normalize_metadata_value(value) or {}


def _build_pipeline_overview(
    rows: list[dict[str, Any]],
    total_rows: int,
    table_limit: int,
    days_range: int,
    timezone_name: str | None = None,
) -> CRMPipelineOverview:
    cards = _build_pipeline_cards(rows, timezone_name=timezone_name)
    chart = _build_pipeline_chart(rows, days_range, timezone_name=timezone_name)
    table = _build_pipeline_table(rows, table_limit)
    return CRMPipelineOverview(cards=cards, chart=chart, table=table, total_rows=total_rows)


def _extract_visitas_sin_chat(payload: dict[str, Any] | None) -> int:
    if not isinstance(payload, dict):
        return 0
    webchat = payload.get("webchat")
    if isinstance(webchat, dict):
        for key in (
            "visitas_sin_chat",
            "visitantes_sin_chat",
            "sin_chat",
            "sin_conversacion",
        ):
            value = webchat.get(key)
            if isinstance(value, (int, float)):
                return int(value)
    for key in ("visitantes", "visitantes_sin_chat", "visitas_sin_chat", "total"):
        value = payload.get(key)
        if isinstance(value, (int, float)):
            return int(value)
    return 0


def _render_catalog_sales_csv(rows: Sequence[dict[str, Any]]) -> str:
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(
        [
            "mes",
            "producto",
            "moneda",
            "total_vendido",
            "unidades_vendidas",
            "leads_ganados",
        ]
    )
    for row in rows:
        if not isinstance(row, dict):
            continue
        writer.writerow(
            [
                row.get("mes") or "",
                row.get("item_nombre") or "",
                (row.get("moneda") or "MXN").upper(),
                row.get("total_vendido") or 0,
                row.get("unidades_vendidas") or 0,
                row.get("leads_ganados") or 0,
            ]
        )
    return output.getvalue()


def _catalog_sales_filename(
    mes_desde: str | None, mes_hasta: str | None, moneda: str | None
) -> str:
    parts = ["ventas-productos"]
    if mes_desde and mes_hasta:
        parts.append(f"{mes_desde}_a_{mes_hasta}")
    elif mes_desde:
        parts.append(f"desde_{mes_desde}")
    elif mes_hasta:
        parts.append(f"hasta_{mes_hasta}")
    if moneda:
        parts.append(moneda.lower())
    return "-".join(parts) + ".csv"


def _build_pipeline_cards(
    rows: list[dict[str, Any]],
    *,
    timezone_name: str | None = None,
) -> CRMPipelineCards:
    zone = ZoneInfo((timezone_name or "UTC").strip() or "UTC")
    now = datetime.now(zone).astimezone(timezone.utc)
    nuevas_threshold = now - timedelta(days=1)
    abiertas = ganadas = perdidas = nuevas = 0
    monto_total = 0.0
    won_amounts: list[float] = []
    close_durations_days: list[float] = []
    top_counter: Counter[str] = Counter()
    top_names: dict[str, str] = {}

    for row in rows:
        estado = (row.get("estado") or "").lower()
        monto = row.get("monto_estimado")
        etapa = row.get("etapa") or {}
        stage_category = (etapa.get("categoria") or row.get("estado") or "abierta").lower()
        is_ganada = estado == "ganada" or stage_category == "ganada"
        is_perdida = estado == "perdida" or stage_category == "perdida"
        if is_ganada:
            ganadas += 1
        elif is_perdida:
            perdidas += 1
        else:
            abiertas += 1
        if stage_category == "ganada" or estado == "ganada":
            closed_amount = _extract_contract_value_from_metadata(row) or (
                float(monto) if isinstance(monto, (int, float)) else None
            )
            if closed_amount is not None:
                monto_total += closed_amount
                won_amounts.append(closed_amount)
            created_at_for_close = _parse_datetime(row.get("creado_en"))
            closed_at = _parse_datetime(row.get("cerrado_en")) or _extract_closed_date_from_metadata(row)
            if created_at_for_close and closed_at and closed_at >= created_at_for_close:
                close_durations_days.append(
                    (closed_at - created_at_for_close).total_seconds() / (24 * 60 * 60)
                )
        created_at = _parse_datetime(row.get("creado_en"))
        if created_at and created_at >= nuevas_threshold:
            nuevas += 1
        asignado = row.get("asignado") or {}
        user_id = asignado.get("id") or row.get("asignado_a_usuario_id")
        display_name = asignado.get("nombre_completo") or asignado.get("correo")
        if user_id:
            key = str(user_id)
            top_counter[key] += 1
            if display_name:
                top_names[key] = display_name

    top_vendedor = None
    if top_counter:
        user_key, total = top_counter.most_common(1)[0]
        top_vendedor = CRMPipelineTopSeller(
            id=_safe_uuid(user_key),
            nombre=top_names.get(user_key),
            total=total,
        )

    return CRMPipelineCards(
        total=len(rows),
        abiertas=abiertas,
        ganadas=ganadas,
        perdidas=perdidas,
        nuevas=nuevas,
        monto_total=monto_total,
        ticket_promedio_ganado=(
            round(sum(won_amounts) / len(won_amounts), 2) if won_amounts else 0
        ),
        dias_promedio_cierre=(
            round(sum(close_durations_days) / len(close_durations_days), 2)
            if close_durations_days
            else 0
        ),
        top_vendedor=top_vendedor,
    )


def _extract_contract_value_from_metadata(row: dict[str, Any]) -> float | None:
    metadata = _ensure_dict(row.get("metadata"), default={})
    stage_prep = _ensure_dict(metadata.get("stage_prep"), default={})
    for prep in stage_prep.values():
        if not isinstance(prep, dict):
            continue
        value = prep.get("contract_value")
        if value is None:
            continue
        try:
            return float(value)
        except (TypeError, ValueError):
            continue
    return None


def _extract_closed_date_from_metadata(row: dict[str, Any]) -> datetime | None:
    metadata = _ensure_dict(row.get("metadata"), default={})
    stage_prep = _ensure_dict(metadata.get("stage_prep"), default={})
    for prep in stage_prep.values():
        if not isinstance(prep, dict):
            continue
        close_date = _clean_text(prep.get("close_date"))
        if not close_date:
            continue
        parsed = _parse_datetime(close_date)
        if parsed:
            return parsed
    return None


def _build_pipeline_chart(
    rows: list[dict[str, Any]],
    days_range: int,
    *,
    timezone_name: str | None = None,
) -> list[CRMPipelineChartPoint]:
    if days_range < 1:
        days_range = 1
    zone = ZoneInfo((timezone_name or "UTC").strip() or "UTC")
    today = datetime.now(zone).date()
    start_date = today - timedelta(days=days_range - 1)
    buckets: dict[date, CRMPipelineChartPoint] = {}
    for offset in range(days_range):
        bucket_date = start_date + timedelta(days=offset)
        buckets[bucket_date] = CRMPipelineChartPoint(
            date=bucket_date.isoformat(),
            nuevos=0,
            ganados=0,
            perdidos=0,
        )

    for row in rows:
        created_at = _parse_datetime(row.get("creado_en"))
        if created_at:
            bucket = buckets.get(created_at.astimezone(zone).date())
            if bucket:
                bucket.nuevos += 1
        estado = (row.get("estado") or "").lower()
        cerrado_at = _parse_datetime(row.get("cerrado_en")) or _extract_closed_date_from_metadata(row)
        if not cerrado_at:
            continue
        bucket = buckets.get(cerrado_at.astimezone(zone).date())
        if not bucket:
            continue
        if estado == "ganada":
            bucket.ganados += 1
        elif estado == "perdida":
            bucket.perdidos += 1

    return [buckets[bucket_date] for bucket_date in sorted(buckets)]


def _build_pipeline_table(
    rows: list[dict[str, Any]], table_limit: int
) -> list[CRMPipelineTableRow]:
    sorted_rows = sorted(
        rows,
        key=lambda r: _parse_datetime(r.get("creado_en"))
        or datetime.min.replace(tzinfo=timezone.utc),
        reverse=True,
    )
    table: list[CRMPipelineTableRow] = []
    for index, row in enumerate(sorted_rows[:table_limit], start=1):
        etapa = row.get("etapa") or {}
        contacto = row.get("contacto") or {}
        asignado = row.get("asignado") or {}
        propietario = row.get("propietario") or {}
        cuenta = row.get("cuenta") or {}
        categoria = (etapa.get("categoria") or row.get("estado") or "abierta").lower()
        cerrado_dt = _parse_datetime(row.get("cerrado_en"))
        monto_estimado = row.get("monto_estimado")
        moneda = row.get("moneda") or "MXN"
        metric_meta = {
            "value": monto_estimado,
            "currency": moneda,
            "formatted": _format_currency(monto_estimado, moneda),
        }
        status_meta = _build_status_meta(categoria, cerrado_dt)
        header = (
            row.get("titulo")
            or contacto.get("nombre_completo")
            or cuenta.get("nombre")
            or "Oportunidad sin nombre"
        )
        reviewer = asignado.get("nombre_completo") or "Sin asignar"
        table.append(
            CRMPipelineTableRow(
                id=index,
                header=header,
                type=etapa.get("nombre") or "Sin etapa",
                status=categoria,
                target=str(monto_estimado or 0),
                limit=contacto.get("correo") or "—",
                reviewer=reviewer,
                raw={
                    "lead_id": row.get("id"),
                    "contacto_id": contacto.get("id"),
                    "etapa_id": row.get("etapa_id"),
                    "etapa_nombre": etapa.get("nombre"),
                    "etapa_codigo": etapa.get("codigo"),
                    "etapa_metadatos": etapa.get("metadata"),
                    "categoria": categoria,
                    "canal": (row.get("metadata") or {}).get("canal"),
                    "creado_en": row.get("creado_en"),
                    "actualizado_en": row.get("actualizado_en"),
                    "cerrado_en": row.get("cerrado_en"),
                    "monto_estimado": monto_estimado,
                    "moneda": moneda,
                    "probabilidad": row.get("probabilidad"),
                    "proyecto_nombre": row.get("titulo") or row.get("descripcion"),
                    "proyecto_necesidades": row.get("descripcion"),
                    "lead_score": (row.get("metadata") or {}).get("lead_score"),
                    "asignado_id": row.get("asignado_a_usuario_id"),
                    "asignado_nombre": reviewer,
                    "propietario_id": row.get("propietario_usuario_id"),
                    "propietario_nombre": propietario.get("nombre_completo"),
                    "contacto_correo": contacto.get("correo"),
                    "contacto_telefono": contacto.get("telefono_e164"),
                    "contacto_empresa": contacto.get("company_name"),
                    "contacto_notas": contacto.get("notes"),
                    "contacto_estado": contacto.get("estado") or contacto.get("captura_estado"),
                    "motivo_cierre": row.get("motivo_perdida"),
                    "tags": (row.get("metadata") or {}).get("tags"),
                    "metadata": row.get("metadata"),
                    "status_meta": status_meta,
                    "metric_meta": metric_meta,
                },
            )
        )
    return table


def _build_status_meta(categoria: str, cerrado_en: datetime | None) -> dict[str, str]:
    if categoria == "ganada":
        return {"label": "Ganado", "variant": "default"}
    if categoria == "perdida":
        return {"label": "Perdido", "variant": "destructive"}
    if cerrado_en:
        return {"label": "Cerrado", "variant": "secondary"}
    return {"label": "En proceso", "variant": "outline"}


def _format_currency(value: Any, currency: str) -> str:
    if not isinstance(value, (int, float)):
        return "—"
    formatted = f"{value:,.0f}"
    return f"{formatted} {currency}".strip()


def _parse_datetime(value: Any) -> datetime | None:
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    if isinstance(value, str) and value:
        try:
            normalized = value.replace("Z", "+00:00")
            parsed = datetime.fromisoformat(normalized)
            return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
        except ValueError:
            return None
    return None


def _safe_uuid(value: str | UUID | None) -> UUID | None:
    if isinstance(value, UUID):
        return value
    if isinstance(value, str):
        try:
            return UUID(value)
        except ValueError:
            return None
    return None


def _build_pipeline_board(
    stage_rows: list[dict[str, Any]],
    opportunity_rows: list[dict[str, Any]],
    tablero_id: UUID | None = None,
) -> CRMPipelineBoard:
    """Construye el board filtrando etapas y tarjetas por tablero."""

    tablero_filter = str(tablero_id) if tablero_id else None
    if tablero_filter is None:
        tablero_filter = _infer_tablero_id(stage_rows, opportunity_rows)
    stage_map: dict[UUID, CRMPipelineBoardStage] = {}
    stage_lookup_by_id: dict[UUID, CRMPipelineBoardStage] = {}
    canonical_stage_by_code: dict[str, CRMPipelineBoardStage] = {}

    def _stage_can_inherit_board(stage_code: str) -> bool:
        normalized = stage_code.lower()
        return normalized in {
            "prospeccion_primer_contacto",
            "cerrado_ganado",
            "cerrado_perdido",
            "ganado",
            "perdido",
        }

    def _stage_dedup_key(stage_code: str) -> str | None:
        normalized = stage_code.lower()
        if normalized == "prospeccion_primer_contacto":
            return normalized
        if normalized == "ganado" or normalized.endswith("_ganado"):
            return "cerrado_ganado"
        if normalized == "perdido" or normalized.endswith("_perdido"):
            return "cerrado_perdido"
        return None

    def add_stage_rows() -> None:
        for stage_row in stage_rows:
            stage = _stage_from_row(stage_row)
            if not stage:
                continue
            if (
                tablero_filter
                and not stage.tablero_id
                and _stage_can_inherit_board(stage.codigo or "")
            ):
                stage = CRMPipelineBoardStage(
                    **{
                        **stage.model_dump(),
                        "tablero_id": tablero_filter,
                    }
                )
            if tablero_filter and stage.tablero_id != tablero_filter:
                continue
            dedup_key = _stage_dedup_key(stage.codigo or "")
            if dedup_key:
                existing = canonical_stage_by_code.get(dedup_key)
                if existing is not None:
                    stage_lookup_by_id[stage.id] = existing
                    continue
                canonical_stage_by_code[dedup_key] = stage
            stage_map[stage.id] = stage
            stage_lookup_by_id[stage.id] = stage

    add_stage_rows()
    if not stage_map and stage_rows and tablero_filter:
        tablero_filter = None
        add_stage_rows()

    sin_conversacion: list[CRMPipelineBoardCard] = []

    for row in opportunity_rows:
        card = _card_from_opportunity(row)
        if card is None:
            continue
        card_tablero_id = _tablero_id_from_metadata(card.metadata)
        stage = stage_lookup_by_id.get(card.etapa_id) or stage_map.get(card.etapa_id)
        stage_tablero_id = stage.tablero_id if stage else _tablero_id_from_row(row)
        if tablero_filter:
            if card_tablero_id and card_tablero_id != tablero_filter:
                continue
            if stage_tablero_id and stage_tablero_id != tablero_filter:
                continue
            if not card_tablero_id and not stage_tablero_id:
                stage_code = (stage.codigo or "").lower() if stage else ""
                if _stage_can_inherit_board(stage_code):
                    pass
                else:
                    continue
        if stage is None:
            stage = _stage_from_opportunity(row)
            if stage and (not tablero_filter or stage.tablero_id == tablero_filter):
                dedup_key = _stage_dedup_key(stage.codigo or "")
                if dedup_key:
                    existing = canonical_stage_by_code.get(dedup_key)
                    if existing is not None:
                        stage_lookup_by_id[stage.id] = existing
                        stage = existing
                    else:
                        canonical_stage_by_code[dedup_key] = stage
                stage_map[stage.id] = stage
                stage_lookup_by_id[stage.id] = stage
        if stage:
            stage.tarjetas.append(card)
        if not card.conversacion_id and not _is_manual_card(card.metadata):
            sin_conversacion.append(card)

    for stage in stage_map.values():
        stage.tarjetas.sort(
            key=lambda card: card.actualizado_en or datetime.min.replace(tzinfo=timezone.utc),
            reverse=True,
        )

    ordered_stages = sorted(
        stage_map.values(),
        key=lambda stage: (stage.orden, stage.nombre.lower()),
    )

    sin_conversacion.sort(
        key=lambda card: card.actualizado_en or datetime.min.replace(tzinfo=timezone.utc),
        reverse=True,
    )

    return CRMPipelineBoard(
        stages=ordered_stages,
        sin_conversacion=sin_conversacion,
        visitantes_sin_chat=0,
    )


def _coerce_json_dict(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            if isinstance(parsed, dict):
                return parsed
        except json.JSONDecodeError:
            return {}
    return {}


def _coerce_bool(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        if value == 1:
            return True
        if value == 0:
            return False
        return None
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"si", "sí", "yes", "true", "1"}:
            return True
        if normalized in {"no", "false", "0"}:
            return False
    return None


def _coerce_float(value: Any) -> float | None:
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        trimmed = value.strip()
        if not trimmed:
            return None
        try:
            return float(trimmed)
        except ValueError:
            return None
    return None


def _safe_pct(numerator: int, denominator: int) -> float | None:
    if denominator <= 0:
        return None
    return round((numerator / denominator) * 100, 1)


def _build_scoring_kpis_slice(*, rows: list[dict[str, Any]]) -> dict[str, Any]:
    score_values: list[float] = []
    grades: Counter[str] = Counter()
    confidences: Counter[str] = Counter()
    response_bucket: Counter[str] = Counter()
    evasive_values: list[float] = []
    unique_opportunities: set[str] = set()

    accepts_true = accepts_total = 0
    requested_true = requested_total = 0
    scheduled_true = scheduled_total = 0
    confirmed_true = confirmed_total = 0
    attended_true = attended_total = 0

    for row in rows:
        opportunity_id = row.get("oportunidad_id")
        if opportunity_id:
            unique_opportunities.add(str(opportunity_id))

        score = _coerce_float(row.get("score_total"))
        if score is not None:
            score_values.append(max(0.0, min(score, 100.0)))

        grade = row.get("grade")
        if isinstance(grade, str) and grade.strip():
            grades[grade.strip().lower()] += 1

        confidence = row.get("confidence")
        if isinstance(confidence, str) and confidence.strip():
            confidences[confidence.strip().lower()] += 1

        events = _coerce_json_dict(row.get("events"))

        accept = _coerce_bool(events.get("accepted_answering_questions"))
        if accept is not None:
            accepts_total += 1
            if accept:
                accepts_true += 1

        requested = _coerce_bool(events.get("appointment_requested"))
        if requested is not None:
            requested_total += 1
            if requested:
                requested_true += 1

        scheduled = _coerce_bool(events.get("appointment_scheduled"))
        if scheduled is not None:
            scheduled_total += 1
            if scheduled:
                scheduled_true += 1

        confirmed = _coerce_bool(events.get("appointment_confirmed"))
        if confirmed is not None:
            confirmed_total += 1
            if confirmed:
                confirmed_true += 1

        attended = _coerce_bool(events.get("appointment_attended"))
        if attended is not None:
            attended_total += 1
            if attended:
                attended_true += 1

        evasive = _coerce_float(events.get("evasive_answers_count"))
        if evasive is not None:
            evasive_values.append(max(0.0, evasive))

        bucket = events.get("response_time_bucket")
        if isinstance(bucket, str) and bucket.strip():
            response_bucket[bucket.strip().lower()] += 1

    avg_score = round(sum(score_values) / len(score_values), 1) if score_values else None
    avg_evasive = round(sum(evasive_values) / len(evasive_values), 2) if evasive_values else None

    return {
        "total_eventos": len(rows),
        "oportunidades_unicas": len(unique_opportunities),
        "score_promedio": avg_score,
        "distribucion_grade": dict(grades),
        "distribucion_confidence": dict(confidences),
        "acepta_preguntas_pct": _safe_pct(accepts_true, accepts_total),
        "agenda_cita_pct": _safe_pct(scheduled_true, scheduled_total or requested_total),
        "confirma_cita_pct": _safe_pct(confirmed_true, confirmed_total),
        "asiste_cita_pct": _safe_pct(attended_true, attended_total),
        "evasivas_promedio": avg_evasive,
        "respuesta_bucket": dict(response_bucket),
    }


def _latest_rows_by_opportunity(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    latest_by_opportunity: dict[str, dict[str, Any]] = {}
    for row in rows:
        opportunity_id = row.get("oportunidad_id")
        if not opportunity_id:
            continue
        key = str(opportunity_id)
        if key not in latest_by_opportunity:
            # rows ya llegan en created_at DESC desde repositorio
            latest_by_opportunity[key] = row
    return list(latest_by_opportunity.values())


def _build_scoring_kpis(*, rows: list[dict[str, Any]], window_days: int) -> CRMPipelineScoringKpis:
    event_based = _build_scoring_kpis_slice(rows=rows)
    opportunity_latest_based = _build_scoring_kpis_slice(rows=_latest_rows_by_opportunity(rows))
    return CRMPipelineScoringKpis(
        window_days=window_days,
        total_eventos=event_based["total_eventos"],
        oportunidades_unicas=event_based["oportunidades_unicas"],
        score_promedio=event_based["score_promedio"],
        distribucion_grade=event_based["distribucion_grade"],
        distribucion_confidence=event_based["distribucion_confidence"],
        acepta_preguntas_pct=event_based["acepta_preguntas_pct"],
        agenda_cita_pct=event_based["agenda_cita_pct"],
        confirma_cita_pct=event_based["confirma_cita_pct"],
        asiste_cita_pct=event_based["asiste_cita_pct"],
        evasivas_promedio=event_based["evasivas_promedio"],
        respuesta_bucket=event_based["respuesta_bucket"],
        event_based=event_based,
        opportunity_latest_based=opportunity_latest_based,
    )


def _build_scoring_config_bundle(
    *,
    canal: Literal["whatsapp", "webchat"],
    profile_rows: list[dict[str, Any]],
    question_rows: list[dict[str, Any]],
    reprompt_rows: list[dict[str, Any]],
    rule_rows: list[dict[str, Any]],
) -> CRMScoringConfigBundle:
    return CRMScoringConfigBundle(
        canal=canal,
        profiles=[CRMScoringProfile.model_validate(row) for row in profile_rows],
        questions=[CRMScoringQuestion.model_validate(row) for row in question_rows],
        reprompts=[CRMScoringQuestionReprompt.model_validate(row) for row in reprompt_rows],
        rules=[CRMScoringRule.model_validate(row) for row in rule_rows],
    )


