async def _seed_scoring_defaults(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    canal: Literal["whatsapp", "webchat"],
    force: bool,
) -> CRMScoringSeedResponse:
    existing_questions = await repo.list_scoring_questions(
        organizacion_id=organizacion_id,
        canal=canal,
        include_inactive=True,
    )
    if existing_questions and not force:
        return CRMScoringSeedResponse(
            canal=canal,
            seeded=False,
            message="Ya existe configuración para este canal. Usa force=true para volver a sembrar.",
        )

    profile = await repo.upsert_scoring_profile(
        payload={
            "organizacion_id": str(organizacion_id),
            "canal": canal,
            "nombre": "default",
            "activo": True,
            "weights": {
                "capacidad_financiera": 30,
                "urgencia": 20,
                "nivel_decision": 20,
                "autoridad": 15,
                "interaccion_compromiso": 15,
            },
            "thresholds": {"explorando_max": 50, "interesado_max": 75, "listo_min": 76},
            "confidence_thresholds": {"high_min": 0.8, "medium_min": 0.5},
            "metadata": {"source": "seed_defaults_v1"},
        }
    )

    question_specs = _default_scoring_question_specs(canal)
    rules_by_field = _default_scoring_rules_by_field()
    questions_upserted = 0
    reprompts_upserted = 0
    rules_inserted = 0

    for spec in question_specs:
        question_row = await repo.upsert_scoring_question(
            payload={
                "organizacion_id": str(organizacion_id),
                "canal": canal,
                "field_key": spec["field_key"],
                "question_text": spec["question_text"],
                "question_type": "single_choice",
                "orden": spec["orden"],
                "activa": True,
                "required_for_case_a": spec["required_for_case_a"],
                "repregunta_max": spec["repregunta_max"],
                "allow_unknown": True,
                "allow_refused": True,
                "metadata": spec.get("metadata") or {},
            }
        )
        questions_upserted += 1

        question_id = str(question_row.get("id") or "").strip()
        if not question_id:
            continue

        await repo.upsert_scoring_question_reprompt(
            payload={
                "question_id": question_id,
                "organizacion_id": str(organizacion_id),
                "canal": canal,
                "intento": 1,
                "prompt_text": "¿Me ayudas con este dato para recomendarte mejor?",
                "activa": True,
                "metadata": {"source": "seed_defaults_v1"},
            }
        )
        reprompts_upserted += 1

        existing_rules = await repo.list_scoring_rules(
            organizacion_id=organizacion_id,
            canal=canal,
            question_id=UUID(question_id),
            include_inactive=True,
        )
        existing_rule_keys = {
            (
                str(row.get("rule_type") or "").strip().lower(),
                str(row.get("match_value") or "").strip().lower(),
                str(row.get("score") or ""),
                str(row.get("priority") or ""),
            )
            for row in existing_rules
        }
        for rule in rules_by_field.get(spec["field_key"], []):
            rule_key = (
                str(rule.get("rule_type") or "").strip().lower(),
                str(rule.get("match_value") or "").strip().lower(),
                str(rule.get("score") or ""),
                str(rule.get("priority") or ""),
            )
            if rule_key in existing_rule_keys:
                continue
            await repo.upsert_scoring_rule(
                payload={
                    "organizacion_id": str(organizacion_id),
                    "question_id": question_id,
                    "canal": canal,
                    "rule_type": rule["rule_type"],
                    "match_value": rule.get("match_value"),
                    "score": rule["score"],
                    "priority": rule.get("priority", 100),
                    "activa": True,
                    "metadata": {"source": "seed_defaults_v1"},
                }
            )
            rules_inserted += 1

    profile_id = profile.get("id")
    return CRMScoringSeedResponse(
        canal=canal,
        seeded=True,
        profile_id=UUID(str(profile_id)) if profile_id else None,
        questions_upserted=questions_upserted,
        reprompts_upserted=reprompts_upserted,
        rules_inserted=rules_inserted,
        message="Seed completado.",
    )


def _infer_tablero_id(
    stage_rows: list[dict[str, Any]], opportunity_rows: list[dict[str, Any]]
) -> str | None:
    """Determina el tablero más representativo cuando no se especifica."""

    stage_order: list[str] = []
    for row in stage_rows:
        tablero_from_metadata = _tablero_id_from_metadata(
            _ensure_dict(row.get("metadata") or row.get("metadatos"), default={})
        )
        tablero_from_column = _tablero_id_from_metadata({"tablero_id": row.get("tablero_id")})
        candidate = tablero_from_metadata or tablero_from_column
        if candidate and candidate not in stage_order:
            stage_order.append(candidate)

    tablero_counts: dict[str, int] = {}
    for row in opportunity_rows:
        candidates = {
            _tablero_id_from_metadata(_ensure_dict(row.get("metadata"), default={})),
            _tablero_id_from_metadata({"tablero_id": row.get("tablero_id")}),
            _tablero_id_from_row(row),
        }
        candidates.discard(None)
        for candidate in candidates:
            tablero_counts[candidate] = tablero_counts.get(candidate, 0) + 1

    if tablero_counts:
        best_tablero = max(
            tablero_counts.items(),
            key=lambda item: (
                item[1],
                (-stage_order.index(item[0]) if item[0] in stage_order else -len(stage_order)),
            ),
        )[0]
        return best_tablero

    if len(stage_order) == 1:
        return stage_order[0]
    return None


async def _build_pipeline_card_response(
    *,
    repo: CRMRepository,
    organizacion_id: UUID,
    oportunidad_id: UUID,
) -> CRMPipelineCardResponse:
    row = await repo.get_pipeline_opportunity(
        organizacion_id=organizacion_id,
        oportunidad_id=oportunidad_id,
    )
    if not row:
        raise HTTPException(status_code=404, detail="opportunity_not_found")
    stage = _stage_from_opportunity(row)
    card = _card_from_opportunity(row)
    if stage is None or card is None:
        raise HTTPException(status_code=404, detail="pipeline_card_unavailable")
    return CRMPipelineCardResponse(stage=stage, card=card)


def _history_item_from_row(row: dict[str, Any]) -> CRMPipelineHistoryItem:
    history_id = _safe_uuid(row.get("id"))
    if history_id is None:
        raise HTTPException(status_code=502, detail="history_entry_missing_id")
    opportunity_id = _safe_uuid(row.get("oportunidad_id"))
    if opportunity_id is None:
        raise HTTPException(status_code=502, detail="history_entry_missing_opportunity")
    metadata = _ensure_dict(row.get("metadata"), default={})
    tipo = metadata.get("tipo") or "movimiento"
    nota = metadata.get("nota")
    cambiado_por = _ensure_dict(row.get("cambiado_por"), default={})
    etapa_origen = _ensure_dict(row.get("etapa_origen"), default={})
    etapa_destino = _ensure_dict(row.get("etapa_destino"), default={})
    return CRMPipelineHistoryItem(
        id=history_id,
        oportunidad_id=opportunity_id,
        tipo=str(tipo),
        cambiado_en=_parse_datetime(row.get("cambiado_en")),
        cambiado_por_id=_safe_uuid(row.get("cambiado_por_usuario_id")),
        cambiado_por_nombre=cambiado_por.get("nombre_completo"),
        fuente=row.get("fuente"),
        etapa_origen_id=_safe_uuid(row.get("etapa_origen_id")),
        etapa_origen_nombre=etapa_origen.get("nombre"),
        etapa_destino_id=_safe_uuid(row.get("etapa_destino_id")),
        etapa_destino_nombre=etapa_destino.get("nombre"),
        motivo=row.get("motivo"),
        nota=nota if isinstance(nota, str) and nota.strip() else None,
        metadata=metadata or None,
    )


def _stage_from_row(row: dict[str, Any]) -> CRMPipelineBoardStage | None:
    stage_id = _safe_uuid(row.get("id"))
    if not stage_id:
        return None
    metadata = _ensure_dict(row.get("metadata") or row.get("metadatos"), default={})
    tablero_id = _tablero_id_from_metadata(metadata)
    tablero_from_column = _tablero_id_from_metadata({"tablero_id": row.get("tablero_id")})
    tablero_value = tablero_id or tablero_from_column
    return CRMPipelineBoardStage(
        id=stage_id,
        nombre=row.get("nombre") or "Sin etapa",
        codigo=row.get("codigo") or "",
        categoria=row.get("categoria") or "abierta",
        orden=int(row.get("orden") or 0),
        tablero_id=tablero_value,
        metadatos=metadata,
        tarjetas=[],
    )


def _stage_from_opportunity(row: dict[str, Any]) -> CRMPipelineBoardStage | None:
    etapa = row.get("etapa") or {}
    etapa_id = _safe_uuid(row.get("etapa_id") or etapa.get("id"))
    if not etapa_id:
        return None
    metadata = _ensure_dict(etapa.get("metadata") or etapa.get("metadatos"), default={})
    tablero_id = _tablero_id_from_metadata(metadata)
    tablero_from_column = _tablero_id_from_metadata({"tablero_id": etapa.get("tablero_id")})
    tablero_value = tablero_id or tablero_from_column
    return CRMPipelineBoardStage(
        id=etapa_id,
        nombre=etapa.get("nombre") or "Sin etapa",
        codigo=etapa.get("codigo") or "",
        categoria=etapa.get("categoria") or row.get("estado") or "abierta",
        orden=int(etapa.get("orden") or 0),
        tablero_id=tablero_value,
        metadatos=metadata,
        tarjetas=[],
    )


def _card_from_opportunity(row: dict[str, Any]) -> CRMPipelineBoardCard | None:
    oportunidad_id = _safe_uuid(row.get("id"))
    etapa_id = _safe_uuid(row.get("etapa_id"))
    if not oportunidad_id or not etapa_id:
        return None
    metadata = _ensure_dict(row.get("metadata"), default={})
    contacto = _ensure_dict(row.get("contacto"), default={})
    cuenta = _ensure_dict(row.get("cuenta"), default={})
    asignado = _ensure_dict(row.get("asignado"), default={})
    stored_project_name = metadata.get("project_name")
    raw_title = None
    if isinstance(stored_project_name, str) and stored_project_name.strip():
        raw_title = stored_project_name.strip()
    else:
        title_value = row.get("titulo")
        if isinstance(title_value, str) and title_value.strip():
            raw_title = title_value.strip()
    titulo_value = raw_title or cuenta.get("nombre") or "Oportunidad sin nombre"

    contacto_nombre = _clean_text(row.get("contacto_nombre")) or None
    metadata_contacto_nombre = _clean_text(metadata.get("contacto_nombre")) or None
    contacto_nombre_relacion = _clean_text(contacto.get("nombre_completo")) or None
    contacto_datos = _ensure_dict(
        contacto.get("persona_datos") or contacto.get("contacto_datos"),
        default={},
    )
    contacto_profile_name = _clean_text(contacto_datos.get("profile_name")) or None
    nombre = contacto_nombre_relacion or metadata_contacto_nombre or contacto_nombre
    conversacion_id = _safe_uuid(metadata.get("conversacion_id"))
    asignado_nombre = asignado.get("nombre_completo") or asignado.get("correo")
    prioridad = metadata.get("lead_score")
    tags_value = metadata.get("tags")
    etiquetas = (
        [str(tag) for tag in tags_value if isinstance(tag, str)]
        if isinstance(tags_value, list)
        else None
    )
    actualizado_en = _parse_datetime(row.get("actualizado_en"))
    canal = metadata.get("canal") or metadata.get("channel")
    origen_contacto = (
        _clean_text(contacto.get("origen"))
        or _clean_text(metadata.get("contacto_origen"))
        or _clean_text(metadata.get("contact_origin"))
        or _clean_text(metadata.get("origen_contacto"))
        or _clean_text(metadata.get("contact_source"))
        or None
    )
    contacto_correo = (
        _clean_text(contacto.get("correo_principal"))
        or _clean_text(contacto.get("correo_institucional"))
        or _clean_text(contacto.get("correo"))
        or _clean_text(metadata.get("contacto_correo"))
        or None
    )
    contacto_telefono = (
        _clean_text(contacto.get("telefono_movil_1_e164"))
        or _clean_text(contacto.get("telefono_principal_e164"))
        or _clean_text(contacto.get("telefono_e164"))
        or _clean_text(contacto.get("telefono"))
        or _clean_text(metadata.get("contacto_telefono"))
        or None
    )
    contacto_empresa = (
        _clean_text(contacto.get("company_name"))
        or _clean_text(cuenta.get("nombre"))
        or _clean_text(metadata.get("contacto_empresa"))
        or None
    )
    necesidad_proposito = (
        _clean_text(contacto.get("necesidad_proposito"))
        or cuenta.get("necesidad_proposito")
        or _clean_text(metadata.get("contacto_necesidad"))
        or metadata.get("necesidad_proposito")
    )
    proyecto_nombre = (
        _clean_text(metadata.get("project_name"))
        or _clean_text(row.get("titulo"))
        or _clean_text(cuenta.get("nombre"))
        or None
    )
    proyecto_necesidades = _clean_text(metadata.get("proyecto_necesidades")) or _clean_text(row.get("descripcion")) or None

    return CRMPipelineBoardCard(
        tarjeta_id=oportunidad_id,
        contacto_id=_safe_uuid(contacto.get("id")),
        conversacion_id=conversacion_id,
        origen=origen_contacto,
        codigo_oportunidad=_clean_text(row.get("codigo_oportunidad")) or None,
        titulo=titulo_value,
        nombre=nombre,
        contacto_profile_name=contacto_profile_name,
        correo=contacto_correo,
        telefono=contacto_telefono,
        empresa=contacto_empresa,
        notas=_clean_text(metadata.get("contacto_notas")) or contacto.get("notas") or contacto.get("notes"),
        necesidad_proposito=necesidad_proposito,
        canal=canal,
        estado=contacto.get("estado") or contacto.get("captura_estado"),
        etapa_id=etapa_id,
        etapa_nombre=(row.get("etapa") or {}).get("nombre") or "Sin etapa",
        etapa_codigo=(row.get("etapa") or {}).get("codigo"),
        monto=row.get("monto_estimado"),
        moneda=row.get("moneda"),
        probabilidad=row.get("probabilidad"),
        proyecto_nombre=proyecto_nombre,
        proyecto_necesidades=proyecto_necesidades,
        asignado_id=_safe_uuid(row.get("asignado_a_usuario_id")),
        asignado_nombre=asignado_nombre,
        prioridad=float(prioridad) if isinstance(prioridad, (int, float)) else None,
        actualizado_en=actualizado_en,
        etiquetas=etiquetas,
        metadata=metadata,
    )


# ---------------------------------------------------------------------------
# Prospección · Buscador web
# ---------------------------------------------------------------------------


class BuscadorTopDomain(BaseModel):
    domain: str
    count: int


class BuscadorTopSource(BaseModel):
    host: str
    count: int


class BuscadorStats(BaseModel):
    emails_total: int
    unique_email_domains: int
    unique_source_hosts: int
    top_email_domains: list[BuscadorTopDomain] = Field(default_factory=list)
    top_source_hosts: list[BuscadorTopSource] = Field(default_factory=list)
    crawl_metrics: dict[str, Any] | None = None
    checkpoint: dict[str, Any] | None = None


class BuscadorResultItem(BaseModel):
    id: UUID | None = None
    source_url: str
    email: str
    name: str | None = None
    position: str | None = None
    phone: str | None = None
    extension: str | None = None
    address: str | None = None


def _dedupe_buscador_result_rows(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    unique: list[dict[str, Any]] = []
    seen_emails: set[str] = set()
    for row in rows:
        email_value = _normalize_email(row.get("correo") or row.get("email"))
        if not email_value:
            continue
        if email_value in seen_emails:
            continue
        seen_emails.add(email_value)
        item = dict(row)
        item["correo"] = email_value
        unique.append(item)
    return unique


class BuscadorRunPayload(BaseModel):
    sitio: Literal["demo", "simple", "domain"] = "domain"
    url: HttpUrl | None = None
    mode: Literal["generic", "government", "intelligent", "auto", "stealth"] = "generic"
    max_pages: int = Field(default=200, ge=1, le=5000)
    max_depth: int = Field(default=3, ge=1, le=50)
    max_workers: int = Field(default=3, ge=1, le=5)
    max_runtime: int | None = Field(default=None, ge=10, le=7200)
    max_queue_size: int | None = Field(default=None, ge=10, le=20000)
    max_no_new_emails: int | None = Field(default=None, ge=1, le=1000)
    max_memory_mb: int | None = Field(default=None, ge=64, le=8192)
    resume_job_id: UUID | None = None

    @model_validator(mode="after")
    def validate_url(self) -> BuscadorRunPayload:
        if self.sitio in {"simple", "domain"} and not self.url:
            raise ValueError("Debes proporcionar una URL para este tipo de scraper.")
        return self


class BuscadorJobParamsResponse(BaseModel):
    sitio: Literal["demo", "simple", "domain"]
    url: HttpUrl | None = None
    mode: Literal["generic", "government", "intelligent", "auto", "stealth"]
    max_pages: int
    max_depth: int
    max_workers: int = 3
    max_runtime: int | None = None
    max_queue_size: int | None = None
    max_no_new_emails: int | None = None
    max_memory_mb: int | None = None
    seed_urls: list[str] | None = None
    skip_urls: list[str] | None = None
    resume_job_id: UUID | None = None


class BuscadorJobResponse(BaseModel):
    id: UUID
    status: Literal[
        "pending",
        "running",
        "pausing",
        "canceling",
        "completed",
        "failed",
        "paused",
        "canceled",
    ]
    created_at: datetime
    started_at: datetime | None = None
    finished_at: datetime | None = None
    duration_ms: int | None = None
    total: int | None = None
    stats: BuscadorStats | None = None
    error: str | None = None
    params: BuscadorJobParamsResponse


class BuscadorJobsListResponse(BaseModel):
    items: list[BuscadorJobResponse]
    total: int
    limit: int
    offset: int


class GuardarBuscadorProspectosPayload(BaseModel):
    result_ids: list[UUID] | None = None
    segmento: str | None = None
    save_all: bool = False

    @field_validator("result_ids")
    @classmethod
    def _dedupe_result_ids(cls, value: list[UUID] | None) -> list[UUID] | None:
        if value is None:
            return None
        unique: list[UUID] = []
        seen: set[UUID] = set()
        for item in value:
            if item in seen:
                continue
            seen.add(item)
            unique.append(item)
        return unique


@router.post(
    "/prospeccion/buscador/run",
    response_model=BuscadorJobResponse,
    status_code=status.HTTP_202_ACCEPTED,
)
async def prospeccion_buscador_run(
    payload: BuscadorRunPayload,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    organizacion_id: UUID = Depends(require_organizacion_id),
) -> BuscadorJobResponse:
    """Agenda la ejecución del Buscador y devuelve el identificador del job."""

    seed_urls: list[str] = []
    skip_urls: list[str] = []
    if payload.resume_job_id:
        try:
            resume_job = await repo.get_buscador_job(
                job_id=payload.resume_job_id,
                organizacion_id=organizacion_id,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not resume_job:
            raise HTTPException(status_code=404, detail="resume_job_not_found")
        resume_status = str(resume_job.get("status") or "pending")
        if resume_status not in {"completed", "paused", "canceled", "failed"}:
            raise HTTPException(status_code=409, detail="resume_job_not_ready")

        resume_stats = resume_job.get("stats") if isinstance(resume_job.get("stats"), dict) else {}
        checkpoint = resume_stats.get("checkpoint") if isinstance(resume_stats.get("checkpoint"), dict) else {}
        visited_urls = checkpoint.get("visited_urls") if isinstance(checkpoint, dict) else None
        if isinstance(visited_urls, list):
            for value in visited_urls:
                if isinstance(value, str) and value.strip():
                    skip_urls.append(value.strip())
        pending_queue_urls = checkpoint.get("pending_queue_urls") if isinstance(checkpoint, dict) else None
        if isinstance(pending_queue_urls, list):
            for value in pending_queue_urls:
                if isinstance(value, str) and value.strip():
                    seed_urls.append(value.strip())
        queue_sample = checkpoint.get("remaining_queue_sample") if isinstance(checkpoint, dict) else None
        if isinstance(queue_sample, list):
            for value in queue_sample:
                if isinstance(value, str) and value.strip():
                    seed_urls.append(value.strip())

        offset = 0
        limit = 1000
        while len(seed_urls) < 5000:
            try:
                chunk = await repo.list_buscador_resultados(
                    organizacion_id=organizacion_id,
                    job_id=payload.resume_job_id,
                    limit=limit,
                    offset=offset,
                )
            except CRMRepositoryError as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc
            if not chunk:
                break
            for row in chunk:
                source_url = _clean_text(row.get("url") or row.get("source_url"))
                if source_url:
                    seed_urls.append(source_url)
            offset += len(chunk)
            if len(chunk) < limit:
                break

        # Dedup final de seeds preservando orden.
        dedup_seed_urls: list[str] = []
        seen_seed: set[str] = set()
        for value in seed_urls:
            if value in seen_seed:
                continue
            seen_seed.add(value)
            dedup_seed_urls.append(value)
        seed_urls = dedup_seed_urls

        dedup_skip_urls: list[str] = []
        seen_skip: set[str] = set()
        for value in skip_urls:
            if value in seen_skip:
                continue
            seen_skip.add(value)
            dedup_skip_urls.append(value)
        skip_urls = dedup_skip_urls

    params = BuscadorParams(
        sitio=payload.sitio,
        url=str(payload.url) if payload.url else None,
        mode=payload.mode,
        max_pages=payload.max_pages,
        max_depth=payload.max_depth,
        max_workers=payload.max_workers,
        max_runtime=payload.max_runtime,
        max_queue_size=payload.max_queue_size,
        max_no_new_emails=payload.max_no_new_emails,
        max_memory_mb=payload.max_memory_mb,
        seed_urls=seed_urls or None,
        skip_urls=skip_urls or None,
        resume_job_id=str(payload.resume_job_id) if payload.resume_job_id else None,
    )

    job_payload: dict[str, Any] = {
        "status": "pending",
        "params": _params_to_dict(params),
    }
    if usuario_id:
        job_payload["creado_por"] = str(usuario_id)

    try:
        job_row = await repo.create_buscador_job(organizacion_id=organizacion_id, payload=job_payload)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    BUSCADOR_JOB_MANAGER.schedule_job(repo=repo, job_row=job_row, params=params)
    return _job_row_to_response(job_row)


